          // THREE big front-door bubbles. SUB-MAINS opens the group layer; PLAYER
          // WORLDS opens the player-made shelf (those worlds collapse behind it
          // instead of crowding main); the CHAMPION is a core world sized big in
          // place below (marked where the crown is set). Fixed positions = anchored.
          // a tight triangle at the heart: CHAMPION at the apex (pinned where the
          // crown is set, below), SUB-MAINS + PLAYER WORLDS along the base.
          // LOCKED center triangle: champion at the apex (seated where the crown
          // lands, below), SUB-MAINS + PLAYER WORLDS along the base. The field
          // clusters around these three; they never drift.
          want['SUB-MAINS'] = { launch: 'SUB-MAIN', style: 8, hue: 0.58, big: 1, cat: 2, fixed: [215, 285] }
          want['PLAYER WORLDS'] = { launch: 'players:', style: 8, hue: 0.34, big: 1, cat: 3, fixed: [297, 285] }
        }
        for (const n of Object.keys(want)) {
          if (!U.bubbles[n]) {
            const sb = shared && shared.bubbles[n]
            if (sb) {
              // this world already has its place in the shared universe
              U.bubbles[n] = { x: sb.x, y: sb.y, vx: 0, vy: 0, justPlaced: 1, anchored: 1,
                born: sb.born || now, launch: want[n].launch, style: want[n].style, hue: (want[n].hue != null ? want[n].hue : hueOf(n)), score: 2 }
            } else {
              // truly newborn — spawn on the RIM at the emptiest bearing so it
              // never lands on top of a sibling; packing pressure and score then
              // sort it inward from there (the old center-spawn caused overlaps)
              const others = Object.keys(U.bubbles).map(k => U.bubbles[k]).filter(Boolean)
              let maxR = 40
              const angs = []
              for (const o of others) {
                angs.push(Math.atan2((o.y - 256) / 0.74, o.x - 256))
                maxR = Math.max(maxR, Math.hypot(o.x - 256, (o.y - 256) / 0.74))
              }
              let a2 = angOf(n)
              if (angs.length > 0) {
                angs.sort((p, q) => p - q)
                let widest = -1
                for (let k = 0; k < angs.length; k++) {
                  const lo = angs[k], hi = k + 1 < angs.length ? angs[k + 1] : angs[0] + 6.28318
                  if (hi - lo > widest) { widest = hi - lo; a2 = lo + (hi - lo) / 2 }
                }
              }
              const rr = maxR + 78
              U.bubbles[n] = { x: 256 + Math.cos(a2) * rr, y: 256 + Math.sin(a2) * rr * 0.74, vx: 0, vy: 0,
                born: now, launch: want[n].launch, style: want[n].style, hue: (want[n].hue != null ? want[n].hue : hueOf(n)), score: 2 }
              if (!calmBoot) U.wake = 10   // a birth perturbs the settled field — but never the loading one
            }
          }
          const B = U.bubbles[n]
          B.launch = want[n].launch
          B.big = !!want[n].big
          B.cat = want[n].cat || 0   // 2 = sub-mains glyph · 3 = player-worlds glyph (own render band, never an icon slot)
          if (want[n].fixed) {   // a locked seat — first pin wakes the field so neighbours clear out
            if (!B.pinned) U.wake = Math.max(U.wake, 5)
            B.x = want[n].fixed[0]; B.y = want[n].fixed[1]; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1
          }
          if (adopt && adopt.bubbles[n] && !want[n].big) {   // the shared arrangement wins — but the big three always float free by gravity
            const sb2 = adopt.bubbles[n]
            B.x = sb2.x; B.y = sb2.y; B.vx = 0; B.vy = 0; B.anchored = 1
            if (sb2.born) B.born = sb2.born
          }
          // participation pressure: cell activity + birth heat
          const cellAge = cellAt[n] ? (now - cellAt[n]) / 60000 : 999
          const bornHeat = Math.max(0, 1 - (now - B.born) / 120000)
          const T = (tvr && tvr.data && tvr.data.round) ? tvr.data : null
          // the tier a world has climbed — but its pull DECAYS over days without
          // fresh support, so the field clears out on its own (half-life ~3d).
          let reach = T && T.reached ? (T.reached[n] || 0) : 0
          if (reach > 1 && T && T.reachedAt && T.reachedAt[n]) {
            const ageDays = (now - T.reachedAt[n]) / 86400000
            reach = 1 + (reach - 1) * Math.pow(0.5, ageDays / 3)
          }
          // LIVE pressure: every vote cast in the open tier pushes its world
          // toward the crown right now — the constellation moves as people vote,
          // before any tier resolves.
          let live = 0
          if (T && T.cells) for (const c of T.cells) { const v = c.votes || {}; for (const k in v) if (v[k] === n) live++ }
          // the reigning world — or QUANTIC DOJO as the seeded first champion so
          // there's always a starting place until a vote crowns someone.
          const champName = (T && T.champion) || 'QUANTIC DOJO'
          const champ = n === champName
          B.crown = !!champ
          if (champ) {   // the reigning world sits LOCKED at the triangle's apex, wearing the crown
            B.big = true
            if (!B.pinned) U.wake = Math.max(U.wake, 5)
            B.x = 256; B.y = 210; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1
          } else if (B.pinned && !B.cat) {   // dethroned — rejoin the floating field
            B.pinned = 0; B.anchored = 0; B.big = false
          }
          // NEW vs VOTED: a world that has climbed a tier, holds the crown, or is
          // taking live votes belongs to the voted cluster at center; everything
          // else is a new arrival held in the outer ring. A status flip re-settles
          // it into the other band (un-anchor so it can cross the buffer).
          const nowVoted = live > 0 || reach > 1 || champ || !!B.cat   // the big category bubbles belong to the central cluster too
          if (!B.justPlaced && !!B.voted !== nowVoted) { B.anchored = 0; U.wake = Math.max(U.wake, 7) }
          B.voted = nowVoted
          // a world with a hand-coded style is a house mini. Otherwise: if the
          // engine has rendered this world's OWN visual into an atlas slot, the
          // bubble shows that (the world's real look); else a LIVING EMBLEM in
          // the world's own palette (hue from its field colors). Nothing stored.
          if (want[n].hue != null) B.hue = want[n].hue
          const slots = (typeof window !== 'undefined' && window.__cafeIconSlots) || null
          B.iconSlot = slots && slots[n] != null ? slots[n] : null
          // before the first icon pass lands, an un-styled bubble (style 8) shows
          // a spinner instead of flashing the default emblem
          const ready = (typeof window !== 'undefined') ? window.__cafeIconReady : true
          B.iconLoading = !B.cat && B.style >= 8 && B.style < 30 && !ready   // atlas not uploaded yet: unstyled bubbles wait. Category glyphs (cat) and maker avatars (30-34) draw from the shader — no atlas.
          const ns = SUB
            ? 1 + ((want[n].heat || 0) * 0.5) + (want[n].mineSub ? 100 : 0)
            : 1 / (1 + cellAge / 20) + bornHeat + reach * 1.4 + live * 0.7 + (champ ? 6 : 0)
          // chant shifts perturb — but a bubble just placed from the shared
          // universe getting its first real score is not a shift, it's arrival.
          // Threshold 1.0: only REAL events move the field (a champion crowned
          // ±6, a tier climbed ±1.4, a birth) — the slow decay of heat and cell
          // age drifts scores by less and must NOT reshuffle the room. (At 0.03
          // the field woke on almost every poll and no layout ever held.)
          if (!B.justPlaced && !calmBoot && Math.abs(ns - B.score) > 1.0) U.wake = Math.max(U.wake, 7)
          delete B.justPlaced
          // the big three own the deepest gravity — champion #1, then the two
          // category bubbles — so they sink to the very heart and cluster there.
          B.score = champ ? 40 : (B.cat ? 26 : ns)
        }
        // a degraded first pass only ADDS — pruning waits for the full poll,
        // so a slow spaces fetch can't blink player worlds out and back
        if (!firstFill) for (const n of Object.keys(U.bubbles)) if (!want[n]) delete U.bubbles[n]
        // NOTHING renders without the roster's word — a stale shared-doc bubble
        // (a world hidden since it was saved) must never get even one frame.
        // On a degraded first pass it just waits in U.bubbles for the full poll.
        U.order = Object.keys(U.bubbles).filter(n => want[n]).sort((a2, b2) => U.bubbles[b2].score - U.bubbles[a2].score).slice(0, 200)
        if ((MF || SUB || PL) && U.order.length === 0 && !U.hintedEmpty && typeof window !== 'undefined') {
          U.hintedEmpty = true
          const emptyText = MF ? 'no worlds on your deed yet - brew yours'
            : HOUSE ? 'the house is empty — no unclaimed worlds right now'
            : PL ? 'no makers yet — sign up and brew the first world'
            : (subKey ? 'an empty shelf — members can pin worlds here' : 'no sub-mains yet — found yours')
          window.dispatchEvent(new CustomEvent('cafe:caption', { detail: { text: emptyText, kind: 'hint' } }))
        }
        if (!MF && !SUB && !PL) U.hintedEmpty = false
      } catch (e2) { /* shelf unreachable — the universe holds its shape */ }
    })()
  }

  // ── gravity with friction: everyone falls toward the middle, packing
  // pressure sorts them — the strongest chant sinks deepest. The sim only
  // runs while perturbed (a birth, a score shift); then friction locks it. ──
  if (U.wake > 0) {
    U.wake -= dt2
    const fr = Math.exp(-3.4 * dt2)
    let maxV = 0   // track the fastest bubble this frame — the field isn't "settled" until everyone has nearly stopped
    // NEW-vs-VOTED banding — MAIN ONLY. MY WORLDS / SUB-MAIN have no votes, so
    // there every world just clusters at center (banded = false). On main the
    // voted worlds pack the middle; new arrivals are held in an outer ring one
    // BUFFER (90) beyond the voted cluster's edge, so the two groups read clearly.
    const banded = !MF && !SUB && !PL   // only MAIN bands (voted center vs new ring); every other view just clusters + settles
    let votedR = 40
    if (banded) for (const n of U.order) { const B = U.bubbles[n]; if (B && B.voted) votedR = Math.max(votedR, Math.hypot(B.x - 256, B.y - 256)) }
    const ringR = Math.max(votedR + 90, 170)
    for (let i = 0; i < U.order.length; i++) {
      const B = U.bubbles[U.order[i]]
      if (!B) continue
      // an ANCHORED bubble came from the saved layout: it holds its exact place
      // as a fixed repulsor, so a newborn (or a late-loading world) settles into
      // the gaps WITHOUT dragging the arrangement everyone already sees.
      if (!B.anchored) {
        const dx = 256 - B.x, dy = 256 - B.y
        const dd = Math.hypot(dx, dy) || 1
        if (banded && !B.voted) {
          // a new arrival springs to the outer ring: pushed OUT if it's inside the
          // buffer, pulled IN if it drifted past — the gap to the voted cluster holds
          const err = ringR - dd
          B.vx += (B.x - 256) / dd * err * 0.6 * dt2
          B.vy += (B.y - 256) / dd * err * 0.6 * dt2
        } else if (dd > 2) {
          const g = 26 * (0.5 + B.score * 2.2)   // participation breaks past friction
          B.vx += dx / dd * g * dt2
          B.vy += dy / dd * g * dt2
        }
      }
      for (let j = i + 1; j < U.order.length; j++) {
        const C = U.bubbles[U.order[j]]
        if (!C) continue
        let sx = B.x - C.x, sy = B.y - C.y
        let sd = Math.hypot(sx, sy)
        if (sd < 0.5) { sx = Math.cos(angOf(U.order[i])); sy = Math.sin(angOf(U.order[i])); sd = 1 }
        // a BIG bubble clears a wider berth so the field makes space around it.
        // Anchored (pinned) big bubbles push neighbours out but never move themselves.
        // ONE collision rule for every bubble — same class, sized by each one's
        // own radius (big ≈ 31u, small ≈ 25u) plus a constant breathing gap.
        const rSum = (B.big ? 31 : 25) + (C.big ? 31 : 25)
        // a big bubble keeps EXTRA distance from the field so its click zone is clear
        const clr = rSum + ((B.big || C.big) ? 58 : 36)
        if (sd < clr) {
          const push = (clr - sd) * 9 * dt2
          if (!B.anchored) { B.vx += sx / sd * push; B.vy += sy / sd * push }
          if (!C.anchored) { C.vx -= sx / sd * push; C.vy -= sy / sd * push }
        }
        // HARD floor: enforce a real GAP (not just no-overlap) as a direct position
        // correction, so even a SETTLED / adopted layout keeps its breathing room —
        // the soft velocity push only spaces things while they're moving. Moves
        // anchored bubbles too; only the PINNED three are immovable.
        const floor = rSum + ((B.big || C.big) ? 40 : 16)
        if (sd < floor) {
          const over = floor - sd, nx = sx / sd, ny = sy / sd
          if (!B.pinned && !C.pinned) { B.x += nx * over * 0.5; B.y += ny * over * 0.5; C.x -= nx * over * 0.5; C.y -= ny * over * 0.5 }
          else if (!B.pinned) { B.x += nx * over; B.y += ny * over }
          else if (!C.pinned) { C.x -= nx * over; C.y -= ny * over }
        }
      }
      // the CROWN is a physical object: an invisible collider above the champion's
      // brow — nothing may drift over it. (Champion sits pinned at 256,210; the
      // crown rides ~42u above with an ~18u radius.)
      if (!MF && !SUB && !PL && !B.pinned) {   // main commons only — that's where the champion reigns
        const kx = B.x - 256, ky = B.y - (210 - 42)
        const kr = 18 + (B.big ? 31 : 25)
        const kd = Math.hypot(kx, ky)
        if (kd < kr && kd > 0.01) { B.x += kx / kd * (kr - kd); B.y += ky / kd * (kr - kd) }
      }
      if (!B.anchored) {
        B.vx *= fr; B.vy *= fr
        B.x += B.vx * dt2; B.y += B.vy * dt2
        const v = Math.abs(B.vx) + Math.abs(B.vy)
        if (v > maxV) maxV = v
      }
    }
    // don't lock mid-flight: if anything is still moving, keep the sim awake so
    // the field reaches rest (a big crowd like THE HOUSE needs time to pack in).
    // Cap the reprieve so a pathological jitter can't run forever.
    if (maxV > 3 && U.wake <= 0 && (U.settleGuard = (U.settleGuard || 0) + dt2) < 12) U.wake = 0.2
    if (U.wake <= 0) {
      U.settleGuard = 0   // friction locks them in place — and the whole field is
      // now the saved layout, so everything anchors: a later newborn moves alone.
      for (const n of U.order) { const B = U.bubbles[n]; if (B) { B.vx = 0; B.vy = 0; B.anchored = 1 } }
      // the settled arrangement becomes everyone's: publish it to THIS mode's
      // layout slot so every player (and every reload) adopts it at rest. MY
      // WORLDS and SUB-MAIN each persist too now, so they stop flying in.
      if (U.order.length > 0) {
        const at = Date.now()
        U.sharedAt = at
        const out = {}
        for (const n of Object.keys(U.bubbles)) {
          const B = U.bubbles[n]
          if (B) out[n] = { x: Math.round(B.x * 10) / 10, y: Math.round(B.y * 10) / 10, born: B.born }
        }
        fetch('/api/engine/save', { method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ slot: layoutSlot, data: { v: 3, at, bubbles: out } }) }).catch(() => {})
      }
    }
  }

  // ── exploring: drag empty space to pan · Z/X to zoom ──
  const kE = k => { const n = wd['key_' + k + '_n'] || 0; const was = U.kN[k] || 0; U.kN[k] = n; return n > was }
  if (kE('z')) { U.cam.z = Math.min(2.4, U.cam.z * 1.25); U.zoomHold = 0.28 }
  if (kE('x')) { U.cam.z = Math.max(0.35, U.cam.z / 1.25); U.zoomHold = 0.28 }
  U.zoomHold = Math.max(0, (U.zoomHold || 0) - dt2)
  const hasM = wd.mouse_x !== undefined
  const mgx = wd.mouse_x ?? 256, mgy = wd.mouse_y ?? 256
  const down = !!wd.mouse_down
  // cursor in universe coords
  const cux = U.cam.x + (mgx - 256) / U.cam.z
  const cuy = U.cam.y + (mgy - 256) / U.cam.z
  // NEAREST door within reach wins. The old test ("< 30" with a self-cancelling
  // zoom term) let a FARTHER door — whichever came last in draw order — claim the
  // hover whenever two hit-circles overlapped, so the tooltip named/linked the
  // wrong world. Picking the closest makes the name + click-target match the icon
  // the cursor is actually on.
  // BIG bubbles win outright when the cursor is inside their disc — they're the
  // navigation anchors and a tightly-packed neighbour must never steal their click.
  let hovered = -1, best = 1.0
  for (let i = 0; i < U.order.length; i++) {
    const B = U.bubbles[U.order[i]]
    if (!B) continue
    const d = Math.hypot(cux - B.x, cuy - B.y)
    if (B.big && d < 34) { hovered = i; best = -1; break }   // inside a big disc: claim it, stop looking
    const nd = d / (B.big ? 38 : 30)
    if (best >= 0 && nd < best) { best = nd; hovered = i }
  }
  if (down && !U.prevDown) { U.downX = mgx; U.downY = mgy; U.dx = mgx; U.dy = mgy; U.moved = 0; U.drag = hovered < 0 ? 1 : 0 }
  if (down && U.drag) {
    U.cam.x -= (mgx - U.dx) / U.cam.z
    U.cam.y -= (mgy - U.dy) / U.cam.z
    U.moved += Math.abs(mgx - U.dx) + Math.abs(mgy - U.dy)
  }
  // TETHER: the map has an edge. Never let the camera stray past the field into
  // empty void — the pan limit is the OUTERMOST world's distance from center
  // plus a margin, so you can always reach the edge worlds but not drag off into
  // blankness. Adapts to each mode (dense main vs a sparse MY WORLDS) and runs
  // every frame, so zooms and snaps stay inside it too.
  let fieldR = 60
  for (let i = 0; i < U.order.length; i++) {
    const B = U.bubbles[U.order[i]]
    if (B) fieldR = Math.max(fieldR, Math.hypot(B.x - 256, B.y - 256))
  }
  const maxOff = fieldR + 200
  const ox = U.cam.x - 256, oy = U.cam.y - 256
  const od = Math.hypot(ox, oy)
  if (od > maxOff) { U.cam.x = 256 + ox / od * maxOff; U.cam.y = 256 + oy / od * maxOff }
  U.dx = mgx; U.dy = mgy
  if (!down && U.prevDown) {
    if (hovered >= 0 && U.moved < 8 && typeof window !== 'undefined') {
      const B = U.bubbles[U.order[hovered]]
      if (B) {
        // stepping into a WORLD goes quiet (a late portals dispatch would
        // follow the player in) — but entering a sub-main morphs this same
        // scene, so the doors keep speaking
        // sub: and players: are IN-SCENE morphs — the universe keeps speaking;
        // only a real departure (loading another world) goes quiet
        // sub: · players: · house: are IN-SCENE morphs — the universe keeps
        // speaking; only a real departure (loading a world/profile) goes quiet
        const lm = String(B.launch)
        if (lm.slice(0, 4) !== 'sub:' && lm !== 'players:' && lm !== 'house:') U.launched = 1
        window.dispatchEvent(new CustomEvent('cafe:launch', { detail: B.launch }))
      }
    }
    U.drag = 0
  }
  U.prevDown = down
  if (!U.launched && hovered !== U.lastHover && typeof window !== 'undefined') {
    U.lastHover = hovered
    window.dispatchEvent(new CustomEvent('cafe:hover', { detail: hovered >= 0 ? U.order[hovered] : null }))
  }

  // ── tell the shell where the doors are (uv space) — it pins the hover
  // tooltip and live head-counts there. Sent when cam or layout moves, and
  // re-announced every 2s regardless: the shell drops portal events during
  // scene changes, so a one-shot could be lost forever ──
  U.portalT = (U.portalT || 0) - dt2
  if (typeof window !== 'undefined') {
    // live geometry EVERY tick: the shell's thumbnail layer reads this in its
    // own rAF loop so world-face inlays stay welded to the shader's bubbles
    // through pans and zooms (events are too slow — they ride React state)
    window.__cafeBubbles = U.launched ? [] : U.order.map(n => {
      const B = U.bubbles[n]
      return B && { name: n, x: (B.x - U.cam.x) * U.cam.z / 256, y: (B.y - U.cam.y) * U.cam.z / 256, r: 0.098 * U.cam.z * (B.big ? 1.25 : 1) }
    }).filter(Boolean)
    // DOM chrome (count chips) can't share the canvas's frame, so it visibly
    // lags the shader during motion. Flag when the camera is moving; the shell
    // hides the chips until it settles, where their placement is pixel-exact.
    window.__cafeCamMoving = (U.wake > 0 || (down && U.drag) || U.zoomHold > 0) ? 1 : 0
  }
  if (!U.launched && typeof window !== 'undefined') {
    let sig = ((U.cam.x * 10) | 0) + '|' + ((U.cam.y * 10) | 0) + '|' + ((U.cam.z * 100) | 0)
    for (const n of U.order) { const B = U.bubbles[n]; if (B) sig += '|' + n + ':' + ((B.x * 10) | 0) + ',' + ((B.y * 10) | 0) }
    if (sig !== U.portalSig || U.portalT <= 0) {
      U.portalSig = sig
      U.portalT = 2
      window.dispatchEvent(new CustomEvent('cafe:portals', {
        detail: U.order.map(n => {
          const B = U.bubbles[n]
          return B && { name: n, launch: B.launch, x: (B.x - U.cam.x) * U.cam.z / 256, y: (B.y - U.cam.y) * U.cam.z / 256, r: 0.098 * U.cam.z * (B.big ? 1.25 : 1) }
        }).filter(Boolean),
      }))
    }
  }

  // the group layer speaks for itself when empty — with or without shell UI
  if (SUB) {
    wd.hud = U.order.length ? [] : [{
      id: 'sm_empty', type: 'text', x: '22%', y: '46%',
      text: subKey ? 'an empty shelf — JOIN, then + PIN A WORLD (top center)'
                   : 'no sub-mains yet — ⌂ FOUND YOURS (top center) starts the first',
      color: '#c9b370', fontSize: '14px',
    }]
  }

  // ── publish: cam, count, cursor(uv), then (x, y, style+hue, headCount) per bubble ──
  // stride 4 now — the 4th value is the live head-count, drawn IN the bubble by
  // the shader (the shell fills window.__cafeCounts from /api/presence)
  const heads = (typeof window !== 'undefined' && window.__cafeCounts) || {}
  const u = [U.cam.x, U.cam.y, U.cam.z, U.order.length, (mgx - 256) / 256, (mgy - 256) / 256]
  for (const n of U.order) {
    const B = U.bubbles[n]
    // st>=9 → the world's own visual, rendered into atlas slot (st-9). else the
    // house mini (0-7) or living emblem (8), tinted by the world's hue.
    const styleInt = (!B.iconLoading && B.iconSlot != null && B.iconSlot >= 0) ? (9 + B.iconSlot) : (B.iconLoading ? 99 : B.style)
    const frac = (B.iconSlot != null && B.iconSlot >= 0) ? 0 : Math.min(0.999, B.hue != null ? B.hue : 0)
    const band = B.cat ? B.cat * 400 : (B.big ? 400 : 0)   // 800 sub-mains · 1200 player-worlds · 400 champion-big · 0 normal
    u.push(B.x, B.y, band + (B.crown ? 200 : 0) + styleInt + frac, Math.min(99, heads[n] || 0))
  }
  // the local player's BREWED icon, packed at the tail (fx, hue, size) — read by
  // the shader at 6 + bubbleCount*4, so it never collides with the bubble stride
  const ic = (typeof window !== 'undefined' && window.__cafeIcon) || {}
  // BREWED GLYPH: when the engine has swapped the player's own WGSL into the
  // shader's mod_playerglyph container, fx packs as -1 — the shader draws the
  // glyph in the preset's seat and the preset stands down.
  // no brewed fx at all (icon state not landed yet) = 5, the default cursor
  u.push(wd.__glyphOn === 1 ? -1 : (typeof ic.fx === 'number' ? ic.fx | 0 : 5), typeof ic.hue === 'number' ? ic.hue : 0.55, typeof ic.size === 'number' ? ic.size : 1.0)
  // the dancing shader effect IS the other player here — suppress the DOM cursor
  // pip that would otherwise draw a dot on top of it
  wd.noPresenceCursors = true
  // other players — positions are already smoothly interpolated upstream (entity
  // interpolation in the engine's presence loop), so just pack them. Screen coords
  // (256 = center). Capped so we never overrun the 96-float buffer.
  const others = Array.isArray(wd.presence) ? wd.presence : []
  const cap = Math.max(0, Math.min(others.length, 12, Math.floor((256 - u.length - 1) / 4)))
  u.push(cap)
  for (let k = 0; k < cap; k++) {
    const o = others[k] || {}
    // stride 4: x, y, hue, glyph seat (mod_pg0-2 in the shader; -1 = comet)
    const sl = Number.isFinite(o.slot) ? o.slot : -1
    u.push((Number(o.x) - 256) / 256, (Number(o.y) - 256) / 256, ((Number(o.hue) || 0) % 360) / 360, sl)
  }
  wd.gpuUniforms = u
} catch (e) { /* keep the door open */ }

visualTypes.wgsl:
fn cf_stars(p: vec2f, t: f32) -> vec3f {
  var c = vec3f(0.008, 0.007, 0.016);
  c += vec3f(0.05, 0.025, 0.09) * smoothstep(0.4, 0.9, fbm(p * 1.5 + vec2f(t * 0.004, 0.0), 4));
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let sp = p * (16.0 + fl * 26.0) + fl * 31.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let fp = fract(sp) - 0.5;
    let tw = 0.5 + 0.5 * sin(t * (0.5 + h * 1.4) + h * 40.0);
    c += vec3f(0.8, 0.75, 0.95) * step(0.985, h) * smoothstep(0.24, 0.03, length(fp)) * tw * (1.1 - fl * 0.4);
  }
  return c;
}

// bit (c,r) of the SYMMETRIC pixel-art arrow. Columns are centered (c=0 is the
// middle column), so the shape is mirror-symmetric: bit(c,r) == bit(-c,r). Rows
// run downward from the tip. It's a triangular head (rows 0-5) over a straight
// stem (rows 6-12); hw[r] is each row's half-width in pixels.
fn cf_curbit(c: i32, r: i32) -> f32 {
  if (r < 0 || r > 12) { return 0.0; }
  var hw = array<i32, 13>(0, 1, 2, 3, 4, 5, 1, 1, 1, 1, 1, 1, 1);
  if (abs(c) <= hw[r]) { return 1.0; }
  return 0.0;
}

// DEFAULT CURSOR (fx 5) — the un-brewed look: a crisp 8-BIT arrow, rendered
// nearest-neighbor from a bitmap so it reads as intentional pixel art (fits the
// retro cafe). SYMMETRIC: points straight up, mirror-symmetric about its
// vertical axis. White fill, a 1-pixel black outline. The TIP is the top-center
// pixel at the local origin = the real selection point. No strobe, no wobble.
// Returns (rgb, coverage); the caller mixes it over the scene. Screen +y is down.
fn cf_defcursor(local0: vec2f, phase: f32) -> vec4f {
  let cell = 0.11;                             // size of one art-pixel in local units
  let c = i32(floor(local0.x / cell + 0.5));   // centered columns (c=0 straddles x=0)
  let r = i32(floor(local0.y / cell));         // rows down from the tip
  let solid = cf_curbit(c, r);
  // outline = an empty cell touching the silhouette (8-neighbourhood)
  var nb = max(max(cf_curbit(c - 1, r), cf_curbit(c + 1, r)), max(cf_curbit(c, r - 1), cf_curbit(c, r + 1)));
  nb = max(nb, max(max(cf_curbit(c - 1, r - 1), cf_curbit(c + 1, r - 1)), max(cf_curbit(c - 1, r + 1), cf_curbit(c + 1, r + 1))));
  let outline = (1.0 - solid) * step(0.5, nb);
  if (solid > 0.5) { return vec4f(0.97, 0.97, 1.0, 1.0); }         // white body
  if (outline > 0.5) { return vec4f(0.05, 0.05, 0.08, 1.0); }      // black outline
  return vec4f(0.0);
}

// A PLAYER — a bounded, directional glow. Meant to become programmable (an
// effect id + params + facing, brewed per person); for now a hardcoded Glow with
// a nose + pupil so its direction reads. local: offset from the player center,
// ~1.0 at the edge. dir: unit facing. Returns additive rgb.
fn cf_player(local0: vec2f, dir: vec2f, phase: f32, fx: i32, tint: vec3f) -> vec3f {
  // DANCE — bob, sway, squash-and-stretch on this player's own beat. A groove
  // in place, never a spin. dir is the base facing (the groove leans around it).
  let bob = sin(phase * 3.1) * 0.16;                 // up-down
  let sway = sin(phase * 2.2 + 0.6) * 0.17;          // side-to-side
  let squash = 1.0 + 0.17 * sin(phase * 6.0);        // pulse
  let fdir = normalize(dir + vec2f(0.0, 0.0001));    // guard the zero vector
  let side = vec2f(-fdir.y, fdir.x);
  var local = local0 - fdir * bob - side * sway;     // move the body as it dances
  local = vec2f(local.x * squash, local.y / squash); // squash & stretch
  let d2 = dot(local, local);
  let fwd = max(0.0, dot(local, fdir));              // ahead of center, along the facing
  let body = exp(-d2 * 5.0);                         // round glow body
  let nose = fwd * exp(-d2 * 2.2);                   // stretches the glow toward the facing
  // LOOK — brewed per player. 0 comet · 1 ring · 2 eyes · 3 spark.
  if (fx == 1) {
    let r = abs(sqrt(d2) - 0.5);                     // a dancing ring
    return tint * exp(-r * r * 45.0) * 1.7;
  }
  if (fx == 2) {
    let el = local - side * 0.30 - fdir * 0.10;      // two eyes, looking along the facing
    let er = local + side * 0.30 - fdir * 0.10;
    let eyes = exp(-dot(el, el) * 55.0) + exp(-dot(er, er) * 55.0);
    return tint * body * 1.2 + vec3f(1.0, 0.98, 0.9) * eyes * 0.8;
  }
  if (fx == 3) {
    let ang = atan2(local.y, local.x);               // a five-point spark, spinning on its beat
    let star = pow(max(0.0, cos(ang * 5.0 + phase * 2.0)), 6.0);
    return tint * exp(-d2 * 3.0) * (0.5 + star * 1.4) * 1.5;
  }
  if (fx == 4) {
    // THE WALKING CUP — a cream cup with a handle, striding on stub legs.
    // Drawn solid over the glow layer; tint only warms the steam. All motion
    // rides the same slow dance phase — no strobe, no flash.
    let wt = phase * 0.9;
    let lean = 0.07 * sin(wt);
    var q = local0;
    q = vec2f(q.x * cos(lean) + q.y * sin(lean), -q.x * sin(lean) + q.y * cos(lean));
    q.y = q.y + 0.05 * abs(sin(wt)) - 0.06;
    var cup = vec3f(0.0);
    var cov = 0.0;
    // two stub legs, half a phase apart (screen +y is down)
    for (var li: i32 = 0; li < 2; li++) {
      let lph = wt + f32(li) * 3.14159;
      let hip = vec2f(-0.11 + 0.22 * f32(li), 0.34);
      let foot = vec2f(hip.x + 0.11 * sin(lph), 0.56 - 0.07 * max(0.0, sin(lph + 1.5708)));
      let pa = q - hip; let ba = foot - hip;
      let hseg = clamp(dot(pa, ba) / max(dot(ba, ba), 0.0001), 0.0, 1.0);
      let dleg = length(pa - ba * hseg) - 0.055;
      let mleg = smoothstep(0.02, -0.02, dleg);
      cup = mix(cup, vec3f(0.93, 0.88, 0.80), mleg); cov = max(cov, mleg);
      let dboot = length(q - foot - vec2f(0.02, 0.02)) - 0.07;
      let mboot = smoothstep(0.02, -0.02, dboot);
      cup = mix(cup, vec3f(0.42, 0.27, 0.16), mboot); cov = max(cov, mboot);
    }
    // body — rounded box; handle — a ring on the right
    let bq = abs(q - vec2f(0.0, 0.0)) - vec2f(0.30, 0.32) + vec2f(0.12);
    let dbody = length(max(bq, vec2f(0.0))) + min(max(bq.x, bq.y), 0.0) - 0.12;
    let dring = abs(length(q - vec2f(0.40, 0.02)) - 0.13) - 0.05;
    let dcup = min(dbody, dring);
    let mcup = smoothstep(0.02, -0.02, dcup);
    cup = mix(cup, vec3f(0.95, 0.91, 0.84), mcup); cov = max(cov, mcup);
    // rim band + coffee at the top (up is -y)
    let rq = abs(q - vec2f(0.0, -0.30)) - vec2f(0.295, 0.055);
    let drim = max(rq.x, rq.y);
    let mrim = smoothstep(0.015, -0.015, drim) * mcup;
    cup = mix(cup, vec3f(0.34, 0.20, 0.11), mrim);
    // sleepy face — two happy-closed eyes and a small smile, inked into the cream
    let deL = length((q - vec2f(-0.12, -0.06)) * vec2f(1.0, 1.8)) - 0.045;
    let deR = length((q - vec2f(0.12, -0.06)) * vec2f(1.0, 1.8)) - 0.045;
    let dsm = length((q - vec2f(0.0, 0.10)) * vec2f(1.0, 1.6)) - 0.06;
    let dsm2 = length((q - vec2f(0.0, 0.06)) * vec2f(1.0, 1.6)) - 0.075;
    let face = max(smoothstep(0.012, -0.012, deL), max(smoothstep(0.012, -0.012, deR),
               smoothstep(0.012, -0.012, dsm) * smoothstep(-0.012, 0.012, dsm2)));
    cup = mix(cup, vec3f(0.30, 0.19, 0.12), face * mcup);
    // steam — two faint wisps rising on the slow beat, tinted by the brew
    var steam = vec3f(0.0);
    for (var si: i32 = 0; si < 2; si++) {
      let fsi = f32(si);
      let rise = fract(phase * 0.05 + fsi * 0.5);
      let wp = vec2f((fsi - 0.5) * 0.16 + 0.05 * sin(phase * 0.4 + fsi * 2.0 + rise * 5.0), -0.45 - rise * 0.42);
      let ds = dot(q - wp, q - wp);
      steam += (vec3f(0.75, 0.72, 0.68) + tint * 0.25) * exp(-ds * 70.0) * (1.0 - rise) * rise * 3.2 * 0.35;
    }
    // solid cup over a soft warm halo; additive-safe (bounded, calm)
    let halo = tint * exp(-d2 * 2.4) * 0.22;
    return cup * 1.9 + steam + halo * (1.0 - cov);
  }
  // 0: comet glow (default)
  let g = body * 1.3 + nose * 1.6;
  let eye = local - fdir * 0.30;                     // a pupil pushed forward — a clear aim
  let pupil = exp(-dot(eye, eye) * 55.0) * body;
  return tint * g + vec3f(1.0, 0.98, 0.9) * pupil * 0.8;
}

fn visual_cf_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let mp = vec2f(uni(4), uni(5));     // cursor (uv coords)
  let cam = vec2f(uni(0), uni(1));
  let zm = uni(2);

  // ── the room: stars seen through curved space (your cursor is a lens) ──
  var p = uv;
  let md = uv - mp;
  let mr2 = max(dot(md, md), 0.002);
  p -= md * (0.010 / mr2) * smoothstep(0.9, 0.2, length(md));
  var col = cf_stars(p, t);

  // warm hearth-light from below — this is a cafe, not a void
  col += vec3f(0.10, 0.055, 0.02) * pow(max(0.0, uv.y + 0.2), 2.0) * (0.8 + 0.2 * sin(t * 0.7));

  // ── the bubble universe: live positions, pressure-ranked, explorable ──
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    let stRaw = i32(floor(sv));
    let bigBand = stRaw / 400;          // 0 normal · 1 champion (big + its OWN icon) · 2 sub-mains · 3 player-worlds
    let big = select(0, 1, bigBand > 0);
    let ab = stRaw % 400;
    let st = ab % 200;
    let hue = fract(sv);
    let headCount = i32(uni(9 + i * 4) + 0.5);
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm * select(1.0, 1.25, big > 0);
    let hov = smoothstep(R * 1.9, R * 1.1, length(mp - ctr));
    let rr = R * (1.0 + hov * 0.12);
    if (d < rr) {
      let q = (uv - ctr) / rr;                     // -1..1 inside the disc
      var g = vec3f(0.0);
      if (bigBand == 2) {
        // SUB-MAINS — five gatherings around one hearth, threads of light between
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.015, 0.02, 0.045);
        g += cA * exp(-dot(q, q) * 9.0) * 0.9;
        for (var k = 0; k < 5; k++) {
          let ak = f32(k) * 1.2566 + t * 0.15;
          let dirk = vec2f(cos(ak), sin(ak));
          let tt = clamp(dot(q, dirk), 0.0, 0.52);
          let sd2 = length(q - dirk * tt);
          g += cA * exp(-sd2 * sd2 * 900.0) * 0.3;
          let hk = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.2 + 0.05 + vec3f(0.0, 0.33, 0.67)));
          let nd = length(q - dirk * 0.52);
          g += hk * exp(-nd * nd * 260.0) * 1.5;
          g += hk * exp(-nd * nd * 55.0) * 0.25;
        }
      } else if (bigBand == 3) {
        // PLAYER WORLDS — a hand-made planet, its makers orbiting on a tilted ring
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        let pd = length(q);
        let surf = fbm3(q * 4.0 + vec2f(t * 0.05, 0.0));
        let bands = 0.6 + 0.4 * sin(q.y * 9.0 + surf * 3.0);
        var pc = cA * (0.35 + 0.6 * bands * (0.45 + surf * 0.6));
        pc *= smoothstep(0.47, 0.43, pd);
        pc *= 0.8 + 0.4 * clamp(1.0 - length(q - vec2f(-0.2, -0.2)), 0.0, 1.0);
        g = pc;
        let rq = vec2f(q.x, q.y * 2.6 + q.x * 0.4);
        g += cA * smoothstep(0.05, 0.0, abs(length(rq) - 0.74)) * 0.4;
        for (var k = 0; k < 3; k++) {
          let ak = t * 0.6 + f32(k) * 2.094;
          let op = vec2f(cos(ak) * 0.74, sin(ak) * 0.285 - cos(ak) * 0.11);
          let hk = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.3 + 0.55 + vec3f(0.0, 0.33, 0.67)));
          let od = length(q - op);
          g += hk * exp(-od * od * 300.0) * 1.6;
        }
      } else if (bigBand == 4) {
        // THE HOUSE — a warm little cottage with a lit window (unclaimed worlds)
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.02, 0.02, 0.03);
        // body: a square below, roof: a triangle above
        let body = step(abs(q.x), 0.42) * step(-0.05, q.y) * step(q.y, 0.5);
        let roof = step(abs(q.x) + (q.y + 0.05) * 0.95, 0.5) * step(q.y, -0.05) * step(-0.6, q.y);
        let house = clamp(body + roof, 0.0, 1.0);
        g = mix(g, vec3f(0.55, 0.3, 0.14) * (0.8 + 0.3 * cA), house);
        // the lit window — a warm hearth glow
        let win = step(abs(q.x - 0.0), 0.13) * step(0.08, q.y) * step(q.y, 0.34);
        g += vec3f(1.0, 0.78, 0.35) * win * (0.9 + 0.2 * sin(t * 1.8));
        g += vec3f(1.0, 0.7, 0.3) * exp(-dot(q - vec2f(0.0, 0.2), q - vec2f(0.0, 0.2)) * 8.0) * 0.25;
      } else if (st >= 30 && st <= 34) {
        // a MAKER bubble wearing the player's BREWED avatar (preset fx 0-4)
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * 0.10 + vec3f(0.02);
        g += cf_player(q * 2.4, vec2f(0.0, 1.0), t * 1.4, st - 30, cA * 1.5) * 1.6;
        g += cA * exp(-dot(q, q) * 3.5) * 0.35;   // a soft aura in their hue
      } else if (st == 0) {
        // FABRIC — a lens wandering through stars
        var pp = q * 2.0;
        let lc = vec2f(sin(t * 0.6) * 0.5, cos(t * 0.47) * 0.4);
        let ld = pp - lc;
        pp -= ld * (0.16 / max(dot(ld, ld), 0.02));
        g = cf_stars(pp * 1.6, t) * 2.2;
        g += vec3f(0.5, 0.9, 1.1) * exp(-dot(ld, ld) * 14.0) * 0.4;
      } else if (st == 1) {
        // ORRERY — three worlds around a coal
        g = vec3f(0.02, 0.015, 0.03);
        g += vec3f(3.0, 1.7, 0.5) * exp(-dot(q, q) * 30.0);
        for (var k = 1; k <= 3; k++) {
          let fk = f32(k);
          let a = t * (0.9 - fk * 0.18) + fk * 2.1;
          let pp = q - vec2f(cos(a), sin(a)) * (0.22 + fk * 0.17);
          var pc = vec3f(0.45, 0.5, 0.65);
          if (k == 2) { pc = vec3f(0.2, 0.45, 0.8); }
          if (k == 3) { pc = vec3f(0.8, 0.5, 0.25); }
          g += pc * exp(-dot(pp, pp) * 260.0) * 1.6;
        }
      } else if (st == 2) {
        // GARNET — the crystal
        let qa = rotate(q, t * 0.4);
        let cd = abs(qa.x) * 0.866 + abs(qa.y) * 0.5;
        let inside = smoothstep(0.62, 0.58, max(cd, abs(qa.y)));
        let facet = 0.6 + 0.4 * sin(qa.x * 9.0 + qa.y * 7.0 + t * 0.8);
        g = mix(vec3f(0.02, 0.01, 0.02), vec3f(0.75, 0.18, 0.25) * facet, inside);
        g += vec3f(1.6, 0.9, 0.7) * pow(max(0.0, facet - 0.75) * 4.0, 2.0) * inside;
      } else if (st == 3) {
        // ONE DAY — a sky that keeps its whole day
        let ph = fract(t * 0.05);
        let el = sin(ph * 6.28318) * 0.8;
        let day = smoothstep(-0.2, 0.4, el);
        g = mix(vec3f(0.02, 0.02, 0.06), vec3f(0.25, 0.5, 0.8), day * (0.5 - q.y * 0.5));
        g = mix(g, vec3f(0.9, 0.4, 0.15), smoothstep(0.3, 0.0, abs(el)) * max(0.0, -q.y + 0.2) * 0.9);
        let sun = vec2f(cos(ph * 6.28318 - 1.57) * 0.6, -el * 0.55 + 0.1);
        g += vec3f(3.0, 2.0, 0.9) * exp(-dot(q - sun, q - sun) * 60.0) * max(day, 0.15);
        if (q.y > 0.25) { g = mix(g, g * vec3f(0.5, 0.6, 0.8), 0.6); }   // the sea below
      } else if (st == 4) {
        // SAIL — one boat, one sea
        g = mix(vec3f(0.35, 0.5, 0.65), vec3f(0.05, 0.14, 0.2), smoothstep(-0.1, 0.5, q.y));
        let w = sin(q.x * 9.0 + t * 1.4) * 0.05;
        g = mix(g, vec3f(0.03, 0.10, 0.14), smoothstep(w + 0.02, w - 0.02, -q.y + 0.1) * 0.0 + smoothstep(w - 0.02, w + 0.06, q.y - 0.05));
        let sail = max(max(-(q.x + 0.05) * 3.0, q.y + 0.15), (q.x * 0.9 + q.y * 0.8) - 0.28);
        g = mix(g, vec3f(1.0, 0.96, 0.88), smoothstep(0.02, -0.02, sail));
      } else if (st == 5) {
        // SOLSTICE — a sun you carry over a valley
        g = vec3f(0.03, 0.04, 0.09);
        let sp = vec2f(sin(t * 0.5) * 0.45, -0.3 + cos(t * 0.5) * 0.12);
        g += vec3f(3.2, 2.2, 0.9) * exp(-dot(q - sp, q - sp) * 40.0);
        let hill = q.y - (0.25 + 0.15 * sin(q.x * 3.0 + 1.0));
        let lit = max(0.0, 1.0 - length(q - sp) * 1.4);
        g = mix(g, mix(vec3f(0.03, 0.05, 0.02), vec3f(0.15, 0.3, 0.08), lit), smoothstep(-0.02, 0.02, hill));
      } else if (st == 6) {
        // TIDERUNNER — wind over water
        let band = sin(q.y * 14.0 - t * 1.1 + sin(q.x * 4.0) * 0.7);
        g = mix(vec3f(0.05, 0.13, 0.17), vec3f(0.12, 0.25, 0.3), 0.5 + 0.5 * band);
        g += vec3f(0.8, 0.85, 0.85) * pow(max(0.0, band - 0.8) * 5.0, 2.0) * 0.4;
        let bt = q - vec2f(sin(t * 0.4) * 0.4, 0.0);
        g += vec3f(0.9, 0.85, 0.75) * exp(-dot(bt, bt) * 300.0) * 1.2;
      } else if (st == 7) {
        // SIGNAL — a television waiting for a word
        let sn = hash21(floor(q * 24.0) + floor(t * 9.0));
        g = vec3f(sn * 0.5);
        g += vec3f(0.3, 1.0, 0.45) * exp(-dot(q, q) * 8.0) * (0.28 + 0.14 * sin(t * 2.0));
        g *= 0.82 + 0.18 * sin(q.y * 60.0 - t * 8.0);
      } else if (st == 99) {
        // its shader icon is still rendering — a quiet sweeping spinner, not a
        // default planet, so a loading bubble reads as "on its way"
        let ang = atan2(q.y, -q.x);
        let rd = length(q);
        let ring = smoothstep(0.09, 0.0, abs(rd - 0.5));
        let sweep = fract(ang / 6.2831 + t * 0.7);
        let comet = smoothstep(0.0, 0.55, sweep) * smoothstep(1.0, 0.55, sweep);
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.02, 0.02, 0.03) + cA * ring * (0.12 + comet * 1.3);
      } else if (st >= 9) {
        // a real world — its screenshot, folded into the bubble by the shader.
        // A BIG (champion) bubble insets its icon so it doesn't fill edge-to-edge
        // and read as oversized next to the category glyphs.
        g = cafeIcon(st - 9, q * select(1.0, 1.32, big > 0));
        g *= 0.9 + 0.2 * (1.0 - length(q));   // gentle spherical shading
      } else {
        // a young world — a banded seed-planet in its own hue
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * (0.22 + 0.5 * fbm3(q * 3.0 + vec2f(t * 0.08, f32(i) * 3.7)));
        g += cA * 0.4 * smoothstep(0.6, 1.0, 1.0 - abs(q.y * 2.2 + 0.3 * sin(q.x * 3.0 + t * 0.4)));
        let mn = q - vec2f(cos(t * 0.5 + f32(i) * 1.9), sin(t * 0.5 + f32(i) * 1.9) * 0.6) * 0.78;
        g += vec3f(0.85) * exp(-dot(mn, mn) * 260.0);
        g *= 0.85 + 0.3 * (1.0 - length(q));
      }
      // (the head-count number is gone — presence is the dancing players now)
      // glass edge + hover bloom — the top three wear their OWN rim colors:
      // champion solar gold, SUB-MAINS sky blue, PLAYER WORLDS spring green
      let edge = smoothstep(1.0, 0.86, length(q));
      col = mix(col, g, edge);
      var rim = vec3f(1.2, 0.85, 0.4);
      var rimBase = 0.25;
      if (bigBand == 1) { rim = vec3f(1.5, 1.0, 0.3); rimBase = 0.45; }
      else if (bigBand == 2) { rim = vec3f(0.45, 0.75, 1.55); rimBase = 0.45; }
      else if (bigBand == 3) { rim = vec3f(0.4, 1.45, 0.65); rimBase = 0.45; }
      else if (bigBand == 4) { rim = vec3f(1.4, 0.75, 0.35); rimBase = 0.45; }
      col += rim * exp(-pow((length(q) - 0.97) * 9.0, 2.0)) * (rimBase + hov * 1.3);
    } else {
      // halo when hovered
      col += vec3f(1.0, 0.7, 0.3) * exp(-pow((d - rr) * 22.0, 2.0)) * hov * 0.8;
    }
    // presence players HOVER at the edge — half inside, half out — so they draw
    // in a band that spills BEYOND the disc, not clipped by the d<rr face mask.
    // Additive onto col; the SMALL scale of the cursor's big roaming effect.
    // One player per real occupant (headCount), up to 6.
    if (d < rr * 1.6) {
      let ql = (uv - ctr) / rr;                              // disc-local; >1 outside the bubble
      let nP = min(headCount, 6);
      for (var k = 0; k < nP; k++) {
        let ga = f32(k) * 2.39996 + f32(i) * 1.7;            // static seat around the rim
        let orb = vec2f(cos(ga), sin(ga));
        let plocal = (ql - orb) * 3.2;                       // seat ON the rim (radius 1.0), spilling out
        let hueK = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.16 + vec3f(0.0, 0.33, 0.67)));
        let ph = t * 1.5 + f32(k) * 1.3 + f32(i) * 0.7;      // each dances on its own beat
        col += cf_player(plocal, orb, ph, 0, hueK * 1.6) * 1.8; // hold the seat, dance in place
      }
    }
  }

  // the CROWN, over everything — a small gold crown resting on the champion's
  // brow (no ring, no halo — just the crown)
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    let sr = i32(floor(sv));
    let abc = sr % 400;
    if (abc < 200) { continue; }        // crown flag lives in the 200 band, under the big band
    let bigc = sr / 400;
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let R = 0.098 * zm * select(1.0, 1.25, bigc > 0);
    // SOLAR CROWN — a small sun-forged crown above the brow: molten gold body,
    // breathing corona, rays flaring off the teeth
    let cp = (uv - (ctr + vec2f(0.0, -R * 1.28))) / (R * 0.38);
    if (abs(cp.x) < 2.2 && cp.y > -2.2 && cp.y < 1.4) {
      // three teeth: a triangle wave over the band, tips pointing up (soft edges)
      let teeth = 1.0 - abs(fract(cp.x * 1.5 + 0.5) - 0.5) * 2.0;
      let topY = -0.12 - teeth * 0.88;
      let m = smoothstep(1.04, 0.98, abs(cp.x)) * smoothstep(topY - 0.06, topY + 0.05, cp.y) * smoothstep(0.55, 0.45, cp.y);
      // molten gold: banded shimmer rolling across the metal
      let molten = 0.75 + 0.25 * sin(cp.x * 7.0 - t * 2.6) * sin(cp.y * 5.0 + t * 1.9);
      let gold = mix(vec3f(0.85, 0.55, 0.12), vec3f(1.0, 0.9, 0.5), clamp(0.5 - cp.y * 0.6, 0.0, 1.0)) * molten;
      col = mix(col, gold, m);
      // corona: the whole crown breathes light like a low sun
      let bd = length(vec2f(cp.x * 0.62, cp.y + 0.25));
      col += vec3f(1.0, 0.72, 0.28) * exp(-bd * bd * 2.6) * (0.16 + 0.05 * sin(t * 1.7)) * (1.0 - m);
      // rays flaring off the three tips
      for (var k = -1; k <= 1; k++) {
        let jp = cp - vec2f(f32(k) * 0.667, -1.0);
        let jd = length(jp);
        let ja = atan2(jp.y, jp.x);
        let flare = 0.5 + 0.5 * sin(ja * 6.0 + t * 2.4 + f32(k) * 2.1);
        col += vec3f(1.0, 0.95, 0.72) * exp(-jd * jd * 30.0) * (0.55 + 0.35 * flare);
        col += vec3f(1.0, 0.85, 0.45) * exp(-jd * 6.0) * flare * 0.22;
      }
    }
  }

  // the local player — the "you" roaming the open grid, dancing in place. Its
  // look/hue/size are BREWED: read from the uniform tail (packed after all the
  // bubbles, so bubble offsets never move). fx, hue, size = uni(sb, sb+1, sb+2).
  let sb = 6 + i32(uni(3) + 0.5) * 4;
  // fx -1 = a custom BREWED GLYPH field is riding the cursor instead — the
  // preset dance (and its soft core) stands down. round(), not +0.5: the old
  // truncation folded -1 back to 0 and the comet haunted the glyph.
  let selfFx = i32(round(uni(sb)));
  let selfHue = uni(sb + 1);
  let selfSize = max(uni(sb + 2), 0.25);
  let selfTint = 0.5 + 0.5 * cos(6.2831 * (selfHue + vec3f(0.0, 0.33, 0.67)));
  if (selfFx == 5) {
    // DEFAULT CURSOR — nothing brewed yet: a small stylized pointer whose TIP
    // sits on the real pointer position (local origin), mixed OVER the scene.
    // Brewed looks (presets 0-4, custom glyphs) are untouched.
    let dc = cf_defcursor((uv - mp) * (10.0 / selfSize), t * 1.6);
    col = mix(col, dc.rgb, dc.a);
  } else if (selfFx >= 0) {
    col += cf_player((uv - mp) * (4.5 / selfSize), vec2f(0.0, 1.0), t * 1.6, selfFx, selfTint * 1.3) * 1.1;
    col += selfTint * 0.9 * exp(-dot(uv - mp, uv - mp) * 1400.0) * 0.4;   // a soft core in your hue
  } else {
    // BREWED GLYPH — the player's own WGSL fills the mod_playerglyph container
    // (a no-op until the engine swaps it in). Same seat as the presets, but a
    // tighter cell: a glyph fills its whole cell to |uv|=1, so the preset scale
    // read twice as large as intended. 9.0 ≈ a cursor-sized icon at size 1.
    // The distance guard is the frame budget: only pixels inside the cell pay
    // for the glyph at all — user code can be arbitrarily fancy without taxing
    // the other ~99% of the screen.
    let gd = uv - mp;
    let gcell = selfSize / 9.0;
    if (dot(gd, gd) < gcell * gcell * 1.1) {
      let gl = mod_playerglyph(gd * (9.0 / selfSize), t);
      col += gl.rgb * clamp(gl.a, 0.0, 1.0) * 1.5;
    }
  }

  // the OTHER players — their live cursors, dancing, so you see them move around
  // the cafe. Packed after the self-icon: count at sb+3, then (x, y, hue, seat)
  // each. seat >= 0 means their BREWED GLYPH sits in that mod_pg slot — draw
  // their real icon; seat -1 is the comet everyone starts as.
  let ob = sb + 3;
  let nOthers = i32(uni(ob) + 0.5);
  for (var k = 0; k < nOthers; k++) {
    let opos = vec2f(uni(ob + 1 + k * 4), uni(ob + 2 + k * 4));
    let ohue = uni(ob + 3 + k * 4);
    let oseat = i32(round(uni(ob + 4 + k * 4)));
    let otint = 0.5 + 0.5 * cos(6.2831 * (ohue + vec3f(0.0, 0.33, 0.67)));
    if (oseat >= 0) {
      // their glyph, slightly smaller than your own (13 vs your 9) — same
      // distance guard: only pixels inside their cell run their code
      let od = uv - opos;
      let ocell = 1.0 / 13.0;
      if (dot(od, od) < ocell * ocell * 1.2) {
        var og = vec4f(0.0);
        if (oseat == 0) { og = mod_pg0(od * 13.0, t); }
        else if (oseat == 1) { og = mod_pg1(od * 13.0, t); }
        else { og = mod_pg2(od * 13.0, t); }
        col += og.rgb * clamp(og.a, 0.0, 1.0) * 1.4;
      }
    } else {
      // un-brewed player: the SAME default pixel arrow you wear, tinted by their
      // hue so players still read apart. A touch smaller than your own (12 vs
      // your 10). The white body takes the tint; the dark outline stays dark.
      let dc = cf_defcursor((uv - opos) * 12.0, t * 1.6);
      col = mix(col, dc.rgb * (0.45 + otint), dc.a);
    }
  }

  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(60.0)), 1.0);
}

stepHooks.code:
try {
  const wd = sim.worldData
  if (!wd.__book || wd.__book.v !== 1) wd.__book = { v: 1, laws: {}, order: [] }
  const B = wd.__book
  const pdt = Math.min(dt, 0.05)

  const DESC = {
    attract: 'matter falls toward a point',
    wind: 'a current carries everything',
    vortex: 'space turns around a center',
    predator: 'something hunts the motes',
  }
  const rebuildInstructions = () => {
    let s = 'No controls — this world is watched, not driven.\n'
    s += 'Its laws arrive over HTTP as grafted rule fragments; forces superpose.\n\nLAWS IN FORCE:\n'
    s += B.order.length
      ? B.order.map(n => '\u00b7 ' + n + ' \u2014 ' + ((B.laws[n] && (B.laws[n].desc || DESC[B.laws[n].type])) || '')).join('\n')
      : '\u00b7 none \u2014 matter drifts free'
    wd.instructions = s
  }


  // ── THE BRANCH'S THESIS: law arrives on its own. MAIN waits for HTTP;
  // here the world demonstrates itself — laws accrete, hold, and repeal on a
  // slow clock, forever. Grafts over HTTP still land; they share the book. ──
  if (!wd.__demo) wd.__demo = { t: 0, stage: 0 }
  const D = wd.__demo
  D.t += pdt
  const SCRIPT = [
    [8,  { __graft: { name: 'gravity-well', law: { type: 'attract', x: 180, y: 220, g: 60, desc: 'matter falls toward the well' } } }, 'a law arrives: GRAVITY \u2014 matter falls toward the well'],
    [26, { __graft: { name: 'east-wind', law: { type: 'wind', ax: 34, ay: -6, desc: 'a current carries everything' } } }, 'a law arrives: WIND \u2014 a current carries everything'],
    [44, { __graft: { name: 'the-gyre', law: { type: 'vortex', x: 330, y: 300, w: 70, desc: 'space turns around a center' } } }, 'a law arrives: VORTEX \u2014 space turns around a center'],
    [62, { __graft: { name: 'the-hunter', law: { type: 'predator', speed: 70, desc: 'something hunts the motes' } } }, 'a law arrives: PREDATOR \u2014 something hunts the motes'],
    [82, { __ungraft: { name: 'gravity-well' } }, 'a law is repealed: GRAVITY'],
    [94, { __ungraft: { name: 'east-wind' } }, 'a law is repealed: WIND'],
    [106, { __ungraft: { name: 'the-gyre' } }, 'a law is repealed: VORTEX'],
    [118, { __ungraft: { name: 'the-hunter' } }, 'a law is repealed: PREDATOR \u2014 the matter drifts free'],
  ]
  if (D.stage < SCRIPT.length && D.t >= SCRIPT[D.stage][0]) {
    Object.assign(wd, SCRIPT[D.stage][1])
    if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent('cafe:caption', { detail: { text: SCRIPT[D.stage][2], kind: 'tuned' } }))
    D.stage += 1
  }
  if (D.stage >= SCRIPT.length && D.t >= 132) { D.t = 0; D.stage = 0 }   // rest, then the cycle begins again

  // ── graft / ungraft: the world accepts new law while running ──
  const g = wd.__graft
  if (g && g.name && g.law) {
    B.laws[g.name] = g.law
    if (!B.order.includes(g.name)) B.order.push(g.name)
    delete wd.__graft
    rebuildInstructions()
    wd.__play_sound = [
      { frequency: 520, duration: 0.10, volume: 0.3, type: 'sine' },
      { frequency: 780, duration: 0.16, volume: 0.25, type: 'sine' },
    ]
  }
  const ug = wd.__ungraft
  if (ug && ug.name) {
    delete B.laws[ug.name]
    B.order = B.order.filter(n => n !== ug.name)
    delete wd.__ungraft
    rebuildInstructions()
    wd.__play_sound = { frequency: 240, duration: 0.2, volume: 0.3, type: 'triangle' }
  }
  if (wd.instructions === undefined) rebuildInstructions()

  // ── the matter: motes, moved by the SUM of the laws ──
  const laws = B.order.map(n => B.laws[n]).filter(Boolean)
  let pred = null
  for (const f of sim.fields.values()) {
    const P = f.properties
    const isMote = P && (P.get ? P.get('mote') : P.mote)
    if (!isMote) { f.transform.x = 256; f.transform.y = 256; f.transform.vx = 0; f.transform.vy = 0; continue }
    const T = f.transform
    let fx = (Math.random() - 0.5) * 14, fy = (Math.random() - 0.5) * 14   // base drift
    for (const L of laws) {
      if (L.type === 'attract') {
        const dx = L.x - T.x, dy = L.y - T.y
        const d = Math.hypot(dx, dy) || 1
        fx += dx / d * (L.g || 50); fy += dy / d * (L.g || 50)
      } else if (L.type === 'wind') {
        fx += L.ax || 0; fy += L.ay || 0
      } else if (L.type === 'vortex') {
        const dx = L.x - T.x, dy = L.y - T.y
        const d = Math.hypot(dx, dy) || 1
        fx += (-dy / d) * (L.w || 60) + dx / d * 8
        fy += (dx / d) * (L.w || 60) + dy / d * 8
      }
    }
    T.vx = (T.vx + fx * pdt) * (1 - 0.8 * pdt)
    T.vy = (T.vy + fy * pdt) * (1 - 0.8 * pdt)
    T.x += T.vx * pdt; T.y += T.vy * pdt
    if (T.x < 12) { T.x = 12; T.vx = Math.abs(T.vx) }
    if (T.x > 500) { T.x = 500; T.vx = -Math.abs(T.vx) }
    if (T.y < 12) { T.y = 12; T.vy = Math.abs(T.vy) }
    if (T.y > 500) { T.y = 500; T.vy = -Math.abs(T.vy) }
  }

  // ── the predator law: a hunter that exists only while its law does ──
  const predLaw = laws.find(L => L.type === 'predator')
  if (predLaw) {
    if (!wd.__pred) wd.__pred = { x: 40, y: 40 }
    const Pr = wd.__pred
    let best = null, bd = 1e9
    for (const f of sim.fields.values()) {
      const P = f.properties
      if (!(P && (P.get ? P.get('mote') : P.mote))) continue
      const d = (f.transform.x - Pr.x) ** 2 + (f.transform.y - Pr.y) ** 2
      if (d < bd) { bd = d; best = f }
    }
    if (best) {
      const dx = best.transform.x - Pr.x, dy = best.transform.y - Pr.y
      const d = Math.sqrt(bd) || 1
      Pr.x += dx / d * (predLaw.speed || 70) * pdt
      Pr.y += dy / d * (predLaw.speed || 70) * pdt
      if (d < 10) {   // caught: the mote is reborn at the rim
        best.transform.x = Math.random() < 0.5 ? 16 : 496
        best.transform.y = 16 + Math.random() * 480
        wd.__play_sound = { frequency: 140, duration: 0.08, volume: 0.2, type: 'square' }
      }
    }
  } else { delete wd.__pred }

  // publish law state for the pool to draw
  const A = laws.find(L => L.type === 'attract')
  const W = laws.find(L => L.type === 'wind')
  const V = laws.find(L => L.type === 'vortex')
  wd.gpuUniforms = [
    A ? 1 : 0, A ? A.x : 0, A ? A.y : 0, 0,
    W ? 1 : 0, W ? W.ax : 0, W ? W.ay : 0,
    predLaw ? 1 : 0, wd.__pred ? wd.__pred.x : 0, wd.__pred ? wd.__pred.y : 0,
    V ? 1 : 0, V ? V.x : 0, V ? V.y : 0,
  ]
  wd.hud = [
    { id: 'pf_t', type: 'text', x: '14px', y: '12px', text: 'PROOF \u2014 laws in force: ' + (B.order.join(', ') || 'none'), color: '#c9b370', fontSize: '13px' },
  ]
} catch (e) { /* keep the sim alive */ }

visualTypes.wgsl:
fn cf_stars(p: vec2f, t: f32) -> vec3f {
  var c = vec3f(0.008, 0.007, 0.016);
  c += vec3f(0.05, 0.025, 0.09) * smoothstep(0.4, 0.9, fbm(p * 1.5 + vec2f(t * 0.004, 0.0), 4));
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let sp = p * (16.0 + fl * 26.0) + fl * 31.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let fp = fract(sp) - 0.5;
    let tw = 0.5 + 0.5 * sin(t * (0.5 + h * 1.4) + h * 40.0);
    c += vec3f(0.8, 0.75, 0.95) * step(0.985, h) * smoothstep(0.24, 0.03, length(fp)) * tw * (1.1 - fl * 0.4);
  }
  return c;
}

fn visual_cf_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let mp = vec2f(uni(4), uni(5));     // cursor (uv coords)
  let cam = vec2f(uni(0), uni(1));
  let zm = uni(2);

  // ── the room: stars seen through curved space (your cursor is a lens) ──
  var p = uv;
  let md = uv - mp;
  let mr2 = max(dot(md, md), 0.002);
  p -= md * (0.010 / mr2) * smoothstep(0.9, 0.2, length(md));
  var col = cf_stars(p, t);

  // warm hearth-light from below — this is a cafe, not a void
  col += vec3f(0.10, 0.055, 0.02) * pow(max(0.0, uv.y + 0.2), 2.0) * (0.8 + 0.2 * sin(t * 0.7));

  // ── the bubble universe: live positions, pressure-ranked, explorable ──
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 3);
    let st = i32(floor(sv)) % 16;
    let hue = fract(sv);
    let ctr = vec2f((uni(6 + i * 3) - cam.x) * zm / 256.0, (uni(7 + i * 3) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm;
    let hov = smoothstep(R * 1.9, R * 1.1, length(mp - ctr));
    let rr = R * (1.0 + hov * 0.12);
    if (d < rr) {
      let q = (uv - ctr) / rr;                     // -1..1 inside the disc
      var g = vec3f(0.0);
      if (st == 0) {
        // FABRIC — a lens wandering through stars
        var pp = q * 2.0;
        let lc = vec2f(sin(t * 0.6) * 0.5, cos(t * 0.47) * 0.4);
        let ld = pp - lc;
        pp -= ld * (0.16 / max(dot(ld, ld), 0.02));
        g = cf_stars(pp * 1.6, t) * 2.2;
        g += vec3f(0.5, 0.9, 1.1) * exp(-dot(ld, ld) * 14.0) * 0.4;
      } else if (st == 1) {
        // ORRERY — three worlds around a coal
        g = vec3f(0.02, 0.015, 0.03);
        g += vec3f(3.0, 1.7, 0.5) * exp(-dot(q, q) * 30.0);
        for (var k = 1; k <= 3; k++) {
          let fk = f32(k);
          let a = t * (0.9 - fk * 0.18) + fk * 2.1;
          let pp = q - vec2f(cos(a), sin(a)) * (0.22 + fk * 0.17);
          var pc = vec3f(0.45, 0.5, 0.65);
          if (k == 2) { pc = vec3f(0.2, 0.45, 0.8); }
          if (k == 3) { pc = vec3f(0.8, 0.5, 0.25); }
          g += pc * exp(-dot(pp, pp) * 260.0) * 1.6;
        }
      } else if (st == 2) {
        // GARNET — the crystal
        let qa = rotate(q, t * 0.4);
        let cd = abs(qa.x) * 0.866 + abs(qa.y) * 0.5;
        let inside = smoothstep(0.62, 0.58, max(cd, abs(qa.y)));
        let facet = 0.6 + 0.4 * sin(qa.x * 9.0 + qa.y * 7.0 + t * 0.8);
        g = mix(vec3f(0.02, 0.01, 0.02), vec3f(0.75, 0.18, 0.25) * facet, inside);
        g += vec3f(1.6, 0.9, 0.7) * pow(max(0.0, facet - 0.75) * 4.0, 2.0) * inside;
      } else if (st == 3) {
        // ONE DAY — a sky that keeps its whole day
        let ph = fract(t * 0.05);
        let el = sin(ph * 6.28318) * 0.8;
        let day = smoothstep(-0.2, 0.4, el);
        g = mix(vec3f(0.02, 0.02, 0.06), vec3f(0.25, 0.5, 0.8), day * (0.5 - q.y * 0.5));
        g = mix(g, vec3f(0.9, 0.4, 0.15), smoothstep(0.3, 0.0, abs(el)) * max(0.0, -q.y + 0.2) * 0.9);
        let sun = vec2f(cos(ph * 6.28318 - 1.57) * 0.6, -el * 0.55 + 0.1);
        g += vec3f(3.0, 2.0, 0.9) * exp(-dot(q - sun, q - sun) * 60.0) * max(day, 0.15);
        if (q.y > 0.25) { g = mix(g, g * vec3f(0.5, 0.6, 0.8), 0.6); }   // the sea below
      } else if (st == 4) {
        // SAIL — one boat, one sea
        g = mix(vec3f(0.35, 0.5, 0.65), vec3f(0.05, 0.14, 0.2), smoothstep(-0.1, 0.5, q.y));
        let w = sin(q.x * 9.0 + t * 1.4) * 0.05;
        g = mix(g, vec3f(0.03, 0.10, 0.14), smoothstep(w + 0.02, w - 0.02, -q.y + 0.1) * 0.0 + smoothstep(w - 0.02, w + 0.06, q.y - 0.05));
        let sail = max(max(-(q.x + 0.05) * 3.0, q.y + 0.15), (q.x * 0.9 + q.y * 0.8) - 0.28);
        g = mix(g, vec3f(1.0, 0.96, 0.88), smoothstep(0.02, -0.02, sail));
      } else if (st == 5) {
        // SOLSTICE — a sun you carry over a valley
        g = vec3f(0.03, 0.04, 0.09);
        let sp = vec2f(sin(t * 0.5) * 0.45, -0.3 + cos(t * 0.5) * 0.12);
        g += vec3f(3.2, 2.2, 0.9) * exp(-dot(q - sp, q - sp) * 40.0);
        let hill = q.y - (0.25 + 0.15 * sin(q.x * 3.0 + 1.0));
        let lit = max(0.0, 1.0 - length(q - sp) * 1.4);
        g = mix(g, mix(vec3f(0.03, 0.05, 0.02), vec3f(0.15, 0.3, 0.08), lit), smoothstep(-0.02, 0.02, hill));
      } else if (st == 6) {
        // TIDERUNNER — wind over water
        let band = sin(q.y * 14.0 - t * 1.1 + sin(q.x * 4.0) * 0.7);
        g = mix(vec3f(0.05, 0.13, 0.17), vec3f(0.12, 0.25, 0.3), 0.5 + 0.5 * band);
        g += vec3f(0.8, 0.85, 0.85) * pow(max(0.0, band - 0.8) * 5.0, 2.0) * 0.4;
        let bt = q - vec2f(sin(t * 0.4) * 0.4, 0.0);
        g += vec3f(0.9, 0.85, 0.75) * exp(-dot(bt, bt) * 300.0) * 1.2;
      } else if (st == 7) {
        // SIGNAL — a television waiting for a word
        let sn = hash21(floor(q * 24.0) + floor(t * 9.0));
        g = vec3f(sn * 0.5);
        g += vec3f(0.3, 1.0, 0.45) * exp(-dot(q, q) * 8.0) * (0.28 + 0.14 * sin(t * 2.0));
        g *= 0.82 + 0.18 * sin(q.y * 60.0 - t * 8.0);
      } else {
        // a young world — a banded seed-planet in its own hue
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * (0.22 + 0.5 * fbm3(q * 3.0 + vec2f(t * 0.08, f32(i) * 3.7)));
        g += cA * 0.4 * smoothstep(0.6, 1.0, 1.0 - abs(q.y * 2.2 + 0.3 * sin(q.x * 3.0 + t * 0.4)));
        let mn = q - vec2f(cos(t * 0.5 + f32(i) * 1.9), sin(t * 0.5 + f32(i) * 1.9) * 0.6) * 0.78;
        g += vec3f(0.85) * exp(-dot(mn, mn) * 260.0);
        g *= 0.85 + 0.3 * (1.0 - length(q));
      }
      // glass edge + hover bloom
      let edge = smoothstep(1.0, 0.86, length(q));
      col = mix(col, g, edge);
      col += vec3f(1.2, 0.85, 0.4) * exp(-pow((length(q) - 0.97) * 9.0, 2.0)) * (0.25 + hov * 1.3);
    } else {
      // halo when hovered
      col += vec3f(1.0, 0.7, 0.3) * exp(-pow((d - rr) * 22.0, 2.0)) * hov * 0.8;
    }
  }

  // the crown, over everything — the champion's ring outshines its neighbors
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 3);
    if (i32(floor(sv)) < 16) { continue; }
    let ctr = vec2f((uni(6 + i * 3) - cam.x) * zm / 256.0, (uni(7 + i * 3) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm;
    let ringR = R * 1.24 + sin(t * 2.2) * 0.006;
    col += vec3f(1.0, 0.82, 0.32) * smoothstep(0.012, 0.002, abs(d - ringR)) * 1.3;
    col += vec3f(1.0, 0.7, 0.25) * exp(-max(d - R, 0.0) * 22.0) * 0.4;
  }

  // the cursor itself — a soft ember
  col += vec3f(1.4, 0.9, 0.4) * exp(-dot(uv - mp, uv - mp) * 900.0) * 0.8;

  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(60.0)), 1.0);
}

fn fb_bg(p: vec2f, t: f32) -> vec3f {
  // the unlensed sky: nebula, dust, two starfield depths
  var c = vec3f(0.010, 0.008, 0.022);

  // nebula — indigo body, rose folds, gold filaments
  let q = p * 1.6 + vec2f(0.3, -0.2);
  let n1 = fbm(q + vec2f(t * 0.004, 0.0), 5);
  let n2 = fbm(q * 2.3 + vec2f(7.0, 3.0) - vec2f(0.0, t * 0.003), 4);
  c += vec3f(0.10, 0.05, 0.28) * smoothstep(0.35, 0.85, n1) * 1.1;
  c += vec3f(0.30, 0.08, 0.22) * smoothstep(0.55, 0.9, n1 * 0.6 + n2 * 0.6) * 0.9;
  c += vec3f(0.55, 0.38, 0.12) * pow(smoothstep(0.62, 0.95, n2), 2.0) * 0.8;
  // dark dust lane
  c *= 1.0 - 0.55 * smoothstep(0.55, 0.8, fbm(q * 1.3 + vec2f(21.0, 13.0), 4));

  // stars — two depths, hue-varied, twinkling
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let sp = p * (14.0 + fl * 26.0) + fl * 31.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let h2 = hash21(cell + 91.0);
    let fp = fract(sp) - 0.5 + (vec2f(h, h2) - 0.5) * 0.6;
    let star = step(0.982 - fl * 0.006, h) * smoothstep(0.24, 0.02, length(fp));
    let tw = 0.55 + 0.45 * sin(t * (0.6 + h * 1.6) + h * 40.0);
    let hue = mix(vec3f(0.75, 0.82, 1.05), vec3f(1.05, 0.85, 0.6), h2);
    c += hue * star * tw * (1.4 - fl * 0.5);
  }
  return c;
}

fn fb_mass(i: i32) -> vec3f { return vec3f(uni(9 + i * 3), uni(10 + i * 3), uni(11 + i * 3)); }

// total lens deflection: sample the sky at beta = theta - sum(m_i * d_i / r_i^2)
fn fb_beta(uv: vec2f, mScale: f32, t: f32) -> vec2f {
  var beta = uv;
  let nA = i32(uni(0));
  for (var i = 0; i < 9; i++) {
    if (i >= nA) { break; }
    let m = fb_mass(i);
    let d = uv - m.xy;
    let r2 = max(dot(d, d), 0.0004);
    beta -= d * (m.z * mScale) / r2;
  }
  // the cursor lens
  let md = uv - vec2f(uni(1), uni(2));
  let mr2 = max(dot(md, md), 0.0004);
  beta -= md * (uni(3) * mScale) / mr2;
  // gravitational ripple from the last anchor drop
  let rt = uni(6);
  if (rt < 4.0) {
    let ro = uv - vec2f(uni(7), uni(8));
    let rr = length(ro);
    let wave = sin((rr - rt * 0.9) * 26.0) * exp(-pow((rr - rt * 0.9) * 3.2, 2.0)) * exp(-rt * 1.1);
    beta += (ro / max(rr, 0.01)) * wave * 0.02;
  }
  return beta;
}

fn visual_fb_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let chroma = uni(5) * 0.22;

  // lensed sky, with dispersion: each color feels gravity slightly differently
  let bR = fb_beta(uv, 1.0 - chroma, t);
  let bG = fb_beta(uv, 1.0, t);
  let bB = fb_beta(uv, 1.0 + chroma, t);
  var col = vec3f(fb_bg(bR, t).r, fb_bg(bG, t).g, fb_bg(bB, t).b);

  // spacetime grid, drawn in SOURCE coordinates — lines funnel into the wells
  let g01 = uni(4);
  if (g01 > 0.01) {
    let gc = bG * 7.0;
    let gx = smoothstep(0.06, 0.0, abs(fract(gc.x) - 0.5) - 0.44);
    let gy = smoothstep(0.06, 0.0, abs(fract(gc.y) - 0.5) - 0.44);
    col += vec3f(0.10, 0.22, 0.28) * max(gx, gy) * g01 * 0.8;
  }

  // the masses themselves: dark cores wearing hot photon rings
  let nA = i32(uni(0));
  for (var i = 0; i < 10; i++) {
    var m: vec3f;
    var held = false;
    if (i < nA) { m = fb_mass(i); }
    else if (i == nA) { m = vec3f(uni(1), uni(2), uni(3)); held = true; }
    else { break; }
    if (m.z < 0.0005) { continue; }
    let r = length(uv - m.xy);
    let rs = sqrt(m.z) * 0.55;                 // event-horizon scale from the Einstein radius
    col = mix(col, vec3f(0.0), smoothstep(rs, rs * 0.55, r));
    var ringCol = vec3f(3.2, 2.1, 1.0);
    if (held) { ringCol = vec3f(1.2, 2.6, 3.2); }
    let flick = 0.85 + 0.15 * sin(t * 5.0 + f32(i) * 9.0 + r * 40.0);
    col += ringCol * exp(-pow((r - rs * 1.18) * (34.0 / max(rs, 0.02)) * rs, 2.0) * 3.0) * flick;
    // faint accretion shimmer just outside the ring
    let sh = exp(-pow((r - rs * 1.7) * 8.0 / max(rs, 0.05), 2.0));
    col += vec3f(0.5, 0.3, 0.15) * sh * (0.4 + 0.3 * sin(t * 1.3 + atan2(uv.y - m.y, uv.x - m.x + 1e-5) * 3.0 - t));
  }

  // NaN scrub — nothing poisoned may reach the bloom
  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01, 0.01, 0.02); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(60.0)), 1.0);
}

fn tr_h(pw: vec2f, t: f32, wdir: vec2f) -> f32 {
  let d2 = normalize(wdir + vec2f(-wdir.y, wdir.x) * 0.55);
  var h = sin(dot(pw, wdir) * 0.09 - t * 1.05) * 0.55;
  h += sin(dot(pw, d2) * 0.157 - t * 1.45 + 1.7) * 0.28;
  h += (vnoise(pw * 0.045 + vec2f(t * 0.05, t * 0.03)) - 0.5) * 0.9;
  h += (vnoise(pw * 0.11 - vec2f(t * 0.07, t * 0.02)) - 0.5) * 0.45;
  return h;
}
fn visual_tr_sea(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [windX, windY, wind01, 0]
  var wdir = vec2f(p.x, p.y);
  if (length(wdir) < 0.1) { wdir = vec2f(1.0, 0.0); }
  wdir = normalize(wdir);
  let w01 = clamp(p.z, 0.0, 1.0);
  let pw = uv * 256.0;
  let t = time;

  let h0 = tr_h(pw, t, wdir);
  let hx = tr_h(pw + vec2f(1.6, 0.0), t, wdir);
  let hy = tr_h(pw + vec2f(0.0, 1.6), t, wdir);
  let n = normalize(vec3f(h0 - hx, h0 - hy, 0.85));

  // dusk water: deep slate-teal, warmer toward the sun side
  var c = mix(vec3f(0.050, 0.130, 0.175), vec3f(0.085, 0.170, 0.200), h0 * 0.5 + 0.5);
  let sun2 = normalize(vec2f(-0.66, -0.30));
  c = mix(c, vec3f(0.165, 0.125, 0.115), clamp(dot(uv, sun2) * 0.5 + 0.2, 0.0, 0.45));

  // sky reflection modulated by slope (fresnel-ish from above)
  let skyRef = mix(vec3f(0.22, 0.26, 0.34), vec3f(0.62, 0.36, 0.24), clamp(dot(uv, sun2) + 0.45, 0.0, 1.0));
  c = mix(c, skyRef, clamp(0.22 + 0.35 * (1.0 - n.z), 0.0, 0.6));

  // low-sun glitter — anisotropic, stretched along the sun azimuth
  let L = normalize(vec3f(sun2 * 1.0, 0.24));
  let H = normalize(L + vec3f(0.0, 0.0, 1.0));
  var spec = pow(max(dot(n, H), 0.0), 160.0);
  spec *= 0.55 + 0.65 * vnoise(pw * 0.9 + vec2f(t * 0.8, -t * 0.5));
  c += vec3f(2.6, 1.5, 0.7) * spec * (0.35 + 0.65 * clamp(dot(uv, sun2) + 0.55, 0.0, 1.0));

  // whitecaps grow with wind
  let cap = smoothstep(0.9 - w01 * 0.35, 1.15, h0) * (0.4 + 0.6 * vnoise(pw * 0.5 + vec2f(t * 0.6, 0.0)));
  c = mix(c, vec3f(0.62, 0.66, 0.68), cap * (0.25 + 0.55 * w01));

  // wind streaks — elongated noise aligned with the wind
  let perp = vec2f(-wdir.y, wdir.x);
  let streak = vnoise(vec2f(dot(pw, perp) * 0.55, dot(pw, wdir) * 0.045 - t * 0.5));
  c *= 0.94 + 0.12 * streak * (0.3 + 0.7 * w01);

  // drifting cloud shadows
  let cs = fbm(pw * 0.006 + wdir * t * 0.012, 3);
  c *= 0.82 + 0.28 * cs;

  return vec4f(c, 1.0);
}

fn visual_tr_whirl(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let r = length(uv);
  if (r > 0.97) { return vec4f(0.0); }
  let ang = atan2(uv.y, uv.x);
  let sang = ang + 4.2 * log(r + 0.13) + time * 0.9;
  let streak = pow(0.5 + 0.5 * sin(sang * 3.0), 2.0);
  // bowl darkening toward the drain
  var c = mix(vec3f(0.050, 0.115, 0.150), vec3f(0.008, 0.022, 0.032), smoothstep(0.75, 0.05, r));
  c *= 0.75 + 0.4 * streak;
  // sheared foam collar and inner filaments
  let foamN = vnoise(vec2f(sang * 2.0, r * 14.0 - time * 0.8));
  var foam = exp(-pow((r - 0.72) * 7.0, 2.0)) * (0.4 + 0.6 * foamN);
  foam += smoothstep(0.28, 0.05, r) * streak * 0.5 * foamN;
  c += vec3f(0.55, 0.60, 0.62) * foam;
  let a = smoothstep(0.95, 0.6, r) * 0.92;
  return vec4f(c, a);
}

fn visual_tr_rock(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [seed, 0, surgePhaseOffset, 0]
  let r = length(uv);
  if (r > 0.98) { return vec4f(0.0); }
  let ca = uv / max(r, 0.001);
  let seed = p.x;
  var rockR = 0.46 + 0.16 * (vnoise(ca * 2.1 + vec2f(seed * 9.0, seed * 4.0)) - 0.5) * 2.0;
  rockR += 0.07 * (vnoise(ca * 5.0 + vec2f(seed * 3.0, seed * 7.0)) - 0.5) * 2.0;

  var c = vec3f(0.0);
  var a = 0.0;
  let surge = sin(time * 1.25 + p.z * 6.28);

  if (r < rockR) {
    // craggy top-lit basalt; height falls toward the waterline
    let hgt = clamp((rockR - r) / rockR, 0.0, 1.0);
    let tex = fbm(uv * 9.0 + vec2f(seed * 20.0, 0.0), 4);
    c = mix(vec3f(0.055, 0.052, 0.050), vec3f(0.16, 0.145, 0.125), hgt * (0.5 + 0.5 * tex));
    // warm dusk grazing light from the west
    let sun2 = normalize(vec2f(-0.66, -0.30));
    let grad = vnoise(uv * 7.0 + vec2f(seed * 11.0, 3.0)) - vnoise(uv * 7.0 + sun2 * 0.25 + vec2f(seed * 11.0, 3.0));
    c += vec3f(0.55, 0.30, 0.16) * clamp(grad * 3.0, 0.0, 0.35) * hgt;
    // wet dark band at the waterline
    c *= mix(0.35, 1.0, smoothstep(0.02, 0.14, rockR - r));
    a = 1.0;
  } else {
    // breaking surf collar — swells on a slow pulse, textured foam
    let d = r - rockR;
    let foamN = vnoise(uv * 11.0 + vec2f(time * 0.7, seed * 8.0));
    var foam = exp(-d * d * 160.0) * (0.55 + 0.35 * surge) * (0.45 + 0.55 * foamN);
    foam += exp(-pow((d - 0.10 - 0.03 * surge) * 16.0, 2.0)) * 0.4 * foamN;
    c = vec3f(0.72, 0.75, 0.76) * foam * 1.25;
    a = clamp(foam * 1.15, 0.0, 1.0);
  }
  return vec4f(c, a);
}

fn visual_tr_squall(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [windX, windY, intensity, 0]
  let r = length(uv);
  if (r > 0.98) { return vec4f(0.0); }
  var wdir = vec2f(p.x, p.y);
  if (length(wdir) < 0.1) { wdir = vec2f(1.0, 0.0); }
  wdir = normalize(wdir);
  let perp = vec2f(-wdir.y, wdir.x);
  let edge = smoothstep(0.95, 0.45, r);
  // grey rain veil
  var c = vec3f(0.115, 0.130, 0.145);
  var a = 0.38 * edge * p.z;
  // rain streaks driven along the wind
  let streak = vnoise(vec2f(dot(uv, perp) * 26.0, dot(uv, wdir) * 2.2 - time * 2.2));
  c += vec3f(0.10, 0.11, 0.12) * pow(streak, 3.0) * 2.0;
  // agitated water sheen beneath
  let churn = vnoise(uv * 14.0 + vec2f(time * 1.3, 0.0));
  c += vec3f(0.16, 0.18, 0.19) * churn * 0.35;
  a = clamp(a + pow(streak, 3.0) * 0.25 * edge, 0.0, 0.75);
  return vec4f(c, a);
}

fn visual_tr_light(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [beamAngle, deliverGlow, 0, 0] — islet with tower, rotating beam, and a plank dock (south)
  let r = length(uv);
  var c = vec3f(0.0);
  var a = 0.0;

  // rotating beam wedge over the water (HDR, soft)
  let ang = atan2(uv.y, uv.x);
  var dAng = ang - p.x;
  dAng = atan2(sin(dAng), cos(dAng));
  let wedge = pow(max(cos(dAng), 0.0), 48.0);
  let reach = smoothstep(0.10, 0.30, r) * exp(-r * 1.6);
  c += vec3f(2.0, 1.5, 0.85) * wedge * reach * (1.1 + p.y * 1.4);
  a = max(a, clamp(wedge * reach * 2.0, 0.0, 0.55));

  // islet
  let rockR = 0.40 + 0.10 * (vnoise(uv / max(r, 0.001) * 2.4 + vec2f(4.0, 8.0)) - 0.5) * 2.0;
  if (r < rockR * 0.42) {
    let hgt = clamp((rockR * 0.42 - r) / (rockR * 0.42), 0.0, 1.0);
    let tex = fbm(uv * 8.0 + vec2f(13.0, 5.0), 4);
    c = mix(vec3f(0.06, 0.055, 0.05), vec3f(0.17, 0.15, 0.13), hgt * (0.5 + 0.5 * tex));
    c *= mix(0.4, 1.0, smoothstep(0.01, 0.08, rockR * 0.42 - r));
    a = 1.0;
  } else if (r < rockR * 0.42 + 0.10) {
    let d = r - rockR * 0.42;
    let foamN = vnoise(uv * 12.0 + vec2f(time * 0.7, 2.0));
    let foam = exp(-d * d * 220.0) * (0.6 + 0.3 * sin(time * 1.25)) * (0.5 + 0.5 * foamN);
    c = max(c, vec3f(0.72, 0.75, 0.76) * foam * 1.2);
    a = max(a, clamp(foam, 0.0, 1.0));
  }
  // dock: weathered planks running south
  let dq = uv - vec2f(0.02, 0.30);
  let dockD = sdBox(dq, vec2f(0.055, 0.22));
  if (dockD < 0.0) {
    let plank = 0.8 + 0.2 * sin(dq.y * 90.0);
    c = vec3f(0.30, 0.21, 0.13) * plank * (0.8 + 0.2 * vnoise(dq * 40.0));
    a = 1.0;
  }
  // tower: white drum, red lantern, warm halo
  if (r < 0.085) {
    let ring = smoothstep(0.085, 0.055, r);
    c = mix(vec3f(0.75, 0.72, 0.68), vec3f(0.9, 0.88, 0.84), ring);
    a = 1.0;
  }
  c += vec3f(3.0, 1.6, 0.6) * exp(-r * r * 300.0) * (1.0 + p.y * 2.0);
  return vec4f(c, a);
}

fn visual_tr_raft(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [seed, 0, 0, hidden] — a lantern lashed to a small raft
  if (p.w > 0.5) { return vec4f(0.0); }
  let r = length(uv);
  var c = vec3f(0.0);
  var a = 0.0;
  // expanding ripple rings (slow)
  let rip = sin(r * 22.0 - time * 2.2 + p.x * 9.0) * exp(-r * 2.6);
  c += vec3f(0.10, 0.12, 0.13) * max(rip, 0.0) * 0.8;
  a = max(a, max(rip, 0.0) * 0.35);
  // raft planks
  let rq = rotate(uv, p.x * 6.0);
  if (sdBox(rq, vec2f(0.16, 0.11)) < 0.0) {
    c = vec3f(0.24, 0.17, 0.11) * (0.8 + 0.2 * sin(rq.y * 70.0));
    a = 1.0;
  }
  // warm lantern — gentle breathing, HDR for bloom
  let breathe = 0.85 + 0.15 * sin(time * 1.6 + p.x * 12.0);
  c += vec3f(2.6, 1.5, 0.55) * exp(-r * r * 60.0) * breathe;
  c += vec3f(1.2, 0.6, 0.2) * exp(-r * r * 9.0) * 0.5 * breathe;
  a = max(a, clamp(exp(-r * r * 20.0) * 1.3, 0.0, 1.0));
  return vec4f(c, a);
}

fn visual_tr_boat(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [heading, speed01, boomAngle, heel(-1..1)] — +x forward in boat frame
  let q = rotate(uv, -p.x);
  let spd = clamp(p.y, 0.0, 1.0);
  let sun2n = normalize(vec2f(-0.66, -0.30));
  let shD = rotate(-sun2n, -p.x) * 0.045;      // shadow cast away from the sun, in boat frame
  var c = vec3f(0.0);
  var a = 0.0;

  // ---- Kelvin wake ----
  if (q.x < 0.02 && spd > 0.04) {
    let wx = 0.02 - q.x;
    let wy = q.y;
    let slope = abs(wy) / max(wx, 0.002);
    let armD = abs(slope - 0.354) * wx;
    let arm = exp(-armD * armD * 800.0) * exp(-wx * 2.3);
    var trans = 0.0;
    if (slope < 0.354) {
      trans = (0.5 + 0.5 * sin(wx * (34.0 + 26.0 * (1.0 - spd)))) * exp(-wx * 2.8) * smoothstep(0.354, 0.12, slope);
    }
    let turb = exp(-wy * wy * 260.0) * exp(-wx * 3.0) * (0.55 + 0.45 * vnoise(vec2f(wx * 26.0 - time * 4.0 * spd, wy * 36.0)));
    let foam = (arm + turb * 0.95) * spd;
    c += vec3f(0.70, 0.76, 0.78) * foam * 1.25;
    c += vec3f(0.16, 0.22, 0.26) * trans * spd * 0.8;
    a = max(a, clamp(foam * 1.25 + trans * spd * 0.35, 0.0, 1.0) * 0.9);
  }

  // hull profile: pointed bow (+x), squared transom
  let hL = 0.34;
  let hW = 0.10;
  // ---- shadow on the water (hull + sail silhouette, offset from the sun) ----
  let sq = q - shD;
  let sxn = sq.x / hL;
  if (abs(sxn) < 1.0) {
    let wp = hW * sqrt(max(0.0, 1.0 - sxn * sxn)) * (1.0 - 0.45 * smoothstep(0.1, 1.0, sxn));
    if (abs(sq.y) < wp && sq.x > -hL * 0.94) {
      c = mix(c, vec3f(0.005, 0.012, 0.016), 0.55);
      a = max(a, 0.5);
    }
  }

  // ---- hull ----
  let hq = vec2f(q.x, q.y + p.w * 0.010);     // heel shifts the deck line
  let xn = hq.x / hL;
  if (abs(xn) < 1.0 && hq.x > -hL * 0.94) {
    let wProf = hW * sqrt(max(0.0, 1.0 - xn * xn)) * (1.0 - 0.45 * smoothstep(0.1, 1.0, xn));
    let dy = abs(hq.y);
    if (dy < wProf) {
      // teak deck, planked; brighter on the sunward rail (heel-aware)
      let plank = 0.85 + 0.15 * sin(hq.y * 260.0);
      var deck = vec3f(0.36, 0.26, 0.17) * plank * (0.85 + 0.15 * vnoise(hq * 80.0));
      let railLight = clamp(-hq.y * sign(p.w) * 10.0, -0.2, 0.35);
      deck *= 0.9 + railLight;
      // white gunwale
      let rail = smoothstep(wProf - 0.011, wProf - 0.004, dy);
      deck = mix(deck, vec3f(0.82, 0.80, 0.76), rail);
      // cabin house aft of the mast
      let cd = sdRoundedBox(hq - vec2f(-0.075, 0.0), vec2f(0.055, 0.032), 0.015);
      if (cd < 0.0) { deck = mix(vec3f(0.46, 0.35, 0.24), vec3f(0.55, 0.44, 0.30), 0.5 + 0.5 * sin(hq.x * 200.0)); }
      c = deck * (0.9 + 0.35 * clamp(dot(rotate(vec2f(1.0, 0.0), p.x), -sun2n), 0.0, 1.0));
      a = 1.0;
    }
    // bow spray
    if (xn > 0.55 && spd > 0.35) {
      let bq = hq - vec2f(hL, 0.0);
      let spray = exp(-dot(bq, bq) * 320.0) * spd * (0.5 + 0.5 * vnoise(hq * 60.0 + vec2f(time * 3.0, 0.0)));
      c += vec3f(0.75, 0.8, 0.82) * spray;
      a = max(a, clamp(spray, 0.0, 0.8));
    }
  }

  // ---- rig: mast, boom, canvas ----
  let mast = vec2f(0.075, 0.0);
  let boomAng = p.z;
  let tip = mast + vec2f(cos(3.14159 + boomAng), sin(3.14159 + boomAng)) * 0.27;  // boom sweeps aft
  // sail: curved panel from mast to boom tip, cambered to leeward
  let mid = (mast + tip) * 0.5 + vec2f(-(tip - mast).y, (tip - mast).x) * 0.16;
  let d1 = sdSegment(q, mast, mid);
  let d2 = sdSegment(q, mid, tip);
  let sailD = min(d1, d2);
  if (sailD < 0.020) {
    // cream dacron lit by the low sun
    let lit = 0.65 + 0.4 * clamp(dot(normalize(tip - mast), sun2n), -0.4, 1.0);
    c = vec3f(0.88, 0.84, 0.74) * lit;
    a = 1.0;
  }
  // boom shadow line on deck
  let bD = sdSegment(q, mast, tip);
  if (bD < 0.006) { c = mix(c, vec3f(0.06, 0.05, 0.04), 0.7); a = max(a, 0.9); }
  // mast head
  c += vec3f(0.9, 0.85, 0.75) * exp(-dot(q - mast, q - mast) * 2600.0);
  a = max(a, clamp(exp(-dot(q - mast, q - mast) * 2000.0), 0.0, 1.0));

  a *= smoothstep(1.0, 0.92, length(uv));
  return vec4f(c, a);
}

fn visual_tr_hud(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [hull, cargo, windAngle, wind01] — quiet glass instruments, no chrome
  var c = vec3f(0.0);
  var a = 0.0;
  // wind rose: arrow rotated to where the wind blows
  let wq = rotate((uv - vec2f(-0.86, 0.0)) * vec2f(8.0, 3.6), -p.z);
  let tri = sdEquilateralTriangle(rotate(wq, 1.5708), 0.30);
  let ring = abs(length(wq) - 0.42);
  c += vec3f(0.75, 0.82, 0.88) * smoothstep(0.05, -0.02, tri) * (0.55 + 0.45 * p.w);
  c += vec3f(0.45, 0.55, 0.62) * smoothstep(0.03, 0.0, ring) * 0.5;
  a = max(a, smoothstep(0.05, -0.02, tri) * 0.85);
  a = max(a, smoothstep(0.03, 0.0, ring) * 0.4);
  // hull integrity: three small planks
  for (var i = 0; i < 3; i++) {
    let q = (uv - vec2f(-0.55 + f32(i) * 0.09, 0.0)) * vec2f(12.0, 5.0);
    let on = select(0.12, 1.0, f32(i) < p.x);
    let g = exp(-dot(q, q) * 2.0);
    c += vec3f(0.85, 0.55, 0.35) * g * on;
    a = max(a, g * 0.7);
  }
  // cargo lanterns aboard
  for (var i = 0; i < 4; i++) {
    let q = (uv - vec2f(0.30 + f32(i) * 0.09, 0.0)) * vec2f(12.0, 5.0);
    let on = select(0.10, 1.0, f32(i) < p.y);
    let g = exp(-dot(q, q) * 2.0);
    c += vec3f(1.6, 0.95, 0.35) * g * on;
    a = max(a, g * 0.75 * max(on, 0.25));
  }
  return vec4f(c, clamp(a, 0.0, 1.0) * 0.8);
}

// a moon whose bite orbits with phase — six unique crescents, one per stone
fn se_seg(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

fn se_moon(rel: vec2f, r: f32, ph: f32) -> f32 {
  let d = length(rel);
  let disc = smoothstep(r, r * 0.9, d);
  let bc = vec2f(cos(6.2831853 * ph), sin(6.2831853 * ph)) * r * 0.72;
  let bite = smoothstep(r * 0.98, r * 0.84, length(rel - bc));
  return disc * (1.0 - bite * 0.93);
}

// the aurora's wheel: teal → green → violet → rose, never muddy
fn se_pal(h: f32) -> vec3f {
  return 0.5 + 0.5 * cos(6.2831853 * (h + vec3f(0.0, 0.33, 0.67)));
}

fn visual_selene(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let mc = vec2f(uni(0), uni(1));
  let ph = uni(2);
  let win = uni(10);
  let act2 = uni(12) > 0.5;

  // ════ ACT II — AURORA: the night under the lake ════
  if (act2) {
    let bloom = clamp(uni(11), 0.0, 1.0);

    // the polar night, deeper than the deep
    var col = mix(vec3f(0.004, 0.008, 0.020), vec3f(0.012, 0.020, 0.045), 0.5 - 0.5 * uv.y);
    // hard winter stars
    let sp = uv * 17.0;
    let sh = hash21(floor(sp));
    if (sh > 0.975) {
      col += vec3f(0.7, 0.75, 0.9) * smoothstep(0.18, 0.02, length(fract(sp) - 0.5)) * (0.35 + 0.45 * sin(t * 1.2 + sh * 50.0));
    }
    // the ice field below — a pale breathing band
    let ice = smoothstep(0.55, 0.75, uv.y);
    col = mix(col, vec3f(0.10, 0.13, 0.19) + vec3f(0.02) * sin(uv.x * 8.0 + t * 0.2), ice * 0.9);
    col += vec3f(0.05, 0.07, 0.10) * smoothstep(0.545, 0.56, uv.y) * smoothstep(0.60, 0.56, uv.y);

    // the ribbon you carry: a curtain of sky-light hanging from your cursor
    let rib = se_pal(ph);
    {
      let wave = sin(uv.x * 5.0 + t * 0.9) * 0.05 + sin(uv.x * 11.0 - t * 1.3) * 0.025;
      let spine = mc.y + (uv.x - mc.x) * 0.18 + wave;
      let d = uv.y - spine;
      let across = exp(-abs(uv.x - mc.x) * 2.6);
      let curtain = exp(-max(d, 0.0) * 9.0) * exp(-max(-d, 0.0) * 2.2);
      let streak = 0.55 + 0.45 * vnoise(vec2f(uv.x * 22.0, uv.y * 3.0 - t * 0.6));
      col += rib * curtain * across * streak * (0.55 + 0.25 * sin(t * 2.0));
      col += rib * exp(-dot(uv - mc, uv - mc) * 120.0) * (0.5 + 0.4 * uni(3));
    }

    // six ice-lanterns ringing the night
    let R = 0.68;
    for (var i = 0; i < 6; i++) {
      let fi = f32(i);
      let a = 6.2831853 * fi / 6.0 - 1.5707963;
      let c = vec2f(cos(a), sin(a)) * R;
      let rel = uv - c;
      if (abs(rel.x) < 0.22 && abs(rel.y) < 0.22) {
        let lit = clamp(uni(4 + i), 0.0, 1.0);
        let lc = se_pal(fi / 6.0);
        // the crystal: a rotated diamond of ice
        let q = rotate(rel, 0.7853982);
        let cd = abs(q.x) + abs(q.y);
        let body = smoothstep(0.075, 0.062, cd);
        col = mix(col, mix(vec3f(0.10, 0.13, 0.18), lc * 1.3, lit), body * (0.5 + 0.5 * lit));
        col += lc * exp(-dot(rel, rel) * 240.0) * (0.25 + lit * 1.1);
        // when your ribbon's color nears this lantern's, the rim wakes
        let dh = abs(fract(ph - fi / 6.0 + 0.5) - 0.5);
        let hueWake = smoothstep(0.085, 0.03, dh) * (1.0 - lit);
        col += lc * exp(-pow((cd - 0.075) * 30.0, 2.0)) * hueWake * (0.7 + 0.3 * sin(t * 5.0));
        col += lc * exp(-dot(rel, rel) * 90.0) * lit * 0.35;
      }
    }

    // the corona: all six lit, the sky itself becomes the crown
    if (bloom > 0.003) {
      for (var k = 0; k < 3; k++) {
        let fk = f32(k);
        let arcY = -0.55 + fk * 0.14 + sin(uv.x * 3.0 + t * (0.5 + fk * 0.2) + fk * 2.0) * 0.06;
        let ad = abs(uv.y - arcY);
        let ac = se_pal(fract(uv.x * 0.35 + fk * 0.28 + t * 0.03));
        col += ac * exp(-ad * 26.0) * bloom * (0.30 - fk * 0.07) * (0.7 + 0.3 * vnoise(vec2f(uv.x * 14.0 + fk * 9.0, t * 0.5)));
      }
      // the door home stands in the ice, made of the same light
      let dp = uv - vec2f(0.0, 0.30);
      let door = smoothstep(0.16, 0.13, abs(dp.x)) * smoothstep(0.24, 0.21, abs(dp.y + 0.06));
      col += se_pal(fract(t * 0.05)) * door * bloom * 0.5;
      col += vec3f(0.9, 0.95, 1.0) * exp(-dot(dp, dp) * 30.0) * bloom * 0.25;
    }

    col *= 1.0 - 0.4 * pow(length(uv) * 0.72, 3.0);
    if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
    return vec4f(clamp(col, vec3f(0.0), vec3f(30.0)), 1.0);
  }

  // ════ ACT I — THE DROWNED MOON ════
  let nvy = clamp(uv.y, -1.3, 1.3);

  // the drowned sky
  var col = mix(vec3f(0.010, 0.018, 0.038), vec3f(0.030, 0.055, 0.095), 0.5 - 0.5 * nvy);
  // caustic light from the lake's surface far above
  let ca = sin(uv.x * 9.0 + sin(nvy * 5.0 + t * 0.4) * 1.5 + t * 0.5);
  col += vec3f(0.028, 0.05, 0.07) * (0.5 + 0.5 * ca) * 0.5;
  // drowned stars, dim and wavering
  let sp = uv * 14.0 + vec2f(sin(t * 0.2 + nvy * 2.0) * 0.05, 0.0);
  let sh = hash21(floor(sp));
  if (sh > 0.972) {
    col += vec3f(0.35, 0.45, 0.65) * smoothstep(0.2, 0.03, length(fract(sp) - 0.5)) * (0.4 + 0.4 * sin(t * 1.5 + sh * 40.0));
  }
  // motes rising toward the surface
  let bp = vec2f(uv.x * 10.0, nvy * 6.0 - t * 0.35);
  let bh = hash21(floor(bp));
  if (bh > 0.955) {
    col += vec3f(0.08, 0.13, 0.17) * smoothstep(0.16, 0.02, length(fract(bp) - 0.5));
  }

  // six phase-stones ringing the deep
  let R = 0.68;
  for (var i = 0; i < 6; i++) {
    let fi = f32(i);
    let a = 6.2831853 * fi / 6.0 - 1.5707963;
    let c = vec2f(cos(a), sin(a)) * R;
    let rel = uv - c;
    if (abs(rel.x) < 0.22 && abs(rel.y) < 0.22) {
      let lit = clamp(uni(4 + i), 0.0, 1.0);
      let stone = se_moon(rel, 0.075, fi / 6.0);
      let scol = mix(vec3f(0.15, 0.17, 0.23), vec3f(1.35, 1.30, 1.05), lit);
      col = mix(col, scol, stone * (0.4 + 0.6 * lit));
      // faint carved seat under each stone
      col += vec3f(0.05, 0.06, 0.09) * exp(-dot(rel, rel) * 90.0) * (1.0 - lit);
      // when your moon's phase matches this stone, its rim wakes amber
      let dp = abs(fract(ph - fi / 6.0 + 0.5) - 0.5);
      let phMatch = smoothstep(0.085, 0.03, dp) * (1.0 - lit);
      col += vec3f(1.0, 0.72, 0.28) * exp(-pow((length(rel) - 0.085) * 26.0, 2.0)) * phMatch * (0.6 + 0.4 * sin(t * 5.0));
      // lit stones hold a silver halo
      col += vec3f(0.85, 0.85, 0.6) * exp(-dot(rel, rel) * 150.0) * lit * 0.9;
    }
  }

  // the chapter door: when the ring is lit, the MOON-TREE grows
  let wt = clamp(uni(11), 0.0, 1.0);
  if (wt > 0.005) {
    let g1 = clamp(wt * 3.0, 0.0, 1.0);
    let g2 = clamp(wt * 3.0 - 1.0, 0.0, 1.0);
    let g3 = clamp(wt * 3.0 - 2.0, 0.0, 1.0);
    let p0 = vec2f(0.0, 0.42);
    let p1 = p0 + vec2f(-0.03, -0.20) * g1;
    let p2 = p1 + vec2f(0.05, -0.19) * g2;
    let p3 = p2 + vec2f(-0.02, -0.16) * g3;
    var td = se_seg(uv, p0, p1) - 0.022 * (0.6 + 0.4 * g1);
    td = min(td, se_seg(uv, p1, p2) - 0.016);
    td = min(td, se_seg(uv, p2, p3) - 0.011);
    for (var bi = 0; bi < 5; bi++) {
      let fb = f32(bi);
      let gb = clamp(wt * 4.0 - 2.2 - fb * 0.25, 0.0, 1.0);
      if (gb > 0.01) {
        let root = mix(p2, p3, 0.2 + fb * 0.2);
        let ang = -1.5707963 + (fb - 2.0) * 0.55 + sin(t * 0.4 + fb) * 0.04;
        let tip = root + vec2f(cos(ang), sin(ang)) * (0.14 + fb * 0.014) * gb;
        td = min(td, se_seg(uv, root, tip) - 0.006);
        col += vec3f(1.15, 1.10, 0.75) * exp(-dot(uv - tip, uv - tip) * 900.0) * gb * (0.8 + 0.3 * sin(t * 2.0 + fb * 2.1));
        col += vec3f(0.55, 0.60, 0.45) * exp(-dot(uv - tip, uv - tip) * 120.0) * gb * 0.35;
      }
    }
    if (td < 0.0) { col = mix(vec3f(0.72, 0.68, 0.58), vec3f(0.35, 0.30, 0.24), clamp((uv.y - p2.y) * 2.0, 0.0, 1.0)); }
    col += vec3f(1.0, 0.85, 0.45) * exp(-dot(uv - p3, uv - p3) * 9.0) * wt * 0.30;
    col += vec3f(0.9, 0.75, 0.35) * wt * (0.035 + 0.03 * sin(t * 2.1));
  }

  // the drowned moon you carry
  let mr = uv - mc;
  let held = se_moon(mr, 0.055, ph);
  col = mix(col, vec3f(1.55, 1.55, 1.35), held);
  col += vec3f(0.45, 0.5, 0.68) * exp(-dot(mr, mr) * 55.0) * (0.45 + 0.4 * uni(3));

  col *= 1.0 - 0.4 * pow(length(vec2f(uv.x, nvy)) * 0.72, 3.0);
  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(30.0)), 1.0);
}

const HL_HOR: f32 = 336.0;

fn hl_moonness(ph: f32) -> f32 { return 0.5 - 0.5 * cos(6.2831853 * ph); }

// sky + orb, callable so the lake can mirror it
fn hl_sky(p: vec2f, sun: vec2f, m: f32, t: f32, a: f32) -> vec3f {
  let up = clamp(1.0 - p.y / HL_HOR, 0.0, 1.0);
  // day palette → night palette
  let dayZen = vec3f(0.16, 0.34, 0.62);
  let dayHor = vec3f(0.95, 0.62, 0.32);
  let nightZen = vec3f(0.015, 0.020, 0.055);
  let nightHor = vec3f(0.05, 0.06, 0.13);
  var col = mix(mix(dayHor, dayZen, pow(up, 0.6)), mix(nightHor, nightZen, pow(up, 0.6)), m);

  // light breathes from wherever the orb is (screen-round despite the
  // vertical compression that fits the painting to wide viewports)
  let rel = vec2f(p.x - sun.x, (p.y - sun.y) / a);
  let d = length(rel);
  let warm = mix(vec3f(1.1, 0.7, 0.35), vec3f(0.55, 0.62, 0.80), m);
  col += warm * exp(-d * 0.012) * mix(0.5, 0.28, m);

  // the orb: gold sun ↔ silver moon with craters and a crescent bite
  let r = 26.0;
  if (d < r) {
    var oc = mix(vec3f(3.2, 2.4, 1.1), vec3f(1.6, 1.7, 1.9), m);
    // craters surface only as it becomes moon
    let cr = vnoise(rel * 0.22 + 7.0);
    oc *= 1.0 - m * 0.35 * smoothstep(0.45, 0.8, cr);
    // crescent: a dark disk slides across as moonness grows past half
    let bite = length(rel - vec2f(r * 0.85 * smoothstep(0.35, 1.0, m), -4.0));
    if (m > 0.35 && bite < r * 0.98) { oc *= 0.12; }
    col = oc;
  }
  col += warm * exp(-max(d - r, 0.0) * 0.05) * mix(0.9, 0.55, m);   // corona

  // stars belong to the moon
  if (m > 0.25) {
    let sp2 = p * 0.14;
    let cell = floor(sp2);
    let st = hash21(cell);
    if (st > 0.975 && p.y < HL_HOR - 10.0) {
      let d2 = length(fract(sp2) - 0.5);
      let tw = 0.5 + 0.5 * sin(t * 3.0 + st * 40.0);
      col += vec3f(0.9, 0.92, 1.0) * smoothstep(0.16, 0.02, d2) * tw * smoothstep(0.25, 0.6, m);
    }
  }
  return col;
}

fn hl_ridge(x: f32, seed: f32, amp: f32, base: f32) -> f32 {
  return base - amp * (fbm3(vec2f(x * 0.008 + seed, seed)) - 0.25);
}

fn visual_helios(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  if (uni(24) > 1.5) { return vec4f(0.0); }
  let asp = 1.0;   // contain-fit shows the whole painting
  let p = vec2f((uv.x + 1.0) * 256.0, (uv.y * asp + 1.0) * 256.0);
  let t = time;
  var sun = vec2f(uni(0), uni(1));
  if (sun.x < 1.0) { sun = vec2f(150.0, 120.0); }        // pre-hook default: morning
  let m = hl_moonness(uni(2));
  let gold = uni(4);

  var col: vec3f;
  let LAKE = 424.0;

  if (p.y < LAKE) {
    col = hl_sky(p, sun, m, t, asp);

    // three ridgelines, lit from wherever the orb hangs
    let warm = mix(vec3f(1.0, 0.75, 0.45), vec3f(0.5, 0.58, 0.75), m);
    let sunSide = clamp(1.0 - abs(p.x - sun.x) / 360.0, 0.0, 1.0);
    let r1 = hl_ridge(p.x, 3.0, 90.0, HL_HOR - 40.0);
    let r2 = hl_ridge(p.x, 11.0, 60.0, HL_HOR - 6.0);
    let r3 = hl_ridge(p.x, 27.0, 34.0, HL_HOR + 26.0);
    if (p.y > r3 && p.y < LAKE) {
      col = mix(vec3f(0.10, 0.16, 0.08), vec3f(0.012, 0.02, 0.03), m);
      col += warm * 0.35 * sunSide * smoothstep(r3 + 14.0, r3, p.y);  // lit brow
      col *= 0.9 + 0.2 * vnoise(p * 0.12);
    } else if (p.y > r2) {
      col = mix(vec3f(0.13, 0.20, 0.11), vec3f(0.02, 0.03, 0.05), m);
      col += warm * 0.30 * sunSide * smoothstep(r2 + 12.0, r2, p.y);
      col *= 0.9 + 0.2 * vnoise(p * 0.1 + 5.0);
    } else if (p.y > r1) {
      col = mix(vec3f(0.17, 0.25, 0.15), vec3f(0.03, 0.045, 0.07), m);
      col += warm * 0.28 * sunSide * smoothstep(r1 + 10.0, r1, p.y);
      col *= 0.9 + 0.2 * vnoise(p * 0.08 + 9.0);
    }

    // fireflies rise at night over the near meadow
    if (m > 0.5 && p.y > HL_HOR) {
      let fp2 = p * 0.06 + vec2f(0.0, t * 0.06);
      let fc = floor(fp2);
      let fh = hash21(fc + 31.0);
      if (fh > 0.955) {
        let fd = length(fract(fp2) - 0.5);
        let blink = pow(0.5 + 0.5 * sin(t * 2.5 + fh * 60.0), 3.0);
        col += vec3f(0.9, 1.4, 0.3) * smoothstep(0.10, 0.02, fd) * blink * (m - 0.5) * 2.4;
      }
    }
  } else {
    // the lake: the whole sky again, upside down and breathing
    let ry = LAKE - (p.y - LAKE) * 1.9;
    let wob = vnoise(vec2f(p.x * 0.05, p.y * 0.3 - t * 0.8)) - 0.5;
    var rp = vec2f(p.x + wob * 9.0, ry + wob * 5.0);
    col = hl_sky(rp, sun, m, t, asp) * mix(0.62, 0.5, m);
    col += vec3f(0.04, 0.05, 0.06) * (0.5 + wob);

    // moon-glitter: when the moon is out and its face lies on the lake,
    // the water sparkles along the reflection path
    let refY = LAKE + (LAKE - sun.y) / 1.9;
    let mglow = smoothstep(0.35, 0.75, m) * smoothstep(620.0, 500.0, refY);
    if (mglow > 0.01) {
      let depth = clamp((p.y - LAKE) / (512.0 - LAKE), 0.0, 1.0);
      let spread = 16.0 + 100.0 * depth;                 // the glade widens toward you
      let path = smoothstep(spread, spread * 0.2, abs(p.x - sun.x + wob * 14.0));
      // glint cells — little horizontal flecks, twinkling out of phase
      let gp = vec2f(p.x * 0.12, p.y * 0.3 - t * 0.55);
      let gh = hash21(floor(gp));
      let gd = length((fract(gp) - 0.5) * vec2f(0.9, 2.2));
      let flash = pow(0.5 + 0.5 * sin(t * (2.0 + gh * 6.0) + gh * 47.0), 6.0);
      let glint = smoothstep(0.45, 0.05, gd) * step(0.80, gh) * flash;
      col += vec3f(1.05, 1.12, 1.30) * glint * path * mglow * 2.8;   // the sparkle
      col += vec3f(0.35, 0.40, 0.55) * path * mglow * 0.20 * (0.6 + wob);  // silver sheen
      col += vec3f(1.30, 0.95, 0.40) * path * gold * 0.55 * (0.7 + wob);   // the invitation
    }
  }

  // hold feedback: a slow pulse ring while the orb is aging
  if (uni(3) > 0.01) {
    let ring = abs(length(vec2f(p.x - sun.x, (p.y - sun.y) / asp)) - (30.0 + fract(t * 0.8) * 26.0));
    col += vec3f(0.8, 0.8, 0.7) * uni(3) * smoothstep(3.0, 0.0, ring) * 0.5;
  }

  // the moon's reflection noticed you: the whole valley breathes gold
  if (gold > 0.01) {
    let breath = 0.5 + 0.5 * sin(t * 3.2);
    col += vec3f(1.05, 0.78, 0.28) * gold * (0.10 + 0.11 * breath) * (1.25 - 0.5 * length(uv));
  }

  col *= 1.0 - 0.35 * pow(length(uv), 3.0);
  return vec4f(col, 1.0);
}

fn visual_helios_grove(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  if (uni(24) > 1.5) { return vec4f(0.0); }
  let p = (uv + vec2f(1.0)) * 256.0;
  let t = time;
  let moon = 0.5 - 0.5 * cos(6.2831 * uni(2));
  let grow = uni(11);
  let cue = uni(12);
  let veil = clamp(uni(21), 0.0, 1.0);
  let budsOn = smoothstep(0.94, 0.99, grow);
  let glowc = vec3f(2.2, 1.6, 0.5);
  var col = vec3f(0.0);
  var alpha = 0.0;

  {
    let sp = vec2f(58.0, 372.0);
    let lit = uni(5);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(0.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 0.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 0.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }
  {
    let sp = vec2f(140.0, 394.0);
    let lit = uni(6);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(1.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 1.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 1.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }
  {
    let sp = vec2f(212.0, 408.0);
    let lit = uni(7);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(2.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 2.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 2.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }
  {
    let sp = vec2f(300.0, 408.0);
    let lit = uni(8);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(3.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 3.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 3.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }
  {
    let sp = vec2f(372.0, 394.0);
    let lit = uni(9);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(4.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 4.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 4.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }
  {
    let sp = vec2f(454.0, 372.0);
    let lit = uni(10);
    let q = (p - sp) / 22.0;
    var d = length(q * vec2f(1.0, 1.3) - vec2f(0.0, -0.15)) - 0.85;
    d += (fbm3(q * 2.5 + vec2f(5.7, 0.0)) - 0.5) * 0.25;
    let m = smoothstep(0.06, -0.06, d);
    var rc = mix(vec3f(0.10, 0.11, 0.13), vec3f(0.30, 0.32, 0.36), clamp(0.5 - q.y * 0.5, 0.0, 1.0));
    rc *= 0.55 + 0.45 * (1.0 - moon);
    let pol = polar(q - vec2f(0.0, -0.1));
    let runes = step(0.55, sin(pol.y * 7.0 + 5.0)) * smoothstep(0.10, 0.03, abs(pol.x - 0.52));
    rc = mix(rc, glowc * (0.3 + lit), runes * (0.10 + 0.90 * lit));
    rc += glowc * lit * 0.5 * exp(-length(q) * 1.8);
    rc += glowc * cue * 0.5 * (0.5 + 0.5 * sin(t * 3.0 + 5.0)) * exp(-length(q) * 1.4);
    col = mix(col, rc, m);
    alpha = max(alpha, m);
  }

  if (cue > 0.01 && grow <= 0.001) {
    let shaft = exp(-abs(p.x - 256.0) * 0.04) * smoothstep(430.0, 300.0, p.y) * smoothstep(120.0, 300.0, p.y);
    col += vec3f(2.0, 1.6, 0.6) * shaft * cue * (0.4 + 0.2 * sin(t * 2.0)) * 0.5;
    alpha = max(alpha, clamp(shaft * cue, 0.0, 1.0) * 0.6);
  }

  if (grow > 0.001) {
    var q2 = vec2f(p.x - 256.0, p.y);
    q2.x -= sin(t * 0.5) * 3.0 * clamp((418.0 - p.y) / 200.0, 0.0, 1.0);
    let h01 = clamp((418.0 - p.y) / 300.0, 0.0, 1.0);
    let reveal = smoothstep(grow + 0.03, grow - 0.10, h01);
    var td = 9999.0;
    let taper = mix(9.5, 2.5, h01);
    let top = mix(420.0, 240.0, clamp(grow * 1.5, 0.0, 1.0));
    td = min(td, sdSegment(q2, vec2f(0.0, 424.0), vec2f(0.0, top)) - taper);
    let bg2 = clamp((grow - 0.45) * 3.0, 0.0, 1.0);
    let bg3 = clamp((grow - 0.65) * 3.5, 0.0, 1.0);
    td = min(td, sdSegment(q2, vec2f(0.0, 330.0), mix(vec2f(0.0, 330.0), vec2f(-80.3, 284.0), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(-80.3, 284.0), mix(vec2f(-80.3, 284.0), vec2f(-146.0, 262.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 300.0), mix(vec2f(0.0, 300.0), vec2f(-55.0, 233.0), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(-55.0, 233.0), mix(vec2f(-55.0, 233.0), vec2f(-100.0, 190.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 275.0), mix(vec2f(0.0, 275.0), vec2f(-22.0, 199.5), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(-22.0, 199.5), mix(vec2f(-22.0, 199.5), vec2f(-40.0, 148.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 268.0), mix(vec2f(0.0, 268.0), vec2f(15.4, 194.0), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(15.4, 194.0), mix(vec2f(15.4, 194.0), vec2f(28.0, 144.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 285.0), mix(vec2f(0.0, 285.0), vec2f(49.5, 219.5), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(49.5, 219.5), mix(vec2f(49.5, 219.5), vec2f(90.0, 178.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 320.0), mix(vec2f(0.0, 320.0), vec2f(78.1, 272.0), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(78.1, 272.0), mix(vec2f(78.1, 272.0), vec2f(142.0, 248.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 250.0), mix(vec2f(0.0, 250.0), vec2f(0.0, 172.0), bg2)) - 3.5);
    td = min(td, sdSegment(q2, vec2f(0.0, 172.0), mix(vec2f(0.0, 172.0), vec2f(0.0, 118.0), bg3)) - 2.2);
    td = min(td, sdSegment(q2, vec2f(0.0, 340.0), mix(vec2f(0.0, 340.0), vec2f(-60.0, 300.0), bg3)) - 1.6);
    td = min(td, sdSegment(q2, vec2f(0.0, 310.0), mix(vec2f(0.0, 310.0), vec2f(55.0, 275.0), bg3)) - 1.6);
    td = min(td, sdSegment(q2, vec2f(0.0, 262.0), mix(vec2f(0.0, 262.0), vec2f(-25.0, 205.0), bg3)) - 1.6);
    td = min(td, sdSegment(q2, vec2f(0.0, 292.0), mix(vec2f(0.0, 292.0), vec2f(35.0, 240.0), bg3)) - 1.6);
    let tm = smoothstep(1.5, -1.5, td) * reveal;
    var bark = mix(vec3f(0.20, 0.13, 0.08), vec3f(0.38, 0.26, 0.15), clamp(0.5 + q2.x * 0.02, 0.0, 1.0));
    bark += (fbm3(vec2f(q2.x * 0.05, p.y * 0.15)) - 0.5) * 0.10;
    bark *= 0.5 + 0.5 * (1.0 - moon);
    col = mix(col, bark, tm);
    alpha = max(alpha, tm);
    let lg = smoothstep(0.6, 0.95, grow);
    var lm = 0.0;
    {
      let ld1 = length((p - vec2f(256.0, 190.0)) / vec2f(150.0, 72.0)) - 1.0;
      let ld2 = length((p - vec2f(256.0, 140.0)) / vec2f(92.0, 46.0)) - 1.0;
      let ld = min(ld1, ld2);
      let ln = fbm3(p * 0.03 + vec2f(0.0, t * 0.06)) - 0.5;
      lm = smoothstep(0.05, -0.10, ld + ln * 0.5) * lg;
      var leaf = mix(vec3f(0.10, 0.28, 0.12), vec3f(0.30, 0.58, 0.22), clamp(0.5 + ln + (190.0 - p.y) * 0.004, 0.0, 1.0));
      leaf *= 0.35 + 0.65 * (1.0 - moon * 0.7);
      col = mix(col, leaf, lm * 0.9);
      alpha = max(alpha, lm * 0.9);
      col += vec3f(1.4, 1.1, 0.5) * moon * lg * exp(-abs(ld) * 3.0) * 0.15;
