fn cf_stars(p: vec2f, t: f32) -> vec3f {
  var c = vec3f(0.008, 0.007, 0.016);
  c += vec3f(0.05, 0.025, 0.09) * smoothstep(0.4, 0.9, fbm(p * 1.5 + vec2f(t * 0.004, 0.0), 4));
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let sp = p * (16.0 + fl * 26.0) + fl * 31.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let fp = fract(sp) - 0.5;
    let tw = 0.5 + 0.5 * sin(t * (0.5 + h * 1.4) + h * 40.0);
    c += vec3f(0.8, 0.75, 0.95) * step(0.985, h) * smoothstep(0.24, 0.03, length(fp)) * tw * (1.1 - fl * 0.4);
  }
  return c;
}

// A PLAYER — a bounded, directional glow. Meant to become programmable (an
// effect id + params + facing, brewed per person); for now a hardcoded Glow with
// a nose + pupil so its direction reads. local: offset from the player center,
// ~1.0 at the edge. dir: unit facing. Returns additive rgb.
fn cf_player(local0: vec2f, dir: vec2f, phase: f32, fx: i32, tint: vec3f) -> vec3f {
  // DANCE — bob, sway, squash-and-stretch on this player's own beat. A groove
  // in place, never a spin. dir is the base facing (the groove leans around it).
  let bob = sin(phase * 3.1) * 0.16;                 // up-down
  let sway = sin(phase * 2.2 + 0.6) * 0.17;          // side-to-side
  let squash = 1.0 + 0.17 * sin(phase * 6.0);        // pulse
  let fdir = normalize(dir + vec2f(0.0, 0.0001));    // guard the zero vector
  let side = vec2f(-fdir.y, fdir.x);
  var local = local0 - fdir * bob - side * sway;     // move the body as it dances
  local = vec2f(local.x * squash, local.y / squash); // squash & stretch
  let d2 = dot(local, local);
  let fwd = max(0.0, dot(local, fdir));              // ahead of center, along the facing
  let body = exp(-d2 * 5.0);                         // round glow body
  let nose = fwd * exp(-d2 * 2.2);                   // stretches the glow toward the facing
  // LOOK — brewed per player. 0 comet · 1 ring · 2 eyes · 3 spark.
  if (fx == 1) {
    let r = abs(sqrt(d2) - 0.5);                     // a dancing ring
    return tint * exp(-r * r * 45.0) * 1.7;
  }
  if (fx == 2) {
    let el = local - side * 0.30 - fdir * 0.10;      // two eyes, looking along the facing
    let er = local + side * 0.30 - fdir * 0.10;
    let eyes = exp(-dot(el, el) * 55.0) + exp(-dot(er, er) * 55.0);
    return tint * body * 1.2 + vec3f(1.0, 0.98, 0.9) * eyes * 0.8;
  }
  if (fx == 3) {
    let ang = atan2(local.y, local.x);               // a five-point spark, spinning on its beat
    let star = pow(max(0.0, cos(ang * 5.0 + phase * 2.0)), 6.0);
    return tint * exp(-d2 * 3.0) * (0.5 + star * 1.4) * 1.5;
  }
  // 0: comet glow (default)
  let g = body * 1.3 + nose * 1.6;
  let eye = local - fdir * 0.30;                     // a pupil pushed forward — a clear aim
  let pupil = exp(-dot(eye, eye) * 55.0) * body;
  return tint * g + vec3f(1.0, 0.98, 0.9) * pupil * 0.8;
}

fn visual_cf_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let mp = vec2f(uni(4), uni(5));     // cursor (uv coords)
  let cam = vec2f(uni(0), uni(1));
  let zm = uni(2);

  // ── the room: stars seen through curved space (your cursor is a lens) ──
  var p = uv;
  let md = uv - mp;
  let mr2 = max(dot(md, md), 0.002);
  p -= md * (0.010 / mr2) * smoothstep(0.9, 0.2, length(md));
  var col = cf_stars(p, t);

  // warm hearth-light from below — this is a cafe, not a void
  col += vec3f(0.10, 0.055, 0.02) * pow(max(0.0, uv.y + 0.2), 2.0) * (0.8 + 0.2 * sin(t * 0.7));

  // ── the bubble universe: live positions, pressure-ranked, explorable ──
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    let stRaw = i32(floor(sv));
    let st = stRaw % 200;
    let hue = fract(sv);
    let headCount = i32(uni(9 + i * 4) + 0.5);
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm;
    let hov = smoothstep(R * 1.9, R * 1.1, length(mp - ctr));
    let rr = R * (1.0 + hov * 0.12);
    if (d < rr) {
      let q = (uv - ctr) / rr;                     // -1..1 inside the disc
      var g = vec3f(0.0);
      if (st == 0) {
        // FABRIC — a lens wandering through stars
        var pp = q * 2.0;
        let lc = vec2f(sin(t * 0.6) * 0.5, cos(t * 0.47) * 0.4);
        let ld = pp - lc;
        pp -= ld * (0.16 / max(dot(ld, ld), 0.02));
        g = cf_stars(pp * 1.6, t) * 2.2;
        g += vec3f(0.5, 0.9, 1.1) * exp(-dot(ld, ld) * 14.0) * 0.4;
      } else if (st == 1) {
        // ORRERY — three worlds around a coal
        g = vec3f(0.02, 0.015, 0.03);
        g += vec3f(3.0, 1.7, 0.5) * exp(-dot(q, q) * 30.0);
        for (var k = 1; k <= 3; k++) {
          let fk = f32(k);
          let a = t * (0.9 - fk * 0.18) + fk * 2.1;
          let pp = q - vec2f(cos(a), sin(a)) * (0.22 + fk * 0.17);
          var pc = vec3f(0.45, 0.5, 0.65);
          if (k == 2) { pc = vec3f(0.2, 0.45, 0.8); }
          if (k == 3) { pc = vec3f(0.8, 0.5, 0.25); }
          g += pc * exp(-dot(pp, pp) * 260.0) * 1.6;
        }
      } else if (st == 2) {
        // GARNET — the crystal
        let qa = rotate(q, t * 0.4);
        let cd = abs(qa.x) * 0.866 + abs(qa.y) * 0.5;
        let inside = smoothstep(0.62, 0.58, max(cd, abs(qa.y)));
        let facet = 0.6 + 0.4 * sin(qa.x * 9.0 + qa.y * 7.0 + t * 0.8);
        g = mix(vec3f(0.02, 0.01, 0.02), vec3f(0.75, 0.18, 0.25) * facet, inside);
        g += vec3f(1.6, 0.9, 0.7) * pow(max(0.0, facet - 0.75) * 4.0, 2.0) * inside;
      } else if (st == 3) {
        // ONE DAY — a sky that keeps its whole day
        let ph = fract(t * 0.05);
        let el = sin(ph * 6.28318) * 0.8;
        let day = smoothstep(-0.2, 0.4, el);
        g = mix(vec3f(0.02, 0.02, 0.06), vec3f(0.25, 0.5, 0.8), day * (0.5 - q.y * 0.5));
        g = mix(g, vec3f(0.9, 0.4, 0.15), smoothstep(0.3, 0.0, abs(el)) * max(0.0, -q.y + 0.2) * 0.9);
        let sun = vec2f(cos(ph * 6.28318 - 1.57) * 0.6, -el * 0.55 + 0.1);
        g += vec3f(3.0, 2.0, 0.9) * exp(-dot(q - sun, q - sun) * 60.0) * max(day, 0.15);
        if (q.y > 0.25) { g = mix(g, g * vec3f(0.5, 0.6, 0.8), 0.6); }   // the sea below
      } else if (st == 4) {
        // SAIL — one boat, one sea
        g = mix(vec3f(0.35, 0.5, 0.65), vec3f(0.05, 0.14, 0.2), smoothstep(-0.1, 0.5, q.y));
        let w = sin(q.x * 9.0 + t * 1.4) * 0.05;
        g = mix(g, vec3f(0.03, 0.10, 0.14), smoothstep(w + 0.02, w - 0.02, -q.y + 0.1) * 0.0 + smoothstep(w - 0.02, w + 0.06, q.y - 0.05));
        let sail = max(max(-(q.x + 0.05) * 3.0, q.y + 0.15), (q.x * 0.9 + q.y * 0.8) - 0.28);
        g = mix(g, vec3f(1.0, 0.96, 0.88), smoothstep(0.02, -0.02, sail));
      } else if (st == 5) {
        // SOLSTICE — a sun you carry over a valley
        g = vec3f(0.03, 0.04, 0.09);
        let sp = vec2f(sin(t * 0.5) * 0.45, -0.3 + cos(t * 0.5) * 0.12);
        g += vec3f(3.2, 2.2, 0.9) * exp(-dot(q - sp, q - sp) * 40.0);
        let hill = q.y - (0.25 + 0.15 * sin(q.x * 3.0 + 1.0));
        let lit = max(0.0, 1.0 - length(q - sp) * 1.4);
        g = mix(g, mix(vec3f(0.03, 0.05, 0.02), vec3f(0.15, 0.3, 0.08), lit), smoothstep(-0.02, 0.02, hill));
      } else if (st == 6) {
        // TIDERUNNER — wind over water
        let band = sin(q.y * 14.0 - t * 1.1 + sin(q.x * 4.0) * 0.7);
        g = mix(vec3f(0.05, 0.13, 0.17), vec3f(0.12, 0.25, 0.3), 0.5 + 0.5 * band);
        g += vec3f(0.8, 0.85, 0.85) * pow(max(0.0, band - 0.8) * 5.0, 2.0) * 0.4;
        let bt = q - vec2f(sin(t * 0.4) * 0.4, 0.0);
        g += vec3f(0.9, 0.85, 0.75) * exp(-dot(bt, bt) * 300.0) * 1.2;
      } else if (st == 7) {
        // SIGNAL — a television waiting for a word
        let sn = hash21(floor(q * 24.0) + floor(t * 9.0));
        g = vec3f(sn * 0.5);
        g += vec3f(0.3, 1.0, 0.45) * exp(-dot(q, q) * 8.0) * (0.28 + 0.14 * sin(t * 2.0));
        g *= 0.82 + 0.18 * sin(q.y * 60.0 - t * 8.0);
      } else if (st >= 9) {
        // a real world — its screenshot, folded into the bubble by the shader
        g = cafeIcon(st - 9, q);
        g *= 0.9 + 0.2 * (1.0 - length(q));   // gentle spherical shading
      } else {
        // a young world — a banded seed-planet in its own hue
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * (0.22 + 0.5 * fbm3(q * 3.0 + vec2f(t * 0.08, f32(i) * 3.7)));
        g += cA * 0.4 * smoothstep(0.6, 1.0, 1.0 - abs(q.y * 2.2 + 0.3 * sin(q.x * 3.0 + t * 0.4)));
        let mn = q - vec2f(cos(t * 0.5 + f32(i) * 1.9), sin(t * 0.5 + f32(i) * 1.9) * 0.6) * 0.78;
        g += vec3f(0.85) * exp(-dot(mn, mn) * 260.0);
        g *= 0.85 + 0.3 * (1.0 - length(q));
      }
      // (the head-count number is gone — presence is the dancing players now)
      // glass edge + hover bloom
      let edge = smoothstep(1.0, 0.86, length(q));
      col = mix(col, g, edge);
      col += vec3f(1.2, 0.85, 0.4) * exp(-pow((length(q) - 0.97) * 9.0, 2.0)) * (0.25 + hov * 1.3);
    } else {
      // halo when hovered
      col += vec3f(1.0, 0.7, 0.3) * exp(-pow((d - rr) * 22.0, 2.0)) * hov * 0.8;
    }
    // presence players HOVER at the edge — half inside, half out — so they draw
    // in a band that spills BEYOND the disc, not clipped by the d<rr face mask.
    // Additive onto col; the SMALL scale of the cursor's big roaming effect.
    // One player per real occupant (headCount), up to 6.
    if (d < rr * 1.6) {
      let ql = (uv - ctr) / rr;                              // disc-local; >1 outside the bubble
      let nP = min(headCount, 6);
      for (var k = 0; k < nP; k++) {
        let ga = f32(k) * 2.39996 + f32(i) * 1.7;            // static seat around the rim
        let orb = vec2f(cos(ga), sin(ga));
        let plocal = (ql - orb) * 3.2;                       // seat ON the rim (radius 1.0), spilling out
        let hueK = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.16 + vec3f(0.0, 0.33, 0.67)));
        let ph = t * 1.5 + f32(k) * 1.3 + f32(i) * 0.7;      // each dances on its own beat
        col += cf_player(plocal, orb, ph, 0, hueK * 1.6) * 1.8; // hold the seat, dance in place
      }
    }
  }

  // the crown, over everything — the champion's ring outshines its neighbors
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    if (i32(floor(sv)) < 200) { continue; }
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm;
    let ringR = R * 1.24 + sin(t * 2.2) * 0.006;
    col += vec3f(1.0, 0.82, 0.32) * smoothstep(0.012, 0.002, abs(d - ringR)) * 1.3;
    col += vec3f(1.0, 0.7, 0.25) * exp(-max(d - R, 0.0) * 22.0) * 0.4;
  }

  // the local player — the "you" roaming the open grid, dancing in place. Its
  // look/hue/size are BREWED: read from the uniform tail (packed after all the
  // bubbles, so bubble offsets never move). fx, hue, size = uni(sb, sb+1, sb+2).
  let sb = 6 + i32(uni(3) + 0.5) * 4;
  let selfFx = i32(uni(sb) + 0.5);
  let selfHue = uni(sb + 1);
  let selfSize = max(uni(sb + 2), 0.25);
  let selfTint = 0.5 + 0.5 * cos(6.2831 * (selfHue + vec3f(0.0, 0.33, 0.67)));
  col += cf_player((uv - mp) * (4.5 / selfSize), vec2f(0.0, 1.0), t * 1.6, selfFx, selfTint * 1.3) * 1.1;
  col += selfTint * 0.9 * exp(-dot(uv - mp, uv - mp) * 1400.0) * 0.4;   // a soft core in your hue

  // the OTHER players — their live cursors, dancing, so you see them move around
  // the cafe. Packed after the self-icon: count at sb+3, then (x, y, hue) each.
  let ob = sb + 3;
  let nOthers = i32(uni(ob) + 0.5);
  for (var k = 0; k < nOthers; k++) {
    let opos = vec2f(uni(ob + 1 + k * 3), uni(ob + 2 + k * 3));
    let ohue = uni(ob + 3 + k * 3);
    let otint = 0.5 + 0.5 * cos(6.2831 * (ohue + vec3f(0.0, 0.33, 0.67)));
    col += cf_player((uv - opos) * 5.0, vec2f(0.0, 1.0), t * 1.6 + f32(k) * 1.7, 0, otint * 1.2) * 0.95;
    col += otint * 0.7 * exp(-dot(uv - opos, uv - opos) * 1600.0) * 0.35;   // a soft core in their hue
  }

  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(60.0)), 1.0);
}

fn ga_rd(q: vec3f, h: f32) -> f32 {
  // rhombic dodecahedron: max |dot(q, n)| over the six <110> normals, minus half-width
  let r2 = 0.70710678;
  var m = abs(dot(q, vec3f(r2, r2, 0.0)));
  m = max(m, abs(dot(q, vec3f(r2, -r2, 0.0))));
  m = max(m, abs(dot(q, vec3f(r2, 0.0, r2))));
  m = max(m, abs(dot(q, vec3f(r2, 0.0, -r2))));
  m = max(m, abs(dot(q, vec3f(0.0, r2, r2))));
  m = max(m, abs(dot(q, vec3f(0.0, r2, -r2))));
  return m - h;
}

fn ga_edge(q: vec3f) -> f32 {
  // crystal bevel: how close the two largest face distances are
  let r2 = 0.70710678;
  var a = abs(dot(q, vec3f(r2, r2, 0.0)));
  var b = abs(dot(q, vec3f(r2, -r2, 0.0)));
  if (b > a) { let t = a; a = b; b = t; }
  let c3 = abs(dot(q, vec3f(r2, 0.0, r2)));
  if (c3 > a) { b = a; a = c3; } else if (c3 > b) { b = c3; }
  let c4 = abs(dot(q, vec3f(r2, 0.0, -r2)));
  if (c4 > a) { b = a; a = c4; } else if (c4 > b) { b = c4; }
  let c5 = abs(dot(q, vec3f(0.0, r2, r2)));
  if (c5 > a) { b = a; a = c5; } else if (c5 > b) { b = c5; }
  let c6 = abs(dot(q, vec3f(0.0, r2, -r2)));
  if (c6 > a) { b = a; a = c6; } else if (c6 > b) { b = c6; }
  return smoothstep(0.045, 0.008, a - b);
}

fn ga_cellpos(packed: f32) -> vec3f {
  let ty = floor(packed / 1000.0);
  let idx = packed - ty * 1000.0;
  let kz = floor(idx / 81.0);
  let rem = idx - kz * 81.0;
  let jy = floor(rem / 9.0);
  let ix = rem - jy * 9.0;
  return (vec3f(ix, jy, kz) - vec3f(4.0)) * 0.62;
}
fn ga_celltype(packed: f32) -> f32 { return floor(packed / 1000.0); }

fn ga_rot(p: vec3f, yaw: f32, pitch: f32) -> vec3f {
  let cy = cos(yaw); let sy = sin(yaw);
  var q = vec3f(cy * p.x + sy * p.z, p.y, -sy * p.x + cy * p.z);
  let cp = cos(pitch); let sp = sin(pitch);
  return vec3f(q.x, cp * q.y - sp * q.z, sp * q.y + cp * q.z);
}

// scene SDF over all cells: returns (distance, cellIndex)
fn ga_map(p: vec3f) -> vec2f {
  let n = i32(uni(0));
  let H = 0.438;   // 0.62 / sqrt(2): faces kiss exactly
  var best = 1e5;
  var mat = -1.0;
  for (var i = 0; i < 56; i++) {
    if (i >= n) { break; }
    let packed = uni(8 + i);
    let c = ga_cellpos(packed);
    // cheap sphere reject before the six planes
    let ds = length(p - c) - 0.78;
    if (ds > best) { continue; }
    let d = ga_rd(p - c, H);
    if (d < best) { best = d; mat = f32(i); }
  }
  return vec2f(best, mat);
}

fn ga_stars(rd: vec3f, streak: f32, t: f32) -> vec3f {
  // starfield; streaks along +x when flying
  var c = vec3f(0.004, 0.005, 0.012);
  let sp = rd.yz * 22.0 + vec2f(rd.x * 4.0, 0.0);
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let cell = floor(sp * (1.0 + fl * 0.7) + fl * 13.0);
    let h = hash21(cell);
    let fp = fract(sp * (1.0 + fl * 0.7)) - 0.5;
    var star = step(0.985, h) * smoothstep(0.28, 0.04, length(fp));
    // streaking: smear along x with speed
    let fps = vec2f(fp.x / (1.0 + streak * 6.0), fp.y);
    star = max(star, step(0.985, h) * smoothstep(0.28, 0.04, length(fps)) * streak);
    c += vec3f(0.7, 0.75, 0.9) * star * (0.4 + 0.4 * sin(t * (0.5 + h) + h * 30.0));
  }
  // faint nebula
  c += vec3f(0.05, 0.02, 0.08) * pow(max(0.0, 1.0 - abs(rd.y * 1.6 - 0.2)), 3.0) * (0.5 + 0.5 * vnoise(rd.xz * 3.0));
  return c;
}

fn visual_ga_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let scr = vec2f(uv.x, -uv.y);
  let mode = uni(1);
  let yaw = uni(2);
  let pitch = uni(3);
  let plume = uni(5);
  let tumble = uni(6);
  let speed01 = uni(7);

  // orbit camera
  let R = 7.6;
  let ro0 = vec3f(R * cos(pitch) * cos(yaw), R * sin(pitch), R * cos(pitch) * sin(yaw));
  let fwd = normalize(-ro0);
  let right = normalize(cross(vec3f(0.0, 1.0, 0.0), fwd));
  let up = cross(fwd, right);
  var rd = normalize(fwd * 1.9 + right * scr.x + up * scr.y);
  let ro = ro0;

  var col = ga_stars(rd, speed01 * clamp(mode, 0.0, 1.0), time);

  // in flight the whole ship tumbles — rotate the RAY instead of every cell
  var rro = ro;
  var rrd = rd;
  if (mode > 0.5) {
    rro = ga_rot(ro, 0.0, tumble);
    rrd = ga_rot(rd, 0.0, tumble);
    rro = ga_rot(rro, tumble * 0.35, 0.0);
    rrd = ga_rot(rrd, tumble * 0.35, 0.0);
  }

  // march
  var t = 0.0;
  var hit = false;
  var mm = vec2f(0.0, -1.0);
  // whole-ship bounding sphere: pixels that can't hit anything never march
  let toC = -rro;
  let bClose = dot(toC, rrd);
  let bD2 = dot(toC, toC) - bClose * bClose;
  if (bD2 < 16.0 && bClose > 0.0) {
    t = max(0.0, bClose - 4.0);
    for (var i = 0; i < 44; i++) {
      let p = rro + rrd * t;
      mm = ga_map(p);
      if (mm.x < 0.0025) { hit = true; break; }
      t = t + mm.x * 1.08;
      if (t > bClose + 4.5) { break; }
    }
  }

  if (hit) {
    let p = rro + rrd * t;
    let e = 0.004;
    let d0 = mm.x;
    let nr = normalize(vec3f(
      ga_map(p + vec3f(e, 0.0, 0.0)).x - d0,
      ga_map(p + vec3f(0.0, e, 0.0)).x - d0,
      ga_map(p + vec3f(0.0, 0.0, e)).x - d0));
    let packed = uni(8 + i32(mm.y));
    let ty = ga_celltype(packed);
    let c = ga_cellpos(packed);
    let q = p - c;
    let edge = ga_edge(q);

    // materials by purpose — every component has a FEATURE, not just a color
    var alb = vec3f(0.5);
    var emis = vec3f(0.0);
    var gloss = 24.0;
    var ety = ty;
    var isGhost = false;
    if (ty > 5.5) { ety = ty - 6.0; isGhost = true; }   // ghost previews the real part

    let qn = normalize(q + vec3f(1e-5));
    if (ety < 0.5) {          // CORE — molten heart, pulsing veins
      alb = vec3f(0.55, 0.42, 0.20);
      let vein = smoothstep(0.55, 0.9, vnoise(q.xy * 9.0 + vec2f(time * 0.4, q.z * 9.0)));
      emis = vec3f(2.2, 1.3, 0.35) * (0.45 + 0.4 * sin(time * 2.2)) * (1.0 - edge) * (0.5 + vein);
      gloss = 60.0;
    } else if (ety < 1.5) {   // THRUSTER — gunmetal with a hot engine bell on the rear pole (-x)
      alb = vec3f(0.22, 0.24, 0.28);
      let bell = pow(max(0.0, dot(qn, vec3f(-1.0, 0.0, 0.0))), 6.0);
      alb = mix(alb, vec3f(0.10, 0.08, 0.07), bell * 0.7);
      let idle = 0.35 + 0.25 * sin(time * 3.0);
      emis = vec3f(2.0, 0.9, 0.25) * bell * max(idle, plume * 1.6);   // always glows: THIS is an engine
      gloss = 90.0;
    } else if (ety < 2.5) {   // TANK — steel drum with weld rings
      alb = vec3f(0.46, 0.52, 0.58) * (0.9 + 0.1 * vnoise(q.xy * 30.0));
      let ring = smoothstep(0.10, 0.04, abs(fract(q.x * 3.2 + 0.5) - 0.5));
      alb = mix(alb, vec3f(0.16, 0.18, 0.22), ring * 0.8);
      gloss = 120.0;
    } else if (ety < 3.5) {   // SOLAR — blue glass with a visible cell grid
      let irid = 0.5 + 0.5 * sin(dot(nr, vec3f(4.0, 7.0, 5.0)) + time * 0.3);
      alb = mix(vec3f(0.07, 0.12, 0.38), vec3f(0.15, 0.05, 0.38), irid);
      let gy = smoothstep(0.09, 0.03, abs(fract(q.y * 5.0) - 0.5));
      let gz = smoothstep(0.09, 0.03, abs(fract(q.z * 5.0) - 0.5));
      alb = mix(alb, vec3f(0.02, 0.03, 0.08), max(gy, gz) * 0.85);
      emis = vec3f(0.10, 0.16, 0.45) * irid * 0.5 * (1.0 - max(gy, gz));
      gloss = 200.0;
    } else if (ety < 4.5) {   // CARGO — strapped amber crate
      alb = vec3f(0.55, 0.38, 0.16) * (0.85 + 0.15 * vnoise(q.xz * 22.0));
      let strap = max(smoothstep(0.10, 0.04, abs(q.y)), smoothstep(0.10, 0.04, abs(q.z)));
      alb = mix(alb, vec3f(0.20, 0.13, 0.06), strap * 0.85);
      gloss = 30.0;
    } else {                  // SHIELD — humming crystal bubble
      alb = vec3f(0.50, 0.70, 0.78);
      let hum = 0.5 + 0.5 * sin(time * 1.6 + dot(qn, vec3f(3.0, 5.0, 4.0)));
      emis = vec3f(0.12, 0.35, 0.42) * (0.4 + 0.5 * hum);
      gloss = 160.0;
    }
    if (isGhost) {            // ghost: the part's own look, cyan-pulsed and hollow
      let pulse = 0.45 + 0.4 * sin(time * 5.0);
      emis = alb * pulse * 1.2 + emis * 0.6 + vec3f(0.2, 0.9, 1.1) * edge * 1.8 * pulse;
      alb = alb * 0.22;
    }

    // two-light studio + rim
    let L1 = normalize(vec3f(0.6, 0.75, -0.35));
    let L2 = normalize(vec3f(-0.55, -0.2, 0.6));
    let dif = clamp(dot(nr, L1), 0.0, 1.0) * 1.15 + clamp(dot(nr, L2), 0.0, 1.0) * 0.28;
    let hlf = normalize(L1 - rrd);
    let spec = pow(clamp(dot(nr, hlf), 0.0, 1.0), gloss) * 0.9;
    let fres = pow(clamp(1.0 + dot(rrd, nr), 0.0, 1.0), 3.0);
    var cc = alb * (vec3f(0.10, 0.11, 0.16) + vec3f(1.0, 0.95, 0.88) * dif);
    cc += vec3f(spec);
    cc += vec3f(0.35, 0.45, 0.7) * fres * 0.35;
    // crystal edges: darker bevel + a thread of light
    cc = mix(cc, cc * 0.35 + vec3f(0.5, 0.55, 0.65) * 0.35, edge * 0.85);
    cc += emis;
    col = cc;
  }

  // thruster plumes — additive glow, distance from the ray to points trailing each bell
  if (plume > 0.02) {
    let n = i32(uni(0));
    for (var i = 0; i < 56; i++) {
      if (i >= n) { break; }
      let packed = uni(8 + i);
      if (ga_celltype(packed) != 1.0) { continue; }
      let c = ga_cellpos(packed);
      for (var s = 1; s <= 3; s++) {
        let fs = f32(s);
        var pp = c - vec3f(fs * 0.5, 0.0, 0.0);   // exhaust streams -x (flight axis)
        if (mode > 0.5) {
          pp = ga_rot(pp, -tumble * 0.35, 0.0);
          pp = ga_rot(pp, 0.0, -tumble);
        }
        let w = pp - ro;
        let dRay = length(cross(rd, w));
        let flick = 0.8 + 0.25 * sin(time * 17.0 + fs * 2.0 + f32(i));
        col += vec3f(1.6, 0.75, 0.22) * exp(-dRay * dRay * (30.0 + fs * 22.0)) * plume * flick / fs;
      }
    }
  }

  return vec4f(col, 1.0);
}

fn visual_ga_hud(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // p = [selectedPart 1..5, fuel01, balance01 (1 = clean), mode]
  var c = vec3f(0.0);
  var a = 0.0;
  // component legend: thruster / tank / solar / cargo / shield — W/S moves the ring
  for (var i = 1; i <= 5; i++) {
    let fi = f32(i);
    var tint = vec3f(1.5, 0.55, 0.15);                       // thruster ember
    if (i == 2) { tint = vec3f(0.55, 0.62, 0.70); }          // tank steel
    if (i == 3) { tint = vec3f(0.25, 0.35, 1.2); }           // solar blue
    if (i == 4) { tint = vec3f(0.9, 0.55, 0.18); }           // cargo amber
    if (i == 5) { tint = vec3f(0.35, 0.95, 1.1); }           // shield cyan
    let ctr = vec2f(-0.72 + (fi - 1.0) * 0.36, 0.30);
    let q = (uv - ctr) * vec2f(7.0, 3.2);
    let d = length(q);
    let sel = select(0.0, 1.0, abs(p.x - fi) < 0.5);
    c += tint * exp(-d * d * (2.2 - sel * 0.8)) * (0.35 + 0.75 * sel);
    // selection ring
    c += vec3f(0.9, 1.0, 1.1) * exp(-pow((d - 0.75) * 6.0, 2.0)) * sel * (0.7 + 0.3 * sin(time * 6.0));
