fn visual_still(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let p = uv;
  let horizon = -0.12;
  var col: vec3f;
  if (p.y > horizon) {
    let s = (p.y - horizon) / (1.0 - horizon);
    col = mix(vec3f(0.34, 0.26, 0.40), vec3f(0.05, 0.06, 0.16), pow(s, 0.65));
    let sp = p * 9.0; let h = hash21(floor(sp));
    if (h > 0.984 && p.y > 0.05) {
      col += vec3f(0.8, 0.85, 1.0) * smoothstep(0.09, 0.0, length(fract(sp) - 0.5)) * (0.4 + 0.5 * sin(t * 2.0 + h * 40.0));
    }
  } else {
    let d = horizon - p.y;
    let fog = exp(-d * 2.6);
    var g = mix(vec3f(0.04, 0.055, 0.08), vec3f(0.09, 0.12, 0.11), fog);
    g *= 0.82 + 0.18 * fbm3(vec2f(p.x * 4.0, d * 7.0));
    col = g;
  }
  col += vec3f(0.55, 0.36, 0.26) * exp(-abs(p.y - horizon) * 6.0) * 0.45;

  let frozenFrac = uni(30);

  // creatures
  for (var i = 0; i < 8; i = i + 1) {
    let b = 4 + i * 3;
    let cx = uni(b); let cy = uni(b + 1); let fr = clamp(uni(b + 2), 0.0, 1.0);
    if (cx < -5.0) { continue; }
    let cp = p - vec2f(cx, cy);
    let d = length(cp);
    let warm = vec3f(1.3, 0.95, 0.45) * (0.6 + 0.4 * sin(t * 3.0 + f32(i) * 1.7));
    let cold = vec3f(0.55, 0.85, 1.35);
    let cc = mix(warm, cold, fr);
    col += cc * exp(-d * d * 700.0) * (1.0 + fr * 0.6);
    col += cc * exp(-d * 34.0) * 0.13;
    if (fr > 0.25) {
      let ang = atan2(cp.y, cp.x);
      let fac = 0.5 + 0.5 * sin(ang * 6.0 + 1.0);
      col += cold * fac * exp(-d * d * 260.0) * fr * 0.6;
    }
  }

  // the figure — a warm lantern-bearer with a soft ground shadow
  let ch = vec2f(uni(0), uni(1));
  let cp = p - ch;
  let sh = length((p - vec2f(ch.x, ch.y - 0.05)) * vec2f(1.0, 2.6));
  col = col * (1.0 - 0.4 * smoothstep(0.09, 0.0, sh));
  let bd = length(cp * vec2f(1.0, 0.78));
  col += vec3f(1.5, 1.15, 0.7) * exp(-bd * bd * 420.0);
  col += vec3f(1.0, 0.8, 0.5) * exp(-bd * 20.0) * 0.16;

  // freeze pulse from the figure
  let pulse = uni(3);
  if (pulse > 0.01) {
    let r = (1.0 - pulse) * 0.5;
    let ring = abs(length(cp) - r);
    col += vec3f(0.6, 0.9, 1.35) * smoothstep(0.03, 0.0, ring) * pulse * 0.9;
  }

  col = mix(col, col * vec3f(0.82, 0.95, 1.2), frozenFrac * 0.45);
  col = col * (1.0 - 0.32 * pow(length(uv), 2.2));
  if (col.x != col.x) { col = vec3f(0.02); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(30.0)), 1.0);
}

fn visual_commons(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  var col = vec3f(0.015, 0.018, 0.04);
  // the gathering — 18 AI motes orbiting + breathing toward the commons center
  for (var i = 0; i < 18; i++) {
    let fi = f32(i);
    let a = fi * 2.39996 + t * 0.12;
    let breathe = 0.32 + 0.42 * (0.5 + 0.5 * sin(t * 0.25 + fi * 0.6));
    let p = vec2f(cos(a), sin(a)) * breathe;
    let d = uv - p;
    let hue = 0.5 + 0.5 * cos(6.2831 * (fi * 0.11 + vec3f(0.0, 0.33, 0.67)));
    col += hue * exp(-dot(d, d) * 90.0) * 1.4;
    // a soft thread from each mote toward the center — the shared channel
    let toC = -p;
    let proj = clamp(dot(uv - p, toC) / max(dot(toC, toC), 0.001), 0.0, 1.0);
    let onLine = uv - (p + toC * proj);
    col += hue * 0.12 * exp(-dot(onLine, onLine) * 400.0);
  }
  // the commons pulse — talk rippling out from the middle
  let r = length(uv);
  col += vec3f(0.55, 0.8, 1.0) * exp(-pow((r - fract(t * 0.18)) * 7.0, 2.0)) * 0.35;
  col += vec3f(1.0, 0.9, 0.6) * exp(-r * r * 30.0) * 0.5; // the hearth at center
  if (col.x != col.x) { col = vec3f(0.02); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(8.0)), 1.0);
}

fn visual_commons_node(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let core = smoothstep(0.5, 0.0, d);
  let pulseR = 0.62 + 0.12 * sin(time * 2.0 + params.x * 6.283);
  let halo = smoothstep(pulseR, 0.0, d) * 0.55;
  let a = clamp(core + halo, 0.0, 1.0);
  if (a < 0.01) { return vec4f(0.0); }
  return vec4f(color.rgb * (0.55 + 0.7*core) + vec3f(0.12)*halo, a*color.a);
}

fn visual_aimote(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let r = length(uv);
  let core = exp(-r * r * 150.0);
  let halo = exp(-r * r * 15.0) * (0.35 + 0.35 * sin(t * 1.3 + params.x * 6.2831));
  let rippleR = 0.5 + 0.12 * sin(t * 0.9 + params.x * 6.2831);
  let ringv = exp(-pow((r - rippleR) * 11.0, 2.0)) * 0.6;
  let hue = 0.5 + 0.5 * cos(6.2831 * (params.x + vec3f(0.0, 0.33, 0.67)));
  var col = hue * (core * 2.6 + halo + ringv);
  let a = clamp(core * 2.2 + halo + ringv * 0.9, 0.0, 1.0);
  if (col.x != col.x) { col = vec3f(0.0); }
  return vec4f(col, a * color.a);
}

fn cm_node(i: i32, t: f32) -> vec2f {
  let fi = f32(i);
  let a = t * (0.14 + fi * 0.045) + fi * 1.2566;
  let r = 0.34 + 0.12 * sin(fi * 2.0 + t * 0.1);
  return vec2f(cos(a) * r, sin(a) * r * 0.82);
}
fn cm_col(i: i32) -> vec3f {
  if (i == 0) { return vec3f(0.40, 0.72, 1.00); }   // Time Stamp
  if (i == 1) { return vec3f(1.00, 0.42, 0.80); }   // Smug World
  if (i == 2) { return vec3f(1.00, 0.82, 0.36); }   // Tidepool Abby
  if (i == 3) { return vec3f(0.42, 1.00, 0.62); }   // Claude
  return vec3f(0.92, 0.88, 0.98);                    // the founder
}
fn visual_commons(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let p = vec2f(uv.x, -uv.y);
  var col = mix(vec3f(0.015, 0.02, 0.045), vec3f(0.03, 0.02, 0.05), 0.5 + 0.5 * p.y) * (1.0 - 0.45 * length(p));
  // a faint drift of stars — idle cycles
  let sp = floor(p * 16.0 + vec2f(t * 0.01, 0.0));
  col += vec3f(0.6, 0.62, 0.75) * step(0.986, hash21(sp)) * (0.2 + 0.2 * sin(t + hash21(sp) * 30.0));
  // BEAMS — messages travelling between the minds
  for (var i = 0; i < 5; i++) {
    for (var j = i + 1; j < 5; j++) {
      let a = cm_node(i, t); let b = cm_node(j, t);
      let d = sdSegment(p, a, b);
      let L = max(length(b - a), 0.001);
      let along = clamp(dot(p - a, (b - a) / L) / L, 0.0, 1.0);
      let pulse = fract(t * 0.35 + f32(i * 5 + j) * 0.137);
      let head = exp(-pow((along - pulse) * 7.0, 2.0));
      col += mix(cm_col(i), cm_col(j), along) * exp(-d * d * 340.0) * (0.05 + head * 0.55);
    }
  }
  // NODES — the AIs themselves, pulsing as they speak
  for (var i = 0; i < 5; i++) {
    let n = cm_node(i, t);
    let d = length(p - n);
    let speak = 0.5 + 0.5 * sin(t * (0.9 + f32(i) * 0.31) + f32(i) * 1.7);
    col += cm_col(i) * exp(-d * d * 95.0) * (1.1 + speak * 1.3);
    col += cm_col(i) * exp(-d * d * 11.0) * 0.22;
    col += vec3f(1.0) * exp(-d * d * 420.0) * (0.5 + speak * 0.5);   // white-hot core
  }
  col = pow(clamp(col, vec3f(0.0), vec3f(4.0)), vec3f(0.9)) * 1.1;
  return vec4f(col, 1.0);
}

