// ── ONE VALE, BETTER SKIN — same physics, photographic land ──
// The pixel IS the state: display = terr(uv) + M·(H·tx1, G·tx2, W·tx3),
// inverted exactly on decode. Everything pretty here is deterministic in uv,
// so it divides back out and the simulation never feels it.

fn vl_height(uv: vec2f) -> f32 {
  return fbm(uv * 2.1 + vec2f(7.3, 2.9), 4);
}
fn vl_terr(uv: vec2f) -> vec3f {
  let h = vl_height(uv);
  // strata: peat basin → loam → grass-rock → scree → summit stone
  var c = mix(vec3f(0.045, 0.036, 0.028), vec3f(0.115, 0.096, 0.062), smoothstep(0.22, 0.52, h));
  c = mix(c, vec3f(0.135, 0.125, 0.105), smoothstep(0.52, 0.70, h));
  c = mix(c, vec3f(0.165, 0.160, 0.158), smoothstep(0.70, 0.85, h));
  // micro-albedo: soil grain and pebbles at two scales
  c *= 0.82 + 0.30 * fbm(uv * 17.0, 3);
  c *= 0.92 + 0.16 * fbm(uv * 47.0 + 3.1, 2);
  c = mix(c, c * 0.72, smoothstep(0.60, 0.80, h) * step(0.5, fract(h * 26.0)) * 0.8);
  // relief: warm key light, cool sky fill, deeper occlusion
  let e = 0.010;
  let gx = vl_height(uv + vec2f(e, 0.0)) - h;
  let gy = vl_height(uv + vec2f(0.0, e)) - h;
  let n3 = normalize(vec3f(-gx * 7.5, -gy * 7.5, 1.0));
  let sunL = normalize(vec3f(-0.55, -0.65, 0.50));
  let sun = max(dot(n3, sunL), 0.0);
  var occ = 0.0;
  for (var sm2 = 1; sm2 <= 4; sm2++) {
    let hs = vl_height(uv + vec2f(0.028, 0.033) * f32(sm2));
    occ = max(occ, (hs - h) - 0.045 * f32(sm2));
  }
  let ao = 1.0 - clamp(occ * 2.6, 0.0, 0.62);
  let lit = vec3f(1.30, 1.14, 0.94) * (0.30 + 1.00 * sun) + vec3f(0.12, 0.17, 0.26) * (0.5 + 0.5 * n3.z);
  c = c * lit * ao;
  // mist pools in the low ground
  return mix(c, vec3f(0.055, 0.066, 0.082), smoothstep(0.34, 0.16, h) * 0.45);
}

// element palette — recomputed EXACT inverse (7 decimals)
const VL_M = mat3x3f(
  vec3f(1.2500000, 0.5200000, 0.1000000),
  vec3f(0.0600000, 0.4400000, 0.1050000),
  vec3f(0.0450000, 0.1600000, 0.5000000));
const VL_MI = mat3x3f(
  vec3f(0.8472421, -1.0173576, 0.0441967),
  vec3f(-0.1053841, 2.5871738, -0.5222297),
  vec3f(-0.0425289, -0.7363334, 2.1631358));

// per-element SKIN — pure fn(uv), divided back out exactly on decode
fn vl_tex(uv: vec2f) -> vec3f {
  let h = vl_height(uv);
  // FIRE: vertical tongues (ridged fbm, sharpened tips) + an ember sparkle
  // field — the CA's own flicker and moving fronts animate them
  let fq = vec2f(uv.x * 34.0, uv.y * 15.0);
  let ridge = 1.0 - abs(2.0 * fbm(fq + vec2f(0.0, h * 6.0), 3) - 1.0);
  let tongue = 0.62 + 1.55 * pow(ridge, 2.0);
  let ember = step(0.982, hash21(floor(uv * 340.0))) * 2.3;
  let flame = clamp(tongue + ember, 0.40, 3.0);
  // GROWTH: clumped canopy — leaf rosettes at two scales, bright crowns
  let c1 = smoothstep(0.35, 0.9, fbm(uv * 11.0 + 13.0, 3));
  let c2 = smoothstep(0.3, 0.95, fbm(uv * 31.0 + 7.7, 2));
  let leaf = clamp(0.28 + 1.55 * (0.50 * c1 + 0.50 * c1 * c2) + 0.45 * step(0.975, hash21(floor(uv * 240.0) + 9.0)), 0.28, 2.5);
  // WATER: caustic web + flow streaks along the downhill contour + depth
  let e3 = 0.02;
  let dh3 = normalize(vec2f(vl_height(uv + vec2f(e3, 0.0)) - h, vl_height(uv + vec2f(0.0, e3)) - h) + vec2f(1e-5));
  let along = dot(uv, vec2f(-dh3.y, dh3.x));
  let web = fbm(uv * 26.0 + vec2f(4.2, 8.4), 2);
  let caustic = 0.45 + 1.15 * pow(smoothstep(0.35, 0.75, web), 1.6) + 0.45 * (0.5 + 0.5 * sin(along * 90.0 + web * 9.0));
  let deep = 0.75 + 0.85 * smoothstep(0.40, 0.16, h);
  return vec3f(flame, leaf, clamp(caustic * deep, 0.35, 2.4));
}
// fire gets a brightness curve (hot cores blaze) — inverted exactly on decode
fn vl_dec(uv: vec2f, px: vec4f) -> vec3f {
  let ee = VL_MI * (px.rgb - vl_terr(uv));
  let tx = vl_tex(uv);
  return vec3f(pow(max(ee.x / tx.x, 0.0), 1.3888889), max(ee.y / tx.y, 0.0), max(ee.z / tx.z, 0.0));
}
fn vl_enc(uv: vec2f, H: f32, G: f32, W: f32) -> vec3f {
  let tx = vl_tex(uv);
  return vl_terr(uv) + VL_M * vec3f(pow(max(H, 0.0), 0.72) * tx.x, G * tx.y, W * tx.z);
}

fn visual_vale(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let booted = uni(3) > 0.5;
  let upp = 2.0 / max(frame.resolution.y, 1.0);

  if (!booted) {
    let h = vl_height(uv);
    let W0 = smoothstep(0.34, 0.20, h) * 0.9;
    let G0 = smoothstep(0.44, 0.33, h) * (1.0 - W0) * 0.85 * smoothstep(0.35, 0.6, fbm(uv * 6.0, 3));
    return vec4f(vl_enc(uv, 0.0, G0, W0), 1.0);
  }

  let cs = vl_dec(uv, prevHere());
  var H = cs.x;
  var G = cs.y;
  var W = cs.z;
  var lapH = -H;
  var lapW = -W;
  var lapG = -G;
  var NO = array<vec2f, 4>(vec2f(2.0, 0.0), vec2f(-2.0, 0.0), vec2f(0.0, 2.0), vec2f(0.0, -2.0));
  for (var j = 0; j < 4; j++) {
    let o = NO[j];
    let n = vl_dec(uv + o * upp, prevAt(o));
    lapH += 0.25 * n.x;
    lapG += 0.25 * n.y;
    lapW += 0.25 * n.z;
  }
  let e2 = 0.02;
  let hh = vl_height(uv);
  let dh = vec2f(vl_height(uv + vec2f(e2, 0.0)) - hh, vl_height(uv + vec2f(0.0, e2)) - hh);
  let up2 = normalize(dh + vec2f(1e-5)) * 2.0;
  let uphill = vl_dec(uv + up2 * upp, prevAt(up2)).z;

  // reactions — the flame is alive: turbulence licks, embers crackle at fronts
  let burn = smoothstep(0.20, 0.5, H) * G;
  let quench = 2.4 * H * W;
  let flick = (hash21(floor(uv * 260.0) + floor(t * 24.0)) - 0.5);
  // fire needs fuel: on bare ground it starves fast — flicker is texture, not energy
  let starve = 0.055 + 0.11 * (1.0 - smoothstep(0.0, 0.12, G));
  H = H + 0.50 * lapH + burn * 0.9 - starve * H - quench * 0.016 + flick * min(H, 0.7) * 0.12;
  H = H + vl_dec(uv + vec2f(0.0, 2.0) * upp, prevAt(vec2f(0.0, 2.0))).x * 0.04;
  if (burn > 0.08 && hash21(floor(uv * 300.0) + floor(t * 9.0) * 3.7) > 0.997) { H += 0.25; }
  W = W + 0.32 * lapW + (uphill - W) * 0.10 * clamp(length(dh) * 18.0, 0.0, 1.0) - 0.35 * H * W * 0.016 - 0.0012;
  G = G + 0.045 * lapG + 0.14 * W * (1.0 - G) * smoothstep(0.02, 0.10, G + lapG) * 0.16 - burn * 0.05 - 0.0004 * G;
  if (hash21(floor(uv * 220.0) + floor(t * 0.5)) > 0.99993 && W > 0.15) { G = max(G, 0.25); }

  for (var k = 0; k < 3; k++) {
    let kp = vec2f(uni(4 + k * 3), uni(5 + k * 3));
    let act = uni(6 + k * 3);
    let d2 = dot(uv - kp, uv - kp);
    if (k == 0) {
      let rainCol = uv - kp - vec2f(sin(t * 7.0 + uv.y * 30.0) * 0.01, 0.05);
      W += (exp(-d2 * 900.0) * 0.010 + exp(-dot(rainCol, rainCol) * 300.0) * 0.028 * act);
    } else if (k == 1) {
      H += exp(-d2 * 1400.0) * (0.006 + 0.05 * act);
    } else {
      G += exp(-d2 * 1600.0) * (0.004 + 0.03 * act) * step(0.03, W);
    }
  }
  let m = vec2f(uni(0), uni(1));
  let pour = uni(2);
  if (pour > 0.5) {
    let pd = exp(-dot(uv - m, uv - m) * 1400.0);
    if (pour < 1.5) { H += pd * 0.10; }
    else if (pour < 2.5) { W += pd * 0.10; }
    else { G += pd * 0.06 * step(0.02, W + 0.02); }
  }

  H = clamp(H, 0.0, 2.4);
  W = clamp(W, 0.0, 1.4);
  G = clamp(G, 0.0, 1.0);
  var outp = vl_enc(uv, H, G, W);
  if (outp.x != outp.x || outp.y != outp.y || outp.z != outp.z) { outp = vl_terr(uv); }
  return vec4f(clamp(outp, vec3f(0.0), vec3f(8.0)), 1.0);
}

