try {
  const wd = sim.worldData
  // ═══ QUANTIC DOJO — The Evolution of Tic-Tac-Toe · © 2014 Galen Radtke ═══
  // Xin (X, magenta) and Ohn (O, green) duel on the diamond. Place a piece in
  // the central nine, it attacks; pushes chain; three-in-a-row wins the bout.
  const K = [
    { n: 'Spear',          t: [-1, 0],  m: [-1, 0] },
    { n: 'Sai',            t: [-1, 1],  m: [-1, 1] },
    { n: 'Ninjato',        t: [-1, 0],  m: [0, -1] },
    { n: 'Nunchaku',       t: [-1, 0],  m: [0, 1] },
    { n: 'Giant Shurikin', t: [-2, 0],  m: [-1, 0], rng: 1 },
    { n: 'Arrows',         t: [-2, 2],  m: [-1, 1], rng: 1 },
    { n: 'Exotic Blade',   t: [-1, 0],  m: [1, -1] },
    { n: 'Kusarigama',     t: [-1, 0],  m: [1, 1] },
    { n: 'Ramen',          t: [-1, 0],  m: [1, 0], both: 1 },
    { n: 'Bomb',           t: [-1, 0],  m: [1, 0], bomb: 1 },
    { n: 'Potion',         t: [-1, -1], rot: 1, any: 1 },
    { n: 'Kunai',          t: [-1, 1],  dec: 1 },
  ]
  const inMask = (r, c) => Math.abs(r - 4) + Math.abs(c - 4) <= 4
  const central9 = (r, c) => Math.abs(r - 4) <= 1 && Math.abs(c - 4) <= 1
  const CELL = 40
  const px = (r, c) => [256 + (c - 4) * CELL, 252 + (r - 4) * CELL]
  const rotV = (v, k) => { let o = [v[0], v[1]]; for (let i = 0; i < ((k % 4) + 4) % 4; i++) o = [o[1], -o[0]]; return o }

  if (!wd.__qd || wd.__qd.v !== 5) {
    const tiles = []
    for (let p = 0; p < 2; p++) for (let k = 0; k < 12; k++)
