    wd.__qd = { v: 5, tiles, turn: 0, tn: 1, phase: 0, sel: -1, gr: 0, first: 0, ai: 1, aiT: 0, hseat: -1, preSel: -1,
                win: -1, why: '', wl: [], pend: null, elig: [], moved: [], keys: {}, mh: 0 }
