    for (const t of T) { if (t.on === 1 && t.hits >= 3) { mark(t); t.on = -1; t.r = t.c = -9; tone(120, 0.4, 0.3, 'sawtooth') } t.hits = 0 }
    const a = lines3(0), b = lines3(1)
    if (a.length && b.length) return crown(2, [], 'both hold Three-In-A-Row — a DRAW, honors even')
    if (a.length) return crown(0, a[0], 'THREE-IN-A-ROW')
    if (b.length) return crown(1, b[0], 'THREE-IN-A-ROW')
