try {
  const wd = sim.worldData
  // ── QUANTIC DOJO — after PHILOSOPHY, the tabletop game by Galen Radtke ──
  // Two minds at a fire. Place Ideas, let them push each other, and the first
  // to hold three in a row has reached a Conclusion.
  const KINDS = [
    { n: 'Push',            t: [-1, 0],  m: [-1, 0] },
    { n: 'Corner Push',     t: [-1, 1],  m: [-1, 1] },
    { n: 'Slide Left',      t: [-1, 0],  m: [0, -1] },
    { n: 'Slide Right',     t: [-1, 0],  m: [0, 1] },
    { n: 'Long Shot',       t: [-2, 0],  m: [-1, 0] },
    { n: 'Corner Long Shot',t: [-2, 2],  m: [-1, 1] },
    { n: 'Pull Left',       t: [-1, 0],  m: [1, -1] },
    { n: 'Pull Right',      t: [-1, 0],  m: [1, 1] },
    { n: 'Persuade',        t: [-1, 0],  m: [1, 0], both: 1 },
    { n: 'Toss',            t: [-1, 0],  m: [1, 0], toss: 1 },
    { n: 'Rephrase',        t: [-1, -1], rot: 1, any: 1 },
    { n: 'Decision',        t: [-1, 1],  dec: 1 },
  ]
  const HW = [1, 2, 3, 3, 3, 2, 1]           // stepped cross: 7 rows, halfwidths
  const inMask = (r, c) => r >= 0 && r <= 6 && Math.abs(c - 3) <= HW[r]
  const center9 = (r, c) => r >= 2 && r <= 4 && c >= 2 && c <= 4
  const CELL = 46, BX = 256, BY = 248
  const px = (r, c) => [BX + (c - 3) * CELL, BY + (r - 3) * CELL]
  const rotV = (v, k) => { let o = [v[0], v[1]]; for (let i = 0; i < ((k % 4) + 4) % 4; i++) o = [o[1], -o[0]]; return o }

  if (!wd.__qd || wd.__qd.v !== 1) {
    const tiles = []
    for (let p = 0; p < 2; p++) for (let k = 0; k < 12; k++)
      tiles.push({ id: p * 12 + k, p, k, rot: 0, r: -1, c: -1, on: 0, acted: -1, ax: 0, ay: 0, at: 0, down: 0 })
    wd.__qd = { v: 1, tiles, turn: 0, tn: 1, phase: 0, sel: -1, gr: 0, first: 0,
                win: -1, why: '', wl: [], pend: null, elig: [], moved: [], resp: 0, keys: {}, mh: 0, snd: 0 }
    // dock seats
    for (const t of tiles) {
      const col = Math.floor(t.k / 6), row = t.k % 6
      t.dx = t.p === 0 ? 34 + col * 44 : 434 + col * 44
      t.dy = 108 + row * 52
      t.ax = t.dx; t.ay = t.dy; t.at = -9
    }
  }
  const S = wd.__qd
  const T = S.tiles
  const at = (r, c) => T.find(t => t.on === 1 && t.r === r && t.c === c)
  const now = (S.clk = (S.clk || 0) + Math.min(dt || 0.016, 0.1))
  const mx = wd.mouse_x, my = wd.mouse_y, md = wd.mouse_down
  const hasM = typeof mx === 'number'
  const click = md && !S.mh && hasM
  const keyEdge = k => { const n = wd['key_' + k + '_n'] || 0; const was = S.keys[k] || 0; S.keys[k] = n; return n > was }
  const tone = (f, d, v, ty) => { wd.__play_sound = { frequency: f, duration: d || 0.12, volume: v || 0.22, type: ty || 'sine' } }

  const tgtCell = t => { const o = rotV(KINDS[t.k].t, t.rot); return [t.r + o[0], t.c + o[1]] }
  const mark = t => { const [pxx, pyy] = t.on === 1 ? px(t.r, t.c) : [t.dx, t.dy]; t.ax = pxx; t.ay = pyy; t.at = now }
  // move every tile in the line starting at (r,c) one step along dir; the
  // outermost moves first; past the rim an Idea goes home to its hand
  const lineMove = (r, c, dir) => {
    const seq = []
    let rr = r, cc = c
    while (inMask(rr, cc) && at(rr, cc)) { seq.push(at(rr, cc)); rr += dir[0]; cc += dir[1] }
    const moved = []
    for (let i = seq.length - 1; i >= 0; i--) {
      const t = seq[i], nr = t.r + dir[0], nc = t.c + dir[1]
      mark(t)
      if (!inMask(nr, nc)) { t.on = 0; t.acted = -1; t.rot = 0; tone(180, 0.25, 0.3, 'triangle') }
      else { t.r = nr; t.c = nc }
      moved.push(t.id)
    }
    return moved
  }
  const resolveImpact = (tl, vt, choice) => {
    const K = KINDS[tl.k]
    let moved = []
    if (K.rot) { mark(vt); vt.rot = choice; moved = [vt.id]; if (vt.p === tl.p) vt.acted = -1 }
    else if (K.dec) { const d = rotV(choice === 0 ? [-1, -1] : [-1, 1], tl.rot); moved = lineMove(vt.r, vt.c, d) }
    else if (K.both) {
      const back = rotV([1, 0], tl.rot), or = tl.r, oc = tl.c
      moved = lineMove(tl.r, tl.c, back)
      mark(vt); vt.r = or; vt.c = oc; moved.push(vt.id)
    } else if (K.toss) {
      const back = rotV([1, 0], tl.rot), dr = tl.r + back[0], dc = tl.c + back[1]
      mark(vt)
      if (!inMask(dr, dc)) { vt.on = 0; vt.acted = -1; vt.rot = 0 }
      else { moved = lineMove(dr, dc, back); vt.r = dr; vt.c = dc }
      moved.push(vt.id)
