    afterActivation()
  }
  const afterActivation = () => {
    const mv = new Set(S.moved)
    const el = []
    for (const t of T) {
      if (t.on !== 1 || t.p !== S.turn || t.acted === S.tn || KINDS[t.k].rot) continue
      const [tr, tc] = tgtCell(t)
      if (!inMask(tr, tc)) continue
      const v = at(tr, tc)
      if (!v || v.p === S.turn) continue
      if (mv.has(t.id) || mv.has(v.id)) el.push(t.id)
    }
    if (el.length === 0) return endTurn()
    if (el.length === 1) return beginActivate(T[el[0]])
    S.elig = el; S.phase = 1
  }
  const beginActivate = tl => {
    S.elig = []
    const [tr, tc] = tgtCell(tl)
    const vt = at(tr, tc)
    if (!vt) return endTurn()
    const K = KINDS[tl.k]
    if (K.dec) { S.pend = { t: tl.id, v: vt.id }; S.phase = 2; return }
    if (K.rot) { S.pend = { t: tl.id, v: vt.id, rot: vt.rot }; S.phase = 3; return }
    resolveImpact(tl, vt, 0)
  }
  const lines3 = p => {
    const out = []
    for (let r = 0; r <= 6; r++) for (let c = 0; c <= 6; c++) {
      if (!inMask(r, c)) continue
      for (const d of [[0, 1], [1, 0], [1, 1], [1, -1]]) {
        const cells = [[r, c], [r + d[0], c + d[1]], [r + 2 * d[0], c + 2 * d[1]]]
        if (cells.every(([rr, cc]) => inMask(rr, cc) && at(rr, cc) && at(rr, cc).p === p && !at(rr, cc).down)) out.push(cells)
      }
    }
    return out
  }
  const endTurn = () => {
    S.phase = 0; S.pend = null; S.elig = []; S.moved = []
    const a = lines3(0), b = lines3(1)
    if (a.length && !b.length) return crown(0, a[0], 'a CONCLUSION — three Ideas in a row')
    if (b.length && !a.length) return crown(1, b[0], 'a CONCLUSION — three Ideas in a row')
    S.turn = 1 - S.turn; S.tn++
    // can the new speaker place at all?
    const hand = T.some(t => t.p === S.turn && t.on === 0)
    let room = false
    for (let r = 2; r <= 4; r++) for (let c = 2; c <= 4; c++) if (!at(r, c)) room = true
    if (!hand) return crown(1 - S.turn, [], (S.turn ? 'TEAL' : 'INDIGO') + ' has no Ideas left')
    if (!room) return crown(1 - S.turn, [], 'the center of the conversation is full')
    S.sel = -1
  }
  const crown = (p, cells, why) => {
    S.win = p; S.wl = cells; S.why = why; S.phase = 4
    tone(523, 0.5, 0.3); setTimeout(() => {}, 0)
  }
  const reset = () => { delete wd.__qd }

  // ── input ──
  if (keyEdge('r') && S.phase === 0) S.gr = (S.gr + 1) % 4
  if (S.phase === 4) { if (click) reset() }
  else if (click && hasM) {
    // respect token — pure grace, passed by hand
    if (Math.hypot(mx - 256, my - 40) < 20) { S.resp = 1 - S.resp; tone(880, 0.3, 0.18, 'triangle') }
    // rotate button
    else if (Math.hypot(mx - (S.turn === 0 ? 56 : 456), my - 452) < 20 && S.phase === 0) { S.gr = (S.gr + 1) % 4; tone(440, 0.06, 0.15) }
    // AGREE (concede)
    else if (S.phase === 0 && Math.abs(mx - 256) < 34 && my > 468 && my < 496) {
      const t = T.find(t => t.p === S.turn && t.on === 0)
      if (t) { t.on = 1; t.down = 1; outer: for (let r = 2; r <= 4; r++) for (let c = 2; c <= 4; c++) if (!at(r, c)) { t.r = r; t.c = c; break outer } mark(t) }
      crown(1 - S.turn, [], (S.turn ? 'TEAL' : 'INDIGO') + ' honorably AGREES')
    }
    else if (S.phase === 0) {
      // dock select (your own unplayed)
      let hit = null
      for (const t of T) if (t.p === S.turn && t.on === 0 && Math.abs(mx - t.dx) < 21 && Math.abs(my - t.dy) < 21) hit = t
      if (hit) { S.sel = hit.k; S.gr = 0; tone(392, 0.07, 0.15) }
      else if (S.sel >= 0) {
        const c = Math.round((mx - BX) / CELL) + 3, r = Math.round((my - BY) / CELL) + 3
        const centerBlock = !S.first && r === 3 && c === 3
        if (inMask(r, c) && center9(r, c) && !at(r, c) && !centerBlock) {
