      if (Math.hypot(mx - pxx, my - pyy) < 22) { S.pend.rot = (S.pend.rot + 1) % 4; vt.rot = S.pend.rot; tone(440, 0.05, 0.12) }
      else if (Math.abs(mx - 256) < 34 && my > 468 && my < 496) { const tl = T[S.pend.t]; S.pend = null; S.phase = 0; resolveImpact(tl, vt, vt.rot) }
    }
  }
  S.mh = md ? 1 : 0

  // ── publish ──
  const U = new Array(256).fill(0)
  U[0] = S.turn; U[1] = S.phase; U[2] = S.sel; U[5] = S.gr; U[6] = S.win
  U[7] = now; U[8] = S.resp; U[9] = S.first
  U[10] = hasM ? mx : -99; U[11] = hasM ? my : -99
  for (let i = 0; i < 3; i++) { const c = S.wl[i]; U[12 + i * 2] = c ? c[0] : -9; U[13 + i * 2] = c ? c[1] : -9 }
  if (S.phase === 2 && S.pend) {
    const tl = T[S.pend.t], vt = T[S.pend.v]
    for (const ch of [0, 1]) { const d = rotV(ch === 0 ? [-1, -1] : [-1, 1], tl.rot); U[18 + ch * 2] = vt.r + d[0]; U[19 + ch * 2] = vt.c + d[1] }
  } else { U[18] = -9; U[20] = -9 }
  // ghost
  U[3] = -9; U[4] = -9
