    const c = Math.round((mx - BX) / CELL) + 3, r = Math.round((my - BY) / CELL) + 3
    if (inMask(r, c) && center9(r, c) && !at(r, c) && !(!S.first && r === 3 && c === 3)) { U[3] = r; U[4] = c }
  }
  U[22] = S.pend ? S.pend.v : -1
  U[23] = S.sel
  const eset = new Set(S.elig)
  for (const t of T) {
    const B = 30 + t.id * 7
    let tx = t.dx, ty = t.dy
    if (t.on === 1) { const [pxx, pyy] = px(t.r, t.c) ; tx = pxx; ty = pyy }
    const k = Math.min(1, (now - t.at) / 0.24)
    const e = 1 - (1 - k) * (1 - k)
    U[B] = t.ax + (tx - t.ax) * e; U[B + 1] = t.ay + (ty - t.ay) * e
    U[B + 2] = t.rot; U[B + 3] = t.k; U[B + 4] = t.p
    U[B + 5] = t.down ? 3 : t.on === 1 ? 1 : 0.5   // both hands always on the table
    U[B + 6] = eset.has(t.id) ? 1 : (S.pend && S.pend.v === t.id ? 2 : (t.on === 0 && t.k === S.sel && t.p === S.turn ? 3 : 0))
  }
  wd.gpuUniforms = U

  // ── the table talk (HUD) ──
  const who = S.turn === 0 ? 'INDIGO' : 'TEAL'
  let l1 = '', l2 = ''
  if (S.phase === 0) { l1 = who + ' — share an Idea'; l2 = S.sel >= 0 ? KINDS[S.sel].n + ' · R or ↻ rotates · place it in the center nine' : 'pick an Idea from your side · AGREE (bottom) concedes' }
  else if (S.phase === 1) { l1 = who + ' — your Ideas stir'; l2 = 'click ONE glowing Idea to activate it' }
  else if (S.phase === 2) { l1 = who + ' — a Decision'; l2 = 'click the space the targeted Idea should slide to' }
  else if (S.phase === 3) { l1 = who + ' — Rephrase'; l2 = 'click the Idea to turn it · click AGREE-spot below to settle it' }
  else if (S.phase === 4) { l1 = (S.win === 0 ? 'INDIGO' : 'TEAL') + ' PREVAILS — ' + S.why; l2 = 'click anywhere for a new conversation' }
  wd.hud = [
    { id: 'qd1', type: 'text', x: '50%', y: '18px', color: S.turn === 0 && S.phase !== 4 ? '#8f86e8' : '#5fd3cb', fontSize: '15px', textAlign: 'center', transform: 'translateX(-50%)', text: l1 },
    { id: 'qd2', type: 'text', x: '50%', y: '40px', color: '#c9b896', fontSize: '11px', textAlign: 'center', transform: 'translateX(-50%)', text: l2 },
  ]
} catch (e) {
  sim.worldData.hud = [{ id: 'qderr', type: 'text', x: '14px', y: '104px', color: '#ff6060', fontSize: '12px', text: 'HOOK ERR: ' + String(e).slice(0, 120) }]
}

