            const v = parseInt(n.slice(vAt + 4), 10) || 0
            const base = n.slice(0, vAt)
            if (!best[base] || v > best[base].v) best[base] = { v, scene: n, style: STYLE_OF[n.slice(0, f)] ?? 8 }
          }
          for (const base of Object.keys(best)) {
