    if (zB.r > 0.01 && Math.hypot(qx - zB.lx, qz - zB.lz) < zB.r) { f *= (zB.rule === 5 ? 0.18 : zB.rule === 6 ? 2.2 : 1.0) }
    return f
  }

  // ── PLAYER — a body in the field: your step is scaled by the cell underfoot ──
  const pf = factorAt(V.px, V.pz)
  const step = sdt * pf
  if (V.lx == null) { V.lx = ptr.x != null ? ptr.x : 256; V.ly = ptr.y != null ? ptr.y : 256 }
  const mx = ptr.x != null ? ptr.x : V.lx, my = ptr.y != null ? ptr.y : V.ly
  const absS = 0.006, relS = 0.0052
