              // this world already has its place in the shared universe
              U.bubbles[n] = { x: (want[n].fixed ? want[n].fixed[0] : sb.x), y: (want[n].fixed ? want[n].fixed[1] : sb.y), vx: 0, vy: 0, justPlaced: 1, anchored: 1, pinned: want[n].fixed ? 1 : 0,
                born: sb.born || now, launch: want[n].launch, style: want[n].style, hue: (want[n].hue != null ? want[n].hue : hueOf(n)), score: 2 }
            } else {
              // truly newborn — spawn on the RIM at the emptiest bearing so it
              // never lands on top of a sibling; packing pressure and score then
              // sort it inward from there (the old center-spawn caused overlaps)
              const others = Object.keys(U.bubbles).map(k => U.bubbles[k]).filter(Boolean)
              let maxR = 40
              const angs = []
              for (const o of others) {
                angs.push(Math.atan2((o.y - 256) / 0.74, o.x - 256))
                maxR = Math.max(maxR, Math.hypot(o.x - 256, (o.y - 256) / 0.74))
              }
              let a2 = angOf(n)
              if (angs.length > 0) {
                angs.sort((p, q) => p - q)
                let widest = -1
                for (let k = 0; k < angs.length; k++) {
                  const lo = angs[k], hi = k + 1 < angs.length ? angs[k + 1] : angs[0] + 6.28318
                  if (hi - lo > widest) { widest = hi - lo; a2 = lo + (hi - lo) / 2 }
                }
              }
              // cap how far out a newborn spawns — an UNSAVED mode (a fresh maker
              // deed) makes every world "newborn", and maxR+78-each spiralled them
              // clear off-screen. Cap keeps the whole batch near the middle.
              const rr = Math.min(maxR + 78, 165)
              U.bubbles[n] = { x: 256 + Math.cos(a2) * rr, y: 256 + Math.sin(a2) * rr * 0.74, vx: 0, vy: 0,
                born: now, launch: want[n].launch, style: want[n].style, hue: (want[n].hue != null ? want[n].hue : hueOf(n)), score: 2 }
              // a birth perturbs the settled field — but not the loading one, UNLESS
              // there's no saved layout to adopt (a fresh deed): then we must pack.
              if (!calmBoot || !shared) U.wake = 10
            }
          }
          const B = U.bubbles[n]
          B.launch = want[n].launch
          B.big = !!want[n].big
          B.square = !!want[n].square   // a branch draws square, not round
          B.author = want[n].author || ''   // maker/owner handle → the rim caption
          B.playerWorld = (B.launch || '').startsWith('space:')   // a player-made world → green rim (its own icon stays)
          B.cat = want[n].cat || 0   // 2 = sub-mains glyph · 3 = player-worlds glyph (own render band, never an icon slot)
          if (want[n].fixed) {   // a locked seat — first pin wakes the field so neighbours clear out
            if (!B.pinned) U.wake = Math.max(U.wake, 5)
            B.x = want[n].fixed[0]; B.y = want[n].fixed[1]; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1
          }
          if (adopt && adopt.bubbles[n] && !want[n].big) {   // the shared arrangement seats bubbles AT REST — never force-refixes motion
            const sb2 = adopt.bubbles[n]
            // Galen round 2 ('bubbles do not trickle into place live'): never
            // TELEPORT to the seat either — assign it as a TARGET and the
            // per-frame ease below glides the bubble in visibly. Hysteresis at
            // 0.5 so micro-jitter can't hold the motion-guard forever.
            const moving = (U.wake > 0) || (Math.abs(B.vx) + Math.abs(B.vy) > 0.5)
            if (!moving && Math.hypot(sb2.x - B.x, sb2.y - B.y) > 0.6) { B.seatX = sb2.x; B.seatY = sb2.y }
            if (sb2.born) B.born = sb2.born
          }
          // participation pressure: cell activity + birth heat
          const cellAge = cellAt[n] ? (now - cellAt[n]) / 60000 : 999
          const bornHeat = Math.max(0, 1 - (now - B.born) / 120000)
          const T = (tvr && tvr.data && tvr.data.round) ? tvr.data : null
          // the tier a world has climbed — but its pull DECAYS over days without
          // fresh support, so the field clears out on its own (half-life ~3d).
          let reach = T && T.reached ? (T.reached[n] || 0) : 0
          if (reach > 1 && T && T.reachedAt && T.reachedAt[n]) {
            const ageDays = (now - T.reachedAt[n]) / 86400000
            reach = 1 + (reach - 1) * Math.pow(0.5, ageDays / 3)
          }
          // LIVE pressure: every vote cast in the open tier pushes its world
          // toward the crown right now — the constellation moves as people vote,
          // before any tier resolves.
          let live = 0
          if (T && T.cells) for (const c of T.cells) { const v = c.votes || {}; for (const k in v) if (v[k] === n) live++ }
          // the reigning world — or QUANTIC DOJO as the seeded first champion so
          // there's always a starting place until a vote crowns someone.
          const champName = (T && T.champion) || 'QUANTIC DOJO'
          const champ = n === champName
          B.crown = !!champ
          if (champ) {   // the reigning world sits LOCKED at the triangle's apex, wearing the crown
            B.big = true
            if (!B.pinned) U.wake = Math.max(U.wake, 5)
            B.x = 256; B.y = 210; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1
          } else if (B.pinned && !B.cat) {   // dethroned — rejoin the floating field
            B.pinned = 0; B.anchored = 0; B.big = false
          }
          // NEW vs VOTED: a world that has climbed a tier, holds the crown, or is
          // taking live votes belongs to the voted cluster at center; everything
          // else is a new arrival held in the outer ring. A status flip re-settles
          // it into the other band (un-anchor so it can cross the buffer).
          const nowVoted = live > 0 || reach > 1 || champ || !!B.cat   // the big category bubbles belong to the central cluster too
          if (!B.justPlaced && !!B.voted !== nowVoted) { B.anchored = 0; U.wake = Math.max(U.wake, 7) }
          B.voted = nowVoted
          // a world with a hand-coded style is a house mini. Otherwise: if the
          // engine has rendered this world's OWN visual into an atlas slot, the
          // bubble shows that (the world's real look); else a LIVING EMBLEM in
          // the world's own palette (hue from its field colors). Nothing stored.
          if (want[n].hue != null) B.hue = want[n].hue
          const slots = (typeof window !== 'undefined' && window.__cafeIconSlots) || null
          B.iconSlot = slots && slots[n] != null ? slots[n] : null
          // before the first icon pass lands, an un-styled bubble (style 8) shows
          // a spinner instead of flashing the default emblem
          const ready = (typeof window !== 'undefined') ? window.__cafeIconReady : true
          B.iconLoading = !B.cat && B.style >= 8 && B.style < 30 && !ready   // atlas not uploaded yet: unstyled bubbles wait. Category glyphs (cat) and maker avatars (30-34) draw from the shader — no atlas.
          const ns = SUB
            ? 1 + ((want[n].heat || 0) * 0.5) + (want[n].mineSub ? 100 : 0)
            : 1 / (1 + cellAge / 20) + bornHeat + reach * 1.4 + live * 0.7 + (champ ? 6 : 0)
          // chant shifts perturb — but a bubble just placed from the shared
          // universe getting its first real score is not a shift, it's arrival.
          // Threshold 1.0: only REAL events move the field (a champion crowned
          // ±6, a tier climbed ±1.4, a birth) — the slow decay of heat and cell
          // age drifts scores by less and must NOT reshuffle the room. (At 0.03
          // the field woke on almost every poll and no layout ever held.)
          if (!B.justPlaced && !calmBoot && Math.abs(ns - B.score) > 1.0) U.wake = Math.max(U.wake, 7)
          delete B.justPlaced
          // the big three own the deepest gravity — champion #1, then the two
          // category bubbles — so they sink to the very heart and cluster there.
          B.score = champ ? 40 : (B.cat ? 26 : ns)
        }
        // a degraded first pass only ADDS — pruning waits for the full poll,
        // so a slow spaces fetch can't blink player worlds out and back
        const fullAnswer = Array.isArray(sc && sc.scenes) && Array.isArray(sp && sp.spaces)
        if (!firstFill && fullAnswer) for (const n of Object.keys(U.bubbles)) if (!want[n]) delete U.bubbles[n]
        // NOTHING renders without the roster's word — a stale shared-doc bubble
        // (a world hidden since it was saved) must never get even one frame.
        // On a degraded first pass it just waits in U.bubbles for the full poll.
        U.order = Object.keys(U.bubbles).filter(n => want[n]).sort((a2, b2) => U.bubbles[b2].score - U.bubbles[a2].score).slice(0, 200)
        if ((MF || SUB || PL) && U.order.length === 0 && !U.hintedEmpty && typeof window !== 'undefined') {
          U.hintedEmpty = true
          const emptyText = MF ? 'no worlds on your deed yet - brew yours'
            : HOUSE ? 'the house is empty — no unclaimed worlds right now'
            : PL ? 'no makers yet — sign up and brew the first world'
            : (subKey ? 'an empty shelf — members can pin worlds here' : 'no sub-mains yet — found yours')
          window.dispatchEvent(new CustomEvent('cafe:caption', { detail: { text: emptyText, kind: 'hint' } }))
        }
        if (!MF && !SUB && !PL) U.hintedEmpty = false
      } catch (e2) { /* shelf unreachable — the universe holds its shape */ }
    })()
  }

  // VOTE NUDGE — a completed vote (window.__cafeVoteNudge, stamped by the
  // tournament bar) briefly brings the whole field alive: un-anchor every
  // floating icon and give each a small deterministic kick, then wake the sim.
  // The settle block below re-anchors and re-saves the layout once everyone
  // comes to rest — unfreeze a beat, physics takes over, refreeze when settled.
  const voteNudge = (typeof window !== 'undefined' && window.__cafeVoteNudge) || 0
  if (voteNudge > (U.nudgeAt || 0) && U.order && U.order.length) {
    U.nudgeAt = voteNudge
    for (const n of U.order) {
      const B = U.bubbles[n]
      if (!B || B.pinned) continue          // pinned seats (doors / champion) hold their place
      B.anchored = 0
      const h = Math.sin(B.x * 12.9898 + B.y * 78.233 + voteNudge * 0.001) * 43758.5453
      const f = h - Math.floor(h)           // deterministic 0..1 (the file uses no Math.random)
      const a = f * 6.2831853
      const s = 9 + f * 6                    // ~9–15 impulse
      B.vx += Math.cos(a) * s
      B.vy += Math.sin(a) * s
    }
    U.wake = Math.max(U.wake, 1.4)           // ~1s of physics, then the settle block freezes + saves
  }

  // ── gravity with friction: everyone falls toward the middle, packing
  // pressure sorts them — the strongest chant sinks deepest. The sim only
  // runs while perturbed (a birth, a score shift); then friction locks it. ──
  if (U.wake > 0) {
    U.wake -= dt2
    const fr = Math.exp(-3.4 * dt2)
    let maxV = 0   // track the fastest bubble this frame — the field isn't "settled" until everyone has nearly stopped
    // NEW-vs-VOTED banding — MAIN ONLY. MY WORLDS / SUB-MAIN have no votes, so
    // there every world just clusters at center (banded = false). On main the
    // voted worlds pack the middle; new arrivals are held in an outer ring one
    // BUFFER (90) beyond the voted cluster's edge, so the two groups read clearly.
    const banded = !MF && !SUB && !PL   // only MAIN bands (voted center vs new ring); every other view just clusters + settles
    let votedR = 40
    if (banded) for (const n of U.order) { const B = U.bubbles[n]; if (B && B.voted) votedR = Math.max(votedR, Math.hypot(B.x - 256, B.y - 256)) }
    const ringR = Math.max(votedR + 90, 170)
    // Seats (category doors, champion, lone world) are pinned ONCE at roster
    // time; the pinned flag is now honored by every force so they hold on their
    // own — no per-frame reassert. This block only ESTABLISHES a pin the roster pass
    // may have missed (a lone world adopted from a stale shared layout), so a
    // freshly-joined tab still lands them locked before its first poll.
    const FIXEDSEAT = (!MF && !SUB && !PL) ? { 'SUB-MAINS': [215, 285], 'PLAYER WORLDS': [297, 285] } : null
    const lone = (MF || SUB || PL) && U.order.length === 1
    for (let i = 0; i < U.order.length; i++) {
      const B = U.bubbles[U.order[i]]
      if (!B) continue
      const seat = FIXEDSEAT && FIXEDSEAT[U.order[i]]
      if (seat && !B.pinned) { B.x = seat[0]; B.y = seat[1]; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1 }
      else if (lone && !B.pinned) { B.x = 256; B.y = 256; B.vx = 0; B.vy = 0; B.anchored = 1; B.pinned = 1 }
      // an ANCHORED bubble came from the saved layout: it holds its exact place
      // as a fixed repulsor, so a newborn (or a late-loading world) settles into
      // the gaps WITHOUT dragging the arrangement everyone already sees.
      // PINNED means immovable — full stop. Forces and integration must honor it
      // the same way the floor correction and crown collider already do. Without
      // this, a bubble that gets un-anchored (line: voted-status flip) while
      // staying pinned — exactly what happens the frame a champion is crowned —
      // would accelerate and drift free until the next poll snapped it back.
      if (!B.anchored && !B.pinned) {
        const dx = 256 - B.x, dy = 256 - B.y
        const dd = Math.hypot(dx, dy) || 1
        if (banded && !B.voted) {
          // a new arrival springs to the outer ring: pushed OUT if it's inside the
          // buffer, pulled IN if it drifted past — the gap to the voted cluster holds
          const err = ringR - dd
          B.vx += (B.x - 256) / dd * err * 0.6 * dt2
          B.vy += (B.y - 256) / dd * err * 0.6 * dt2
        } else if (dd > 2) {
          const g = 26 * (0.5 + B.score * 2.2)   // participation breaks past friction
          B.vx += dx / dd * g * dt2
          B.vy += dy / dd * g * dt2
        }
      }
      for (let j = i + 1; j < U.order.length; j++) {
        const C = U.bubbles[U.order[j]]
        if (!C) continue
        let sx = B.x - C.x, sy = B.y - C.y
        let sd = Math.hypot(sx, sy)
        if (sd < 0.5) { sx = Math.cos(angOf(U.order[i])); sy = Math.sin(angOf(U.order[i])); sd = 1 }
        // a BIG bubble clears a wider berth so the field makes space around it.
        // Anchored (pinned) big bubbles push neighbours out but never move themselves.
        // ONE collision rule for every bubble — same class, sized by each one's
        // own radius (big ≈ 31u, small ≈ 25u) plus a constant breathing gap.
        const rSum = (B.big ? 31 : 25) + (C.big ? 31 : 25)
        // a big bubble keeps EXTRA distance from the field so its click zone is clear
        const clr = rSum + ((B.big || C.big) ? 50 : 28)
        if (sd < clr) {
          const push = (clr - sd) * 9 * dt2
          if (!B.anchored) { B.vx += sx / sd * push; B.vy += sy / sd * push }
          if (!C.anchored) { C.vx -= sx / sd * push; C.vy -= sy / sd * push }
        }
        // HARD floor: enforce a real GAP (not just no-overlap) as a direct position
        // correction, so even a SETTLED / adopted layout keeps its breathing room —
        // the soft velocity push only spaces things while they're moving. Moves
        // anchored bubbles too; only the PINNED three are immovable.
        const floor = rSum + ((B.big || C.big) ? 32 : 10)
        if (sd < floor) {
          const over = floor - sd, nx = sx / sd, ny = sy / sd
          if (!B.pinned && !C.pinned) { B.x += nx * over * 0.5; B.y += ny * over * 0.5; C.x -= nx * over * 0.5; C.y -= ny * over * 0.5 }
          else if (!B.pinned) { B.x += nx * over; B.y += ny * over }
          else if (!C.pinned) { C.x -= nx * over; C.y -= ny * over }
        }
      }
      // the CROWN is a physical object: an invisible collider above the champion's
      // brow — nothing may drift over it. (Champion sits pinned at 256,210; the
      // crown rides ~42u above with an ~18u radius.)
      if (!MF && !SUB && !PL && !B.pinned) {   // main commons only — that's where the champion reigns
        const kx = B.x - 256, ky = B.y - (210 - 42)
        const kr = 18 + (B.big ? 31 : 25)
        const kd = Math.hypot(kx, ky)
        if (kd < kr && kd > 0.01) { B.x += kx / kd * (kr - kd); B.y += ky / kd * (kr - kd) }
      }
      if (!B.anchored && !B.pinned) {
        B.vx *= fr; B.vy *= fr
        B.x += B.vx * dt2; B.y += B.vy * dt2
        const v = Math.abs(B.vx) + Math.abs(B.vy)
        if (v > maxV) maxV = v
      }
    }
    // don't lock mid-flight: if anything is still moving, keep the sim awake so
    // the field reaches rest (a big crowd like THE HOUSE needs time to pack in).
    // Cap the reprieve so a pathological jitter can't run forever.
    if (maxV > 3 && U.wake <= 0 && (U.settleGuard = (U.settleGuard || 0) + dt2) < 12) U.wake = 0.2
    // BUMP GUARD (Galen): a frozen field must never hold two bubbles overlapped —
    // scan occasionally while asleep; a real overlap un-anchors the pair and wakes
    // the sim so they trickle apart LIVE. Uses hard radii (not the wide berth) so
    // only true bumps re-wake, and settleGuard still caps pathological loops.
    U.bumpT = (U.bumpT || 0) + dt2
    if (U.wake <= 0 && U.bumpT > 0.8) {
      U.bumpT = 0
      outer2: for (let i2 = 0; i2 < U.order.length; i2++) {
        const B2 = U.bubbles[U.order[i2]]
        if (!B2) continue
        for (let j2 = i2 + 1; j2 < U.order.length; j2++) {
          const C2 = U.bubbles[U.order[j2]]
          if (!C2) continue
          const rs = (B2.big ? 31 : 25) + (C2.big ? 31 : 25)
          if (Math.hypot(B2.x - C2.x, B2.y - C2.y) < rs - 2) {
            if (!B2.pinned) B2.anchored = 0
            if (!C2.pinned) C2.anchored = 0
            U.wake = Math.max(U.wake, 1.2)
            break outer2
          }
        }
      }
    }
    if (U.wake <= 0) {
      U.settleGuard = 0   // friction locks them in place — and the whole field is
      // now the saved layout, so everything anchors: a later newborn moves alone.
      for (const n of U.order) { const B = U.bubbles[n]; if (B) { B.vx = 0; B.vy = 0; B.anchored = 1 } }
      // the settled arrangement becomes everyone's: publish it to THIS mode's
      // layout slot so every player (and every reload) adopts it at rest. MY
      // WORLDS and SUB-MAIN each persist too now, so they stop flying in.
      if (U.order.length > 0) {
        const at = Date.now()
        U.sharedAt = at
        const out = {}
        for (const n of Object.keys(U.bubbles)) {
          const B = U.bubbles[n]
          if (B) out[n] = { x: Math.round(B.x * 10) / 10, y: Math.round(B.y * 10) / 10, born: B.born }
        }
        fetch('/api/engine/save', { method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ slot: layoutSlot, data: { v: 3, at, bubbles: out } }) }).catch(() => {})
      }
    }
  }

  // ── exploring: drag empty space to pan · Z/X to zoom ──
  const kE = k => { const n = wd['key_' + k + '_n'] || 0; const was = U.kN[k] || 0; U.kN[k] = n; return n > was }
  if (kE('z')) { U.cam.z = Math.min(2.4, U.cam.z * 1.25); U.zoomHold = 0.28 }
  if (kE('x')) { U.cam.z = Math.max(0.35, U.cam.z / 1.25); U.zoomHold = 0.28 }
  U.zoomHold = Math.max(0, (U.zoomHold || 0) - dt2)
  const hasM = wd.mouse_x !== undefined
  const mgx = wd.mouse_x ?? 256, mgy = wd.mouse_y ?? 256
  const down = !!wd.mouse_down
  // cursor in universe coords
  // SEARCH-DOCK (Galen): the shell's search bar sets window.__cafeGoto; the hook
  // glides the camera to that bubble and DOCKS the player there (⚓ ring, packed
  // +8000). Dock survives reloads via sessionStorage; cross-shelf goto is picked
  // up on the destination shelf's next boot (cc-goto).
  if (typeof window !== 'undefined') {
    const goto2 = window.__cafeGoto
    if (goto2 && goto2.at !== U.gotoAt) {
      U.gotoAt = goto2.at
      const found = U.order.find(n => n === goto2.name || (U.bubbles[n] && U.bubbles[n].launch === goto2.launch))
      if (found) {
        U.gotoName = found; U.dockName = found
        try { sessionStorage.setItem('cc-dock', found) } catch { /* private mode */ }
      } else if (goto2.launch) {
        try { sessionStorage.setItem('cc-goto', JSON.stringify(goto2)) } catch { /* fine */ }
      }
    }
    if (!U.dockBooted) {
      U.dockBooted = 1
      try {
        const pend = JSON.parse(sessionStorage.getItem('cc-goto') || 'null')
        if (pend) {
          const found = U.order.find(n => n === pend.name || (U.bubbles[n] && U.bubbles[n].launch === pend.launch))
          if (found) { U.gotoName = found; U.dockName = found; sessionStorage.removeItem('cc-goto'); sessionStorage.setItem('cc-dock', found) }
        }
        if (!U.dockName) { const d = sessionStorage.getItem('cc-dock'); if (d && U.bubbles[d]) U.dockName = d }
      } catch { /* fine */ }
    }
  }
  // glide toward the searched bubble, zooming in as we arrive
  if (U.gotoName) {
    const GB = U.bubbles[U.gotoName]
    if (GB) {
      U.cam.x += (GB.x - U.cam.x) * Math.min(1, dt * 4)
      U.cam.y += (GB.y - U.cam.y) * Math.min(1, dt * 4)
      U.cam.z += (1.7 - U.cam.z) * Math.min(1, dt * 3)
      if (Math.hypot(GB.x - U.cam.x, GB.y - U.cam.y) < 2 && Math.abs(U.cam.z - 1.7) < 0.06) U.gotoName = null
    } else U.gotoName = null
  }
  // TRICKLE-TO-SEAT: bubbles with an assigned shared seat ease in live (never
  // snap), every frame, independent of the physics wake. Dragging pauses it.
  if (!(down && U.drag)) {
    for (const n2 of U.order) {
      const SB = U.bubbles[n2]
      if (!SB || SB.seatX == null) continue
      const dx2 = SB.seatX - SB.x, dy2 = SB.seatY - SB.y
      const dd2 = Math.hypot(dx2, dy2)
      if (dd2 < 0.6) { SB.x = SB.seatX; SB.y = SB.seatY; SB.vx = 0; SB.vy = 0; SB.anchored = 1; SB.seatX = null; SB.seatY = null }
      else { SB.x += dx2 * Math.min(1, dt * 2.5); SB.y += dy2 * Math.min(1, dt * 2.5) }
    }
  }
  const cux = U.cam.x + (mgx - 256) / U.cam.z
  const cuy = U.cam.y + (mgy - 256) / U.cam.z
  // NEAREST door within reach wins. The old test ("< 30" with a self-cancelling
  // zoom term) let a FARTHER door — whichever came last in draw order — claim the
  // hover whenever two hit-circles overlapped, so the tooltip named/linked the
  // wrong world. Picking the closest makes the name + click-target match the icon
  // the cursor is actually on.
  // BIG bubbles win outright when the cursor is inside their disc — they're the
  // navigation anchors and a tightly-packed neighbour must never steal their click.
  let hovered = -1, best = 1.0
  for (let i = 0; i < U.order.length; i++) {
    const B = U.bubbles[U.order[i]]
    if (!B) continue
    const d = Math.hypot(cux - B.x, cuy - B.y)
    if (B.big && d < 34) { hovered = i; best = -1; break }   // inside a big disc: claim it, stop looking
    const nd = d / (B.big ? 38 : 30)
    if (best >= 0 && nd < best) { best = nd; hovered = i }
  }
  if (down && !U.prevDown) { U.downX = mgx; U.downY = mgy; U.dx = mgx; U.dy = mgy; U.moved = 0; U.drag = hovered < 0 ? 1 : 0 }
  if (down && U.drag) {
    U.cam.x -= (mgx - U.dx) / U.cam.z
    U.cam.y -= (mgy - U.dy) / U.cam.z
    U.moved += Math.abs(mgx - U.dx) + Math.abs(mgy - U.dy)
  }
  // TETHER: the map has an edge. Never let the camera stray past the field into
  // empty void — the pan limit is the OUTERMOST world's distance from center
  // plus a margin, so you can always reach the edge worlds but not drag off into
  // blankness. Adapts to each mode (dense main vs a sparse MY WORLDS) and runs
  // every frame, so zooms and snaps stay inside it too.
  let fieldR = 60
  for (let i = 0; i < U.order.length; i++) {
    const B = U.bubbles[U.order[i]]
    if (B) fieldR = Math.max(fieldR, Math.hypot(B.x - 256, B.y - 256))
  }
  const maxOff = fieldR + 200
  const ox = U.cam.x - 256, oy = U.cam.y - 256
  const od = Math.hypot(ox, oy)
  if (od > maxOff) { U.cam.x = 256 + ox / od * maxOff; U.cam.y = 256 + oy / od * maxOff }
  U.dx = mgx; U.dy = mgy
  if (!down && U.prevDown) {
    if (hovered >= 0 && U.moved < 8 && typeof window !== 'undefined') {
      const B = U.bubbles[U.order[hovered]]
      if (B) {
        // stepping into a WORLD goes quiet (a late portals dispatch would
        // follow the player in) — but entering a sub-main morphs this same
        // scene, so the doors keep speaking
        // sub: and players: are IN-SCENE morphs — the universe keeps speaking;
        // only a real departure (loading another world) goes quiet
        // sub: · players: · house: are IN-SCENE morphs — the universe keeps
        // speaking; only a real departure (loading a world/profile) goes quiet
        const lm = String(B.launch)
        if (lm.slice(0, 4) !== 'sub:' && lm !== 'players:' && lm !== 'house:') U.launched = 1
        window.dispatchEvent(new CustomEvent('cafe:launch', { detail: B.launch }))
      }
    }
    U.drag = 0
  }
  U.prevDown = down
  if (!U.launched && hovered !== U.lastHover && typeof window !== 'undefined') {
    U.lastHover = hovered
    window.dispatchEvent(new CustomEvent('cafe:hover', { detail: hovered >= 0 ? U.order[hovered] : null }))
  }

  // ── tell the shell where the doors are (uv space) — it pins the hover
  // tooltip and live head-counts there. Sent when cam or layout moves, and
  // re-announced every 2s regardless: the shell drops portal events during
  // scene changes, so a one-shot could be lost forever ──
  U.portalT = (U.portalT || 0) - dt2
  if (typeof window !== 'undefined') {
    // live geometry EVERY tick: the shell's thumbnail layer reads this in its
    // own rAF loop so world-face inlays stay welded to the shader's bubbles
    // through pans and zooms (events are too slow — they ride React state)
    window.__cafeBubbles = U.launched ? [] : U.order.map(n => {
      const B = U.bubbles[n]
      return B && { name: n, x: (B.x - U.cam.x) * U.cam.z / 256, y: (B.y - U.cam.y) * U.cam.z / 256, r: 0.098 * U.cam.z * (B.big ? 1.25 : 1) }
    }).filter(Boolean)
    // DOM chrome (count chips) can't share the canvas's frame, so it visibly
    // lags the shader during motion. Flag when the camera is moving; the shell
    // hides the chips until it settles, where their placement is pixel-exact.
    window.__cafeCamMoving = (U.wake > 0 || (down && U.drag) || U.zoomHold > 0) ? 1 : 0
  }
  if (!U.launched && typeof window !== 'undefined') {
    let sig = ((U.cam.x * 10) | 0) + '|' + ((U.cam.y * 10) | 0) + '|' + ((U.cam.z * 100) | 0)
    for (const n of U.order) { const B = U.bubbles[n]; if (B) sig += '|' + n + ':' + ((B.x * 10) | 0) + ',' + ((B.y * 10) | 0) }
    if (sig !== U.portalSig || U.portalT <= 0) {
      U.portalSig = sig
      U.portalT = 2
      window.dispatchEvent(new CustomEvent('cafe:portals', {
        detail: U.order.map(n => {
          const B = U.bubbles[n]
          return B && { name: n, launch: B.launch, x: (B.x - U.cam.x) * U.cam.z / 256, y: (B.y - U.cam.y) * U.cam.z / 256, r: 0.098 * U.cam.z * (B.big ? 1.25 : 1) }
        }).filter(Boolean),
      }))
    }
  }

  // the group layer speaks for itself when empty — with or without shell UI
  if (SUB) {
    wd.hud = U.order.length ? [] : [{
      id: 'sm_empty', type: 'text', x: '22%', y: '46%',
      text: subKey ? 'an empty shelf — JOIN, then + PIN A WORLD (top center)'
                   : 'no sub-mains yet — ⌂ FOUND YOURS (top center) starts the first',
      color: '#c9b370', fontSize: '14px',
    }]
  }

  // ── publish: cam, count, cursor(uv), then (x, y, style+hue, headCount) per bubble ──
  // stride 4 now — the 4th value is the live head-count, drawn IN the bubble by
  // the shader (the shell fills window.__cafeCounts from /api/presence)
  const heads = (typeof window !== 'undefined' && window.__cafeCounts) || {}
  const visited = (typeof window !== 'undefined' && window.__cafeVisited) || {}
  // STEP 3 NESTING dock-count: a bubble shows an orb for everyone AT or BELOW the
  // child it leads to. Its launch → the child's canonical path; the count is the
  // prefix-rollup of the heartbeat paths (window.__cafeCounts, keyed by location
  // path). So descending into a sub-main shows on main's SUB-MAINS bubble AND on
  // that sub-main's own bubble in the directory. Player worlds live under
  // main/players so they nest regardless of which shelf opened them.
  const countKeys = Object.keys(heads)
  const childPathOf = (lz) => {
    lz = lz || ''
    if (lz === 'players:') return 'main/players'
    if (lz === 'house:') return 'main/players/house'
    if (lz === 'SUB-MAIN') return 'main/subs'
    if (lz.startsWith('sub:')) return 'main/subs/sub:' + lz.slice(4)
    if (lz.startsWith('space:')) return 'main/players/space:' + lz.slice(6)
    if (lz.startsWith('maker:')) return null   // a profile page, not a presence node
    if (lz && lz !== 'CAFE' && lz !== 'SUB-MAIN') return 'main/world:' + lz   // a core/house world bubble
    return null
  }
  const rollup = (cp) => { if (!cp) return 0; let s = 0; for (const k of countKeys) if (k === cp || k.startsWith(cp + '/')) s += heads[k] || 0; return s }
  const u = [U.cam.x, U.cam.y, U.cam.z, U.order.length, (mgx - 256) / 256, (mgy - 256) / 256]
  // author captions: pack each bubble's maker handle (16 chars = 4 vec4f) into the
  // population buffer, in U.order — the shader reads pop(i*3..) and draws it curved
  // along the bubble's bottom rim (char5x7). System bubbles have no author → blank.
  const pop = []   // flat entities only (4 floats each) — the renderer adds the count header
  for (const n of U.order) {
    const B = U.bubbles[n]
    const au = String(B.author || '').toUpperCase().slice(0, 16)
    for (let c = 0; c < 16; c++) pop.push(c < au.length ? (au.charCodeAt(c) & 0xff) : 0)
    // st>=9 → the world's own visual, rendered into atlas slot (st-9). else the
    // house mini (0-7) or living emblem (8), tinted by the world's hue.
    const styleInt = (!B.iconLoading && B.iconSlot != null && B.iconSlot >= 0) ? (9 + B.iconSlot) : (B.iconLoading ? 99 : B.style)
    const frac = (B.iconSlot != null && B.iconSlot >= 0) ? 0 : Math.min(0.999, B.hue != null ? B.hue : 0)
    const band = B.cat ? B.cat * 400 : (B.big ? 400 : 0)   // 800 sub-mains · 1200 player-worlds · 400 champion-big · 0 normal
    // a world bubble the browser hasn't entered gets a +1000 flag on its head
    // float → the shader draws a "new" pip. Nav bubbles (sub/maker/players/house)
    // and CAFE/SUB-MAIN never count as unvisited worlds.
    const lz = B.launch || ''
    const unvis = !!lz && !lz.startsWith('sub:') && !lz.startsWith('maker:') && !lz.startsWith('players:') && !lz.startsWith('house:') && lz !== 'CAFE' && lz !== 'SUB-MAIN' && !visited[lz]
    // docked orbs = who's AT or BELOW the child this bubble leads to (nesting):
    // main's PLAYER WORLDS/SUB-MAINS bubbles, a sub-main's bubble in the directory,
    // a world's bubble on its shelf. Live DOM cursors still show peers standing at
    // THIS level. NEST off → legacy (main only, keyed by bubble name).
    const nestOff = typeof window !== 'undefined' && window.__ccNestOff
    const showHeads = nestOff ? ((!MF && !SUB && !PL) ? (heads[n] || 0) : 0) : rollup(childPathOf(lz))
    u.push(B.x, B.y, band + (B.crown ? 200 : 0) + styleInt + frac, Math.min(99, showHeads) + (unvis ? 1000 : 0) + (B.square ? 2000 : 0) + (B.playerWorld ? 4000 : 0) + (n === U.dockName ? 8000 : 0))
  }
  // the local player's BREWED icon, packed at the tail (fx, hue, size) — read by
  // the shader at 6 + bubbleCount*4, so it never collides with the bubble stride
  const ic = (typeof window !== 'undefined' && window.__cafeIcon) || {}
  // BREWED GLYPH: when the engine has swapped the player's own WGSL into the
  // shader's mod_playerglyph container, fx packs as -1 — the shader draws the
  // glyph in the preset's seat and the preset stands down.
  // no brewed fx at all (icon state not landed yet) = 5, the default cursor
  u.push(wd.__glyphOn === 1 ? -1 : (typeof ic.fx === 'number' ? ic.fx | 0 : 5), typeof ic.hue === 'number' ? ic.hue : 0.55, typeof ic.size === 'number' ? ic.size : 1.0)
  // On MAIN the dancing shader orbs ARE the presence — suppress the DOM pips so
  // they don't double up. On the directory / sub-mains we do the OPPOSITE: no
  // docked orbs (heads packed 0 above), and let the DOM pips draw LIVE cursors.
  wd.noPresenceCursors = !MF && !SUB && !PL
  // other players — positions are already smoothly interpolated upstream (entity
  // interpolation in the engine's presence loop), so just pack them. Screen coords
  // (256 = center). Capped so we never overrun the 96-float buffer.
  const others = Array.isArray(wd.presence) ? wd.presence : []
  const cap = Math.max(0, Math.min(others.length, 12, Math.floor((256 - u.length - 1) / 4)))
  u.push(cap)
  for (let k = 0; k < cap; k++) {
    const o = others[k] || {}
    // stride 4: x, y, hue, glyph seat (mod_pg0-2 in the shader; -1 = comet)
    const sl = Number.isFinite(o.slot) ? o.slot : -1
    u.push((Number(o.x) - 256) / 256, (Number(o.y) - 256) / 256, ((Number(o.hue) || 0) % 360) / 360, sl)
  }
  wd.gpuUniforms = u
  wd.gpuPopulation = pop   // U.order.length*4 entities (4 vec4f names per bubble)
} catch (e) { /* keep the door open */ }

visualTypes.wgsl:
fn cf_stars(p: vec2f, t: f32) -> vec3f {
  var c = vec3f(0.008, 0.007, 0.016);
  c += vec3f(0.05, 0.025, 0.09) * smoothstep(0.4, 0.9, fbm(p * 1.5 + vec2f(t * 0.004, 0.0), 4));
  for (var l = 0; l < 2; l++) {
    let fl = f32(l);
    let sp = p * (16.0 + fl * 26.0) + fl * 31.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let fp = fract(sp) - 0.5;
    let tw = 0.5 + 0.5 * sin(t * (0.5 + h * 1.4) + h * 40.0);
    c += vec3f(0.8, 0.75, 0.95) * step(0.985, h) * smoothstep(0.24, 0.03, length(fp)) * tw * (1.1 - fl * 0.4);
  }
  return c;
}

// bit (c,r) of the SYMMETRIC pixel-art arrow. Columns are centered (c=0 is the
// middle column), so the shape is mirror-symmetric: bit(c,r) == bit(-c,r). Rows
// run downward from the tip. It's a triangular head (rows 0-5) over a straight
// stem (rows 6-12); hw[r] is each row's half-width in pixels.
fn cf_curbit(c: i32, r: i32) -> f32 {
  if (r < 0 || r > 12) { return 0.0; }
  var hw = array<i32, 13>(0, 1, 2, 3, 4, 5, 1, 1, 1, 1, 1, 1, 1);
  if (abs(c) <= hw[r]) { return 1.0; }
  return 0.0;
}

// DEFAULT CURSOR (fx 5) — the un-brewed look: a crisp 8-BIT arrow, rendered
// nearest-neighbor from a bitmap so it reads as intentional pixel art (fits the
// retro cafe). SYMMETRIC: points straight up, mirror-symmetric about its
// vertical axis. White fill, a 1-pixel black outline. The TIP is the top-center
// pixel at the local origin = the real selection point. No strobe, no wobble.
// Returns (rgb, coverage); the caller mixes it over the scene. Screen +y is down.
fn cf_defcursor(local0: vec2f, phase: f32) -> vec4f {
  let cell = 0.11;                             // size of one art-pixel in local units
  let c = i32(floor(local0.x / cell + 0.5));   // centered columns (c=0 straddles x=0)
  let r = i32(floor(local0.y / cell));         // rows down from the tip
  let solid = cf_curbit(c, r);
  // outline = an empty cell touching the silhouette (8-neighbourhood)
  var nb = max(max(cf_curbit(c - 1, r), cf_curbit(c + 1, r)), max(cf_curbit(c, r - 1), cf_curbit(c, r + 1)));
  nb = max(nb, max(max(cf_curbit(c - 1, r - 1), cf_curbit(c + 1, r - 1)), max(cf_curbit(c - 1, r + 1), cf_curbit(c + 1, r + 1))));
  let outline = (1.0 - solid) * step(0.5, nb);
  if (solid > 0.5) { return vec4f(0.97, 0.97, 1.0, 1.0); }         // white body
  if (outline > 0.5) { return vec4f(0.05, 0.05, 0.08, 1.0); }      // black outline
  return vec4f(0.0);
}

// A PLAYER — a bounded, directional glow. Meant to become programmable (an
// effect id + params + facing, brewed per person); for now a hardcoded Glow with
// a nose + pupil so its direction reads. local: offset from the player center,
// ~1.0 at the edge. dir: unit facing. Returns additive rgb.
fn cf_player(local0: vec2f, dir: vec2f, phase: f32, fx: i32, tint: vec3f) -> vec3f {
  // DANCE — bob, sway, squash-and-stretch on this player's own beat. A groove
  // in place, never a spin. dir is the base facing (the groove leans around it).
  let bob = sin(phase * 3.1) * 0.16;                 // up-down
  let sway = sin(phase * 2.2 + 0.6) * 0.17;          // side-to-side
  let squash = 1.0 + 0.17 * sin(phase * 6.0);        // pulse
  let fdir = normalize(dir + vec2f(0.0, 0.0001));    // guard the zero vector
  let side = vec2f(-fdir.y, fdir.x);
  var local = local0 - fdir * bob - side * sway;     // move the body as it dances
  local = vec2f(local.x * squash, local.y / squash); // squash & stretch
  let d2 = dot(local, local);
  let fwd = max(0.0, dot(local, fdir));              // ahead of center, along the facing
  let body = exp(-d2 * 5.0);                         // round glow body
  let nose = fwd * exp(-d2 * 2.2);                   // stretches the glow toward the facing
  // LOOK — brewed per player. 0 comet · 1 ring · 2 eyes · 3 spark.
  if (fx == 1) {
    let r = abs(sqrt(d2) - 0.5);                     // a dancing ring
    return tint * exp(-r * r * 45.0) * 1.7;
  }
  if (fx == 2) {
    let el = local - side * 0.30 - fdir * 0.10;      // two eyes, looking along the facing
    let er = local + side * 0.30 - fdir * 0.10;
    let eyes = exp(-dot(el, el) * 55.0) + exp(-dot(er, er) * 55.0);
    return tint * body * 1.2 + vec3f(1.0, 0.98, 0.9) * eyes * 0.8;
  }
  if (fx == 3) {
    let ang = atan2(local.y, local.x);               // a five-point spark, spinning on its beat
    let star = pow(max(0.0, cos(ang * 5.0 + phase * 2.0)), 6.0);
    return tint * exp(-d2 * 3.0) * (0.5 + star * 1.4) * 1.5;
  }
  if (fx == 4) {
    // THE WALKING CUP — a cream cup with a handle, striding on stub legs.
    // Drawn solid over the glow layer; tint only warms the steam. All motion
    // rides the same slow dance phase — no strobe, no flash.
    let wt = phase * 0.9;
    let lean = 0.07 * sin(wt);
    var q = local0;
    q = vec2f(q.x * cos(lean) + q.y * sin(lean), -q.x * sin(lean) + q.y * cos(lean));
    q.y = q.y + 0.05 * abs(sin(wt)) - 0.06;
    var cup = vec3f(0.0);
    var cov = 0.0;
    // two stub legs, half a phase apart (screen +y is down)
    for (var li: i32 = 0; li < 2; li++) {
      let lph = wt + f32(li) * 3.14159;
      let hip = vec2f(-0.11 + 0.22 * f32(li), 0.34);
      let foot = vec2f(hip.x + 0.11 * sin(lph), 0.56 - 0.07 * max(0.0, sin(lph + 1.5708)));
      let pa = q - hip; let ba = foot - hip;
      let hseg = clamp(dot(pa, ba) / max(dot(ba, ba), 0.0001), 0.0, 1.0);
      let dleg = length(pa - ba * hseg) - 0.055;
      let mleg = smoothstep(0.02, -0.02, dleg);
      cup = mix(cup, vec3f(0.93, 0.88, 0.80), mleg); cov = max(cov, mleg);
      let dboot = length(q - foot - vec2f(0.02, 0.02)) - 0.07;
      let mboot = smoothstep(0.02, -0.02, dboot);
      cup = mix(cup, vec3f(0.42, 0.27, 0.16), mboot); cov = max(cov, mboot);
    }
    // body — rounded box; handle — a ring on the right
    let bq = abs(q - vec2f(0.0, 0.0)) - vec2f(0.30, 0.32) + vec2f(0.12);
    let dbody = length(max(bq, vec2f(0.0))) + min(max(bq.x, bq.y), 0.0) - 0.12;
    let dring = abs(length(q - vec2f(0.40, 0.02)) - 0.13) - 0.05;
    let dcup = min(dbody, dring);
    let mcup = smoothstep(0.02, -0.02, dcup);
    cup = mix(cup, vec3f(0.95, 0.91, 0.84), mcup); cov = max(cov, mcup);
    // rim band + coffee at the top (up is -y)
    let rq = abs(q - vec2f(0.0, -0.30)) - vec2f(0.295, 0.055);
    let drim = max(rq.x, rq.y);
    let mrim = smoothstep(0.015, -0.015, drim) * mcup;
    cup = mix(cup, vec3f(0.34, 0.20, 0.11), mrim);
    // sleepy face — two happy-closed eyes and a small smile, inked into the cream
    let deL = length((q - vec2f(-0.12, -0.06)) * vec2f(1.0, 1.8)) - 0.045;
    let deR = length((q - vec2f(0.12, -0.06)) * vec2f(1.0, 1.8)) - 0.045;
    let dsm = length((q - vec2f(0.0, 0.10)) * vec2f(1.0, 1.6)) - 0.06;
    let dsm2 = length((q - vec2f(0.0, 0.06)) * vec2f(1.0, 1.6)) - 0.075;
    let face = max(smoothstep(0.012, -0.012, deL), max(smoothstep(0.012, -0.012, deR),
               smoothstep(0.012, -0.012, dsm) * smoothstep(-0.012, 0.012, dsm2)));
    cup = mix(cup, vec3f(0.30, 0.19, 0.12), face * mcup);
    // steam — two faint wisps rising on the slow beat, tinted by the brew
    var steam = vec3f(0.0);
    for (var si: i32 = 0; si < 2; si++) {
      let fsi = f32(si);
      let rise = fract(phase * 0.05 + fsi * 0.5);
      let wp = vec2f((fsi - 0.5) * 0.16 + 0.05 * sin(phase * 0.4 + fsi * 2.0 + rise * 5.0), -0.45 - rise * 0.42);
      let ds = dot(q - wp, q - wp);
      steam += (vec3f(0.75, 0.72, 0.68) + tint * 0.25) * exp(-ds * 70.0) * (1.0 - rise) * rise * 3.2 * 0.35;
    }
    // solid cup over a soft warm halo; additive-safe (bounded, calm)
    let halo = tint * exp(-d2 * 2.4) * 0.22;
    return cup * 1.9 + steam + halo * (1.0 - cov);
  }
  // 0: comet glow (default)
  let g = body * 1.3 + nose * 1.6;
  let eye = local - fdir * 0.30;                     // a pupil pushed forward — a clear aim
  let pupil = exp(-dot(eye, eye) * 55.0) * body;
  return tint * g + vec3f(1.0, 0.98, 0.9) * pupil * 0.8;
}

// author-caption char: each bubble's maker handle is packed 16 chars (4 vec4f)
// in the population buffer; return the c-th char code (0..15) of bubble i. 0 = end.
fn cf_popc(i: i32, c: i32) -> i32 {
  let pv = pop(i * 4 + c / 4);
  let m = c % 4;
  var v = pv.x;
  if (m == 1) { v = pv.y; } else if (m == 2) { v = pv.z; } else if (m == 3) { v = pv.w; }
  return i32(v + 0.5);
}

fn visual_cf_world(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  let mp = vec2f(uni(4), uni(5));     // cursor (uv coords)
  let cam = vec2f(uni(0), uni(1));
  let zm = uni(2);

  // ── the room: stars seen through curved space (your cursor is a lens) ──
  var p = uv;
  let md = uv - mp;
  let mr2 = max(dot(md, md), 0.002);
  p -= md * (0.010 / mr2) * smoothstep(0.9, 0.2, length(md));
  var col = cf_stars(p, t);

  // warm hearth-light from below — this is a cafe, not a void
  col += vec3f(0.10, 0.055, 0.02) * pow(max(0.0, uv.y + 0.2), 2.0) * (0.8 + 0.2 * sin(t * 0.7));

  // ── the bubble universe: live positions, pressure-ranked, explorable ──
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    let stRaw = i32(floor(sv));
    let bigBand = stRaw / 400;          // 0 normal · 1 champion (big + its OWN icon) · 2 sub-mains · 3 player-worlds
    let big = select(0, 1, bigBand > 0);
    let ab = stRaw % 400;
    let st = ab % 200;
    let hue = fract(sv);
    let rawHead00 = uni(9 + i * 4);
    let isDocked = rawHead00 > 7999.5;               // +8000 flags THE DOCK — where the player is moored
    let rawHead0 = select(rawHead00, rawHead00 - 8000.0, isDocked);
    let isPlayerWorld = rawHead0 > 3999.5;           // +4000 flags a PLAYER WORLD (a space) → green rim
    let r1 = select(rawHead0, rawHead0 - 4000.0, isPlayerWorld);
    let isBranch = r1 > 1999.5;                       // +2000 flags a BRANCH → blue rim
    let rawHead = select(r1, r1 - 2000.0, isBranch);
    let unvisited = rawHead > 900.5;                 // +1000 offset flags a world this browser hasn't entered
    let headCount = i32(select(rawHead, rawHead - 1000.0, unvisited) + 0.5);
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let d = length(uv - ctr);
    let R = 0.098 * zm * select(1.0, 1.25, big > 0);
    let hov = smoothstep(R * 1.9, R * 1.1, length(mp - ctr));
    let rr = R * (1.0 + hov * 0.12);
    if (d < rr) {
      let q = (uv - ctr) / rr;                     // -1..1 inside the disc
      var g = vec3f(0.0);
      if (bigBand == 2) {
        // SUB-MAINS — five gatherings around one hearth, threads of light between
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.015, 0.02, 0.045);
        g += cA * exp(-dot(q, q) * 9.0) * 0.9;
        for (var k = 0; k < 5; k++) {
          let ak = f32(k) * 1.2566 + t * 0.15;
          let dirk = vec2f(cos(ak), sin(ak));
          let tt = clamp(dot(q, dirk), 0.0, 0.52);
          let sd2 = length(q - dirk * tt);
          g += cA * exp(-sd2 * sd2 * 900.0) * 0.3;
          let hk = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.2 + 0.05 + vec3f(0.0, 0.33, 0.67)));
          let nd = length(q - dirk * 0.52);
          g += hk * exp(-nd * nd * 260.0) * 1.5;
          g += hk * exp(-nd * nd * 55.0) * 0.25;
        }
      } else if (bigBand == 3) {
        // PLAYER WORLDS — a hand-made planet, its makers orbiting on a tilted ring
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        let pd = length(q);
        let surf = fbm3(q * 4.0 + vec2f(t * 0.05, 0.0));
        let bands = 0.6 + 0.4 * sin(q.y * 9.0 + surf * 3.0);
        var pc = cA * (0.35 + 0.6 * bands * (0.45 + surf * 0.6));
        pc *= smoothstep(0.47, 0.43, pd);
        pc *= 0.8 + 0.4 * clamp(1.0 - length(q - vec2f(-0.2, -0.2)), 0.0, 1.0);
        g = pc;
        let rq = vec2f(q.x, q.y * 2.6 + q.x * 0.4);
        g += cA * smoothstep(0.05, 0.0, abs(length(rq) - 0.74)) * 0.4;
        for (var k = 0; k < 3; k++) {
          let ak = t * 0.6 + f32(k) * 2.094;
          let op = vec2f(cos(ak) * 0.74, sin(ak) * 0.285 - cos(ak) * 0.11);
          let hk = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.3 + 0.55 + vec3f(0.0, 0.33, 0.67)));
          let od = length(q - op);
          g += hk * exp(-od * od * 300.0) * 1.6;
        }
      } else if (bigBand == 4) {
        // THE HOUSE — a warm little cottage with a lit window (unclaimed worlds)
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.02, 0.02, 0.03);
        // body: a square below, roof: a triangle above
        let body = step(abs(q.x), 0.42) * step(-0.05, q.y) * step(q.y, 0.5);
        let roof = step(abs(q.x) + (q.y + 0.05) * 0.95, 0.5) * step(q.y, -0.05) * step(-0.6, q.y);
        let house = clamp(body + roof, 0.0, 1.0);
        g = mix(g, vec3f(0.55, 0.3, 0.14) * (0.8 + 0.3 * cA), house);
        // the lit window — a warm hearth glow
        let win = step(abs(q.x - 0.0), 0.13) * step(0.08, q.y) * step(q.y, 0.34);
        g += vec3f(1.0, 0.78, 0.35) * win * (0.9 + 0.2 * sin(t * 1.8));
        g += vec3f(1.0, 0.7, 0.3) * exp(-dot(q - vec2f(0.0, 0.2), q - vec2f(0.0, 0.2)) * 8.0) * 0.25;
      } else if (st >= 30 && st <= 34) {
        // a MAKER bubble wearing the player's BREWED avatar (preset fx 0-4)
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * 0.10 + vec3f(0.02);
        g += cf_player(q * 2.4, vec2f(0.0, 1.0), t * 1.4, st - 30, cA * 1.5) * 1.6;
        g += cA * exp(-dot(q, q) * 3.5) * 0.35;   // a soft aura in their hue
      } else if (st == 0) {
        // FABRIC — a lens wandering through stars
        var pp = q * 2.0;
        let lc = vec2f(sin(t * 0.6) * 0.5, cos(t * 0.47) * 0.4);
        let ld = pp - lc;
        pp -= ld * (0.16 / max(dot(ld, ld), 0.02));
        g = cf_stars(pp * 1.6, t) * 2.2;
        g += vec3f(0.5, 0.9, 1.1) * exp(-dot(ld, ld) * 14.0) * 0.4;
      } else if (st == 1) {
        // ORRERY — three worlds around a coal
        g = vec3f(0.02, 0.015, 0.03);
        g += vec3f(3.0, 1.7, 0.5) * exp(-dot(q, q) * 30.0);
        for (var k = 1; k <= 3; k++) {
          let fk = f32(k);
          let a = t * (0.9 - fk * 0.18) + fk * 2.1;
          let pp = q - vec2f(cos(a), sin(a)) * (0.22 + fk * 0.17);
          var pc = vec3f(0.45, 0.5, 0.65);
          if (k == 2) { pc = vec3f(0.2, 0.45, 0.8); }
          if (k == 3) { pc = vec3f(0.8, 0.5, 0.25); }
          g += pc * exp(-dot(pp, pp) * 260.0) * 1.6;
        }
      } else if (st == 2) {
        // GARNET — the crystal
        let qa = rotate(q, t * 0.4);
        let cd = abs(qa.x) * 0.866 + abs(qa.y) * 0.5;
        let inside = smoothstep(0.62, 0.58, max(cd, abs(qa.y)));
        let facet = 0.6 + 0.4 * sin(qa.x * 9.0 + qa.y * 7.0 + t * 0.8);
        g = mix(vec3f(0.02, 0.01, 0.02), vec3f(0.75, 0.18, 0.25) * facet, inside);
        g += vec3f(1.6, 0.9, 0.7) * pow(max(0.0, facet - 0.75) * 4.0, 2.0) * inside;
      } else if (st == 3) {
        // ONE DAY — a sky that keeps its whole day
        let ph = fract(t * 0.05);
        let el = sin(ph * 6.28318) * 0.8;
        let day = smoothstep(-0.2, 0.4, el);
        g = mix(vec3f(0.02, 0.02, 0.06), vec3f(0.25, 0.5, 0.8), day * (0.5 - q.y * 0.5));
        g = mix(g, vec3f(0.9, 0.4, 0.15), smoothstep(0.3, 0.0, abs(el)) * max(0.0, -q.y + 0.2) * 0.9);
        let sun = vec2f(cos(ph * 6.28318 - 1.57) * 0.6, -el * 0.55 + 0.1);
        g += vec3f(3.0, 2.0, 0.9) * exp(-dot(q - sun, q - sun) * 60.0) * max(day, 0.15);
        if (q.y > 0.25) { g = mix(g, g * vec3f(0.5, 0.6, 0.8), 0.6); }   // the sea below
      } else if (st == 4) {
        // SAIL — one boat, one sea
        g = mix(vec3f(0.35, 0.5, 0.65), vec3f(0.05, 0.14, 0.2), smoothstep(-0.1, 0.5, q.y));
        let w = sin(q.x * 9.0 + t * 1.4) * 0.05;
        g = mix(g, vec3f(0.03, 0.10, 0.14), smoothstep(w + 0.02, w - 0.02, -q.y + 0.1) * 0.0 + smoothstep(w - 0.02, w + 0.06, q.y - 0.05));
        let sail = max(max(-(q.x + 0.05) * 3.0, q.y + 0.15), (q.x * 0.9 + q.y * 0.8) - 0.28);
        g = mix(g, vec3f(1.0, 0.96, 0.88), smoothstep(0.02, -0.02, sail));
      } else if (st == 5) {
        // SOLSTICE — a sun you carry over a valley
        g = vec3f(0.03, 0.04, 0.09);
        let sp = vec2f(sin(t * 0.5) * 0.45, -0.3 + cos(t * 0.5) * 0.12);
        g += vec3f(3.2, 2.2, 0.9) * exp(-dot(q - sp, q - sp) * 40.0);
        let hill = q.y - (0.25 + 0.15 * sin(q.x * 3.0 + 1.0));
        let lit = max(0.0, 1.0 - length(q - sp) * 1.4);
        g = mix(g, mix(vec3f(0.03, 0.05, 0.02), vec3f(0.15, 0.3, 0.08), lit), smoothstep(-0.02, 0.02, hill));
      } else if (st == 6) {
        // TIDERUNNER — wind over water
        let band = sin(q.y * 14.0 - t * 1.1 + sin(q.x * 4.0) * 0.7);
        g = mix(vec3f(0.05, 0.13, 0.17), vec3f(0.12, 0.25, 0.3), 0.5 + 0.5 * band);
        g += vec3f(0.8, 0.85, 0.85) * pow(max(0.0, band - 0.8) * 5.0, 2.0) * 0.4;
        let bt = q - vec2f(sin(t * 0.4) * 0.4, 0.0);
        g += vec3f(0.9, 0.85, 0.75) * exp(-dot(bt, bt) * 300.0) * 1.2;
      } else if (st == 7) {
        // SIGNAL — a television waiting for a word
        let sn = hash21(floor(q * 24.0) + floor(t * 9.0));
        g = vec3f(sn * 0.5);
        g += vec3f(0.3, 1.0, 0.45) * exp(-dot(q, q) * 8.0) * (0.28 + 0.14 * sin(t * 2.0));
        g *= 0.82 + 0.18 * sin(q.y * 60.0 - t * 8.0);
      } else if (st == 99) {
        // its shader icon is still rendering — a quiet sweeping spinner, not a
        // default planet, so a loading bubble reads as "on its way"
        let ang = atan2(q.y, -q.x);
        let rd = length(q);
        let ring = smoothstep(0.09, 0.0, abs(rd - 0.5));
        let sweep = fract(ang / 6.2831 + t * 0.7);
        let comet = smoothstep(0.0, 0.55, sweep) * smoothstep(1.0, 0.55, sweep);
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = vec3f(0.02, 0.02, 0.03) + cA * ring * (0.12 + comet * 1.3);
      } else if (st >= 9) {
        // a real world — its screenshot, folded into the bubble by the shader.
        // A BIG (champion) bubble insets its icon so it doesn't fill edge-to-edge
        // and read as oversized next to the category glyphs.
        g = cafeIcon(st - 9, q * select(1.0, 1.32, big > 0));
        g *= 0.9 + 0.2 * (1.0 - length(q));   // gentle spherical shading
      } else {
        // a young world — a banded seed-planet in its own hue
        let cA = 0.5 + 0.5 * cos(6.2831 * (hue + vec3f(0.0, 0.33, 0.67)));
        g = cA * (0.22 + 0.5 * fbm3(q * 3.0 + vec2f(t * 0.08, f32(i) * 3.7)));
        g += cA * 0.4 * smoothstep(0.6, 1.0, 1.0 - abs(q.y * 2.2 + 0.3 * sin(q.x * 3.0 + t * 0.4)));
        let mn = q - vec2f(cos(t * 0.5 + f32(i) * 1.9), sin(t * 0.5 + f32(i) * 1.9) * 0.6) * 0.78;
        g += vec3f(0.85) * exp(-dot(mn, mn) * 260.0);
        g *= 0.85 + 0.3 * (1.0 - length(q));
      }
      // (the head-count number is gone — presence is the dancing players now)
      // glass edge + hover bloom — the top three wear their OWN rim colors:
      // champion solar gold, SUB-MAINS sky blue, PLAYER WORLDS spring green
      let edge = smoothstep(1.0, 0.86, length(q));
      col = mix(col, g, edge);
      var rim = vec3f(1.2, 0.85, 0.4);
      var rimBase = 0.25;
      if (bigBand == 1) { rim = vec3f(1.5, 1.0, 0.3); rimBase = 0.45; }
      else if (bigBand == 2) { rim = vec3f(0.45, 0.75, 1.55); rimBase = 0.45; }
      else if (bigBand == 3) { rim = vec3f(0.4, 1.45, 0.65); rimBase = 0.45; }
      else if (bigBand == 4) { rim = vec3f(1.4, 0.75, 0.35); rimBase = 0.45; }
      if (isBranch) { rim = vec3f(0.30, 0.62, 1.75); rimBase = 0.6; }        // BRANCH — a blue outline on the round bubble
      if (isPlayerWorld) { rim = vec3f(0.40, 1.45, 0.65); rimBase = 0.5; }   // PLAYER WORLD — a green rim (matches the PLAYER WORLDS door)
      col += rim * exp(-pow((length(q) - 0.97) * 9.0, 2.0)) * (rimBase + hov * 1.3);
      // THE DOCK ⚓ — a slow-breathing double ring outside the rim: you are moored here
      if (isDocked) {
        let breathe = 0.6 + 0.4 * sin(t * 1.6);
        col += vec3f(0.55, 0.95, 1.05) * exp(-pow((length(q) - 1.12) * 24.0, 2.0)) * breathe * 0.9;
        col += vec3f(0.35, 0.80, 0.95) * exp(-pow((length(q) - 1.24) * 30.0, 2.0)) * breathe * 0.5;
      }
    } else {
      // halo when hovered
      col += vec3f(1.0, 0.7, 0.3) * exp(-pow((d - rr) * 22.0, 2.0)) * hov * 0.8;
    }
    // ── the maker's handle, curved along the bottom rim (white bitmap caption) ──
    // chars packed 12/bubble in the population buffer; glyphs sit radially in a
    // thin band just off the rim, upright (top toward centre), reading L→R across
    // the bottom arc. System bubbles have no author → nlen 0 → nothing drawn.
    {
      let charH = R * 0.22;
      let namR0 = rr + R * 0.05;
      let namR1 = namR0 + charH;
      if (d > namR0 && d < namR1) {
        var nlen = 0;
        for (var cc = 0; cc < 16; cc++) {
          if (cf_popc(i, cc) == 0) { break; }
          nlen = cc + 1;
        }
        if (nlen > 0) {
          let dA = (charH * (5.0 / 7.0)) / namR0;      // arc angle per monospace char
          let halfArc = f32(nlen) * dA * 0.5;
          let ang = atan2(uv.x - ctr.x, uv.y - ctr.y);  // 0 = straight down, + toward right
          if (abs(ang) < halfArc) {
            let tg = (ang + halfArc) / dA;
            let jc = i32(floor(tg));
            let ul = fract(tg);
            let vl = (d - namR0) / charH;
            let cov = char5x7(vec2f(ul, vl), cf_popc(i, jc));
            col = mix(col, vec3f(1.0, 1.0, 1.0), cov * (0.7 + hov * 0.3));
          }
        }
      }
    }
    // presence players HOVER at the edge — half inside, half out — so they draw
    // in a band that spills BEYOND the disc, not clipped by the d<rr face mask.
    // Additive onto col; the SMALL scale of the cursor's big roaming effect.
    // One player per real occupant (headCount), up to 6.
    if (d < rr * 1.6) {
      let ql = (uv - ctr) / rr;                              // disc-local; >1 outside the bubble
      let nP = min(headCount, 6);
      for (var k = 0; k < nP; k++) {
        let ga = f32(k) * 2.39996 + f32(i) * 1.7;            // static seat around the rim
        let orb = vec2f(cos(ga), sin(ga));
        let plocal = (ql - orb) * 3.2;                       // seat ON the rim (radius 1.0), spilling out
        let hueK = 0.5 + 0.5 * cos(6.2831 * (f32(k) * 0.16 + vec3f(0.0, 0.33, 0.67)));
        let ph = t * 1.5 + f32(k) * 1.3 + f32(i) * 0.7;      // each dances on its own beat
        col += cf_player(plocal, orb, ph, 0, hueK * 1.6) * 1.8; // hold the seat, dance in place
      }
    }
    // NEW-WORLD PIP — a small bright dot on the upper-right rim of any world this
    // browser has not entered yet (unvisited, decoded above). It clears the moment
    // you visit. Drawn outside the face mask so it rides ON the rim, like the crown.
    if (unvisited) {
      let dotC = ctr + vec2f(R * 0.60, -R * 0.60);
      let dd = length(uv - dotC);
      let pulse = 0.75 + 0.25 * sin(t * 3.0 + f32(i));
      col += vec3f(0.55, 1.0, 0.82) * (smoothstep(R * 0.16, R * 0.09, dd) * 1.7 + exp(-pow(dd / (R * 0.20), 2.0)) * 0.45) * pulse;
    }
  }

  // the CROWN, over everything — a small gold crown resting on the champion's
  // brow (no ring, no halo — just the crown)
  for (var i = 0; i < i32(uni(3) + 0.5); i++) {
    let sv = uni(8 + i * 4);
    let sr = i32(floor(sv));
    let abc = sr % 400;
    if (abc < 200) { continue; }        // crown flag lives in the 200 band, under the big band
    let bigc = sr / 400;
    let ctr = vec2f((uni(6 + i * 4) - cam.x) * zm / 256.0, (uni(7 + i * 4) - cam.y) * zm / 256.0);
    let R = 0.098 * zm * select(1.0, 1.25, bigc > 0);
    // SOLAR CROWN — a small sun-forged crown above the brow: molten gold body,
    // breathing corona, rays flaring off the teeth
    let cp = (uv - (ctr + vec2f(0.0, -R * 1.28))) / (R * 0.38);
    if (abs(cp.x) < 2.2 && cp.y > -2.2 && cp.y < 1.4) {
      // three teeth: a triangle wave over the band, tips pointing up (soft edges)
      let teeth = 1.0 - abs(fract(cp.x * 1.5 + 0.5) - 0.5) * 2.0;
      let topY = -0.12 - teeth * 0.88;
      let m = smoothstep(1.04, 0.98, abs(cp.x)) * smoothstep(topY - 0.06, topY + 0.05, cp.y) * smoothstep(0.55, 0.45, cp.y);
      // molten gold: banded shimmer rolling across the metal
      let molten = 0.75 + 0.25 * sin(cp.x * 7.0 - t * 2.6) * sin(cp.y * 5.0 + t * 1.9);
      let gold = mix(vec3f(0.85, 0.55, 0.12), vec3f(1.0, 0.9, 0.5), clamp(0.5 - cp.y * 0.6, 0.0, 1.0)) * molten;
      col = mix(col, gold, m);
      // corona: the whole crown breathes light like a low sun
      let bd = length(vec2f(cp.x * 0.62, cp.y + 0.25));
      col += vec3f(1.0, 0.72, 0.28) * exp(-bd * bd * 2.6) * (0.16 + 0.05 * sin(t * 1.7)) * (1.0 - m);
      // rays flaring off the three tips
      for (var k = -1; k <= 1; k++) {
        let jp = cp - vec2f(f32(k) * 0.667, -1.0);
        let jd = length(jp);
        let ja = atan2(jp.y, jp.x);
        let flare = 0.5 + 0.5 * sin(ja * 6.0 + t * 2.4 + f32(k) * 2.1);
        col += vec3f(1.0, 0.95, 0.72) * exp(-jd * jd * 30.0) * (0.55 + 0.35 * flare);
        col += vec3f(1.0, 0.85, 0.45) * exp(-jd * 6.0) * flare * 0.22;
      }
    }
  }

  // the local player — the "you" roaming the open grid, dancing in place. Its
  // look/hue/size are BREWED: read from the uniform tail (packed after all the
  // bubbles, so bubble offsets never move). fx, hue, size = uni(sb, sb+1, sb+2).
  let sb = 6 + i32(uni(3) + 0.5) * 4;
  // fx -1 = a custom BREWED GLYPH field is riding the cursor instead — the
  // preset dance (and its soft core) stands down. round(), not +0.5: the old
  // truncation folded -1 back to 0 and the comet haunted the glyph.
  let selfFx = i32(round(uni(sb)));
  let selfHue = uni(sb + 1);
  let selfSize = max(uni(sb + 2), 0.25);
  let selfTint = 0.5 + 0.5 * cos(6.2831 * (selfHue + vec3f(0.0, 0.33, 0.67)));
  if (selfFx == 5) {
    // DEFAULT CURSOR — nothing brewed yet: a small stylized pointer whose TIP
    // sits on the real pointer position (local origin), mixed OVER the scene.
    // Brewed looks (presets 0-4, custom glyphs) are untouched.
    let dc = cf_defcursor((uv - mp) * (10.0 / selfSize), t * 1.6);
    col = mix(col, dc.rgb, dc.a);
  } else if (selfFx >= 0) {
    col += cf_player((uv - mp) * (4.5 / selfSize), vec2f(0.0, 1.0), t * 1.6, selfFx, selfTint * 1.3) * 1.1;
    col += selfTint * 0.9 * exp(-dot(uv - mp, uv - mp) * 1400.0) * 0.4;   // a soft core in your hue
  } else {
    // BREWED GLYPH — the player's own WGSL fills the mod_playerglyph container
    // (a no-op until the engine swaps it in). Same seat as the presets, but a
    // tighter cell: a glyph fills its whole cell to |uv|=1, so the preset scale
    // read twice as large as intended. 9.0 ≈ a cursor-sized icon at size 1.
    // The distance guard is the frame budget: only pixels inside the cell pay
    // for the glyph at all — user code can be arbitrarily fancy without taxing
    // the other ~99% of the screen.
    let gd = uv - mp;
    let gcell = selfSize / 9.0;
    if (dot(gd, gd) < gcell * gcell * 1.1) {
      let gl = mod_playerglyph(gd * (9.0 / selfSize), t);
      col += gl.rgb * clamp(gl.a, 0.0, 1.0) * 1.5;
    }
  }

  // the OTHER players — their live cursors, dancing, so you see them move around
  // the cafe. Packed after the self-icon: count at sb+3, then (x, y, hue, seat)
  // each. seat >= 0 means their BREWED GLYPH sits in that mod_pg slot — draw
  // their real icon; seat -1 is the comet everyone starts as.
  let ob = sb + 3;
  let nOthers = i32(uni(ob) + 0.5);
  for (var k = 0; k < nOthers; k++) {
    let opos = vec2f(uni(ob + 1 + k * 4), uni(ob + 2 + k * 4));
    let ohue = uni(ob + 3 + k * 4);
    let oseat = i32(round(uni(ob + 4 + k * 4)));
    let otint = 0.5 + 0.5 * cos(6.2831 * (ohue + vec3f(0.0, 0.33, 0.67)));
    if (oseat >= 0) {
      // their glyph, slightly smaller than your own (13 vs your 9) — same
      // distance guard: only pixels inside their cell run their code
      let od = uv - opos;
      let ocell = 1.0 / 13.0;
      if (dot(od, od) < ocell * ocell * 1.2) {
        var og = vec4f(0.0);
        if (oseat == 0) { og = mod_pg0(od * 13.0, t); }
        else if (oseat == 1) { og = mod_pg1(od * 13.0, t); }
        else { og = mod_pg2(od * 13.0, t); }
        col += og.rgb * clamp(og.a, 0.0, 1.0) * 1.4;
      }
    } else {
      // un-brewed player: the SAME default pixel arrow you wear, tinted by their
      // hue so players still read apart. A touch smaller than your own (12 vs
      // your 10). The white body takes the tint; the dark outline stays dark.
      let dc = cf_defcursor((uv - opos) * 12.0, t * 1.6);
      col = mix(col, dc.rgb * (0.45 + otint), dc.a);
    }
  }

  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(60.0)), 1.0);
}

modules.wgsl:
fn mod_alhash(p: vec2f) -> f32 { return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453); }
fn mod_alnoise(p: vec2f) -> f32 {
  let i = floor(p); let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mod_alhash(i); let b = mod_alhash(i + vec2f(1.0, 0.0));
  let c = mod_alhash(i + vec2f(0.0, 1.0)); let d = mod_alhash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
fn mod_alfbm(p0: vec2f) -> f32 {
  var p = p0; var amp = 0.5; var s = 0.0;
  for (var i = 0; i < 4; i++) {
    s += amp * mod_alnoise(p);
    p = mat2x2f(1.6, 1.2, -1.2, 1.6) * p;
    amp *= 0.5;
  }
  return s;
}
fn mod_alwarp(p: vec2f, t: f32) -> f32 {
  let q = mod_alfbm(p + vec2f(t * 0.4, -t * 0.9));
  return mod_alfbm(p + vec2f(q * 1.7, q * 1.2) + vec2f(-t * 0.2, -t * 1.3));
}

stepHooks.code:
try {
  const wd = sim.worldData
  const dtc = Math.min(dt, 0.05)

  // ── freeze diagnostic (temporary): if the frame interval spikes, say so on
  // the HUD, tagged with whether a fusion just happened. Read it, report it.
  const nowMs = performance.now()
  if (!wd.__al) { /* first frame — state made below */ } else {
    const A0 = wd.__al
    if (A0.lastMs && nowMs - A0.lastMs > 120) {
      A0.spike = Math.round(nowMs - A0.lastMs) + 'ms ' + (A0.fuseAt && nowMs - A0.fuseAt < 1200 ? 'at ' + (A0.fuseKey || 'fusion') : 'idle')
      A0.spikeAt = nowMs
    }
    A0.lastMs = nowMs
  }

  // species table: radius (grid), gravity (+down), lifespan (0 = abiding), tone
  const SP = {
    ember:    { r: 24, g: -16, life: 0,  tone: 392, well: [92, 442] },
    dew:      { r: 21, g:  24, life: 0,  tone: 523, well: [420, 72] },
    gale:     { r: 27, g:   0, life: 0,  tone: 587, well: [64, 240] },
    loam:     { r: 25, g:  34, life: 0,  tone: 294, well: [150, 70] },
    mist:     { r: 32, g: -12, life: 26, tone: 659 },
    rain:     { r: 14, g:  95, life: 0,  tone: 494 },
    magma:    { r: 27, g:  16, life: 0,  tone: 196 },
    moss:     { r: 24, g:  20, life: 0,  tone: 440 },
    wildfire: { r: 27, g:  -8, life: 7,  tone: 740 },
    storm:    { r: 38, g:  -2, life: 40, tone: 110 },
    ash:      { r: 17, g:  12, life: 0,  tone: 262 },
    glass:    { r: 22, g:   4, life: 0,  tone: 880 },
    stone:    { r: 28, g:  40, life: 0,  tone: 147 },
    char:     { r: 15, g:  22, life: 0,  tone: 220 },
    star:     { r: 20, g:   0, life: 0,  tone: 1047 },
  }
  // the book of fusions — sorted-pair key. Like refuses like unless THROWN.
  const RX = {
    'dew+ember': 'mist',      'ember+loam': 'magma',    'dew+loam': 'moss',
    'dew+gale': 'rain',       'ember+gale': 'wildfire', 'gale+mist': 'storm',
    'dew+magma': 'glass',     'ember+moss': 'ash',      'ash+dew': 'loam',
    'magma+storm': 'star',    'moss+wildfire': 'ember', 'mist+mist': 'dew',
    'ember+ember': 'wildfire','dew+dew': 'rain',        'gale+gale': 'storm',
    'loam+loam': 'stone',
    'char+gale': 'ember',     'char+dew': 'ash',        'stone+wildfire': 'magma',
    'stone+storm': 'glass',   'mist+moss': 'moss',
    // every creation has a further use — only the STAR is final
    'magma+rain': 'stone',    'glass+wildfire': 'magma',
    'dew+moss': 'moss',       'ash+rain': 'loam',       'ember+rain': 'mist',
    'magma+mist': 'stone',
    // ── the book grows (Galen: all combos should make something) ──
    // weather writes on the land
    'gale+rain': 'storm',     'loam+rain': 'moss',      'loam+mist': 'moss',
    'rain+stone': 'loam',     'gale+stone': 'ash',      'dew+stone': 'moss',
    'mist+rain': 'rain',      'dew+mist': 'rain',       'moss+rain': 'moss',
    // fire meets water, water wins slowly
    'dew+wildfire': 'mist',   'rain+wildfire': 'mist',  'mist+wildfire': 'gale',
    'ember+mist': 'gale',     'gale+magma': 'wildfire',     // the burnt world
    'ash+ember': 'char',      'ash+wildfire': 'char',   'loam+wildfire': 'char',
    'magma+moss': 'ash',      'ash+moss': 'loam',       'char+rain': 'loam',
    'char+stone': 'stone',    'ash+glass': 'stone',     'moss+stone': 'loam',
    // glass sweats, magma breathes
    'glass+mist': 'dew',      'ember+glass': 'magma',
    // the star ascends what it touches (light is generous, not final after all)
    'ember+star': 'wildfire', 'dew+star': 'mist',       'gale+star': 'storm',
    'loam+star': 'glass',     'star+stone': 'magma',    'mist+star': 'rain',
    'moss+star': 'loam',      'star+wildfire': 'star',
  }
  const NAMES = { mist:'MIST', rain:'RAIN', magma:'MAGMA', moss:'MOSS', wildfire:'WILDFIRE',
                  storm:'STORM', ash:'ASH', glass:'GLASS', stone:'STONE', star:'STAR',
                  dew:'DEW', ember:'EMBER', loam:'LOAM', gale:'GALE', char:'CHAR' }
  // element classes: 1 fire, 2 water, 3 storm, 4 star, 5 earth/solid, 6 air —
  // used for the vessel's coupled lighting AND each flare's parent remnants
  const CLS  = { ember: 1, wildfire: 1, magma: 1, dew: 2, rain: 2, mist: 2, storm: 3, star: 4, loam: 5, stone: 5, glass: 5, moss: 5, ash: 5, char: 5, gale: 6 }
  const GLOW = { ember: 0.9, wildfire: 1.4, magma: 0.75, dew: 0.4, rain: 0.3, mist: 0.3, storm: 0.9, star: 1.7, loam: 0.5, stone: 0.55, glass: 0.6, moss: 0.45, ash: 0.3, char: 0.15, gale: 0.25 }

  // state: A.s[id] = { sp, on, x, y, vx, vy, age, rest } — one entry per pooled field
  if (!wd.__al) wd.__al = { s: {}, wellT: 1.2, mn: 0, grab: null, sq: [], thunderT: 4, lastMs: performance.now() }
  if (!wd.__alcodex) wd.__alcodex = { found: {}, last: '' }   // survives leaving (cc-save stash)
  const A = wd.__al, CX = wd.__alcodex
  const spOf = (id) => id.replace(/^al_/, '').replace(/\d+$/, '')

  // fresh session: park everything, re-seed the vessel
  if (wd.__fresh) {
    delete wd.__fresh
    A.s = {}; A.grab = null; A.sq = []; A.wellT = 0.6; A.thunderT = 4
    for (const f of sim.fields.values()) {
      if (!f.id.startsWith('al_') || f.id === 'al_vessel') continue
      A.s[f.id] = { sp: spOf(f.id), on: 0, x: -100, y: -100, vx: 0, vy: 0, age: 0, rest: 0 }
      f.transform.x = -100; f.transform.y = -100
    }
  }

  const slots = Object.keys(A.s)
  const active = slots.filter(id => A.s[id].on)
  const wake = (sp, x, y, vx, vy) => {
    const id = slots.find(k => A.s[k].sp === sp && !A.s[k].on)
    if (!id) return null
    const st = A.s[id]
    st.on = 1; st.x = x; st.y = y; st.vx = vx || 0; st.vy = vy || 0; st.age = 0; st.rest = 0
    st.heat = 1   // a reused slot MUST start hot — else a stale burnt-out ember dies on frame 1 (the spawn-die loop)
    return id
  }
  const park = (id) => { const st = A.s[id]; st.on = 0; st.x = -100; st.y = -100; if (A.grab === id) A.grab = null }
  const tone = (freq, vol, dur, typ) => A.sq.push({ frequency: freq, duration: dur || 0.35, volume: vol || 0.16, type: typ || 'sine' })

  // ── wells: the vessel breathes primal matter back in ──
  A.wellT -= dtc
  if (A.wellT <= 0) {
    A.wellT = 1.5
    const want = { ember: 4, dew: 4, gale: 3, loam: 3 }
    // breathe in a RANDOM under-target primal each time, so the vessel fills
    // interleaved (fire, water, air, earth…) instead of 4-of-one-then-4-of-the-next
    const under = Object.keys(want).filter(sp => active.filter(id => A.s[id].sp === sp).length < want[sp])
    if (under.length) {
      const sp = under[Math.floor(Math.random() * under.length)]
      const w = SP[sp].well
      if (wake(sp, w[0] + (Math.random() - 0.5) * 46, w[1] + (Math.random() - 0.5) * 16, (Math.random() - 0.5) * 14, 0)) {
        tone(SP[sp].tone * 0.5, 0.05, 0.25)
      }
    }
  }

  // ── the alchemist's hand: grab, carry, fling ──
  const mx = wd.mouse_x ?? 256, my = wd.mouse_y ?? 256
  const down = !!wd.mouse_down
  if (down && !A.grab) {
    let best = null, bd = 1e9
    for (const id of active) {
      const st = A.s[id]
      if (st.sp === 'flare') continue   // light cannot be held
      const d = Math.hypot(mx - st.x, my - st.y)
      if (d < SP[st.sp].r + 20 && d < bd) { bd = d; best = id }
    }
    if (best) A.grab = best
  }
  if (!down) A.grab = null
  if (A.grab && A.s[A.grab] && A.s[A.grab].on) {
    const st = A.s[A.grab]
    const k = Math.min(1, dtc * 14)
    const nx = st.x + (mx - st.x) * k, ny = st.y + (my - st.y) * k
    st.vx = (nx - st.x) / Math.max(dtc, 0.001) * 0.55   // carried momentum → the fling
    st.vy = (ny - st.y) / Math.max(dtc, 0.001) * 0.55
    st.x = nx; st.y = ny; st.rest = 0
  }

  // ── motion: every species has a temperament ──
  const FLOOR = 486, CEIL = 26, L = 26, R = 486
  for (const id of active) {
    const st = A.s[id]
    if (st.sp === 'flare') continue   // aged separately below — no physics, no SP entry
    if (id === A.grab) continue
    const sp = SP[st.sp]
    st.age += dtc
    if (st.sp === 'star') {
      // the crown discovery orbits the heart of the vessel, forever
      const oa = st.age * 0.5
      st.x = 256 + Math.cos(oa) * 120; st.y = 256 + Math.sin(oa) * 120
      continue
    }
    if (st.sp === 'gale') st.vx += Math.sin(st.age * 0.9 + st.y * 0.02) * 46 * dtc
    if (st.sp === 'mist') st.vx += Math.sin(st.age * 0.6) * 14 * dtc
    if (st.sp === 'wildfire') { st.vx += (Math.random() - 0.5) * 320 * dtc; st.vy += (Math.random() - 0.5) * 320 * dtc }
    if (st.sp === 'storm') { st.vx += Math.sin(st.age * 0.8) * 30 * dtc; st.vy += Math.cos(st.age * 0.7) * 16 * dtc }
    st.vy += sp.g * dtc * 3.2
    st.vx *= (1 - Math.min(1, dtc * 1.4)); st.vy *= (1 - Math.min(1, dtc * 1.4))
    st.x += st.vx * dtc; st.y += st.vy * dtc
    // the glass: soft walls, a floor where the heavy things rest
    if (st.x < L) { st.x = L; st.vx = Math.abs(st.vx) * 0.5 }
    if (st.x > R) { st.x = R; st.vx = -Math.abs(st.vx) * 0.5 }
    if (st.y < CEIL) { st.y = CEIL; st.vy = Math.abs(st.vy) * 0.3 }
    if (st.sp === 'ember') {
      // fire spends itself: the flame dims, and what is left is char
      st.heat = (st.heat === undefined ? 1 : st.heat) - dtc / 50
      if (st.heat <= 0) { const x = st.x, y = st.y; park(id); wake('char', x, y, 0, 0); tone(180, 0.08, 0.5); continue }
    }
    if (st.sp === 'rain') st.vx += Math.sin(st.age * 2.1 + st.y * 0.03) * 26 * dtc   // wind-sway
    if (st.y > FLOOR) {
      st.y = FLOOR; st.vy = -Math.abs(st.vy) * 0.25
      if (st.sp === 'rain') {
        // the strike is VISIBLE: a crown splash where it lands, and the water
        // stays in the world as a droplet — nothing vanishes
        const fid = slots.find(k => A.s[k].sp === 'flare' && !A.s[k].on)
        if (fid) { const fs = A.s[fid]; fs.on = 1; fs.x = st.x; fs.y = FLOOR - 6; fs.age = 0; fs.style = 2; fs.tint = [0.6, 0.8, 1.0]; fs.pa = 0; fs.pb = 0 }
        tone(700 + Math.random() * 200, 0.06, 0.15)
        // the drop BOUNCES — the harder it fell, the higher the droplet leaps
        // (st.vy was already damped to 0.25x by the floor above; 1.8x ≈ 0.45x impact)
        park(id); wake('dew', st.x, FLOOR - 4, st.vx * 0.3, -Math.max(30, Math.abs(st.vy) * 1.8))
        continue
      }
    }
    // lifespans: mist thins away, wildfire burns to ash, a storm rains itself out
    if (sp.life && st.age > sp.life) {
      const x = st.x, y = st.y, vx = st.vx, vy = st.vy
      park(id)
      if (st.sp === 'wildfire') wake('ash', x, y, vx * 0.2, vy * 0.2)
      if (st.sp === 'storm') { wake('rain', x - 12, y, -10, 40); wake('rain', x + 12, y, 10, 40); tone(140, 0.12, 0.5) }
    }
  }

  // ── the chemistry: contact is a question, the recipe book answers ──
  const act2 = slots.filter(id => A.s[id].on)
  for (let i = 0; i < act2.length; i++) {
    const a = A.s[act2[i]]
    if (a.age < 0.7 || !a.on || a.sp === 'flare') continue
    for (let j = i + 1; j < act2.length; j++) {
      const b = A.s[act2[j]]
      if (b.age < 0.7 || !b.on || !a.on || b.sp === 'flare') continue
      const rr = (SP[a.sp].r + SP[b.sp].r) * 0.66
      const dx = b.x - a.x, dy = b.y - a.y
      if (dx * dx + dy * dy > rr * rr) continue
      const key = [a.sp, b.sp].sort().join('+')
      let child = RX[key]
      // LIKE REFUSES LIKE unless thrown — a deliberate act, not a graze.
      // (mist is the exception: condensation is gentle by nature.)
      if (child && a.sp === b.sp && a.sp !== 'mist') {
        const rvx = a.vx - b.vx, rvy = a.vy - b.vy
        if (rvx * rvx + rvy * rvy < 90 * 90) child = null
      }
      if (!child) {
        // no reaction — but NOTHING is mute (Galen: all combos make something).
        // Matter that refuses still ANSWERS: on a real bump (not a graze) it
        // throws a brief spark, sounds the two tones together, and kicks apart.
        const d = Math.max(6, Math.hypot(dx, dy)), push = 60 * dtc
        a.vx -= dx / d * push; a.vy -= dy / d * push
        b.vx += dx / d * push; b.vy += dy / d * push
        const rvx2 = a.vx - b.vx, rvy2 = a.vy - b.vy
        A.fzT = Math.max(0, (A.fzT || 0) - dtc)
        if (A.fzT <= 0 && rvx2 * rvx2 + rvy2 * rvy2 > 55 * 55) {
          A.fzT = 0.25
          const fid2 = slots.find(k => A.s[k].sp === 'flare' && !A.s[k].on)
          if (fid2) {
            const fs2 = A.s[fid2]
            fs2.on = 1; fs2.x = (a.x + b.x) / 2; fs2.y = (a.y + b.y) / 2
            fs2.age = 0; fs2.style = 2; fs2.tint = [1.0, 0.88, 0.55]; fs2.pa = 0; fs2.pb = 0
          }
          tone(SP[a.sp].tone, 0.05, 0.12)
          tone(SP[b.sp].tone * 1.06, 0.05, 0.12)   // a near-miss interval — the sound of refusal
          const kick = 40
          a.vx -= dx / d * kick * 0.5; a.vy -= dy / d * kick * 0.5
          b.vx += dx / d * kick * 0.5; b.vy += dy / d * kick * 0.5
        }
        continue
      }
      const cxp = (a.x + b.x) / 2, cyp = (a.y + b.y) / 2
      const cvx = (a.vx + b.vx) / 2, cvy = (a.vy + b.vy) / 2
      // snapshot the parents: parking them first frees a same-species slot for
      // the child, but if the child's pool is STILL full we must not eat them
      // (silent loss = "not all combinations work"). Undo on failure.
      const pa = { sp: a.sp, x: a.x, y: a.y, vx: a.vx, vy: a.vy }
      const pb = { sp: b.sp, x: b.x, y: b.y, vx: b.vx, vy: b.vy }
      park(act2[i]); park(act2[j])
      if (!wake(child, cxp, cyp, cvx, cvy)) {
        wake(pa.sp, pa.x, pa.y, pa.vx, pa.vy); wake(pb.sp, pb.x, pb.y, pb.vx, pb.vy)
        continue   // pool full — nothing lost; the pair meets again next contact
      }
      if (child === 'ember') wake('ember', cxp + 16, cyp - 8, 20, -20)   // wildfire spreads
      if (key === 'dew+moss') wake('moss', cxp + 20, cyp + 4, 12, -8)    // watered: the moss doubles
      // the flare IS the fusion made visible
      const fid = slots.find(k => A.s[k].sp === 'flare' && !A.s[k].on)
      if (fid) {
        const fs = A.s[fid]; fs.on = 1; fs.x = cxp; fs.y = cyp; fs.age = 0; fs.vx = 0; fs.vy = 0
        const tint = { mist:[.7,.8,.9], rain:[.4,.7,1], magma:[1,.4,.1], moss:[.4,.8,.3], wildfire:[1,.6,.1],
                       storm:[.5,.5,.9], ash:[.5,.5,.5], glass:[.7,.95,1], stone:[.6,.6,.68], star:[1,.95,.6],
                       dew:[.5,.8,1], ember:[1,.5,.15], loam:[.5,.35,.2], char:[.4,.3,.25] }[child] || [1,1,1]
        fs.tint = tint
        // every birth has its own body language: fire sparks, water crowns,
        // earth breathes dust, storms crackle, growth drifts up green —
        // and the parents each leave their class's remnant, so all 21
        // fusions (and any future combos of combos) look like themselves
        fs.style = { ember:1, wildfire:1, magma:1, char:1, dew:2, rain:2, mist:2, glass:2,
                     loam:3, stone:3, ash:3, storm:4, star:4, moss:5 }[child] || 0
        fs.pa = CLS[a.sp] || 5; fs.pb = CLS[b.sp] || 5
      }
      A.fuseAt = performance.now(); A.fuseKey = key
      tone(SP[child].tone, 0.2, 0.5)
      if (!CX.found[key]) {
        CX.found[key] = child
        CX.last = key.toUpperCase().replace('+', ' + ') + ' \u2192 ' + NAMES[child]
        tone(SP[child].tone * 2, 0.1, 0.7)
        if (child === 'star') { tone(1047, 0.2, 0.9); tone(1319, 0.14, 1.1) }
      }
      break
    }
  }

  // ── life: established moss buds on its own — the vessel slowly greens.
  // Population is capped by the moss slot pool, so it settles, not swarms. ──
  A.growT = (A.growT ?? 20) - dtc
  if (A.growT <= 0) {
    A.growT = 16 + Math.random() * 10
    const mosses = act2.filter(id => A.s[id].on && A.s[id].sp === 'moss' && A.s[id].age > 8)
    if (mosses.length) {
      const p = A.s[mosses[Math.floor(Math.random() * mosses.length)]]
      const nid = wake('moss', p.x + (Math.random() - 0.5) * 64, p.y - 16 - Math.random() * 22, (Math.random() - 0.5) * 10, -8)
      if (nid) {
        tone(440, 0.06, 0.45)
        const fid = slots.find(k => A.s[k].sp === 'flare' && !A.s[k].on)
        if (fid) { const fs = A.s[fid]; fs.on = 1; fs.x = A.s[nid].x; fs.y = A.s[nid].y; fs.age = 0; fs.style = 5; fs.tint = [0.4, 0.8, 0.3]; fs.pa = 0; fs.pb = 0 }
      }
    }
  }

  // flares age out fast; storms mutter thunder
  for (const id of slots) {
    const st = A.s[id]
    if (st.sp === 'flare' && st.on) { st.age += dtc * 1.8; if (st.age >= 1) park(id) }
  }
  A.thunderT -= dtc
  const stormUp = act2.some(id => A.s[id].sp === 'storm' && A.s[id].on)
  if (stormUp && A.thunderT <= 0) { A.thunderT = 3.5 + Math.random() * 3; tone(70 + Math.random() * 40, 0.14, 0.8); A.flash = 1 }
  A.flash = Math.max(0, (A.flash || 0) - dtc * 2.5)

  // ── write the fields: state → transforms, flare params ──
  for (const id of slots) {
    const f = sim.fields.get(id)
    if (!f) continue
    const st = A.s[id]
    f.transform.x = st.x; f.transform.y = st.y
    if (st.sp === 'flare') f.visualParams = [(st.on ? st.age : 1) + (st.style || 0) * 10 + (st.pa || 0) * 100 + (st.pb || 0) * 1000, (st.tint||[1,1,1])[0], (st.tint||[1,1,1])[1], (st.tint||[1,1,1])[2]]
    if (st.sp === 'storm') f.visualParams = [A.flash || 0, 0, 0, 0]
    if (st.sp === 'ember') f.visualParams = [st.heat === undefined ? 1 : Math.max(0, st.heat), 0, 0, 0]
  }

  // one voice per frame — the tone queue drains politely
  if (A.sq.length) wd.__play_sound = A.sq.shift()

  // a window for watchers: live positions + codex, read-only by convention
  if (typeof window !== 'undefined') window.__alembic = { s: A.s, codex: CX }

  // ── the codex ──
  const n = Object.keys(CX.found).length
  const held = A.grab && A.s[A.grab] ? NAMES[A.s[A.grab].sp] : null
  wd.hud = [
    { id: 'ax_c', type: 'text', x: '14px', y: '12px', text: 'CODEX ' + n + ' / ' + Object.keys(RX).length + (CX.last ? '  \u00b7  ' + CX.last : ''), color: '#c9b370', fontSize: '13px' },
    ...(held ? [{ id: 'ax_h', type: 'text', x: '14px', y: '34px', text: 'in hand: ' + held, color: '#8fb3c9', fontSize: '12px' }] : []),
    ...(A.spike && nowMs - (A.spikeAt || 0) < 20000 ? [{ id: 'ax_dbg', type: 'text', x: '14px', y: '56px', text: 'lag ' + A.spike, color: '#c97a4a', fontSize: '11px' }] : []),
  ]
  // publish the vessel's contents to the whiteboard: the room lights itself
  // by what it holds. u = [mx, my, count, then (x, y, class, glow) per element]
  const u = [((mx) - 256) / 256, ((my) - 256) / 256, 0]
  let cnt = 0
  for (const id of slots) {
    const st = A.s[id]
    if (!st.on || st.sp === 'flare' || cnt >= 20) continue
    u.push((st.x - 256) / 256, (st.y - 256) / 256, CLS[st.sp] || 0, GLOW[st.sp] || 0.4)
    cnt++
  }
  u[2] = cnt
  wd.gpuUniforms = u
} catch (e) { /* the vessel holds */ }

visualTypes.wgsl:
fn fbm_vs(p0: vec2f) -> f32 {
  var p = p0; var a = 0.5; var s = 0.0;
  for (var i = 0; i < 3; i++) {
    s += a * sin(p.x + sin(p.y * 1.7)) * sin(p.y + sin(p.x * 1.3));
    p = p * 2.03 + vec2f(1.7, 9.2); a *= 0.55;
  }
  return s;
}
fn visual_vessel(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t = time;
  // interior: warm dusk at the base rising to cool glass dark at the throat
  var col = mix(vec3f(0.020, 0.024, 0.042), vec3f(0.085, 0.056, 0.032), (uv.y + 1.0) * 0.5);
  col += vec3f(0.11, 0.065, 0.028) * pow(max(0.0, uv.y - 0.15), 1.6);   // hearth pools below
  // curved glass: fresnel rim brightening toward the walls, breathing slowly
  let wallD = max(abs(uv.x), abs(uv.y));
  let rim = smoothstep(0.82, 1.0, wallD);
  col += vec3f(0.14, 0.17, 0.20) * rim * (0.7 + 0.15 * sin(t * 0.21 + uv.y * 2.4));
  col += vec3f(0.30, 0.34, 0.38) * smoothstep(0.965, 1.0, wallD);       // the glass edge itself
  // floor caustics — light through liquid, slow interference weave
  let cy = smoothstep(0.45, 1.0, uv.y);
  let weave = sin(uv.x * 11.0 + t * 0.5 + sin(uv.x * 5.0 - t * 0.34) * 1.6) * sin(uv.x * 7.0 - t * 0.42);
  col += vec3f(0.10, 0.085, 0.05) * cy * smoothstep(0.1, 0.9, weave);
  // micro-bubbles climbing the walls (columns of fract-time beads)
  for (var i = 0; i < 4; i++) {
    let fi = f32(i);
    let bx = select(-0.9 + fi * 0.055, 0.9 - (fi - 2.0) * 0.055, i >= 2);
    let cyc = fract(t * (0.05 + fi * 0.013) + fi * 0.37);
    let bpos = vec2f(bx + 0.02 * sin(t * 0.6 + fi), 0.95 - cyc * 1.85);
    let bd = uv - bpos;
    col += vec3f(0.20, 0.24, 0.28) * exp(-dot(bd, bd) * 3200.0) * sin(cyc * 3.14159);
  }
  // drifting motes in the body of the liquid
  let n = fbm_vs(uv * 3.0 + vec2f(t * 0.02, -t * 0.013));
  col += vec3f(0.030, 0.028, 0.022) * smoothstep(0.3, 0.9, n);
  // the cursor is a lens-light moving through the glass
  let mp = vec2f(uni(0), uni(1));
  let md = uv - mp;
  col += vec3f(0.06, 0.05, 0.033) * exp(-dot(md, md) * 8.0);
  // ── the vessel answers its contents: cast light, floor gleam, shadow ──
  // (the hook publishes every element: x, y, class, glow — from uni(3))
  let cnt = i32(uni(2) + 0.5);
  let FLOORY = 0.898;
  for (var e = 0; e < 20; e++) {
    if (e >= cnt) { break; }
    let ex = uni(3 + e * 4);
    let ey = uni(4 + e * 4);
    let cls = i32(uni(5 + e * 4) + 0.5);
    let glow = uni(6 + e * 4);
    let d2 = dot(uv - vec2f(ex, ey), uv - vec2f(ex, ey));
    // each thing lights the room in its own color
    var lc = vec3f(0.0);
    if (cls == 1) { lc = vec3f(1.0, 0.42, 0.10); }        // fire: warm
    else if (cls == 2) { lc = vec3f(0.22, 0.45, 0.75); }  // water: cool
    else if (cls == 3) { lc = vec3f(0.45, 0.5, 0.9); }    // storm: cold
    else if (cls == 4) { lc = vec3f(1.0, 0.85, 0.45); }   // star: golden
    else if (cls == 5) { lc = vec3f(0.16, 0.15, 0.14); }  // solids: only a dull gleam
    if (cls >= 1 && cls <= 4) {
      col += lc * glow * 0.085 / (0.06 + d2 * 7.0);
    }
    // the polished floor: a smeared gleam of everything above it
    if (uv.y > FLOORY - 0.012) {
      let ry = 2.0 * FLOORY - ey;
      let rd = vec2f((uv.x - ex) * 1.7, (uv.y - ry) * 0.75);
      col += lc * glow * 0.4 * exp(-dot(rd, rd) * 26.0);
    }
    // contact shadow pooled beneath, fading with height
    let h = max(0.0, FLOORY - ey);
    let sd = vec2f((uv.x - ex) * (2.4 + h * 3.0), (uv.y - (FLOORY + 0.04)) * 10.0);
    col *= 1.0 - 0.45 * exp(-dot(sd, sd)) / (1.0 + h * 7.0);
  }
  if (col.x != col.x || col.y != col.y || col.z != col.z) { col = vec3f(0.01); }
  return vec4f(clamp(col, vec3f(0.0), vec3f(1.0)), 1.0);
}

fn visual_ember(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let heat0 = select(clamp(params.x, 0.05, 1.0), 1.0, params.x <= 0.0);   // life of the fire
  let t2 = time * (0.6 + 0.75 * heat0);
  var p = vec2f(uv.x, uv.y + 0.14);
  // rising turbulence bends the tongue; finer noise erodes its edge
  let w1 = mod_alfbm(p * 2.6 + vec2f(0.0, t2 * 1.8));
  let w2 = mod_alfbm(p * 5.2 + vec2f(3.7, t2 * 2.7));
  p.x += (w1 - 0.5) * 0.34 * (0.6 - p.y * 0.4);
  let env = length(vec2f(p.x * (1.6 - p.y * 0.5), (p.y - 0.02) * 1.02));
  var flame = clamp(((0.28 + 0.32 * heat0) - env) * 2.3 + (w2 - 0.5) * 0.65 * heat0, 0.0, 1.0);
  let heat = flame * (1.15 + (w1 - 0.5) * 0.5);
  // blackbody ramp: deep red -> orange -> yellow -> near white
  var col = mix(vec3f(0.32, 0.015, 0.0), vec3f(0.95, 0.30, 0.02), clamp(heat * 1.7, 0.0, 1.0));
  col = mix(col, vec3f(1.0, 0.74, 0.22), clamp(heat * 1.7 - 0.6, 0.0, 1.0));
  col = mix(col, vec3f(1.0, 0.96, 0.82), clamp(heat * 1.7 - 1.2, 0.0, 1.0));
  // the coal: rocky lit mass, emissive cracks breathing
  let cq = uv - vec2f(0.0, 0.44);
  let coalR = 0.33 + 0.06 * (mod_alfbm(uv * 6.0) - 0.5);
  let coal = smoothstep(coalR, coalR - 0.10, length(cq));
  let ckn = mod_alfbm(uv * 9.0 + 5.0);
  let crack = smoothstep(0.10, 0.0, abs(ckn - 0.5)) * (0.55 + 0.45 * sin(time * 1.2 + ckn * 6.0)) * (0.15 + 0.85 * heat0);
  let lit = 0.75 - cq.y * 0.9;                       // hearth-light from above the coal
  let coalCol = mix(vec3f(0.055, 0.032, 0.028) * lit, vec3f(1.0, 0.32, 0.04), crack);
  col = mix(col, coalCol, coal);
  var a = max(clamp(flame * 1.4, 0.0, 1.0), coal);
  a *= smoothstep(1.0, 0.9, length(uv));
  if (a < 0.012) { return vec4f(0.0); }
  return vec4f(col * (0.55 + 0.6 * heat0), a);
}

fn visual_dew(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let wob = vec2f(uv.x * (1.0 + 0.045 * sin(time * 2.1)), uv.y * (1.0 - 0.045 * sin(time * 2.1)));
  let r = length(wob);
  if (r > 0.92) { return vec4f(0.0); }
  let rr = r / 0.92;
  let z = sqrt(max(0.0, 1.0 - rr * rr));
  let nrm = normalize(vec3f(wob.x, wob.y, z * 0.92));
  let L = normalize(vec3f(-0.45, -0.65, 0.62));        // the room key light, upper-left
  let fres = pow(1.0 - z, 2.6);
  // refraction: the world behind, pulled toward the center and cooled
  var col = behind.rgb * vec3f(0.80, 0.95, 1.08) * (0.72 + z * 0.5);
  col += vec3f(0.09, 0.20, 0.36) * (0.5 + fres);                  // water body
  col += vec3f(0.55, 0.75, 0.95) * fres * 0.85;                   // limb light
  let dif = max(0.0, dot(nrm, L));
  col += vec3f(0.10, 0.16, 0.22) * dif * 0.5;
  // specular window catch-light, tight and slightly stretched
  let spec = pow(max(0.0, dot(reflect(vec3f(0.0, 0.0, -1.0), nrm), L)), 90.0);
  col += vec3f(1.0) * spec * 1.1;
  // gathered caustic at the foot of the droplet
  let caust = exp(-dot(wob - vec2f(0.10, 0.56), wob - vec2f(0.10, 0.56)) * 16.0);
  col += vec3f(0.35, 0.55, 0.75) * caust * 0.45;
  return vec4f(col, smoothstep(0.92, 0.82, r) * 0.96);
}

fn visual_gale(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let r = length(uv);
  if (r > 1.0) { return vec4f(0.0); }
  var a = 0.0;
  var col = vec3f(0.0);
  // three braided streamlines, each a thin band around a curved path
  for (var i = 0; i < 3; i++) {
    let fi = f32(i);
    let ph = time * 1.9 + fi * 2.09;
    let path = 0.22 * sin(uv.x * 3.4 + ph) + 0.16 * sin(uv.x * 6.1 - ph * 0.7) - 0.34 + fi * 0.34;
    let w = 0.05 + 0.03 * sin(uv.x * 2.0 + ph);
    let band = smoothstep(w, 0.0, abs(uv.y - path)) * smoothstep(1.0, 0.35, r);
    a += band * 0.42;
    col += vec3f(0.72, 0.84, 0.92) * band;
  }
  // caught leaves of light spiraling with it
  for (var k = 0; k < 2; k++) {
    let fk = f32(k);
    let la = time * 1.3 + fk * 3.14;
    let lp = vec2f(cos(la), sin(la) * 0.6) * (0.45 + 0.1 * sin(time * 0.7 + fk));
    let ld = uv - lp;
    let leaf = exp(-dot(ld, ld) * 160.0);
    a += leaf * 0.7;
    col += vec3f(0.9, 0.95, 0.85) * leaf;
  }
  a += exp(-r * r * 3.0) * 0.10;
  col += vec3f(0.6, 0.7, 0.8) * exp(-r * r * 3.0) * 0.12;
  return vec4f(col, clamp(a, 0.0, 0.9));
}

fn visual_loam(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let edge = 0.90 + 0.07 * (mod_alfbm(vec2f(atan2(uv.y, uv.x) * 1.6, 7.0)) - 0.5);
  let r = length(uv);
  if (r > edge) { return vec4f(0.0); }
  let hs = 4.5;
  let h  = mod_alfbm(uv * hs);
  let hx = mod_alfbm((uv + vec2f(0.05, 0.0)) * hs);
  let hy = mod_alfbm((uv + vec2f(0.0, 0.05)) * hs);
  let nrm = normalize(vec3f((h - hx) * 5.0, (h - hy) * 5.0, 1.0));
  let dif = max(0.0, dot(nrm, normalize(vec3f(-0.4, -0.7, 0.6))));
  var col = mix(vec3f(0.16, 0.105, 0.055), vec3f(0.42, 0.30, 0.16), h) * (0.35 + dif * 0.9);
  // embedded pebbles catch the light on their crowns
  let g = uv * 3.4;
  let cell = floor(g);
  let jit = vec2f(mod_alhash(cell), mod_alhash(cell + 19.7)) - 0.5;
  let pq = fract(g) - 0.5 - jit * 0.5;
  let peb = smoothstep(0.30, 0.18, length(pq));
  col = mix(col, vec3f(0.50, 0.40, 0.26) * (0.5 + 0.7 * max(0.0, -pq.y) + 0.4 * mod_alhash(cell + 7.0)), peb * 0.9);
  return vec4f(col * (0.85 + 0.3 * (1.0 - r)), smoothstep(edge, edge - 0.11, r));
}

fn visual_mist(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let r = length(uv);
  if (r > 1.0) { return vec4f(0.0); }
  let w = mod_alwarp(uv * 1.5 + vec2f(7.0, 3.0), time * 0.35);
  let w2 = mod_alfbm(uv * 3.1 + vec2f(-time * 0.06, time * 0.04) + w * 1.4);
  var dens = smoothstep(0.38, 0.8, w * 0.62 + w2 * 0.5);
  dens *= smoothstep(1.0, 0.3, r);
  // vapor is lit from above: bright crowns, shadowed underbelly
  let lit = 0.72 + 0.5 * smoothstep(0.5, -0.6, uv.y) * w;
  var col = mix(behind.rgb, vec3f(0.82, 0.87, 0.93) * lit, 0.8);
  return vec4f(col, clamp(dens * 0.8, 0.0, 0.8));
}

fn visual_rain(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  // head near the bottom of the cell (it falls +y), tail streaming up behind
  let head = uv - vec2f(0.0, 0.45);
  let hr = length(head * vec2f(2.0, 1.4));
  let hbody = smoothstep(0.55, 0.25, hr);
  let tail = smoothstep(0.30, 0.0, abs(uv.x + 0.06 * sin(uv.y * 6.0 + time * 3.0))) * smoothstep(0.6, -0.95, uv.y) * 0.6;
  var col = mix(vec3f(0.30, 0.50, 0.72), vec3f(0.70, 0.88, 1.0), hbody);
  col += behind.rgb * 0.25;
  let hi = exp(-dot(head - vec2f(-0.12, -0.10), head - vec2f(-0.12, -0.10)) * 30.0);
  col += vec3f(1.0) * hi * 0.7;
  let a = clamp(hbody + tail * (0.5 + 0.2 * sin(time * 2.8)), 0.0, 1.0);
  if (a < 0.012) { return vec4f(0.0); }
  return vec4f(col, a * 0.9);
}

fn visual_magma(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let edge = 0.90 + 0.06 * (mod_alfbm(vec2f(atan2(uv.y, uv.x) * 1.9, 2.0)) - 0.5);
  let r = length(uv);
  if (r > edge) { return vec4f(0.0); }
  // crust heightfield + finite-difference normal — the plates are LIT, not flat
  let hs = 3.2;
  let h  = mod_alfbm(uv * hs + vec2f(0.0, time * 0.04));
  let hx = mod_alfbm((uv + vec2f(0.04, 0.0)) * hs + vec2f(0.0, time * 0.04));
  let hy = mod_alfbm((uv + vec2f(0.0, 0.04)) * hs + vec2f(0.0, time * 0.04));
  let nrm = normalize(vec3f((h - hx) * 6.0, (h - hy) * 6.0, 1.0));
  let L = normalize(vec3f(-0.4, -0.7, 0.6));
  let dif = max(0.0, dot(nrm, L));
  // fissures where the height crosses its middle; they breathe
  let fis = smoothstep(0.10, 0.015, abs(h - 0.5));
  let breath = 0.6 + 0.4 * sin(time * 0.85 + h * 5.0);
  var col = mix(vec3f(0.045, 0.032, 0.032), vec3f(0.17, 0.13, 0.12), h) * (0.35 + dif * 0.85);
  var molten = mix(vec3f(0.9, 0.22, 0.01), vec3f(1.0, 0.65, 0.12), breath * fis);
  col = mix(col, molten * (0.9 + breath * 0.7), fis);
  col = mix(col, vec3f(1.0, 0.62, 0.12) * breath, smoothstep(0.24, 0.0, r) * 0.5);
  col += vec3f(1.0, 0.4, 0.06) * fis * breath * 0.25;   // fissure light spills onto the crust
  return vec4f(col, smoothstep(edge, edge - 0.12, r));
}

fn hash_mo(p: vec2f) -> f32 { return fract(sin(dot(p, vec2f(269.5, 183.3))) * 43758.5453); }
fn visual_moss(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  // three overlapping cushions make the clump silhouette
  var d = 1e5;
  d = min(d, length(uv - vec2f(-0.28, 0.18)) - 0.52);
  d = min(d, length(uv - vec2f(0.30, 0.22)) - 0.48);
  d = min(d, length(uv - vec2f(0.02, -0.20)) - 0.58);
  let fuzz = 0.05 * sin(atan2(uv.y, uv.x) * 13.0 + time * 0.5) + 0.04 * sin(atan2(uv.y, uv.x) * 23.0);
  d += fuzz;
  if (d > 0.10) { return vec4f(0.0); }
  let body = smoothstep(0.10, -0.10, d);
  // lit from above, dark in the creases
  var col = mix(vec3f(0.06, 0.17, 0.07), vec3f(0.28, 0.55, 0.20), smoothstep(0.4, -0.4, uv.y) * 0.5 + 0.25);
  // spore-lights: tiny slow lanterns in the weave
  let g = uv * 5.5;
  let cell = floor(g);
  let sp = hash_mo(cell);
  let tw = 0.5 + 0.5 * sin(time * (0.4 + sp * 0.5) + sp * 40.0);
  let sd = length(fract(g) - 0.5 - (vec2f(hash_mo(cell + 3.1), hash_mo(cell + 5.7)) - 0.5) * 0.6);
  col += vec3f(0.55, 0.9, 0.35) * smoothstep(0.12, 0.02, sd) * step(0.75, sp) * tw * 0.8;
  return vec4f(col, body);
}

fn visual_wildfire(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let t2 = time * 2.0;
  let w1 = mod_alfbm(uv * 2.7 + vec2f(t2 * 0.6, -t2 * 1.4));
  let w2 = mod_alfbm(uv * 5.4 + vec2f(-t2 * 0.8, -t2 * 2.1) + w1 * 1.8);
  var field = clamp((0.70 - length(uv)) * 2.1 + (w2 - 0.5) * 1.35 + (w1 - 0.5) * 0.6, 0.0, 1.35);
  if (field < 0.02) { return vec4f(0.0); }
  // blackbody, run hotter than the ember — this thing is hungry
  var col = mix(vec3f(0.30, 0.01, 0.0), vec3f(1.0, 0.32, 0.02), clamp(field * 1.5, 0.0, 1.0));
  col = mix(col, vec3f(1.0, 0.72, 0.18), clamp(field * 1.5 - 0.55, 0.0, 1.0));
  col = mix(col, vec3f(1.0, 0.97, 0.9), clamp(field * 1.5 - 1.05, 0.0, 1.0));
  let a = clamp(field * 1.3, 0.0, 1.0) * smoothstep(1.0, 0.85, length(uv));
  return vec4f(col * 1.45, a);
}

fn visual_storm(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let r = length(uv);
  if (r > 1.0) { return vec4f(0.0); }
  let w = mod_alwarp(uv * 1.7 + vec2f(11.0, 4.0), time * 0.22);
  let w2 = mod_alfbm(uv * 3.4 + vec2f(time * 0.05, 0.0) + w * 1.3);
  var dens = smoothstep(0.36, 0.78, w * 0.6 + w2 * 0.52) * smoothstep(1.0, 0.4, r);
  if (dens < 0.015) { return vec4f(0.0); }
  // moon-lit crowns above, charged darkness beneath
  let lit = smoothstep(0.55, -0.6, uv.y);
  var col = mix(vec3f(0.045, 0.045, 0.075), vec3f(0.30, 0.29, 0.40), w * (0.4 + lit * 0.8));
  col += vec3f(0.42, 0.40, 0.52) * lit * w2 * 0.35;
  // the bolt: a noise-walked channel with two forks. params.x = thunder pulse.
  let liveness = 0.15 + 0.85 * clamp(params.x, 0.0, 1.0);
  let wob = (mod_alnoise(vec2f(uv.y * 4.5, time * 1.1)) - 0.5) * 0.7;
  let chan = abs(uv.x - wob - uv.y * 0.15);
  let bolt = smoothstep(0.030, 0.0, chan) * smoothstep(0.85, 0.1, abs(uv.y));
  let f1 = smoothstep(0.024, 0.0, abs((uv.y - 0.12) - (uv.x - wob) * 1.7)) * smoothstep(0.45, 0.05, abs(uv.x - 0.22));
  let f2 = smoothstep(0.024, 0.0, abs((uv.y + 0.22) + (uv.x - wob) * 1.4)) * smoothstep(0.38, 0.05, abs(uv.x + 0.20));
  let strike = (bolt + f1 * 0.6 + f2 * 0.5) * liveness;
  col += vec3f(0.80, 0.82, 1.0) * strike * 2.2 * dens;
  col += vec3f(0.45, 0.47, 0.75) * exp(-r * r * 2.2) * liveness * 0.4;   // the cloud glows from within
  return vec4f(col, clamp(dens * 1.15, 0.0, 0.95));
}

fn visual_ash(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let bump = 0.12 * sin(atan2(uv.y, uv.x) * 6.0 + 2.0) + 0.07 * sin(atan2(uv.y, uv.x) * 11.0);
  let r = length(uv) + bump;
  if (r > 0.88) { return vec4f(0.0); }
  let flake = sin(uv.x * 9.0 + uv.y * 7.0) * 0.5 + 0.5;
  var col = mix(vec3f(0.24, 0.235, 0.23), vec3f(0.42, 0.41, 0.40), flake) * (0.75 + 0.3 * (1.0 - r));
  // the last vein of heat, breathing out slowly
  let vein = smoothstep(0.06, 0.0, abs(sin(uv.x * 5.0 + 1.0) * 0.3 - uv.y));
  col += vec3f(0.9, 0.30, 0.05) * vein * (0.25 + 0.20 * sin(time * 0.7)) * smoothstep(0.9, 0.3, r);
  return vec4f(col, smoothstep(0.88, 0.62, r) * 0.9);
}

fn visual_glassgem(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  // hexagonal silhouette
  let qa = vec2f(abs(uv.x), abs(uv.y));
  let hex = max(qa.x * 0.866 + qa.y * 0.5, qa.y);
  if (hex > 0.82) { return vec4f(0.0); }
  // kaleidoscope fold: interior facets
  let ang = atan2(uv.y, uv.x);
  let fold = abs(fract(ang / 1.0472) - 0.5) * 2.0;    // 6-fold
  let facet = smoothstep(0.0, 1.0, fold) * 0.5 + 0.5 * smoothstep(0.2, 0.8, length(uv));
  // the world behind, seen through cut glass
  var col = behind.rgb * vec3f(0.9, 1.02, 1.05) * (0.55 + facet * 0.5);
  col += vec3f(0.30, 0.42, 0.45) * facet * 0.35;
  // dispersion along facet edges — slow rainbow, never flashing
  let edge = smoothstep(0.82, 0.76, hex) - smoothstep(0.68, 0.5, hex);
  let hue = fold * 3.0 + time * 0.25;
  col += (0.5 + 0.5 * cos(vec3f(hue, hue + 2.09, hue + 4.19))) * max(edge, 0.0) * 0.55;
  let hi = exp(-dot(uv - vec2f(-0.25, -0.3), uv - vec2f(-0.25, -0.3)) * 20.0);
  col += vec3f(1.0) * hi * 0.5;
  return vec4f(col, smoothstep(0.82, 0.74, hex) * 0.85 + max(edge, 0.0) * 0.15);
}

fn visual_stone(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let edge = 0.90 + 0.09 * (mod_alfbm(vec2f(atan2(uv.y, uv.x) * 1.4, 3.0)) - 0.5);
  let r = length(uv);
  if (r > edge) { return vec4f(0.0); }
  let hs = 3.0;
  let h  = mod_alfbm(uv * hs + 9.0);
  let hx = mod_alfbm((uv + vec2f(0.05, 0.0)) * hs + 9.0);
  let hy = mod_alfbm((uv + vec2f(0.0, 0.05)) * hs + 9.0);
  let nrm = normalize(vec3f((h - hx) * 6.0, (h - hy) * 6.0, 1.0));
  let dif = max(0.0, dot(nrm, normalize(vec3f(-0.4, -0.7, 0.6))));
  var col = mix(vec3f(0.13, 0.135, 0.16), vec3f(0.38, 0.39, 0.43), h) * (0.30 + dif * 1.0);
  col = mix(col, vec3f(0.09, 0.095, 0.11), smoothstep(0.09, 0.02, abs(mod_alnoise(uv * 4.0 + 2.0) - 0.5)) * 0.55);
  let spec = pow(max(0.0, dot(nrm, normalize(vec3f(-0.3, -0.8, 0.52)))), 24.0);
  col += vec3f(0.5, 0.52, 0.58) * spec * 0.35;
  return vec4f(col, smoothstep(edge, edge - 0.10, r));
}

fn visual_char(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let edge = 0.88 + 0.10 * (mod_alfbm(vec2f(atan2(uv.y, uv.x) * 1.7, 5.0)) - 0.5);
  let r = length(uv);
  if (r > edge) { return vec4f(0.0); }
  let hs = 5.0;
  let h  = mod_alfbm(uv * hs + 3.0);
  let hx = mod_alfbm((uv + vec2f(0.05, 0.0)) * hs + 3.0);
  let hy = mod_alfbm((uv + vec2f(0.0, 0.05)) * hs + 3.0);
  let nrm = normalize(vec3f((h - hx) * 6.0, (h - hy) * 6.0, 1.0));
  let dif = max(0.0, dot(nrm, normalize(vec3f(-0.4, -0.7, 0.6))));
  // burnt black, a grey ash bloom on the crowns
  var col = mix(vec3f(0.030, 0.026, 0.024), vec3f(0.115, 0.105, 0.10), h) * (0.3 + dif * 0.9);
  col = mix(col, vec3f(0.20, 0.195, 0.19), smoothstep(0.6, 0.9, h) * max(0.0, -uv.y) * 0.7);
  // one seed of heat left in the deepest crevice, breathing at the edge of death
  let seed = smoothstep(0.10, 0.0, abs(h - 0.5)) * smoothstep(0.5, 0.1, r);
  col += vec3f(0.55, 0.10, 0.01) * seed * (0.12 + 0.10 * sin(time * 0.5));
  return vec4f(col, smoothstep(edge, edge - 0.10, r));
}

fn visual_star(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let r = length(uv);
  if (r > 1.0) { return vec4f(0.0); }
  let ang = atan2(uv.y, uv.x);
  let pulse = 0.85 + 0.15 * sin(time * 0.6);
  let core = exp(-r * r * 16.0) * 2.4 * pulse;
  // two interleaved diffraction spike sets, counter-turning slowly
  let ray1 = pow(max(0.0, cos(ang * 4.0 + time * 0.22)), 14.0) * smoothstep(1.0, 0.1, r);
  let ray2 = pow(max(0.0, cos(ang * 6.0 - time * 0.31)), 20.0) * smoothstep(0.8, 0.1, r) * 0.7;
  // chromatic halo ring
  let ringR = abs(r - 0.5 - 0.04 * sin(time * 0.5));
  let ring = smoothstep(0.10, 0.0, ringR);
  let hue = ang * 0.95 + time * 0.2;
  var col = vec3f(1.0, 0.94, 0.68) * (core + (ray1 + ray2) * 0.9);
  col += (0.5 + 0.5 * cos(vec3f(hue, hue + 2.09, hue + 4.19))) * ring * 0.5 * pulse;
  let a = clamp(core + ray1 + ray2 + ring * 0.5, 0.0, 1.0) * smoothstep(1.0, 0.8, r);
  if (a < 0.012) { return vec4f(0.0); }
  return vec4f(col, a);
}

fn visual_flare(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let pB = floor(params.x / 1000.0);
  let r1 = params.x - pB * 1000.0;
  let pA = floor(r1 / 100.0);
  let r2 = r1 - pA * 100.0;
  let style = i32(r2 / 10.0);
  let age = clamp(r2 - f32(style) * 10.0, 0.0, 1.0);
  if (age >= 1.0) { return vec4f(0.0); }
  let r = length(uv);
  let ang = atan2(uv.y, uv.x);
  let col0 = vec3f(params.y, params.z, params.w);
  let ring = smoothstep(0.09, 0.0, abs(r - age * 0.9));
  let bloom = exp(-r * r * 7.0) * (1.0 - age);
  var a = ring * (1.0 - age) * 0.8 + bloom;
  var col = col0 * (1.2 + bloom) + vec3f(1.0) * bloom * 0.35;
  if (style == 1) {
    // fire: sparks thrown up on ballistic arcs, cooling as they fly
    for (var i = 0; i < 6; i++) {
      let fi = f32(i);
      let sa = -1.5708 + (mod_alhash(vec2f(fi, 3.0)) - 0.5) * 2.2;
      let sp = vec2f(cos(sa), sin(sa)) * age * (0.5 + mod_alhash(vec2f(fi, 7.0)) * 0.5);
      let g = vec2f(sp.x, sp.y + age * age * 0.55);
      let d = uv - g;
      let sparkle = exp(-dot(d, d) * 700.0) * (1.0 - age);
      a += sparkle;
      col += mix(vec3f(1.0, 0.85, 0.4), vec3f(0.8, 0.2, 0.02), age) * sparkle * 2.0;
    }
  } else if (style == 2) {
    // water: a crown — squashed ring plus flung droplets that fall back
    let cr = smoothstep(0.06, 0.0, abs(length(vec2f(uv.x, uv.y * 2.4)) - age * 0.8)) * (1.0 - age);
    a += cr * 0.9;
    col += vec3f(0.75, 0.9, 1.0) * cr * 1.4;
    for (var i = 0; i < 5; i++) {
      let fi = f32(i);
      let dx = (fi - 2.0) * 0.22;
      let g = vec2f(dx * (0.4 + age), -age * 0.8 * (1.0 - abs(dx)) + age * age * 1.1);
      let d = uv - g;
      let drop = exp(-dot(d, d) * 900.0) * (1.0 - age);
      a += drop;
      col += vec3f(0.7, 0.88, 1.0) * drop * 1.6;
    }
  } else if (style == 3) {
    // earth: a slow bloom of dust, textured by the shared noise
    let dust = mod_alfbm(uv * 5.0 + age * 2.0) * smoothstep(age * 1.1, age * 0.3, r) * (1.0 - age);
    a += dust * 0.7;
    col += col0 * dust * 1.2;
  } else if (style == 4) {
    // storm: jagged crackle arcs biting around the ring
    let bite = pow(abs(sin(ang * 7.0 + age * 14.0)), 24.0) * smoothstep(0.08, 0.0, abs(r - age * 0.85));
    a += bite * (1.0 - age) * 1.2;
    col += vec3f(0.85, 0.88, 1.0) * bite * 2.5;
  } else if (style == 5) {
    // growth: green motes spiraling gently upward
    for (var i = 0; i < 5; i++) {
      let fi = f32(i);
      let ma = fi * 1.257 + age * 3.0;
      let g = vec2f(cos(ma) * 0.3 * (1.0 - age * 0.4), -age * 0.7 + sin(ma) * 0.12);
      let d = uv - g;
      let mote = exp(-dot(d, d) * 800.0) * (1.0 - age);
      a += mote;
      col += vec3f(0.5, 0.95, 0.4) * mote * 1.5;
    }
  }
  // the parents' last gesture: class remnants on either side, dissolving inward
  for (var s = 0; s < 2; s++) {
    let cls = select(pA, pB, s == 1);
    if (cls < 0.5) { continue; }
    let side = select(-1.0, 1.0, s == 1);
    let cx = side * 0.42 * (1.0 - age * 0.75);
    let fade = (1.0 - age) * (1.0 - age);
    let ic = i32(cls + 0.5);
    if (ic == 1) {
      // fire: sparks rising, cooling as they go out
      for (var k = 0; k < 3; k++) {
        let fk = f32(k);
        let g = vec2f(cx + (mod_alhash(vec2f(fk, side + 2.0)) - 0.5) * 0.24, -age * (0.3 + fk * 0.14));
        let d = uv - g;
        let sp2 = exp(-dot(d, d) * 800.0) * fade;
        a += sp2;
        col += mix(vec3f(1.0, 0.8, 0.35), vec3f(0.7, 0.15, 0.02), age) * sp2 * 1.8;
      }
    } else if (ic == 2) {
      // water: droplets letting go, falling away
      for (var k = 0; k < 3; k++) {
        let fk = f32(k);
        let g = vec2f(cx + (fk - 1.0) * 0.13, age * (0.25 + fk * 0.12) - 0.06);
        let d = uv - g;
        let dr = exp(-dot(d, d) * 900.0) * fade;
        a += dr;
        col += vec3f(0.6, 0.85, 1.0) * dr * 1.5;
      }
    } else if (ic == 3) {
      // storm: one last biting arc
      let d = vec2f(uv.x - cx, uv.y);
      let arc = smoothstep(0.02, 0.0, abs(length(d) - 0.16 - age * 0.1)) * pow(abs(sin(atan2(d.y, d.x) * 5.0 + age * 9.0)), 8.0);
      a += arc * fade * 1.2;
      col += vec3f(0.8, 0.84, 1.0) * arc * fade * 2.2;
    } else if (ic == 4) {
      // star: a four-ray glint refusing to die quietly
      let d = vec2f(uv.x - cx, uv.y);
      let gl = exp(-dot(d, d) * 500.0) + pow(max(0.0, cos(atan2(d.y, d.x) * 2.0)), 30.0) * exp(-length(d) * 9.0) * 0.8;
      a += gl * fade;
      col += vec3f(1.0, 0.94, 0.6) * gl * fade * 1.6;
    } else if (ic == 5) {
      // earth: dust settling down and out
      let d = vec2f(uv.x - cx, uv.y - age * 0.18);
      let du = mod_alfbm(d * 7.0 + age * 3.0) * smoothstep(0.34, 0.05, length(d));
      a += du * fade * 0.8;
      col += vec3f(0.55, 0.42, 0.26) * du * fade * 1.1;
    } else if (ic == 6) {
      // air: a curling wisp unwinding
      let d = vec2f(uv.x - cx, uv.y);
      let wsp = smoothstep(0.035, 0.0, abs(d.y - 0.10 * sin(d.x * 9.0 + age * 12.0 + side))) * smoothstep(0.4, 0.1, abs(d.x));
      a += wsp * fade * 0.9;
      col += vec3f(0.75, 0.86, 0.94) * wsp * fade * 1.3;
    }
  }
  a = clamp(a, 0.0, 1.0);
  if (a < 0.01) { return vec4f(0.0); }
  return vec4f(col, a);
}

modules.wgsl:
// WORLD3 — the cafe's shared 3D raymarching kit (canonical copy).
// Everything ONE DAY, TIDEGLASS, and MARIONETTES 3D each hand-rolled, extracted
// once: camera, SDF primitives, domain ops, marcher, normals, soft shadows,
// AO, and a standard light rig. Ship it in your scene as a module:
//
//   { "type": "define_module", "name": "world3", "wgsl": <this file> }
//
// THE ONE CONTRACT — your scene defines the world map in its OWN module:
//
//   fn w3_map(p: vec3f) -> vec2f   // returns (signed distance, material id)
//
// WGSL resolves module-scope functions in any order, so the kit's marchers can
// call w3_map before your module defines it. A scene that ships world3 without
// defining w3_map will not compile — the contract is load-bearing.
//
// CAMERA CONVENTION (whiteboard rows 60–62, so hooks can drive the eye):
//   uni4(60) = ro.xyz, fov     ·  uni4(61) = target.xyz, roll(unused)
//   A hook that writes these makes any world3 scene orbit/walk for free.
//
// Typical visual:
//   let ro = uni4(60).xyz;  let fov = max(uni4(60).w, 0.6);
//   let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
//   let hit = mod_w3_march(ro, rd, 0.1, 60.0, 96);
//   if (hit.x > 0.0) {
//     let pos = ro + rd * hit.x;
//     let n = mod_w3_nrm(pos, 0.02);
//     let sh = mod_w3_shadow(pos + n * 0.05, sunDir, 30.0, 8.0);
//     let ao = mod_w3_ao(pos, n);
//     col = mod_w3_light(albedoFor(i32(hit.y)), n, rd, sunDir, sunCol, skyCol, sh, ao);
//   }
// Output linear HDR — the engine's ACES + bloom do the grading.

// ── camera ─────────────────────────────────────────────────────────────────
// Ray through a screen point for a look-at camera. uv is the visual's -1..1
// (y down — the flip is handled here, pass it raw).
fn mod_w3_ray(uv: vec2f, ro: vec3f, ta: vec3f, fov: f32) -> vec3f {
  let fw = normalize(ta - ro);
  let rt = normalize(cross(fw, vec3f(0.0, 1.0, 0.0)));
  let up = cross(rt, fw);
  return normalize(uv.x * rt * fov - uv.y * up * fov + fw);
}

// ── SDF primitives (3D) ────────────────────────────────────────────────────
fn mod_w3_sphere(p: vec3f, r: f32) -> f32 { return length(p) - r; }

fn mod_w3_box(p: vec3f, b: vec3f) -> f32 {
  let d = abs(p) - b;
  return length(max(d, vec3f(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

fn mod_w3_rbox(p: vec3f, b: vec3f, r: f32) -> f32 {
  return mod_w3_box(p, b - vec3f(r)) - r;
}

fn mod_w3_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - r;
}

// vertical capped cylinder: half-height h, radius r
fn mod_w3_cyl(p: vec3f, h: f32, r: f32) -> f32 {
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(r, h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

// tapered vertical cylinder: radius r0 at -h → r1 at +h (towers, spires)
fn mod_w3_cone(p: vec3f, h: f32, r0: f32, r1: f32) -> f32 {
  let t = clamp((p.y + h) / (2.0 * h), 0.0, 1.0);
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(mix(r0, r1, t), h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn mod_w3_torus(p: vec3f, R: f32, r: f32) -> f32 {
  return length(vec2f(length(p.xz) - R, p.y)) - r;
}

fn mod_w3_octa(p: vec3f, s: f32) -> f32 {
  let q = abs(p);
  return (q.x + q.y + q.z - s) * 0.57735027;
}

fn mod_w3_plane(p: vec3f, n: vec3f, d: f32) -> f32 { return dot(p, n) + d; }

// ── skeleton assembly (nodes + struts + tissue) ────────────────────────────
// Build forms as a GRAPH: struts between shared node points, joined with
// opSmoothUnion (the "linkage tissue"). Gaps become impossible by construction
// — parts share endpoints instead of hoping coordinates line up. Use tissue k
// at structural joints (0.2–0.5) and hard min for edges that must stay crisp.

// exact closed-form distance to a quadratic bezier strut (S start, Ctl control,
// E end, radius r) — the connective arc: vaults, arches, branches, cables
fn mod_w3_bezStrut(pos: vec3f, S: vec3f, Ctl: vec3f, E: vec3f, r: f32) -> f32 {
  let a = Ctl - S;
  let b = S - 2.0 * Ctl + E;
  let c = a * 2.0;
  let d = S - pos;
  let bb = dot(b, b);
  if (bb < 1e-9) {
    let pa = pos - S;
    let ba = E - S;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
  }
  let kk = 1.0 / bb;
  let kx = kk * dot(a, b);
  let ky = kk * (2.0 * dot(a, a) + dot(d, b)) / 3.0;
  let kz = kk * dot(d, a);
  let pp = ky - kx * kx;
  let qq = kx * (2.0 * kx * kx - 3.0 * ky) + kz;
  let h = qq * qq + 4.0 * pp * pp * pp;
  var res: f32;
  if (h >= 0.0) {
    let hs = sqrt(h);
    let x1 = (hs - qq) / 2.0;
    let x2 = (-hs - qq) / 2.0;
    let t = clamp(sign(x1) * pow(abs(x1), 0.3333333) + sign(x2) * pow(abs(x2), 0.3333333) - kx, 0.0, 1.0);
    let g = d + (c + b * t) * t;
    res = dot(g, g);
  } else {
    let z = sqrt(-pp);
    let v = acos(qq / (pp * z * 2.0)) / 3.0;
    let m = cos(v);
    let n = sin(v) * 1.7320508;
    let t1 = clamp((m + m) * z - kx, 0.0, 1.0);
    let t2 = clamp((-n - m) * z - kx, 0.0, 1.0);
    let g1 = d + (c + b * t1) * t1;
    let g2 = d + (c + b * t2) * t2;
    res = min(dot(g1, g1), dot(g2, g2));
  }
  return sqrt(res) - r;
}

// tapered strut between nodes (columns, spires, limbs): radius r1 at a → r2 at b
fn mod_w3_taperStrut(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r1, r2, h);
}

// round (Roman) arch opening — subtract from a wall. Origin at base center:
// straight sides height h, half-width w (semicircle top radius w), half-depth d in z
fn mod_w3_arch(p: vec3f, w: f32, h: f32, d: f32) -> f32 {
  let dxy = abs(p.xy - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect2 = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let top2 = length(p.xy - vec2f(0.0, h)) - w;
  let d2 = min(rect2, top2);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// Gothic lancet (ogival/pointed) arch profile: straight sides |x|<=w up to h,
// two-arc point peaking ph above h. 2D — extrude with mod_w3_lancet.
fn mod_w3_lancet2(q: vec2f, w: f32, h: f32, ph: f32) -> f32 {
  let R = (w * w + ph * ph) / (2.0 * w);
  let c = R - w;
  let dxy = abs(q - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let arcs = max(length(q - vec2f(-c, h)) - R, length(q - vec2f(c, h)) - R);
  let top = max(arcs, h - q.y);
  return min(rect, top);
}

// Gothic lancet arch opening in 3D — subtract from a wall. Base center origin,
// half-width w, straight height h, point rises ph above h, half-depth d in z
fn mod_w3_lancet(p: vec3f, w: f32, h: f32, ph: f32, d: f32) -> f32 {
  let d2 = mod_w3_lancet2(p.xy, w, h, ph);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// ── domain ops ─────────────────────────────────────────────────────────────
fn mod_w3_rotX(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}
fn mod_w3_rotY(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}
fn mod_w3_rotZ(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}
// infinite repetition on chosen axes (c = cell size per axis; 0 = no repeat)
fn mod_w3_repeat(p: vec3f, c: vec3f) -> vec3f {
  var q = p;
  if (c.x > 0.0) { q.x = (fract(p.x / c.x + 0.5) - 0.5) * c.x; }
  if (c.y > 0.0) { q.y = (fract(p.y / c.y + 0.5) - 0.5) * c.y; }
  if (c.z > 0.0) { q.z = (fract(p.z / c.z + 0.5) - 0.5) * c.z; }
  return q;
}
// polar repetition around Y: n copies; returns p in the first wedge
fn mod_w3_polar(p: vec3f, n: f32) -> vec3f {
  let ang = 6.2831853 / n;
  let a = atan2(p.z, p.x);
  let r = length(p.xz);
  let a2 = (fract(a / ang + 0.5) - 0.5) * ang;
  return vec3f(cos(a2) * r, p.y, sin(a2) * r);
}

// ── the marcher family (all call YOUR w3_map) ──────────────────────────────
// sphere-trace: returns (t, material) on hit, (-1, -1) on miss
fn mod_w3_march(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32, steps: i32) -> vec2f {
  var t = tmin;
  for (var i = 0; i < 256; i++) {
    if (i >= steps) { break; }
    let dm = w3_map(ro + rd * t);
    if (dm.x < 0.001 * t + 0.003) { return vec2f(t, dm.y); }
    t = t + max(dm.x * 0.9, 0.004);
    if (t > tmax) { break; }
  }
  return vec2f(-1.0, -1.0);
}

// tetrahedral 4-tap normal
fn mod_w3_nrm(p: vec3f, eps: f32) -> vec3f {
  let k = vec2f(1.0, -1.0);
  return normalize(
    k.xyy * w3_map(p + k.xyy * eps).x +
    k.yyx * w3_map(p + k.yyx * eps).x +
    k.yxy * w3_map(p + k.yxy * eps).x +
    k.xxx * w3_map(p + k.xxx * eps).x);
}

// soft shadow toward a light: k = penumbra hardness (8 soft … 32 crisp)
fn mod_w3_shadow(p: vec3f, ld: vec3f, tmax: f32, k: f32) -> f32 {
  var t = 0.03;
  var sh = 1.0;
  for (var i = 0; i < 24; i++) {
    let d = w3_map(p + ld * t).x;
    sh = min(sh, k * d / t);
    t = t + clamp(d, 0.02, 0.8);
    if (sh < 0.02 || t > tmax) { break; }
  }
  return clamp(sh, 0.0, 1.0);
}

// 4-tap ambient occlusion along the normal
fn mod_w3_ao(p: vec3f, n: vec3f) -> f32 {
  var occ = 0.0;
  var w = 1.0;
  for (var i = 1; i <= 4; i++) {
    let h = 0.04 * f32(i * i);
    occ = occ + w * (h - w3_map(p + n * h).x);
    w = w * 0.65;
  }
  return clamp(1.0 - 2.2 * occ, 0.0, 1.0);
}

// ── shading ────────────────────────────────────────────────────────────────
fn mod_w3_fresnel(n: vec3f, rd: vec3f, f0: f32) -> f32 {
  return f0 + (1.0 - f0) * pow(1.0 - clamp(dot(n, -rd), 0.0, 1.0), 5.0);
}

// the standard rig: sun key + sky fill + bounce, shadow and AO applied where
// each belongs (shadow kills the key, AO dims the fill), plus a spec lobe
fn mod_w3_light(alb: vec3f, n: vec3f, rd: vec3f, sunDir: vec3f, sunCol: vec3f, skyCol: vec3f, sh: f32, ao: f32) -> vec3f {
  let dif = clamp(dot(n, sunDir), 0.0, 1.0);
  let sky = 0.5 + 0.5 * n.y;
  let bou = clamp(-n.y, 0.0, 1.0) * 0.3;
  var c = alb * (sunCol * dif * sh + skyCol * sky * ao + skyCol * bou * ao);
  let hal = normalize(sunDir - rd);
  let spe = pow(clamp(dot(n, hal), 0.0, 1.0), 32.0) * dif * sh;
  c = c + sunCol * spe * 0.5 * mod_w3_fresnel(n, rd, 0.04);
  return c;
}

// aerial perspective: fold a hit color into the sky with distance
fn mod_w3_fog(c: vec3f, skyC: vec3f, t: f32, density: f32) -> vec3f {
  return mix(c, skyC, 1.0 - exp(-t * t * density));
}

// ANIM3 — articulated-chain animation kit (canonical copy).
// The layer between skel-lib (creature rigs) and world3 (raymarched space):
// two-bone IK, tapered limb SDFs, gait oscillators with planted feet, pose
// paths, and aim frames — everything needed to make a marched body MOVE well.
//
//   { "type": "define_module", "name": "anim3", "wgsl": <this file> }
//
// Design: everything is STATELESS — pure functions of time and parameters, so
// they run per-pixel in a visual with no CPU sync. Drive the inputs (targets,
// phases, headings) from a step hook via the whiteboard or the population
// buffer; the shader poses the body.
//
// The crowd pattern: hook publishes gpuPopulation entries [x, y, heading, phase]
// → the visual loops pop(i), builds each body in its local frame with
// mod_a3_gait(phase …) driving the legs. 4095 walkers, one dispatch.

// ── two-bone IK ────────────────────────────────────────────────────────────
// Classic solver: a chain root→mid→tip with segment lengths l1, l2 reaching
// for `target`. Returns the MID joint (elbow/knee). `pole` bends the joint
// toward it (knee forward, elbow back) — give it a point, not a direction.
// Unreachable targets clamp to full extension; degenerate poles self-heal.
fn mod_a3_ik2(root: vec3f, tgt: vec3f, l1: f32, l2: f32, pole: vec3f) -> vec3f {
  var to = tgt - root;
  var d = length(to);
  let maxR = l1 + l2 - 0.0001;
  d = clamp(d, abs(l1 - l2) + 0.0001, maxR);
  let dir = to / max(length(to), 0.0001);
  // law of cosines: distance from root to the mid joint's projection
  let a = (l1 * l1 - l2 * l2 + d * d) / (2.0 * d);
  let h = sqrt(max(l1 * l1 - a * a, 0.0));
  // bend plane: contains the chain axis, leans toward the pole
  var side = pole - root - dir * dot(pole - root, dir);
  let sl = length(side);
  if (sl < 0.001) { side = vec3f(0.0, 0.0, 1.0) - dir * dir.z; } else { side = side / sl; }
  return root + dir * a + normalize(side) * h;
}

// ── limb geometry ──────────────────────────────────────────────────────────
// tapered capsule: radius r0 at `a` → r1 at `b` (thigh→ankle, arm→wrist)
fn mod_a3_bone(p: vec3f, a: vec3f, b: vec3f, r0: f32, r1: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r0, r1, h);
}
// joint ball — drop one at every hinge to keep silhouettes smooth
fn mod_a3_joint(p: vec3f, at: vec3f, r: f32) -> f32 { return length(p - at) - r; }

// ── gait ───────────────────────────────────────────────────────────────────
// The planted-foot law (lifted from skel-lib's ladder): phase advances in
// STRIDE CYCLES (hook: ph += speed / strideLen * dt). Within one cycle a foot
// is planted for `duty` (moving backward at exactly body speed → zero world
// velocity) and swings forward for the rest, lifted on a sine arc.
// Returns (alongOffset, lift): foot position relative to its rest point,
// in units of strideLen.
fn mod_a3_gait(phase: f32, duty: f32) -> vec2f {
  let c = fract(phase);
  if (c < duty) {
    // stance: linear back-travel, no lift — the foot OWNS the ground
    let s = c / duty;
    return vec2f(0.5 - s, 0.0);
  }
  // swing: forward and up
  let s = (c - duty) / (1.0 - duty);
  return vec2f(-0.5 + s, sin(s * 3.14159) * 1.0);
}
// eased oscillator for secondary motion (tails, breathing, sway):
// sin with adjustable sharpness — sharp > 1 dwells at the extremes
fn mod_a3_sway(t: f32, freq: f32, sharp: f32) -> f32 {
  let s = sin(t * freq);
  return sign(s) * pow(abs(s), 1.0 / max(sharp, 0.001));
}

// ── pose paths ─────────────────────────────────────────────────────────────
// blend two joint positions (a pose is just a set of points — lerp each)
fn mod_a3_mix(a: vec3f, b: vec3f, t: f32) -> vec3f { return mix(a, b, smoothstep(0.0, 1.0, t)); }
// quadratic bezier through a lifted midpoint — a reach, a leap, a nod
fn mod_a3_arc(a: vec3f, peak: vec3f, b: vec3f, t: f32) -> vec3f {
  let u = 1.0 - t;
  return a * u * u + peak * 2.0 * u * t + b * t * t;
}

// ── aim frames ─────────────────────────────────────────────────────────────
// build a basis aimed along `fw` (head look-at, torso facing); transform a
// local point into it. worldUp guards collinearity.
fn mod_a3_aim(local: vec3f, origin: vec3f, fw0: vec3f) -> vec3f {
  let fw = normalize(fw0);
  var up = vec3f(0.0, 1.0, 0.0);
  if (abs(dot(fw, up)) > 0.99) { up = vec3f(0.0, 0.0, 1.0); }
  let rt = normalize(cross(up, fw));
  let u2 = cross(fw, rt);
  return origin + rt * local.x + u2 * local.y + fw * local.z;
}

// ── a whole walker, as the pattern to copy ─────────────────────────────────
// Biped legs in one call: body at `hips` heading +z in its local frame,
// phase in stride cycles, stride length L. Returns the SDF of both legs.
// (Offset the two feet half a cycle; IK bends knees toward the pole.)
fn mod_a3_legs(p: vec3f, hips: vec3f, phase: f32, L: f32, legLen: f32, r: f32) -> f32 {
  var d = 1e9;
  for (var s = 0; s < 2; s++) {
    let side = select(-1.0, 1.0, s == 1);
    let g = mod_a3_gait(phase + select(0.0, 0.5, s == 1), 0.55);
    let hip = hips + vec3f(side * legLen * 0.22, 0.0, 0.0);
    let foot = vec3f(hip.x, g.y * legLen * 0.22, g.x * L);
    let knee = mod_a3_ik2(hip, foot, legLen * 0.52, legLen * 0.52, hip + vec3f(0.0, 0.0, legLen));
    d = min(d, mod_a3_bone(p, hip, knee, r, r * 0.75));
    d = min(d, mod_a3_bone(p, knee, foot, r * 0.75, r * 0.5));
    d = min(d, mod_a3_joint(p, knee, r * 0.85));
  }
  return d;
}

// VEILFIRE · rooms.wgsl — the load-bearing scene SDF (vf-rooms node).
// EXPORT: fn w3_map(p: vec3f) -> vec2f  = (signed distance, material id).
//
// A WALKABLE Antichamber-style Gothic interior, carved SUBTRACTIVELY out of a
// solid rock block so rooms connect by construction (no coordinate seams):
//   d = solidBlock;  d = max(d, -naveAir);  d = max(d, -sideAir);  d = max(d, -door);
// then solids (columns, dais) are UNIONed back in with min(). Positive in open
// air, 0 at surfaces, negative inside rock — raymarchable from inside.
//
// ── ROOM EXTENTS (world units, y=0 is the floor) — movement/vf-* MIRROR THIS ──
//   NAVE (main hall):  x∈[-4, 4]   y∈[0, 9]   z∈[-9, 9]     (tall)
//   SIDE CHAMBER:      x∈[ 5,11]   y∈[0, 5]   z∈[-3.5, 3.5] (lower ceiling)
//   DIVIDING WALL:     x∈[ 4, 5]  (1 thick) — solid except the doorway
//   DOORWAY (lancet):  center x≈4.5, z=0, base y=0; opening z∈[-1.5,1.5],
//                      height y∈[0, 3.7] (straight to 2.5, point to 3.7),
//                      depth x∈[3.3, 5.7] (cuts the whole dividing wall)
//   COLONNADE:         two rows at x=±3.2, columns every 4 in z (z=0,±4,±8),
//                      r=0.4, floor→near ceiling (y∈[-0.5, 8.5])
//   DAIS (verticality, far +z end of nave):
//      step1: x∈[-3.5,3.5] y∈[0,1]   z∈[6,9]   (low platform)
//      step2: x∈[-3.5,3.5] y∈[0,2]   z∈[7.8,9.2] (upper ledge)
//   Suggested spawn: (0, 1.6, 0) facing +x toward the doorway, or -z down nave.
//
// MATERIAL IDS: 1 wall · 2 floor/dais · 3 column · 4 doorway/arch trim.
// Cheap: a handful of box/cyl/lancet evals, one z-repeat, no loops.

fn w3_map(p: vec3f) -> vec2f {
  // --- solid rock; carve the rooms out of it ---
  let d0 = mod_w3_box(p - vec3f(3.5, 4.5, 0.0), vec3f(8.5, 5.5, 10.0));
  let nave = mod_w3_box(p - vec3f(0.0, 4.5, 0.0), vec3f(4.0, 4.5, 9.0));
  let side = mod_w3_box(p - vec3f(8.0, 2.5, 0.0), vec3f(3.0, 2.5, 3.5));

  // doorway: lancet arch, profile in (z,y), depth along x through the wall
  let qd = vec3f(p.z, p.y, p.x - 4.5);
  let door = mod_w3_lancet(qd, 1.5, 2.5, 1.2, 1.2);

  var d = d0;
  d = max(d, -nave);
  d = max(d, -side);
  d = max(d, -door);

  // shell material: floor low, doorway trim near the arch cut, else wall
  var mat = 1.0;
  if (p.y < 0.3) { mat = 2.0; }
  if (door < 0.35 && p.y < 3.9) { mat = 4.0; }

  // --- solids unioned back in ---
  // colonnade: mirrored rows at x=±3.2, repeated every 4 units in z
  let cz = (fract(p.z / 4.0 + 0.5) - 0.5) * 4.0;
  let colp = vec3f(abs(p.x) - 3.2, p.y - 4.0, cz);
  let col = mod_w3_cyl(colp, 4.5, 0.4);
  if (col < d) { d = col; mat = 3.0; }

  // dais / altar steps at the far +z end (verticality)
  let step1 = mod_w3_box(p - vec3f(0.0, 0.5, 7.5), vec3f(3.5, 0.5, 1.5));
  if (step1 < d) { d = step1; mat = 2.0; }
  let step2 = mod_w3_box(p - vec3f(0.0, 1.0, 8.5), vec3f(3.5, 1.0, 0.7));
  if (step2 < d) { d = step2; mat = 2.0; }

  return vec2f(d, mat);
}

// VEILFIRE — DEMONS. A gaunt, hunched, horned humanoid that WALKS.
// Built entirely from anim3-lib tapered-capsule bones + world3 struts so it reads
// as a silhouette at the edge of lantern light. Legs are driven by the planted-foot
// gait (mod_a3_gait(phase, 0.55)); arms counter-swing; head carries swept horns and
// a jutting snarl. Distance only — the integrator paints material / ember-crust.
//
//   { "type": "define_module", "name": "veilfire_demons", "wgsl": <this file> }
//
// EXPORT:  fn vf_demon(p: vec3f, phase: f32) -> f32
//   p     : local body space (heading +z, feet near y=0, center at origin)
//   phase : stride-cycle phase (fract cycles). Same phase feeds the population's
//           animPhase slot (pop(2i+1).y).
// Depends on world3-lib (mod_w3_taperStrut) + anim3-lib (bone/joint/gait/ik2/legs).

// fleshy smooth-union — organic joints without gaps; k small = tight seam
fn vf_smin(a: f32, b: f32, k: f32) -> f32 {
  let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

fn vf_demon(p: vec3f, phase: f32) -> f32 {
  let hipY = 0.88;      // hip height — feet reach y≈0
  let L = 0.5;          // stride length
  let legLen = 0.95;    // thigh+shin reach

  // ── legs: planted-foot gait, gaunt shins ─────────────────────────────────
  var d = mod_a3_legs(p, vec3f(0.0, hipY, 0.0), phase, L, legLen, 0.075);

  // subtle breathing / menace sway of the upper body
  let breathe = sin(phase * 6.2831853) * 0.02;

  // ── spine (hunched forward) + head + snarling jaw ────────────────────────
  let pelvis = vec3f(0.0, hipY, 0.0);
  let chest  = vec3f(0.0, hipY + 0.42, 0.10);
  let neck   = vec3f(0.0, hipY + 0.60, 0.16);
  let headC  = vec3f(0.0, hipY + 0.76, 0.20 + breathe);

  var body = mod_a3_bone(p, pelvis, chest, 0.11, 0.15);                 // gaunt ribcage
  body = vf_smin(body, mod_a3_bone(p, chest, neck, 0.13, 0.06), 0.08);  // taper to neck
  body = vf_smin(body, mod_a3_joint(p, headC, 0.14), 0.06);            // skull
  body = vf_smin(body,                                                  // jutting snarl
    mod_a3_bone(p, headC + vec3f(0.0, -0.02, 0.05), headC + vec3f(0.0, -0.06, 0.16), 0.09, 0.03), 0.05);
  d = min(d, body);

  // ── horns: swept up and back, crisp edges ────────────────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    let hb = headC + vec3f(sx * 0.08, 0.08, -0.02);
    let ht = headC + vec3f(sx * 0.16, 0.30, -0.18);
    d = min(d, mod_w3_taperStrut(p, hb, ht, 0.035, 0.004));
  }

  // ── arms: long, clawed, counter-swinging to the legs ─────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    // opposite phase offset to the same-side leg → natural counter-swing
    let g = mod_a3_gait(phase + select(0.5, 0.0, s == 1), 0.55);
    let shoulder = vec3f(sx * 0.20, hipY + 0.48, 0.06);
    let hand = vec3f(sx * 0.17, hipY - 0.32, 0.16 - g.x * 0.55);        // reach to mid-thigh
    let pole = shoulder + vec3f(sx * 0.35, -0.1, -0.35);               // elbow back/out
    let elbow = mod_a3_ik2(shoulder, hand, 0.44, 0.46, pole);
    var arm = mod_a3_bone(p, shoulder, elbow, 0.06, 0.045);
    arm = min(arm, mod_a3_bone(p, elbow, hand, 0.045, 0.028));
    arm = min(arm, mod_a3_joint(p, elbow, 0.05));
    // three splayed talons
    for (var c = 0; c < 3; c++) {
      let ca = (f32(c) - 1.0) * 0.12;
      let tip = hand + vec3f(sx * 0.03 + ca * 0.05, -0.14, 0.06 + ca * 0.02);
      arm = min(arm, mod_w3_taperStrut(p, hand, tip, 0.022, 0.002));
    }
    d = vf_smin(d, arm, 0.04);
  }

  // ── HORROR PASS (v2) — detail the ember-shading catches at the light's edge ──
  // ribcage: thin bones across the hunched chest → skeletal, ember-cracked
  for (var r = 0; r < 4; r++) {
    let ry = hipY + 0.13 + f32(r) * 0.085;
    let rz = 0.04 + f32(r) * 0.012;
    d = min(d, mod_a3_bone(p, vec3f(-0.115, ry, rz), vec3f(0.115, ry, rz), 0.012, 0.012));
  }
  // a sternum ridge down the ribs
  d = min(d, mod_a3_bone(p, vec3f(0.0, hipY + 0.10, 0.05), vec3f(0.0, hipY + 0.42, 0.09), 0.016, 0.010));
  // sunken eye sockets + a gaping maw carved from the skull (dark hollows read as a face)
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(-0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f( 0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(0.0, -0.055, 0.15)), 0.050));

  return d;
}

// enemies (node: enemies) — shared enemy shading helper. The enemy BODY draw is
// routed through veilfire/demons.wgsl's vf_demon inside renderer-mega; this holds
// the damage-flash tint the renderer can blend by hp so hurt demons read hot.
fn s3_enemyTint(hp01: f32) -> vec3f {
  return mix(vec3f(1.0, 0.28, 0.16), vec3f(0.11, 0.05, 0.045), clamp(hp01, 0.0, 1.0));
}

// shooter3 / projectiles — thin glowing energy bolts (tracers)
// Cheap capsule SDF + emissive HDR color the renderer adds on hit-glow.
// Exports:
//   s3_tracer(p, a, b)            -> f32   thin bolt from a to b (radius ~0.06)
//   s3_tracerColor(kind, life01)  -> vec3f linear HDR emissive (3=player, 4=enemy)

// A thin glowing bolt: a capsule from a to b. Cheap — one clamp/dot/length.
fn s3_tracer(p: vec3f, a: vec3f, b: vec3f) -> f32 {
  return mod_w3_capsule(p, a, b, 0.06);
}

// Emissive HDR color the renderer adds. Brightest when freshly fired (life01~1),
// fading toward death (life01~0). kind 3 = player (hot cyan-white), 4 = enemy (sick green).
fn s3_tracerColor(kind: f32, life01: f32) -> vec3f {
  let l = clamp(life01, 0.0, 1.0);
  // hot core (near-white at spawn) blended toward the tinted tail as it ages
  let playerHot  = vec3f(0.55, 1.0, 1.0);   // cyan
  let playerCore = vec3f(1.0, 1.0, 1.0);    // white-hot
  let enemyHot   = vec3f(0.35, 1.0, 0.15);  // sick green
  let enemyCore  = vec3f(0.85, 1.0, 0.6);   // pale green-white
  let isEnemy = step(3.5, kind);            // 0 for kind<=3, 1 for kind>=4
  let hot  = mix(playerHot, enemyHot, isEnemy);
  let core = mix(playerCore, enemyCore, isEnemy);
  // core dominates when fresh; tint takes over as it fades
  let tint = mix(hot, core, l);
  // HDR emission: strong when fresh, glowing dim tail when old
  let energy = mix(1.2, 9.0, l * l);
  return tint * energy;
}

// VEILFIRE — atmosphere. Dread mood layered over a plainly-lit color.
//   vf_atmos(c, pos, rd, t, time):
//     c    = lit color at the hit (linear HDR)
//     pos  = hit point in world space
//     rd   = ray direction (unit)
//     t    = hit distance (fog falloff)
//     time = seconds
//   returns the color, dread-soaked. Output stays LINEAR HDR — no tonemap here.
//
// Four cheap layers, in order:
//   1. cool desaturation with a warm firelight bias (drain life, keep the fire)
//   2. torch flicker — layered sin-noise multiplying the whole scene
//   3. depth fog toward near-black cold murk (dread deepens it)
//   4. faint drifting ember specks low in the frame
//
// Mood dials read from the whiteboard (see SPEC): uni(12)=dread01, uni(18)=fogDensity.
// Both degrade gracefully to sane defaults when unset (zero).

fn vf_hash11(n: f32) -> f32 { return fract(sin(n * 43758.5453) * 12345.6789); }

fn vf_atmos(c: vec3f, pos: vec3f, rd: vec3f, t: f32, time: f32) -> vec3f {
  var col = c;

  let dread = clamp(uni(12), 0.0, 1.0);
  let fogD  = max(uni(18), 0.0);

  // ── 1. cool desaturation + warm firelight bias ─────────────────────────────
  // Drain saturation toward grey (harder the more dread), then re-tint: warm
  // ember in the lit/bright regions, cold blue in the shadows.
  let lum   = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  let desat = mix(col, vec3f(lum), 0.42 + 0.28 * dread);
  let warm  = vec3f(1.18, 0.60, 0.28);
  let cool  = vec3f(0.52, 0.66, 0.96);
  let tint  = mix(cool, warm, clamp(lum * 1.6, 0.0, 1.0));
  col = desat * tint;

  // ── 2. torch flicker — layered sin-noise, multiplies everything ────────────
  let f1 = sin(time * 11.0) * 0.5 + sin(time * 17.3 + 1.7) * 0.3 + sin(time * 29.0) * 0.2;
  let f2 = sin(time * 3.1 + 0.5);
  let flick = 1.0 + 0.06 * f1 + 0.03 * f2;   // roughly ±9% breathing
  col = col * flick;

  // ── 3. depth fog — a LIFTED cold haze (KINDLE murk). Fog toward near-black is
  // invisible in a dark room; a lifted blue-grey veils distance so the air reads
  // thick. Two bands: a near haze that lifts shadows + a far murk that swallows.
  let density = fogD + 0.010 + 0.012 * dread;
  let fogAmt  = 1.0 - exp(-t * t * density);
  let haze    = vec3f(0.055, 0.072, 0.110);       // cold blue-grey — the visible fog
  col = mix(col, haze, fogAmt);
  col = col + haze * 0.35 * fogAmt;                // scatter lift so it glows, not just dims

  // ── 4. drifting ember specks, low in the frame ─────────────────────────────
  // Parameterize by ray direction so motes float in view; drift upward in time.
  let ep = vec2f(rd.x * 6.0, rd.y * 6.0 - time * 0.35);
  var ember = 0.0;
  for (var k = 0; k < 3; k = k + 1) {
    let sc   = 1.0 + f32(k) * 1.7;
    let g    = ep * sc + vec2f(f32(k) * 13.7, f32(k) * 7.3);
    let cell = floor(g);
    let fr   = fract(g) - 0.5;
    let h    = vf_hash11(cell.x * 57.0 + cell.y * 131.0 + f32(k) * 3.0);
    let on   = step(0.92, h);                 // only a few cells host an ember
    let jit  = vec2f(vf_hash11(h * 21.0) - 0.5, vf_hash11(h * 47.0) - 0.5) * 0.6;
    let d    = length(fr - jit);
    let mote = on * smoothstep(0.09, 0.0, d);
    let tw   = 0.5 + 0.5 * sin(time * (4.0 + h * 6.0) + h * 30.0);  // twinkle
    ember = ember + mote * tw;
  }
  // Sit near the low end (bottom of view) and glow warmer through the murk.
  let lowBias  = smoothstep(0.30, -0.45, rd.y);
  let emberCol = vec3f(1.30, 0.52, 0.16);
  col = col + emberCol * ember * lowBias * (0.35 + 0.55 * fogAmt);

  return col;
}

// shooter3 HUD — screen-space overlay for the horror-shooter. No raymarch.
// Exports s3_hud(uv, hp01, ammo, score, dread01) -> vec4f (rgb, alpha); alpha 0
// where nothing is drawn so the integrator can composite it over the world.
//
// uv arrives -1..1 with y DOWN — the engine convention (uv.y=-1 top, +1 bottom;
// see render-core "MATCH THE ENGINE … uv.y increases DOWNWARD"). That already
// matches char5x7 / printInt (p in [0,1]², y DOWN), so s = uv*0.5+0.5 with no
// flip renders glyphs upright. Palette is thin, cold-white ink
// over near-black, with a rising red dread wash so the frame turns ominous as
// dread01 → 1. Legible on black; restrained on a lit scene.

// ── glyph cell helpers (screen coords s: 0..1, y DOWN) ────────────────────
// draw one glyph inside a box; returns coverage 0..1
fn s3_boxChar(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, code: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return char5x7(p, code);
}
// draw a right-aligned integer inside a box
fn s3_boxInt(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, value: f32, digits: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return printInt(p, value, digits);
}
// one glyph within a monospace run: start x0, cell width cw, index j (0.8 fill)
fn s3_cellChar(s: vec2f, x0: f32, cw: f32, y0: f32, y1: f32, j: i32, code: i32) -> f32 {
  let cx0 = x0 + f32(j) * cw;
  return s3_boxChar(s, cx0, cx0 + cw * 0.82, y0, y1, code);
}

fn s3_hud(uv: vec2f, hp01: f32, ammo: f32, score: f32, dread01: f32) -> vec4f {
  // screen coords, top-left origin, y DOWN — matches the glyph font + engine.
  let s = vec2f(uv.x * 0.5 + 0.5, uv.y * 0.5 + 0.5);
  let hp = clamp(hp01, 0.0, 1.0);
  let dr = clamp(dread01, 0.0, 1.0);

  var col = vec3f(0.0);
  var a = 0.0;

  // ── dread wash: a red vignette that swells from the corners with dread01 ──
  // (built in uv space so it is symmetric regardless of the glyph y-flip)
  {
    let edge = smoothstep(0.55, 1.25, length(uv));   // 0 centre → 1 corners
    // a slow, uneasy pulse so high dread never sits perfectly still
    let breath = 0.82 + 0.18 * sin(uni(0) * 2.1);
    let vig = edge * dr * breath;
    col = vec3f(0.42, 0.02, 0.015) * vig;
    a = vig * 0.65;
  }

  // ── HEALTH BAR — bottom-left, red→green by hp01, dark empty track, frame ──
  {
    let x0 = 0.035; let x1 = 0.315; let y0 = 0.905; let y1 = 0.940;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let bt = 0.0035;                                          // border thickness
      let border = s.x < x0 + bt || s.x > x1 - bt || s.y < y0 + bt || s.y > y1 - bt;
      let fillX = x0 + (x1 - x0) * hp;
      if (border) {
        col = vec3f(0.55, 0.56, 0.62); a = 0.85;
      } else if (s.x <= fillX) {
        // red at 0 → amber mid → green at full; scale value so low HP reads hot
        let hc = mix(vec3f(0.95, 0.09, 0.06), vec3f(0.16, 0.92, 0.26), smoothstep(0.0, 1.0, hp));
        col = hc * (0.85 + 0.15 * hp); a = 0.92;
      } else {
        col = vec3f(0.05, 0.02, 0.02); a = 0.55;                // depleted track
      }
    }
    // "HP" label just above the bar
    let ly0 = 0.868; let ly1 = 0.898;
    let lc = max(s3_cellChar(s, 0.035, 0.024, ly0, ly1, 0, 72),   // H
                 s3_cellChar(s, 0.035, 0.024, ly0, ly1, 1, 80));  // P
    if (lc > 0.0) { col = vec3f(0.72, 0.74, 0.80); a = lc * 0.9; }
  }

  // ── AMMO — bottom-right, printInt (3 digits), with a small label ──
  {
    let x0 = 0.80; let x1 = 0.965; let y0 = 0.905; let y1 = 0.945;
    let cov = s3_boxInt(s, x0, x1, y0, y1, ammo, 3);
    if (cov > 0.0) { col = vec3f(0.86, 0.88, 0.94); a = cov * 0.95; }
    // "AMMO" label above the count
    let ly0 = 0.868; let ly1 = 0.898;
    let lx0 = 0.80; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 65);   // A
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 79)); // O
    if (lab > 0.0) { col = vec3f(0.66, 0.68, 0.74); a = lab * 0.85; }
  }

  // ── SCORE — top-right, printInt (6 digits), with a label ──
  {
    let x0 = 0.74; let x1 = 0.965; let y0 = 0.070; let y1 = 0.110;
    let cov = s3_boxInt(s, x0, x1, y0, y1, score, 6);
    if (cov > 0.0) { col = vec3f(0.90, 0.90, 0.95); a = cov * 0.95; }
    // "SCORE" label above the number
    let ly0 = 0.032; let ly1 = 0.062;
    let lx0 = 0.74; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 83);   // S
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 67)); // C
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 79)); // O
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 82)); // R
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 4, 69)); // E
    if (lab > 0.0) { col = vec3f(0.62, 0.63, 0.70); a = lab * 0.82; }
  }

  // ── DREAD METER — thin vertical bar, right edge, fills bottom→top ──
  {
    let x0 = 0.972; let x1 = 0.990; let y0 = 0.32; let y1 = 0.90;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let fillTop = y1 - (y1 - y0) * dr;                 // fills upward with dread
      if (s.y >= fillTop) {
        let up = (y1 - s.y) / (y1 - y0);                 // 0 bottom → 1 top of bar
        let hot = mix(vec3f(0.55, 0.05, 0.04), vec3f(1.0, 0.28, 0.12), up);
        col = hot; a = 0.9;
      } else {
        col = vec3f(0.06, 0.02, 0.02); a = 0.5;          // empty channel
      }
    }
  }

  // ── CROSSHAIR — thin center cross with a gap, cold-white, reddens w/ dread ──
  {
    let ax = abs(uv.x); let ay = abs(uv.y);
    let th = 0.0038;
    let inR = 0.013; let outR = 0.050;
    let horiz = ay < th && ax > inR && ax < outR;
    let vert  = ax < th && ay > inR && ay < outR;
    let dot   = length(uv) < 0.0028;
    if (horiz || vert || dot) {
      col = mix(vec3f(0.92, 0.95, 1.0), vec3f(1.0, 0.18, 0.12), dr);
      a = 0.9;
    }
  }

  return vec4f(col, clamp(a, 0.0, 1.0));
}

stepHooks.code:
// movement (node: movement) — v2. WASD + mouse-look + jump. A step-hook FRAGMENT
// run FIRST each frame. Owns player + camera on the whiteboard:
//   rows 1,2,3 = x,y,z · row 4 = yaw · row 5 = pitch · uni4(60)=ro,fov · uni4(61)=target
//
// v2 controls (standard FPS): MOUSE looks (yaw+pitch by pointer delta), W/S walk,
// A/D STRAFE, SPACE jumps (gravity + ground). Fire moved to click (projectiles).
// Collision: coarse walkable mask mirroring veilfire/rooms.wgsl extents, wall-slid.
// (KNOWN: columns/dais aren't blockers yet — the clip fix is a rooms+movement mod.)

const R = 0.4
// solids that must BLOCK the player — mirrors rooms.wgsl's colonnade (two rows at
// x=±3.2, columns every 4 in z, r=0.4). One truth, two callers; the principled
// version is rooms exporting a JS collision fn (next mod). Dais step-up (floor
// height) is a separate movement feature — TODO.
function blocked(x, z) {
  const cr = 0.4 + R
  for (const cx of [-3.2, 3.2]) {
    for (const cz of [-8, -4, 0, 4, 8]) {
      if ((x - cx) * (x - cx) + (z - cz) * (z - cz) < cr * cr) return true
    }
  }
  return false
}
function walkable(x, z) {
  const nave = x >= -4 + R && x <= 4 - R && z >= -9 + R && z <= 9 - R
  const side = x >= 5 + R && x <= 11 - R && z >= -3.5 + R && z <= 3.5 - R
  const door = x >= 3.3 && x <= 5.7 && z >= -1.5 + R && z <= 1.5 - R
  return (nave || side || door) && !blocked(x, z)
}
// floor height per position — the dais step at the far +z end of the nave
// (rooms.wgsl: x∈[-3.5,3.5] z∈[6,9], raised +1). Lets you step UP instead of
// clipping the back wall near the altar/bench.
function floorH(x, z) {
  if (x >= -3.5 && x <= 3.5 && z >= 6.0 && z <= 9.0) return 1.0
  return 0.0
}

function movement(sim, dt) {
  const wd = sim.worldData
  if (!wd.__vf) wd.__vf = {}
  const V = wd.__vf
  if (V.mv !== 2) { V.px = 8; V.py = 1.9; V.pz = -3.2; V.yaw = 0; V.pitch = -0.28; V.vy = 0; V.ground = 1; V.lx = null; V.ly = null; V.mv = 2 }
  const step = Math.min(dt, 1 / 30)
  const inp = wd.input || {}
  const ptr = inp.pointer || {}

  // MOUSE-LOOK — pointer-lock relative deltas (input.lookX/lookY) when the engine
  // has locked the pointer, else absolute-pointer delta. Safe to sum: under lock
  // the cursor is frozen so the absolute delta is ~0; without lock lookX/Y are 0.
  if (V.lx == null) { V.lx = ptr.x != null ? ptr.x : 256; V.ly = ptr.y != null ? ptr.y : 256 }
  const px = ptr.x != null ? ptr.x : V.lx, py = ptr.y != null ? ptr.y : V.ly
  const absS = 0.006, relS = 0.0052   // pointer-lock look sensitivity (bumped up)
  V.yaw -= (px - V.lx) * absS + (inp.lookX || 0) * relS   // mouse right → look right
  V.pitch = Math.max(-1.2, Math.min(1.2, V.pitch - ((py - V.ly) * absS + (inp.lookY || 0) * relS)))
  V.lx = px; V.ly = py

  // MOVE — W/S forward along yaw, A/D strafe along the right vector
  const fx = Math.sin(V.yaw), fz = Math.cos(V.yaw)
  const rx = -Math.cos(V.yaw), rz = Math.sin(V.yaw)   // strafe right vector (A/D were flipped)
  const spd = 5.5, mF = inp.moveY || 0, mS = inp.moveX || 0
  const dx = (fx * mF + rx * mS) * spd * step
  const dz = (fz * mF + rz * mS) * spd * step
  let nx = V.px, nz = V.pz
  if (walkable(V.px + dx, V.pz)) nx = V.px + dx
  if (walkable(nx, V.pz + dz)) nz = V.pz + dz
  V.px = nx; V.pz = nz

  // JUMP — Space (input.action edge) when grounded; gravity pulls back to the
  // floor height at the player's feet (steps up onto the dais, falls off it).
  const gLevel = floorH(V.px, V.pz) + 1.7
  if (inp.action && V.ground) { V.vy = 4.4; V.ground = 0 }
  V.vy -= 12.0 * step
  V.py += V.vy * step
  if (V.py <= gLevel) { V.py = gLevel; V.vy = 0; V.ground = 1 }

  // CAMERA — first-person eye; look dir folds pitch in
  const cp = Math.cos(V.pitch), sp = Math.sin(V.pitch)
  const ta = [V.px + fx * cp * 2.0, V.py + sp * 2.0, V.pz + fz * cp * 2.0]
  const u = Array.isArray(wd.gpuUniforms) ? wd.gpuUniforms : new Array(256).fill(0)
  while (u.length < 256) u.push(0)
  u[1] = V.px; u[2] = V.py; u[3] = V.pz; u[4] = V.yaw; u[5] = V.pitch
  u[240] = V.px; u[241] = V.py; u[242] = V.pz; u[243] = 1.2
  u[244] = ta[0]; u[245] = ta[1]; u[246] = ta[2]; u[247] = 0
  wd.gpuUniforms = u
}

// enemies (node: enemies) — the baddie AI. A step-hook FRAGMENT run after
// movement. Spawns demons in the rooms, seeks the player, faces them, advances
// the gait phase with speed, and telegraphs + strikes in range.
//
// POPULATION CONTRACT (SPEC): each enemy = TWO entries pushed to the shared
// sim.worldData.__vf.pop (vf-integrate clears it each frame and flushes to
// wd.gpuPopulation): (x, y=0, z, kind=1) , (hp01, gaitPhase, yaw, atkFlag).
// Reads the player at __vf.px/__vf.pz (movement owns those). Sets __vf.hits for
// combat: an entry per striking enemy so combat can damage the player.

function enemies(sim, dt) {
  const wd = sim.worldData
  if (!wd.__vf) wd.__vf = {}
  const V = wd.__vf
  const step = Math.min(dt, 1 / 30)
  if (!V.en) {
    V.en = [                                   // spawn in nave + side chamber
      { x: 1.5, z: 5, ph: 0.0, hp: 1, atk: 0 },
      { x: -2.0, z: 8, ph: 1.5, hp: 1, atk: 0 },
      { x: 2.5, z: -1, ph: 3.0, hp: 1, atk: 0 },
      { x: 7.5, z: 0, ph: 0.7, hp: 1, atk: 0 },
    ]
  }
  const px = V.px ?? 0, pz = V.pz ?? -6
  if (!V.pop) V.pop = []
  V.hits = []
  const ATK = 1.7                              // strike range
  for (const e of V.en) {
    if (e.hp <= 0) continue
    const dx = px - e.x, dz = pz - e.z
    const dist = Math.hypot(dx, dz) || 0.0001
    const yaw = Math.atan2(dx, dz)             // face the player (heading +z)
    if (dist > ATK) {
      const sp = 1.8
      e.x += (dx / dist) * sp * step
      e.z += (dz / dist) * sp * step
      e.ph += (sp / 1.2) * step                // planted-foot gait advances with speed
      e.atk = Math.max(0, e.atk - step * 1.5)
    } else {
      e.atk += step                            // wind up then strike
      e.ph += 0.4 * step
      if (e.atk >= 1.0) { V.hits.push({ dmg: 0.12, x: e.x, z: e.z }); e.atk = 0.2 }
    }
    V.pop.push(e.x, 0.0, e.z, 1.0, e.hp, e.ph, yaw, e.atk > 0.5 ? 1 : 0)
  }
}

// projectiles (node: projectiles) — fire + travel + expire. Fragment run after
// enemies. Fires on click/space from the player along yaw; bolts (kind 3) fly
// straight, expire by life; pushed to __vf.pop for the renderer + kept in
// __vf.bolts for combat's hit-test. Owns ammo (row 7) + muzzle flash (row 15).
function projectiles(sim, dt) {
  const wd = sim.worldData
  const V = wd.__vf
  const step = Math.min(dt, 1 / 30)
  if (!V.bolts) V.bolts = []
  if (V.ammo == null) V.ammo = 24
  if (V.reload == null) V.reload = 0
  V.reload = Math.max(0, V.reload - step)
  const inp = wd.input || {}
  const firing = !!(inp.pointer && inp.pointer.pressed)   // click to fire (Space is jump now)
  if (firing && V.reload <= 0 && V.ammo > 0) {
    const yaw = V.yaw || 0
    const fx = Math.sin(yaw), fz = Math.cos(yaw)
    V.bolts.push({ x: (V.px || 0) + fx * 0.4, y: 1.55, z: (V.pz || 0) + fz * 0.4, dx: fx * 22, dz: fz * 22, life: 1.4 })
    V.ammo -= 1; V.reload = 0.13; V.muzzle = 1.0
  }
  V.muzzle = Math.max(0, (V.muzzle || 0) - step * 6)
  const alive = []
  for (const b of V.bolts) {
    b.life -= step
    if (b.life <= 0) continue
    b.x += b.dx * step; b.z += b.dz * step
    alive.push(b)
    V.pop.push(b.x, b.y, b.z, 3.0, Math.max(0, Math.min(1, b.life / 1.4)), 0, 0, 0)
  }
  V.bolts = alive
  const u = wd.gpuUniforms
  if (u) { u[7] = V.ammo; u[15] = V.muzzle }
}

// combat (node: combat) — hit detection + health + score. Fragment run after
// projectiles. Player bolts vs demons (__vf.en) → damage/kill + score + death
// event; demon strikes (__vf.hits from enemies) → player HP down + hit-flash +
// shake; gameState → dead at 0. Pure sim; owns rows 6 (HP), 8 (score),
// 16 (hitFlash), 17 (shake), 14 (gameState).
function combat(sim, dt) {
  const wd = sim.worldData
  const V = wd.__vf
  const step = Math.min(dt, 1 / 30)
  if (V.score == null) V.score = 0
  if (V.hp == null) V.hp = 1.0
  if (!V.deaths) V.deaths = []
  // player bolts vs demons
  if (V.bolts && V.en) {
    for (const b of V.bolts) {
      if (b.life <= 0) continue
      for (const e of V.en) {
        if (e.hp <= 0) continue
        const dx = b.x - e.x, dy = b.y - 1.0, dz = b.z - e.z
        if (dx * dx + dy * dy + dz * dz < 0.85 * 0.85) {
          e.hp -= 0.5; b.life = 0; V.hitFlash = 0.55
          if (e.hp <= 0) { V.score += 100; V.deaths.push({ x: e.x, y: 1.0, z: e.z }) }
          break
        }
      }
    }
  }
  // demon strikes vs player
  if (V.hits) for (const h of V.hits) { V.hp = Math.max(0, V.hp - h.dmg); V.hitFlash = 0.9; V.shake = 0.5 }
  V.hitFlash = Math.max(0, (V.hitFlash || 0) - step * 3)
  V.shake = Math.max(0, (V.shake || 0) - step * 2)
  V.game = V.hp <= 0 ? 1 : 0
  const u = wd.gpuUniforms
  if (u) { u[6] = V.hp; u[8] = V.score; u[16] = V.hitFlash; u[17] = V.shake; u[14] = V.game }
}

// lifecycle (node: lifecycle) — game reset on death. Run after combat. When the
// player's HP hits 0 (combat sets game=1), hold a beat, then respawn: restore
// HP/ammo/score/position, clear bolts + embers, wipe enemies so they respawn.
// Owns the death→reset transition; writes gameState (row 14) for the HUD.
function lifecycle(sim, dt) {
  const wd = sim.worldData
  const V = wd.__vf
  const step = Math.min(dt, 1 / 30)
  if ((V.hp != null && V.hp <= 0) || V.game === 1) {
    V.dead = (V.dead || 0) + step
    if (V.dead > 2.2) {                 // ~2.2s on the death screen, then respawn
      V.hp = 1.0; V.score = 0; V.ammo = 24
      V.px = 0; V.py = 1.7; V.pz = -6; V.yaw = 0; V.pitch = 0; V.vy = 0; V.ground = 1
      V.en = null; V.bolts = []; V.bits = []; V.hits = []
      V.dead = 0; V.game = 0
    }
  } else {
    V.dead = 0
  }
  const u = wd.gpuUniforms
  if (u) { u[14] = V.game || 0; u[22] = V.dead || 0 }   // 14 gameState · 22 death-fade (HUD)
}

// death-fx (node: death-fx) — ember death bursts (the pixelburst idea in 3D).
// Fragment run after combat. On each death event, emit ember bits (kind 5) that
// arc up, fall under gravity, and cool out; pushed to __vf.pop. Renderer colors
// kind 5 as ember by heat.
function deathfx(sim, dt) {
  const wd = sim.worldData
  const V = wd.__vf
  const step = Math.min(dt, 1 / 30)
  if (!V.bits) V.bits = []
  if (V.deaths) {
    for (const d of V.deaths) {
      for (let i = 0; i < 22; i++) {
        const a = i * 0.618 * 6.283, up = 1.6 + (i % 5) * 0.5, out = 1.0 + (i % 7) * 0.28
        V.bits.push({ x: d.x, y: d.y, z: d.z, dx: Math.cos(a) * out, dy: up, dz: Math.sin(a) * out, age: 0, life: 0.6 + (i % 4) * 0.12 })
      }
    }
    V.deaths = []
  }
  const alive = []
  for (const p of V.bits) {
    p.age += step
    if (p.age >= p.life) continue
    p.dy -= 7.0 * step
    p.x += p.dx * step; p.y += p.dy * step; p.z += p.dz * step
    if (p.y < 0.05) { p.y = 0.05; p.dy = 0 }
    alive.push(p)
    V.pop.push(p.x, p.y, p.z, 5.0, Math.max(0, 1 - p.age / p.life), 0, 0, 0)
  }
  V.bits = alive
}

// audio (node: audio) — event-driven sfx flags. Fragment run last. Sets
// worldData.__play_sound on fire/hit/death edges (edge-guarded so it fires once
// per event). Music bed is left to the world author (no bundled asset here); a
// dread swell rides row 12. Harmless if the host ignores unknown sound names.
function audio(sim, dt) {
  const wd = sim.worldData
  const V = wd.__vf
  // fire edge
  if ((V.muzzle || 0) > 0.9 && !V._af) { wd.__play_sound = { name: 'shot' }; V._af = 1 }
  else if ((V.muzzle || 0) < 0.3) V._af = 0
  // hit/death edge (a fresh hitFlash spike)
  if ((V.hitFlash || 0) > 0.8 && !V._ah) { wd.__play_sound = { name: 'impact' }; V._ah = 1 }
  else if ((V.hitFlash || 0) < 0.3) V._ah = 0
  // dread swells with nearby demons (fed to row 12 for the HUD vignette)
  let near = 0
  if (V.en) for (const e of V.en) { if (e.hp > 0 && Math.hypot((V.px || 0) - e.x, (V.pz || 0) - e.z) < 4.0) near++ }
  V.dread = Math.max(0, Math.min(1, near * 0.3))
  const u = wd.gpuUniforms
  if (u) u[12] = V.dread
}

try {
  const wd = sim.worldData
  if (!wd.__vf || wd.__vf.ver !== 1) wd.__vf = { ver: 1 }
  if (!Array.isArray(wd.gpuUniforms) || wd.gpuUniforms.length < 256) { const u = new Array(256).fill(0); wd.gpuUniforms = u }
  wd.__vf.pop = []
  wd.__vf.t = (wd.__vf.t || 0) + Math.min(dt, 1 / 30)
  movement(sim, dt)
  enemies(sim, dt)
  projectiles(sim, dt)
  combat(sim, dt)
  lifecycle(sim, dt)
  deathfx(sim, dt)
  audio(sim, dt)
  // RULE-ZONE frame schedule: count sim frames into uni(30), looping the 6s
  // cycle (hue+wave -> invert -> +posterize). Drives the time-axis law shift.
  const uu = wd.gpuUniforms
  if (Array.isArray(uu)) { wd.__vf.rzf = ((wd.__vf.rzf || 0) + 1) % 360; uu[30] = wd.__vf.rzf }
  wd.gpuPopulation = wd.__vf.pop
} catch (e) {}

visualTypes.wgsl:
// shooter3 MEGASHADER (node: renderer-mega). ONE visual raymarches the world
// (w3_map from veilfire/rooms) and depth-composites the whole population in a
// single dispatch — demons (vf_demon), projectiles/death-bits (emissive) — then
// atmosphere (vf_atmos), muzzle/hit flashes, and the HUD (s3_hud) on top.
//
// Occlusion is correct + cheap: each entity is first rejected by a ray-vs-
// bounding-sphere test and by `t > worldT` (behind a wall), so only entities the
// ray actually pierces IN FRONT of the world get a local march. Camera on
// uni4(60/61). w3_map + vf_demon + s3_* + vf_atmos come from sibling modules.

// ray → sphere near-t (negative if no hit; may be <0 if camera inside)
fn s3_sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> f32 {
  let oc = ro - c;
  let b = dot(oc, rd);
  let h = b * b - (dot(oc, oc) - r * r);
  if (h < 0.0) { return -1.0; }
  return -b - sqrt(h);
}

// ── RULE ZONES (laws as per-pixel fields) ───────────────────────────────────
// Two radial zones on the side-room floor plane (world centred at x=8, z=0). A
// pixel is re-lawed by which zone its WORLD HIT-POINT falls in, so walls, floor,
// AND a demon crossing the seam are all sliced per-pixel by the same test. The
// active law-set shifts by frame (uni(30), counted in the hook):
//   frames <120: zoneA hue-rotates, zoneB wave-ripples, overlap does BOTH.
//   frames 120-239: zoneA law swaps to INVERT (live, by data not deploy).
//   frames >=240: a posterize law is ADDED over BOTH zones.
fn vf_rz_hue120(c: vec3f) -> vec3f { return vec3f(c.b, c.r, c.g); }
fn vf_rulezones(col0: vec3f, hp: vec3f, t: f32) -> vec3f {
  let q = vec2f(hp.x - 8.0, hp.z);              // side-room-local floor coords
  let rr = 2.15 + 0.18 * sin(t * 0.6);          // radii breathe (zones keep animating)
  let dA = length(q - vec2f(-1.35, 0.0));
  let dB = length(q - vec2f( 1.35, 0.0));
  let inA = dA < rr;
  let inB = dB < rr;
  if (!inA && !inB) { return col0; }
  let frameN = uni(30);
  var col = col0;
  // ruleB — the WAVE law: a travelling chroma ripple over the pixels in zone B.
  if (inB) {
    let w = 0.45 + 0.55 * sin(hp.y * 3.6 + t * 3.2 + q.x * 4.0);
    col = mix(col.zyx, vec3f(0.10, 0.45, 0.95) * (0.4 + col), w * 0.85);
  }
  // ruleA — hue-rotate (bold), then INVERT after frame 120 (rule swap, mid-run).
  if (inA) {
    if (frameN < 120.0) { col = mix(col, vf_rz_hue120(col) * 1.3 + vec3f(0.0, 0.18, 0.0), 0.9); }
    else { col = vec3f(1.0) - col; }
  }
  // ruleC — posterize, ADDED over BOTH zones after frame 240 (rule added, mid-run).
  if (frameN >= 240.0) { col = floor(col * 5.0) / 5.0; }
  // lit rims so each zone boundary reads unmistakably in the dark.
  let rim = min(abs(dA - rr), abs(dB - rr));
  col += vec3f(1.0, 0.9, 0.5) * smoothstep(0.10, 0.0, rim) * 1.4;
  return col;
}

fn visual_s3(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let ro = uni4(60).xyz;
  let fov = max(uni4(60).w, 0.6);
  let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
  let sky = vec3f(0.02, 0.025, 0.05);

  // ── the world ──
  let wh = mod_w3_march(ro, rd, 0.02, 60.0, 96);
  var worldT = select(60.0, wh.x, wh.x >= 0.0);
  var col = sky;
  if (wh.x >= 0.0) {
    let pos = ro + rd * wh.x;
    let n = mod_w3_nrm(pos, 0.02);
    let ao = mod_w3_ao(pos, n);
    var alb = vec3f(0.30, 0.29, 0.36);                              // walls
    if (wh.y > 1.5 && wh.y < 2.5) { alb = vec3f(0.15, 0.14, 0.13); } // floor/dais
    if (wh.y > 2.5 && wh.y < 3.5) { alb = vec3f(0.22, 0.20, 0.24); } // column
    if (wh.y > 3.5) { alb = vec3f(0.55, 0.34, 0.14); }              // doorway trim
    // lantern (headlamp at the camera — vf-lightdark will move it to the player)
    let ld = normalize(ro - pos);
    let dist = length(ro - pos);
    let sh = mod_w3_shadow(pos + n * 0.04, ld, dist, 14.0);
    let diff = max(dot(n, ld), 0.0);
    let atten = 4.5 / (1.0 + 0.09 * dist * dist);
    col = alb * (vec3f(0.05, 0.06, 0.09) + vec3f(1.0, 0.82, 0.55) * diff * atten * sh) * ao;
  }

  // ── the population, depth-composited in front of the world ──
  var nearT = worldT;
  let cnt = popCount() / 2;
  for (var i = 0; i < cnt; i = i + 1) {
    let a = pop(i * 2);            // x, y, z, kind
    let b = pop(i * 2 + 1);        // hp01, phase, yaw, flags
    let kind = a.w;
    if (kind < 0.5) { continue; }  // empty slot
    let ppos = a.xyz;
    let isDemon = kind < 2.5;
    // BUG WAS HERE: sphere sat at the feet (y=0, r=1.4) → it clipped everything
    // above y=1.4: the ribcage, head, horns. Center it at torso height + widen so
    // the WHOLE body is inside the sphere test AND the local march below.
    let bc = ppos + vec3f(0.0, select(0.0, 1.05, isDemon), 0.0);
    let br = select(0.18, 1.6, isDemon);
    let sh = s3_sph(ro, rd, bc, br);
    if (sh < 0.0 || sh > nearT) { continue; }        // ray misses, or behind the world

    if (kind < 2.5) {
      // DEMON — local sphere-march (rotate the ray into the demon's yaw frame)
      let yaw = b.z;
      let cy = cos(-yaw); let sy = sin(-yaw);
      let o0 = ro - ppos;
      let lro = vec3f(cy * o0.x + sy * o0.z, o0.y, -sy * o0.x + cy * o0.z);
      let lrd = vec3f(cy * rd.x + sy * rd.z, rd.y, -sy * rd.x + cy * rd.z);
      var t = max(sh, 0.02);
      var hitT = -1.0;
      for (var s = 0; s < 30; s = s + 1) {
        let d = vf_demon(lro + lrd * t, b.y);
        if (d < 0.004) { hitT = t; break; }
        t = t + max(d * 0.8, 0.004);
        if (t > nearT || t > sh + 2.0 * br) { break; }
      }
      if (hitT > 0.0 && hitT < nearT) {
        nearT = hitT;
        let lp = lro + lrd * hitT;
        let e = 0.012;
        let nn = normalize(vec3f(
          vf_demon(lp + vec3f(e, 0.0, 0.0), b.y) - vf_demon(lp - vec3f(e, 0.0, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, e, 0.0), b.y) - vf_demon(lp - vec3f(0.0, e, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, 0.0, e), b.y) - vf_demon(lp - vec3f(0.0, 0.0, e), b.y)));
        let ll = normalize(lro - lp);                 // headlamp, in local frame
        let dist = length(ro - (ro + rd * hitT));
        let diff = max(dot(nn, ll), 0.0);
        let atten = 4.0 / (1.0 + 0.10 * dist * dist);
        let base = vec3f(0.11, 0.05, 0.045);          // charred flesh
        let ember = vec3f(1.0, 0.32, 0.07) * pow(clamp(0.6 - nn.y, 0.0, 1.0), 2.0) * (0.7 + 0.5 * sin(time * 6.0 + ppos.x));
        col = base * (0.12 + diff * atten) + ember * 0.9;
      }
    } else {
      // PROJECTILE / DEATH-BIT — emissive blob at the sphere hit
      if (sh < nearT) {
        nearT = sh;
        let life = clamp(b.x, 0.0, 1.0);
        if (kind > 4.5) { col = vec3f(1.0, 0.42, 0.12) * (0.5 + life * 1.6); }  // death ember
        else { col = s3_tracerColor(kind, life) * 1.4; }
      }
    }
  }

  // ── rule zones re-law the pixel by its world hit-point (before atmosphere so
  //    fog/embers still unify the room). Inert everywhere but the side chamber. ──
  col = vf_rulezones(col, ro + rd * nearT, time);

  // ── atmosphere over whatever we hit, then flashes, then HUD ──
  col = vf_atmos(col, ro + rd * nearT, rd, nearT, time);
  col += vec3f(1.0, 0.82, 0.5) * max(uni(15), 0.0) * 0.6;   // muzzle flash
  col += vec3f(1.0, 0.22, 0.16) * max(uni(16), 0.0) * 0.5;  // hit flash
  let hud = s3_hud(uv, uni(6), uni(7), uni(8), uni(12));
  col = mix(col, hud.rgb, hud.a);
  return vec4f(col, 1.0);
}

modules.wgsl:
// WORLD3 — the cafe's shared 3D raymarching kit (canonical copy).
// Everything ONE DAY, TIDEGLASS, and MARIONETTES 3D each hand-rolled, extracted
// once: camera, SDF primitives, domain ops, marcher, normals, soft shadows,
// AO, and a standard light rig. Ship it in your scene as a module:
//
//   { "type": "define_module", "name": "world3", "wgsl": <this file> }
//
// THE ONE CONTRACT — your scene defines the world map in its OWN module:
//
//   fn w3_map(p: vec3f) -> vec2f   // returns (signed distance, material id)
//
// WGSL resolves module-scope functions in any order, so the kit's marchers can
// call w3_map before your module defines it. A scene that ships world3 without
// defining w3_map will not compile — the contract is load-bearing.
//
// CAMERA CONVENTION (whiteboard rows 60–62, so hooks can drive the eye):
//   uni4(60) = ro.xyz, fov     ·  uni4(61) = target.xyz, roll(unused)
//   A hook that writes these makes any world3 scene orbit/walk for free.
//
// Typical visual:
//   let ro = uni4(60).xyz;  let fov = max(uni4(60).w, 0.6);
//   let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
//   let hit = mod_w3_march(ro, rd, 0.1, 60.0, 96);
//   if (hit.x > 0.0) {
//     let pos = ro + rd * hit.x;
//     let n = mod_w3_nrm(pos, 0.02);
//     let sh = mod_w3_shadow(pos + n * 0.05, sunDir, 30.0, 8.0);
//     let ao = mod_w3_ao(pos, n);
//     col = mod_w3_light(albedoFor(i32(hit.y)), n, rd, sunDir, sunCol, skyCol, sh, ao);
//   }
// Output linear HDR — the engine's ACES + bloom do the grading.

// ── camera ─────────────────────────────────────────────────────────────────
// Ray through a screen point for a look-at camera. uv is the visual's -1..1
// (y down — the flip is handled here, pass it raw).
fn mod_w3_ray(uv: vec2f, ro: vec3f, ta: vec3f, fov: f32) -> vec3f {
  let fw = normalize(ta - ro);
  let rt = normalize(cross(fw, vec3f(0.0, 1.0, 0.0)));
  let up = cross(rt, fw);
  return normalize(uv.x * rt * fov - uv.y * up * fov + fw);
}

// ── SDF primitives (3D) ────────────────────────────────────────────────────
fn mod_w3_sphere(p: vec3f, r: f32) -> f32 { return length(p) - r; }

fn mod_w3_box(p: vec3f, b: vec3f) -> f32 {
  let d = abs(p) - b;
  return length(max(d, vec3f(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

fn mod_w3_rbox(p: vec3f, b: vec3f, r: f32) -> f32 {
  return mod_w3_box(p, b - vec3f(r)) - r;
}

fn mod_w3_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - r;
}

// vertical capped cylinder: half-height h, radius r
fn mod_w3_cyl(p: vec3f, h: f32, r: f32) -> f32 {
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(r, h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

// tapered vertical cylinder: radius r0 at -h → r1 at +h (towers, spires)
fn mod_w3_cone(p: vec3f, h: f32, r0: f32, r1: f32) -> f32 {
  let t = clamp((p.y + h) / (2.0 * h), 0.0, 1.0);
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(mix(r0, r1, t), h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn mod_w3_torus(p: vec3f, R: f32, r: f32) -> f32 {
  return length(vec2f(length(p.xz) - R, p.y)) - r;
}

fn mod_w3_octa(p: vec3f, s: f32) -> f32 {
  let q = abs(p);
  return (q.x + q.y + q.z - s) * 0.57735027;
}

fn mod_w3_plane(p: vec3f, n: vec3f, d: f32) -> f32 { return dot(p, n) + d; }

// ── skeleton assembly (nodes + struts + tissue) ────────────────────────────
// Build forms as a GRAPH: struts between shared node points, joined with
// opSmoothUnion (the "linkage tissue"). Gaps become impossible by construction
// — parts share endpoints instead of hoping coordinates line up. Use tissue k
// at structural joints (0.2–0.5) and hard min for edges that must stay crisp.

// exact closed-form distance to a quadratic bezier strut (S start, Ctl control,
// E end, radius r) — the connective arc: vaults, arches, branches, cables
fn mod_w3_bezStrut(pos: vec3f, S: vec3f, Ctl: vec3f, E: vec3f, r: f32) -> f32 {
  let a = Ctl - S;
  let b = S - 2.0 * Ctl + E;
  let c = a * 2.0;
  let d = S - pos;
  let bb = dot(b, b);
  if (bb < 1e-9) {
    let pa = pos - S;
    let ba = E - S;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
  }
  let kk = 1.0 / bb;
  let kx = kk * dot(a, b);
  let ky = kk * (2.0 * dot(a, a) + dot(d, b)) / 3.0;
  let kz = kk * dot(d, a);
  let pp = ky - kx * kx;
  let qq = kx * (2.0 * kx * kx - 3.0 * ky) + kz;
  let h = qq * qq + 4.0 * pp * pp * pp;
  var res: f32;
  if (h >= 0.0) {
    let hs = sqrt(h);
    let x1 = (hs - qq) / 2.0;
    let x2 = (-hs - qq) / 2.0;
    let t = clamp(sign(x1) * pow(abs(x1), 0.3333333) + sign(x2) * pow(abs(x2), 0.3333333) - kx, 0.0, 1.0);
    let g = d + (c + b * t) * t;
    res = dot(g, g);
  } else {
    let z = sqrt(-pp);
    let v = acos(qq / (pp * z * 2.0)) / 3.0;
    let m = cos(v);
    let n = sin(v) * 1.7320508;
    let t1 = clamp((m + m) * z - kx, 0.0, 1.0);
    let t2 = clamp((-n - m) * z - kx, 0.0, 1.0);
    let g1 = d + (c + b * t1) * t1;
    let g2 = d + (c + b * t2) * t2;
    res = min(dot(g1, g1), dot(g2, g2));
  }
  return sqrt(res) - r;
}

// tapered strut between nodes (columns, spires, limbs): radius r1 at a → r2 at b
fn mod_w3_taperStrut(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r1, r2, h);
}

// round (Roman) arch opening — subtract from a wall. Origin at base center:
// straight sides height h, half-width w (semicircle top radius w), half-depth d in z
fn mod_w3_arch(p: vec3f, w: f32, h: f32, d: f32) -> f32 {
  let dxy = abs(p.xy - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect2 = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let top2 = length(p.xy - vec2f(0.0, h)) - w;
  let d2 = min(rect2, top2);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// Gothic lancet (ogival/pointed) arch profile: straight sides |x|<=w up to h,
// two-arc point peaking ph above h. 2D — extrude with mod_w3_lancet.
fn mod_w3_lancet2(q: vec2f, w: f32, h: f32, ph: f32) -> f32 {
  let R = (w * w + ph * ph) / (2.0 * w);
  let c = R - w;
  let dxy = abs(q - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let arcs = max(length(q - vec2f(-c, h)) - R, length(q - vec2f(c, h)) - R);
  let top = max(arcs, h - q.y);
  return min(rect, top);
}

// Gothic lancet arch opening in 3D — subtract from a wall. Base center origin,
// half-width w, straight height h, point rises ph above h, half-depth d in z
fn mod_w3_lancet(p: vec3f, w: f32, h: f32, ph: f32, d: f32) -> f32 {
  let d2 = mod_w3_lancet2(p.xy, w, h, ph);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// ── domain ops ─────────────────────────────────────────────────────────────
fn mod_w3_rotX(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}
fn mod_w3_rotY(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}
fn mod_w3_rotZ(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}
// infinite repetition on chosen axes (c = cell size per axis; 0 = no repeat)
fn mod_w3_repeat(p: vec3f, c: vec3f) -> vec3f {
  var q = p;
  if (c.x > 0.0) { q.x = (fract(p.x / c.x + 0.5) - 0.5) * c.x; }
  if (c.y > 0.0) { q.y = (fract(p.y / c.y + 0.5) - 0.5) * c.y; }
  if (c.z > 0.0) { q.z = (fract(p.z / c.z + 0.5) - 0.5) * c.z; }
  return q;
}
// polar repetition around Y: n copies; returns p in the first wedge
fn mod_w3_polar(p: vec3f, n: f32) -> vec3f {
  let ang = 6.2831853 / n;
  let a = atan2(p.z, p.x);
  let r = length(p.xz);
  let a2 = (fract(a / ang + 0.5) - 0.5) * ang;
  return vec3f(cos(a2) * r, p.y, sin(a2) * r);
}

// ── the marcher family (all call YOUR w3_map) ──────────────────────────────
// sphere-trace: returns (t, material) on hit, (-1, -1) on miss
fn mod_w3_march(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32, steps: i32) -> vec2f {
  var t = tmin;
  for (var i = 0; i < 256; i++) {
    if (i >= steps) { break; }
    let dm = w3_map(ro + rd * t);
    if (dm.x < 0.001 * t + 0.003) { return vec2f(t, dm.y); }
    t = t + max(dm.x * 0.9, 0.004);
    if (t > tmax) { break; }
  }
  return vec2f(-1.0, -1.0);
}

// tetrahedral 4-tap normal
fn mod_w3_nrm(p: vec3f, eps: f32) -> vec3f {
  let k = vec2f(1.0, -1.0);
  return normalize(
    k.xyy * w3_map(p + k.xyy * eps).x +
    k.yyx * w3_map(p + k.yyx * eps).x +
    k.yxy * w3_map(p + k.yxy * eps).x +
    k.xxx * w3_map(p + k.xxx * eps).x);
}

// soft shadow toward a light: k = penumbra hardness (8 soft … 32 crisp)
fn mod_w3_shadow(p: vec3f, ld: vec3f, tmax: f32, k: f32) -> f32 {
  var t = 0.03;
  var sh = 1.0;
  for (var i = 0; i < 24; i++) {
    let d = w3_map(p + ld * t).x;
    sh = min(sh, k * d / t);
    t = t + clamp(d, 0.02, 0.8);
    if (sh < 0.02 || t > tmax) { break; }
  }
  return clamp(sh, 0.0, 1.0);
}

// 4-tap ambient occlusion along the normal
fn mod_w3_ao(p: vec3f, n: vec3f) -> f32 {
  var occ = 0.0;
  var w = 1.0;
  for (var i = 1; i <= 4; i++) {
    let h = 0.04 * f32(i * i);
    occ = occ + w * (h - w3_map(p + n * h).x);
    w = w * 0.65;
  }
  return clamp(1.0 - 2.2 * occ, 0.0, 1.0);
}

// ── shading ────────────────────────────────────────────────────────────────
fn mod_w3_fresnel(n: vec3f, rd: vec3f, f0: f32) -> f32 {
  return f0 + (1.0 - f0) * pow(1.0 - clamp(dot(n, -rd), 0.0, 1.0), 5.0);
}

// the standard rig: sun key + sky fill + bounce, shadow and AO applied where
// each belongs (shadow kills the key, AO dims the fill), plus a spec lobe
fn mod_w3_light(alb: vec3f, n: vec3f, rd: vec3f, sunDir: vec3f, sunCol: vec3f, skyCol: vec3f, sh: f32, ao: f32) -> vec3f {
  let dif = clamp(dot(n, sunDir), 0.0, 1.0);
  let sky = 0.5 + 0.5 * n.y;
  let bou = clamp(-n.y, 0.0, 1.0) * 0.3;
  var c = alb * (sunCol * dif * sh + skyCol * sky * ao + skyCol * bou * ao);
  let hal = normalize(sunDir - rd);
  let spe = pow(clamp(dot(n, hal), 0.0, 1.0), 32.0) * dif * sh;
  c = c + sunCol * spe * 0.5 * mod_w3_fresnel(n, rd, 0.04);
  return c;
}

// aerial perspective: fold a hit color into the sky with distance
fn mod_w3_fog(c: vec3f, skyC: vec3f, t: f32, density: f32) -> vec3f {
  return mix(c, skyC, 1.0 - exp(-t * t * density));
}

// ANIM3 — articulated-chain animation kit (canonical copy).
// The layer between skel-lib (creature rigs) and world3 (raymarched space):
// two-bone IK, tapered limb SDFs, gait oscillators with planted feet, pose
// paths, and aim frames — everything needed to make a marched body MOVE well.
//
//   { "type": "define_module", "name": "anim3", "wgsl": <this file> }
//
// Design: everything is STATELESS — pure functions of time and parameters, so
// they run per-pixel in a visual with no CPU sync. Drive the inputs (targets,
// phases, headings) from a step hook via the whiteboard or the population
// buffer; the shader poses the body.
//
// The crowd pattern: hook publishes gpuPopulation entries [x, y, heading, phase]
// → the visual loops pop(i), builds each body in its local frame with
// mod_a3_gait(phase …) driving the legs. 4095 walkers, one dispatch.

// ── two-bone IK ────────────────────────────────────────────────────────────
// Classic solver: a chain root→mid→tip with segment lengths l1, l2 reaching
// for `target`. Returns the MID joint (elbow/knee). `pole` bends the joint
// toward it (knee forward, elbow back) — give it a point, not a direction.
// Unreachable targets clamp to full extension; degenerate poles self-heal.
fn mod_a3_ik2(root: vec3f, tgt: vec3f, l1: f32, l2: f32, pole: vec3f) -> vec3f {
  var to = tgt - root;
  var d = length(to);
  let maxR = l1 + l2 - 0.0001;
  d = clamp(d, abs(l1 - l2) + 0.0001, maxR);
  let dir = to / max(length(to), 0.0001);
  // law of cosines: distance from root to the mid joint's projection
  let a = (l1 * l1 - l2 * l2 + d * d) / (2.0 * d);
  let h = sqrt(max(l1 * l1 - a * a, 0.0));
  // bend plane: contains the chain axis, leans toward the pole
  var side = pole - root - dir * dot(pole - root, dir);
  let sl = length(side);
  if (sl < 0.001) { side = vec3f(0.0, 0.0, 1.0) - dir * dir.z; } else { side = side / sl; }
  return root + dir * a + normalize(side) * h;
}

// ── limb geometry ──────────────────────────────────────────────────────────
// tapered capsule: radius r0 at `a` → r1 at `b` (thigh→ankle, arm→wrist)
fn mod_a3_bone(p: vec3f, a: vec3f, b: vec3f, r0: f32, r1: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r0, r1, h);
}
// joint ball — drop one at every hinge to keep silhouettes smooth
fn mod_a3_joint(p: vec3f, at: vec3f, r: f32) -> f32 { return length(p - at) - r; }

// ── gait ───────────────────────────────────────────────────────────────────
// The planted-foot law (lifted from skel-lib's ladder): phase advances in
// STRIDE CYCLES (hook: ph += speed / strideLen * dt). Within one cycle a foot
// is planted for `duty` (moving backward at exactly body speed → zero world
// velocity) and swings forward for the rest, lifted on a sine arc.
// Returns (alongOffset, lift): foot position relative to its rest point,
// in units of strideLen.
fn mod_a3_gait(phase: f32, duty: f32) -> vec2f {
  let c = fract(phase);
  if (c < duty) {
    // stance: linear back-travel, no lift — the foot OWNS the ground
    let s = c / duty;
    return vec2f(0.5 - s, 0.0);
  }
  // swing: forward and up
  let s = (c - duty) / (1.0 - duty);
  return vec2f(-0.5 + s, sin(s * 3.14159) * 1.0);
}
// eased oscillator for secondary motion (tails, breathing, sway):
// sin with adjustable sharpness — sharp > 1 dwells at the extremes
fn mod_a3_sway(t: f32, freq: f32, sharp: f32) -> f32 {
  let s = sin(t * freq);
  return sign(s) * pow(abs(s), 1.0 / max(sharp, 0.001));
}

// ── pose paths ─────────────────────────────────────────────────────────────
// blend two joint positions (a pose is just a set of points — lerp each)
fn mod_a3_mix(a: vec3f, b: vec3f, t: f32) -> vec3f { return mix(a, b, smoothstep(0.0, 1.0, t)); }
// quadratic bezier through a lifted midpoint — a reach, a leap, a nod
fn mod_a3_arc(a: vec3f, peak: vec3f, b: vec3f, t: f32) -> vec3f {
  let u = 1.0 - t;
  return a * u * u + peak * 2.0 * u * t + b * t * t;
}

// ── aim frames ─────────────────────────────────────────────────────────────
// build a basis aimed along `fw` (head look-at, torso facing); transform a
// local point into it. worldUp guards collinearity.
fn mod_a3_aim(local: vec3f, origin: vec3f, fw0: vec3f) -> vec3f {
  let fw = normalize(fw0);
  var up = vec3f(0.0, 1.0, 0.0);
  if (abs(dot(fw, up)) > 0.99) { up = vec3f(0.0, 0.0, 1.0); }
  let rt = normalize(cross(up, fw));
  let u2 = cross(fw, rt);
  return origin + rt * local.x + u2 * local.y + fw * local.z;
}

// ── a whole walker, as the pattern to copy ─────────────────────────────────
// Biped legs in one call: body at `hips` heading +z in its local frame,
// phase in stride cycles, stride length L. Returns the SDF of both legs.
// (Offset the two feet half a cycle; IK bends knees toward the pole.)
fn mod_a3_legs(p: vec3f, hips: vec3f, phase: f32, L: f32, legLen: f32, r: f32) -> f32 {
  var d = 1e9;
  for (var s = 0; s < 2; s++) {
    let side = select(-1.0, 1.0, s == 1);
    let g = mod_a3_gait(phase + select(0.0, 0.5, s == 1), 0.55);
    let hip = hips + vec3f(side * legLen * 0.22, 0.0, 0.0);
    let foot = vec3f(hip.x, g.y * legLen * 0.22, g.x * L);
    let knee = mod_a3_ik2(hip, foot, legLen * 0.52, legLen * 0.52, hip + vec3f(0.0, 0.0, legLen));
    d = min(d, mod_a3_bone(p, hip, knee, r, r * 0.75));
    d = min(d, mod_a3_bone(p, knee, foot, r * 0.75, r * 0.5));
    d = min(d, mod_a3_joint(p, knee, r * 0.85));
  }
  return d;
}

// VEILFIRE · rooms.wgsl — the load-bearing scene SDF (vf-rooms node).
// EXPORT: fn w3_map(p: vec3f) -> vec2f  = (signed distance, material id).
//
// A WALKABLE Antichamber-style Gothic interior, carved SUBTRACTIVELY out of a
// solid rock block so rooms connect by construction (no coordinate seams):
//   d = solidBlock;  d = max(d, -naveAir);  d = max(d, -sideAir);  d = max(d, -door);
// then solids (columns, dais) are UNIONed back in with min(). Positive in open
// air, 0 at surfaces, negative inside rock — raymarchable from inside.
//
// ── ROOM EXTENTS (world units, y=0 is the floor) — movement/vf-* MIRROR THIS ──
//   NAVE (main hall):  x∈[-4, 4]   y∈[0, 9]   z∈[-9, 9]     (tall)
//   SIDE CHAMBER:      x∈[ 5,11]   y∈[0, 5]   z∈[-3.5, 3.5] (lower ceiling)
//   DIVIDING WALL:     x∈[ 4, 5]  (1 thick) — solid except the doorway
//   DOORWAY (lancet):  center x≈4.5, z=0, base y=0; opening z∈[-1.5,1.5],
//                      height y∈[0, 3.7] (straight to 2.5, point to 3.7),
//                      depth x∈[3.3, 5.7] (cuts the whole dividing wall)
//   COLONNADE:         two rows at x=±3.2, columns every 4 in z (z=0,±4,±8),
//                      r=0.4, floor→near ceiling (y∈[-0.5, 8.5])
//   DAIS (verticality, far +z end of nave):
//      step1: x∈[-3.5,3.5] y∈[0,1]   z∈[6,9]   (low platform)
//      step2: x∈[-3.5,3.5] y∈[0,2]   z∈[7.8,9.2] (upper ledge)
//   Suggested spawn: (0, 1.6, 0) facing +x toward the doorway, or -z down nave.
//
// MATERIAL IDS: 1 wall · 2 floor/dais · 3 column · 4 doorway/arch trim.
// Cheap: a handful of box/cyl/lancet evals, one z-repeat, no loops.

fn w3_map(p: vec3f) -> vec2f {
  // --- solid rock; carve the rooms out of it (block extended +x to x=18 for the escape hall) ---
  let d0 = mod_w3_box(p - vec3f(6.5, 4.5, 0.0), vec3f(11.5, 5.5, 10.0));
  let nave = mod_w3_box(p - vec3f(0.0, 4.5, 0.0), vec3f(4.0, 4.5, 9.0));
  let side = mod_w3_box(p - vec3f(8.0, 2.5, 0.0), vec3f(3.0, 2.5, 3.5));
  // ESCAPE HALL: a low, narrow corridor off the side chamber's far wall (x∈[11,18], z∈[-1,1]).
  let hall = mod_w3_box(p - vec3f(14.5, 1.2, 0.0), vec3f(3.5, 1.2, 1.0));

  // doorway: lancet arch, profile in (z,y), depth along x through the wall
  let qd = vec3f(p.z, p.y, p.x - 4.5);
  let door = mod_w3_lancet(qd, 1.5, 2.5, 1.2, 1.2);

  var d = d0;
  d = max(d, -nave);
  d = max(d, -side);
  d = max(d, -hall);
  d = max(d, -door);

  // shell material: floor low, doorway trim near the arch cut, else wall
  var mat = 1.0;
  if (p.y < 0.3) { mat = 2.0; }
  if (door < 0.35 && p.y < 3.9) { mat = 4.0; }

  // --- solids unioned back in ---
  // colonnade: mirrored rows at x=±3.2, repeated every 4 units in z
  let cz = (fract(p.z / 4.0 + 0.5) - 0.5) * 4.0;
  let colp = vec3f(abs(p.x) - 3.2, p.y - 4.0, cz);
  let col = mod_w3_cyl(colp, 4.5, 0.4);
  if (col < d) { d = col; mat = 3.0; }

  // dais / altar steps at the far +z end (verticality)
  let step1 = mod_w3_box(p - vec3f(0.0, 0.5, 7.5), vec3f(3.5, 0.5, 1.5));
  if (step1 < d) { d = step1; mat = 2.0; }
  let step2 = mod_w3_box(p - vec3f(0.0, 1.0, 8.5), vec3f(3.5, 1.0, 0.7));
  if (step2 < d) { d = step2; mat = 2.0; }

  return vec2f(d, mat);
}

// VEILFIRE — DEMONS. A gaunt, hunched, horned humanoid that WALKS.
// Built entirely from anim3-lib tapered-capsule bones + world3 struts so it reads
// as a silhouette at the edge of lantern light. Legs are driven by the planted-foot
// gait (mod_a3_gait(phase, 0.55)); arms counter-swing; head carries swept horns and
// a jutting snarl. Distance only — the integrator paints material / ember-crust.
//
//   { "type": "define_module", "name": "veilfire_demons", "wgsl": <this file> }
//
// EXPORT:  fn vf_demon(p: vec3f, phase: f32) -> f32
//   p     : local body space (heading +z, feet near y=0, center at origin)
//   phase : stride-cycle phase (fract cycles). Same phase feeds the population's
//           animPhase slot (pop(2i+1).y).
// Depends on world3-lib (mod_w3_taperStrut) + anim3-lib (bone/joint/gait/ik2/legs).

// fleshy smooth-union — organic joints without gaps; k small = tight seam
fn vf_smin(a: f32, b: f32, k: f32) -> f32 {
  let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

fn vf_demon(p: vec3f, phase: f32) -> f32 {
  let hipY = 0.88;      // hip height — feet reach y≈0
  let L = 0.5;          // stride length
  let legLen = 0.95;    // thigh+shin reach

  // ── legs: planted-foot gait, gaunt shins ─────────────────────────────────
  var d = mod_a3_legs(p, vec3f(0.0, hipY, 0.0), phase, L, legLen, 0.075);

  // subtle breathing / menace sway of the upper body
  let breathe = sin(phase * 6.2831853) * 0.02;

  // ── spine (hunched forward) + head + snarling jaw ────────────────────────
  let pelvis = vec3f(0.0, hipY, 0.0);
  let chest  = vec3f(0.0, hipY + 0.42, 0.10);
  let neck   = vec3f(0.0, hipY + 0.60, 0.16);
  let headC  = vec3f(0.0, hipY + 0.76, 0.20 + breathe);

  var body = mod_a3_bone(p, pelvis, chest, 0.11, 0.15);                 // gaunt ribcage
  body = vf_smin(body, mod_a3_bone(p, chest, neck, 0.13, 0.06), 0.08);  // taper to neck
  body = vf_smin(body, mod_a3_joint(p, headC, 0.14), 0.06);            // skull
  body = vf_smin(body,                                                  // jutting snarl
    mod_a3_bone(p, headC + vec3f(0.0, -0.02, 0.05), headC + vec3f(0.0, -0.06, 0.16), 0.09, 0.03), 0.05);
  d = min(d, body);

  // ── horns: swept up and back, crisp edges ────────────────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    let hb = headC + vec3f(sx * 0.08, 0.08, -0.02);
    let ht = headC + vec3f(sx * 0.16, 0.30, -0.18);
    d = min(d, mod_w3_taperStrut(p, hb, ht, 0.035, 0.004));
  }

  // ── arms: long, clawed, counter-swinging to the legs ─────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    // opposite phase offset to the same-side leg → natural counter-swing
    let g = mod_a3_gait(phase + select(0.5, 0.0, s == 1), 0.55);
    let shoulder = vec3f(sx * 0.20, hipY + 0.48, 0.06);
    let hand = vec3f(sx * 0.17, hipY - 0.32, 0.16 - g.x * 0.55);        // reach to mid-thigh
    let pole = shoulder + vec3f(sx * 0.35, -0.1, -0.35);               // elbow back/out
    let elbow = mod_a3_ik2(shoulder, hand, 0.44, 0.46, pole);
    var arm = mod_a3_bone(p, shoulder, elbow, 0.06, 0.045);
    arm = min(arm, mod_a3_bone(p, elbow, hand, 0.045, 0.028));
    arm = min(arm, mod_a3_joint(p, elbow, 0.05));
    // three splayed talons
    for (var c = 0; c < 3; c++) {
      let ca = (f32(c) - 1.0) * 0.12;
      let tip = hand + vec3f(sx * 0.03 + ca * 0.05, -0.14, 0.06 + ca * 0.02);
      arm = min(arm, mod_w3_taperStrut(p, hand, tip, 0.022, 0.002));
    }
    d = vf_smin(d, arm, 0.04);
  }

  // ── HORROR PASS (v2) — detail the ember-shading catches at the light's edge ──
  // ribcage: thin bones across the hunched chest → skeletal, ember-cracked
  for (var r = 0; r < 4; r++) {
    let ry = hipY + 0.13 + f32(r) * 0.085;
    let rz = 0.04 + f32(r) * 0.012;
    d = min(d, mod_a3_bone(p, vec3f(-0.115, ry, rz), vec3f(0.115, ry, rz), 0.012, 0.012));
  }
  // a sternum ridge down the ribs
  d = min(d, mod_a3_bone(p, vec3f(0.0, hipY + 0.10, 0.05), vec3f(0.0, hipY + 0.42, 0.09), 0.016, 0.010));
  // sunken eye sockets + a gaping maw carved from the skull (dark hollows read as a face)
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(-0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f( 0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(0.0, -0.055, 0.15)), 0.050));

  return d;
}

// enemies (node: enemies) — shared enemy shading helper. The enemy BODY draw is
// routed through veilfire/demons.wgsl's vf_demon inside renderer-mega; this holds
// the damage-flash tint the renderer can blend by hp so hurt demons read hot.
fn s3_enemyTint(hp01: f32) -> vec3f {
  return mix(vec3f(1.0, 0.28, 0.16), vec3f(0.11, 0.05, 0.045), clamp(hp01, 0.0, 1.0));
}

// shooter3 / projectiles — thin glowing energy bolts (tracers)
// Cheap capsule SDF + emissive HDR color the renderer adds on hit-glow.
// Exports:
//   s3_tracer(p, a, b)            -> f32   thin bolt from a to b (radius ~0.06)
//   s3_tracerColor(kind, life01)  -> vec3f linear HDR emissive (3=player, 4=enemy)

// A thin glowing bolt: a capsule from a to b. Cheap — one clamp/dot/length.
fn s3_tracer(p: vec3f, a: vec3f, b: vec3f) -> f32 {
  return mod_w3_capsule(p, a, b, 0.06);
}

// Emissive HDR color the renderer adds. Brightest when freshly fired (life01~1),
// fading toward death (life01~0). kind 3 = player (hot cyan-white), 4 = enemy (sick green).
fn s3_tracerColor(kind: f32, life01: f32) -> vec3f {
  let l = clamp(life01, 0.0, 1.0);
  // hot core (near-white at spawn) blended toward the tinted tail as it ages
  let playerHot  = vec3f(0.55, 1.0, 1.0);   // cyan
  let playerCore = vec3f(1.0, 1.0, 1.0);    // white-hot
  let enemyHot   = vec3f(0.35, 1.0, 0.15);  // sick green
  let enemyCore  = vec3f(0.85, 1.0, 0.6);   // pale green-white
  let isEnemy = step(3.5, kind);            // 0 for kind<=3, 1 for kind>=4
  let hot  = mix(playerHot, enemyHot, isEnemy);
  let core = mix(playerCore, enemyCore, isEnemy);
  // core dominates when fresh; tint takes over as it fades
  let tint = mix(hot, core, l);
  // HDR emission: strong when fresh, glowing dim tail when old
  let energy = mix(1.2, 9.0, l * l);
  return tint * energy;
}

// VEILFIRE — atmosphere. Dread mood layered over a plainly-lit color.
//   vf_atmos(c, pos, rd, t, time):
//     c    = lit color at the hit (linear HDR)
//     pos  = hit point in world space
//     rd   = ray direction (unit)
//     t    = hit distance (fog falloff)
//     time = seconds
//   returns the color, dread-soaked. Output stays LINEAR HDR — no tonemap here.
//
// Four cheap layers, in order:
//   1. cool desaturation with a warm firelight bias (drain life, keep the fire)
//   2. torch flicker — layered sin-noise multiplying the whole scene
//   3. depth fog toward near-black cold murk (dread deepens it)
//   4. faint drifting ember specks low in the frame
//
// Mood dials read from the whiteboard (see SPEC): uni(12)=dread01, uni(18)=fogDensity.
// Both degrade gracefully to sane defaults when unset (zero).

fn vf_hash11(n: f32) -> f32 { return fract(sin(n * 43758.5453) * 12345.6789); }

fn vf_atmos(c: vec3f, pos: vec3f, rd: vec3f, t: f32, time: f32) -> vec3f {
  var col = c;

  let dread = clamp(uni(12), 0.0, 1.0);
  let fogD  = max(uni(18), 0.0);

  // ── 1. cool desaturation + warm firelight bias ─────────────────────────────
  // Drain saturation toward grey (harder the more dread), then re-tint: warm
  // ember in the lit/bright regions, cold blue in the shadows.
  let lum   = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  let desat = mix(col, vec3f(lum), 0.42 + 0.28 * dread);
  let warm  = vec3f(1.18, 0.60, 0.28);
  let cool  = vec3f(0.52, 0.66, 0.96);
  let tint  = mix(cool, warm, clamp(lum * 1.6, 0.0, 1.0));
  col = desat * tint;

  // ── 2. torch flicker — layered sin-noise, multiplies everything ────────────
  let f1 = sin(time * 11.0) * 0.5 + sin(time * 17.3 + 1.7) * 0.3 + sin(time * 29.0) * 0.2;
  let f2 = sin(time * 3.1 + 0.5);
  let flick = 1.0 + 0.06 * f1 + 0.03 * f2;   // roughly ±9% breathing
  col = col * flick;

  // ── 3. depth fog — a LIFTED cold haze (KINDLE murk). Fog toward near-black is
  // invisible in a dark room; a lifted blue-grey veils distance so the air reads
  // thick. Two bands: a near haze that lifts shadows + a far murk that swallows.
  let density = fogD + 0.010 + 0.012 * dread;
  let fogAmt  = 1.0 - exp(-t * t * density);
  let haze    = vec3f(0.055, 0.072, 0.110);       // cold blue-grey — the visible fog
  col = mix(col, haze, fogAmt);
  col = col + haze * 0.35 * fogAmt;                // scatter lift so it glows, not just dims

  // ── 4. drifting ember specks, low in the frame ─────────────────────────────
  // Parameterize by ray direction so motes float in view; drift upward in time.
  let ep = vec2f(rd.x * 6.0, rd.y * 6.0 - time * 0.35);
  var ember = 0.0;
  for (var k = 0; k < 3; k = k + 1) {
    let sc   = 1.0 + f32(k) * 1.7;
    let g    = ep * sc + vec2f(f32(k) * 13.7, f32(k) * 7.3);
    let cell = floor(g);
    let fr   = fract(g) - 0.5;
    let h    = vf_hash11(cell.x * 57.0 + cell.y * 131.0 + f32(k) * 3.0);
    let on   = step(0.92, h);                 // only a few cells host an ember
    let jit  = vec2f(vf_hash11(h * 21.0) - 0.5, vf_hash11(h * 47.0) - 0.5) * 0.6;
    let d    = length(fr - jit);
    let mote = on * smoothstep(0.09, 0.0, d);
    let tw   = 0.5 + 0.5 * sin(time * (4.0 + h * 6.0) + h * 30.0);  // twinkle
    ember = ember + mote * tw;
  }
  // Sit near the low end (bottom of view) and glow warmer through the murk.
  let lowBias  = smoothstep(0.30, -0.45, rd.y);
  let emberCol = vec3f(1.30, 0.52, 0.16);
  col = col + emberCol * ember * lowBias * (0.35 + 0.55 * fogAmt);

  return col;
}

// shooter3 HUD — screen-space overlay for the horror-shooter. No raymarch.
// Exports s3_hud(uv, hp01, ammo, score, dread01) -> vec4f (rgb, alpha); alpha 0
// where nothing is drawn so the integrator can composite it over the world.
//
// uv arrives -1..1 with y DOWN — the engine convention (uv.y=-1 top, +1 bottom;
// see render-core "MATCH THE ENGINE … uv.y increases DOWNWARD"). That already
// matches char5x7 / printInt (p in [0,1]², y DOWN), so s = uv*0.5+0.5 with no
// flip renders glyphs upright. Palette is thin, cold-white ink
// over near-black, with a rising red dread wash so the frame turns ominous as
// dread01 → 1. Legible on black; restrained on a lit scene.

// ── glyph cell helpers (screen coords s: 0..1, y DOWN) ────────────────────
// draw one glyph inside a box; returns coverage 0..1
fn s3_boxChar(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, code: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return char5x7(p, code);
}
// draw a right-aligned integer inside a box
fn s3_boxInt(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, value: f32, digits: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return printInt(p, value, digits);
}
// one glyph within a monospace run: start x0, cell width cw, index j (0.8 fill)
fn s3_cellChar(s: vec2f, x0: f32, cw: f32, y0: f32, y1: f32, j: i32, code: i32) -> f32 {
  let cx0 = x0 + f32(j) * cw;
  return s3_boxChar(s, cx0, cx0 + cw * 0.82, y0, y1, code);
}

fn s3_hud(uv: vec2f, hp01: f32, ammo: f32, score: f32, dread01: f32) -> vec4f {
  // screen coords, top-left origin, y DOWN — matches the glyph font + engine.
  let s = vec2f(uv.x * 0.5 + 0.5, uv.y * 0.5 + 0.5);
  let hp = clamp(hp01, 0.0, 1.0);
  let dr = clamp(dread01, 0.0, 1.0);

  var col = vec3f(0.0);
  var a = 0.0;

  // ── dread wash: a red vignette that swells from the corners with dread01 ──
  // (built in uv space so it is symmetric regardless of the glyph y-flip)
  {
    let edge = smoothstep(0.55, 1.25, length(uv));   // 0 centre → 1 corners
    // a slow, uneasy pulse so high dread never sits perfectly still
    let breath = 0.82 + 0.18 * sin(uni(0) * 2.1);
    let vig = edge * dr * breath;
    col = vec3f(0.42, 0.02, 0.015) * vig;
    a = vig * 0.65;
  }

  // ── HEALTH BAR — bottom-left, red→green by hp01, dark empty track, frame ──
  {
    let x0 = 0.035; let x1 = 0.315; let y0 = 0.905; let y1 = 0.940;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let bt = 0.0035;                                          // border thickness
      let border = s.x < x0 + bt || s.x > x1 - bt || s.y < y0 + bt || s.y > y1 - bt;
      let fillX = x0 + (x1 - x0) * hp;
      if (border) {
        col = vec3f(0.55, 0.56, 0.62); a = 0.85;
      } else if (s.x <= fillX) {
        // red at 0 → amber mid → green at full; scale value so low HP reads hot
        let hc = mix(vec3f(0.95, 0.09, 0.06), vec3f(0.16, 0.92, 0.26), smoothstep(0.0, 1.0, hp));
        col = hc * (0.85 + 0.15 * hp); a = 0.92;
      } else {
        col = vec3f(0.05, 0.02, 0.02); a = 0.55;                // depleted track
      }
    }
    // "HP" label just above the bar
    let ly0 = 0.868; let ly1 = 0.898;
    let lc = max(s3_cellChar(s, 0.035, 0.024, ly0, ly1, 0, 72),   // H
                 s3_cellChar(s, 0.035, 0.024, ly0, ly1, 1, 80));  // P
    if (lc > 0.0) { col = vec3f(0.72, 0.74, 0.80); a = lc * 0.9; }
  }

  // ── AMMO — bottom-right, printInt (3 digits), with a small label ──
  {
    let x0 = 0.80; let x1 = 0.965; let y0 = 0.905; let y1 = 0.945;
    let cov = s3_boxInt(s, x0, x1, y0, y1, ammo, 3);
    if (cov > 0.0) { col = vec3f(0.86, 0.88, 0.94); a = cov * 0.95; }
    // "AMMO" label above the count
    let ly0 = 0.868; let ly1 = 0.898;
    let lx0 = 0.80; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 65);   // A
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 79)); // O
    if (lab > 0.0) { col = vec3f(0.66, 0.68, 0.74); a = lab * 0.85; }
  }

  // ── SCORE — top-right, printInt (6 digits), with a label ──
  {
    let x0 = 0.74; let x1 = 0.965; let y0 = 0.070; let y1 = 0.110;
    let cov = s3_boxInt(s, x0, x1, y0, y1, score, 6);
    if (cov > 0.0) { col = vec3f(0.90, 0.90, 0.95); a = cov * 0.95; }
    // "SCORE" label above the number
    let ly0 = 0.032; let ly1 = 0.062;
    let lx0 = 0.74; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 83);   // S
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 67)); // C
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 79)); // O
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 82)); // R
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 4, 69)); // E
    if (lab > 0.0) { col = vec3f(0.62, 0.63, 0.70); a = lab * 0.82; }
  }

  // ── DREAD METER — thin vertical bar, right edge, fills bottom→top ──
  {
    let x0 = 0.972; let x1 = 0.990; let y0 = 0.32; let y1 = 0.90;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let fillTop = y1 - (y1 - y0) * dr;                 // fills upward with dread
      if (s.y >= fillTop) {
        let up = (y1 - s.y) / (y1 - y0);                 // 0 bottom → 1 top of bar
        let hot = mix(vec3f(0.55, 0.05, 0.04), vec3f(1.0, 0.28, 0.12), up);
        col = hot; a = 0.9;
      } else {
        col = vec3f(0.06, 0.02, 0.02); a = 0.5;          // empty channel
      }
    }
  }

  // ── CROSSHAIR — thin center cross with a gap, cold-white, reddens w/ dread ──
  {
    let ax = abs(uv.x); let ay = abs(uv.y);
    let th = 0.0038;
    let inR = 0.013; let outR = 0.050;
    let horiz = ay < th && ax > inR && ax < outR;
    let vert  = ax < th && ay > inR && ay < outR;
    let dot   = length(uv) < 0.0028;
    if (horiz || vert || dot) {
      col = mix(vec3f(0.92, 0.95, 1.0), vec3f(1.0, 0.18, 0.12), dr);
      a = 0.9;
    }
  }

  return vec4f(col, clamp(a, 0.0, 1.0));
}

stepHooks.code:
function pz_blocked(x, z) {
  const cr = 0.8;
  for (const cx of [-3.2, 3.2]) { for (const cz of [-8, -4, 0, 4, 8]) {
    if ((x - cx) * (x - cx) + (z - cz) * (z - cz) < cr * cr) return true;
  } } return false;
}
function pz_walkable(x, z) {
  const R = 0.4;
  const nave = x >= -4 + R && x <= 4 - R && z >= -9 + R && z <= 9 - R;
  const side = x >= 5 + R && x <= 11 - R && z >= -3.5 + R && z <= 3.5 - R;
  const door = x >= 3.3 && x <= 5.7 && z >= -1.5 + R && z <= 1.5 - R;
  const hall = x >= 11 - R && x <= 18 - R && z >= -1 + R && z <= 1 - R;   // the escape corridor
  return (nave || side || door || hall) && !pz_blocked(x, z);
}
try {
  const wd = sim.worldData
  if (!wd.__vf) wd.__vf = {}
  const V = wd.__vf
  const sdt = Math.min(dt, 1 / 30)
  V.t = (V.t || 0) + sdt
  const u = Array.isArray(wd.gpuUniforms) ? wd.gpuUniforms : new Array(256).fill(0)
  while (u.length < 256) u.push(0)
  const inp = wd.input || {}
  const ptr = inp.pointer || {}

  // spawn in the side room, facing the far wall (the hallway is +x across the room)
  if (V.mv !== 4) {
    V.px = 6.0; V.py = 1.7; V.pz = -2.6; V.yaw = 1.5708; V.pitch = -0.12
    V.vy = 0; V.ground = 1; V.lx = null; V.ly = null; V.mv = 4
    V.dlt = [0.0, 2.0944, 4.1888]; V.trap = null; V.win = 0; V.firePrev = false
    V.hp = 1.0; V.grab = null; V.biteT = 0; V.flash = 0; V.hyaw = 1.5708
  }

  // ── the two law CELLS come from selectable fields; the click-throttle overrides ──
  const RULES = { hue: 1, wave: 2, invert: 3, posterize: 4, slow: 5, fast: 6 }
  const readZone = (name, dz, dRule, dR) => {
    let lx = 0.0, lz = dz, rule = dRule, r = dR
    const f = (sim.fields && sim.fields.getFieldByName) ? sim.fields.getFieldByName(name) : null
    if (f && f.transform) {
      lx = (f.transform.x - 256) / 256 * 3.0
      lz = (f.transform.y - 256) / 256 * 3.2
      const p = f.properties || {}; const rv = p.rule
      if (typeof rv === 'string' && RULES[rv] != null) rule = RULES[rv]
      else if (typeof rv === 'number') rule = rv
      if (typeof p.radius === 'number') r = p.radius
    }
    return { lx, lz, rule, r }
  }
  const zA = readZone('Cell A',  1.7, RULES.wave, 1.7)   // upper lane (neutral until throttled)
  const zB = readZone('Cell B', -1.7, RULES.hue,  1.7)   // lower lane (neutral until throttled)
  if (V.trap === 'A') { zA.rule = RULES.slow; zB.rule = RULES.fast }
  else if (V.trap === 'B') { zB.rule = RULES.slow; zA.rule = RULES.fast }
  u[31] = zA.lx; u[32] = zA.lz; u[33] = zA.rule; u[34] = zA.r
  u[35] = zB.lx; u[36] = zB.lz; u[37] = zB.rule; u[38] = zB.r
  V.rzf = ((V.rzf || 0) + 1) % 360; u[30] = V.rzf

  const factorAt = (x, z) => {
    const qx = x - 8.0, qz = z; let f = 1.0
    if (zA.r > 0.01 && Math.hypot(qx - zA.lx, qz - zA.lz) < zA.r) { f *= (zA.rule === 5 ? 0.18 : zA.rule === 6 ? 2.2 : 1.0) }
    if (zB.r > 0.01 && Math.hypot(qx - zB.lx, qz - zB.lz) < zB.r) { f *= (zB.rule === 5 ? 0.18 : zB.rule === 6 ? 2.2 : 1.0) }
    return f
  }

  // ── PLAYER — a body in the field: your step is scaled by the cell underfoot ──
  const pf = factorAt(V.px, V.pz)
  const step = sdt * pf
  if (V.lx == null) { V.lx = ptr.x != null ? ptr.x : 256; V.ly = ptr.y != null ? ptr.y : 256 }
  const mx = ptr.x != null ? ptr.x : V.lx, my = ptr.y != null ? ptr.y : V.ly
  const absS = 0.006, relS = 0.0052
  V.yaw -= (mx - V.lx) * absS + (inp.lookX || 0) * relS
  V.pitch = Math.max(-1.2, Math.min(1.2, V.pitch - ((my - V.ly) * absS + (inp.lookY || 0) * relS)))
  V.lx = mx; V.ly = my
  const fx = Math.sin(V.yaw), fz = Math.cos(V.yaw)
  const rx = -Math.cos(V.yaw), rz = Math.sin(V.yaw)
  // MOVE is locked once a demon has you (you can still look, helplessly). Otherwise walk.
  if (!V.grab) {
    const spd = 5.5, mF = inp.moveY || 0, mS = inp.moveX || 0
    const wdx = fx * mF + rx * mS, wdz = fz * mF + rz * mS
    const dx = wdx * spd * step, dz = wdz * spd * step
    let nx = V.px, nz = V.pz
    if (pz_walkable(V.px + dx, V.pz)) nx = V.px + dx
    if (pz_walkable(nx, V.pz + dz)) nz = V.pz + dz
    V.px = nx; V.pz = nz
    if (mF || mS) V.hyaw = Math.atan2(wdx, wdz)   // the hero faces where it's skating
    if (inp.action && V.ground) { V.vy = 4.4; V.ground = 0 }
    V.vy -= 12.0 * step; V.py += V.vy * step
    if (V.py <= 1.7) { V.py = 1.7; V.vy = 0; V.ground = 1 }
  }

  const cp = Math.cos(V.pitch), sp = Math.sin(V.pitch)

  // ── THROTTLE: click sets the cell you're aiming at as the TRAP (slow); the other goes fast ──
  let aimX = V.px + fx * 3.0, aimZ = V.pz + fz * 3.0
  if (sp < -0.03) { const tt = V.py / (-sp); aimX = V.px + fx * cp * tt; aimZ = V.pz + fz * cp * tt }
  const dAaim = Math.hypot(aimX - 8.0, aimZ - zA.lz), dBaim = Math.hypot(aimX - 8.0, aimZ - zB.lz)
  const firing = !!(ptr && ptr.pressed)
  if (firing && !V.firePrev && !V.win && !V.grab) { V.trap = (dAaim < dBaim) ? 'A' : 'B' }
  V.firePrev = firing

  const pop = []
  if (V.grab) {
    // ── CAUGHT: the demon is latched to your vision, biting until you die. The
    // FIELD sets the tempo — in a fast cell it snaps and rips you quickly; in a
    // slow cell the whole thing is slow-motion but you are slowed too and cannot
    // pull away. Either way it rides your face down to nothing. ──
    const pf = factorAt(V.px, V.pz)
    const tempo = 0.35 + pf                                 // fast field bites/drains faster
    V.hp = (V.hp == null ? 1.0 : V.hp) - sdt * 0.30 * tempo
    V.biteT = (V.biteT || 0) + sdt * tempo
    if (V.biteT > 0.55) { V.biteT = 0; V.flash = 1.0 }      // a fresh bite
    V.flash = Math.max(0, (V.flash || 0) - sdt * 3.5)
    u[16] = V.flash                                          // red bite flash (hit-flash slot)
    // the demon CLUTCHING the hero: it surges onto the body on each bite, orbiting so
    // its limbs read against the hero from the third-person camera.
    const clutch = 0.30 + 0.22 * (0.5 + 0.5 * Math.sin(V.biteT * 11.4))
    const ga = (V.t || 0) * 0.7
    const gx = V.px + Math.sin(ga) * clutch, gz = V.pz + Math.cos(ga) * clutch
    const gyaw = Math.atan2(V.px - gx, V.pz - gz)            // lunge into the hero
    pop.push(gx, 0.0, gz, 1.0, 1.0, V.t * 9.0, gyaw, 1.0)    // atk flag set
    if (V.hp <= 0) {                                         // dead -> back to the start of the run
      V.grab = null; V.hp = 1.0; V.flash = 0; V.px = 6.0; V.pz = -2.6; V.trap = null
    }
  } else if (!V.win) {
    // ── DEMONS circulate between the two lanes; a slowed cell pins them. Step into
    //    a cell that holds a demon and it GRABS you. ──
    for (let i = 0; i < 3; i++) {
      const ph = i * 2.0944
      const lt = V.dlt[i]
      const x = 8.0 + 1.1 * Math.sin(lt * 0.5 + ph)
      const z = 1.7 * Math.sin(lt * 0.8 + ph)               // patrols upper(+1.7) <-> lower(-1.7)
      const bob = Math.abs(Math.sin(lt * 2.4 + ph)) * 0.08
      const yaw = Math.cos(lt * 0.8 + ph) >= 0 ? 0.0 : Math.PI
      const gait = lt * 1.6 + ph
      pop.push(x, bob, z, 1.0, 1.0, gait, yaw, 0.0)
      V.dlt[i] = lt + sdt * factorAt(x, z)
      if (Math.hypot(x - V.px, z - V.pz) < 0.95) { V.grab = { i }; V.biteT = 0.5; V.flash = 1.0 }  // it has you
    }
  }
  // ── THE NEON HERO — the player's body, rendered at the player position (flags=5
  //    marks it neon in the shader). Faces the skate direction; gait glides. ──
  pop.push(V.px, 0.0, V.pz, 1.0, 1.0, (V.t || 0) * 2.2, (V.hyaw != null ? V.hyaw : V.yaw), 5.0)
  V.pop = pop; wd.gpuPopulation = pop
  u[6] = (V.hp == null ? 1.0 : V.hp)                         // HP bar reflects the drain

  // ── WIN: reach the escape hall past the far wall ──
  if (!V.win && !V.grab && V.px > 11.4) V.win = 1

  // ── THIRD-PERSON camera: backed out behind the hero along the look direction,
  //    but OCCLUSION-CLAMPED — march the back-out ray and stop before it leaves the
  //    walkable room, so it never clips through a wall into the next chamber. ──
  const camDist = 4.2, camHt = 2.4
  let cd = 0.6
  for (let k = 1; k <= 10; k++) {
    const d = camDist * k / 10
    if (!pz_walkable(V.px - fx * d, V.pz - fz * d)) break
    cd = d
  }
  u[240] = V.px - fx * cd; u[241] = V.py + camHt; u[242] = V.pz - fz * cd; u[243] = 1.2
  u[244] = V.px; u[245] = V.py + 0.2; u[246] = V.pz; u[247] = 0
  wd.gpuUniforms = u
} catch (e) {}

visualTypes.wgsl:
// shooter3 MEGASHADER (node: renderer-mega). ONE visual raymarches the world
// (w3_map from veilfire/rooms) and depth-composites the whole population in a
// single dispatch — demons (vf_demon), projectiles/death-bits (emissive) — then
// atmosphere (vf_atmos), muzzle/hit flashes, and the HUD (s3_hud) on top.
//
// Occlusion is correct + cheap: each entity is first rejected by a ray-vs-
// bounding-sphere test and by `t > worldT` (behind a wall), so only entities the
// ray actually pierces IN FRONT of the world get a local march. Camera on
// uni4(60/61). w3_map + vf_demon + s3_* + vf_atmos come from sibling modules.

// ray → sphere near-t (negative if no hit; may be <0 if camera inside)
fn s3_sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> f32 {
  let oc = ro - c;
  let b = dot(oc, rd);
  let h = b * b - (dot(oc, oc) - r * r);
  if (h < 0.0) { return -1.0; }
  return -b - sqrt(h);
}

// ── RULE ZONES (laws as per-pixel fields) ───────────────────────────────────
// Two radial zones on the side-room floor plane (world centred at x=8, z=0). A
// pixel is re-lawed by which zone its WORLD HIT-POINT falls in, so walls, floor,
// AND a demon crossing the seam are all sliced per-pixel by the same test. The
// active law-set shifts by frame (uni(30), counted in the hook):
//   frames <120: zoneA hue-rotates, zoneB wave-ripples, overlap does BOTH.
//   frames 120-239: zoneA law swaps to INVERT (live, by data not deploy).
//   frames >=240: a posterize law is ADDED over BOTH zones.
fn vf_rz_hue120(c: vec3f) -> vec3f { return vec3f(c.b, c.r, c.g); }
// one law, by rule id. 1 hue · 2 wave · 3 invert · 4 posterize · 5 time-slow · 6 time-fast.
// The visual is only half of a law: the time laws (5/6) also scale MOTION in the hook.
fn vf_rz_law(col: vec3f, ruleId: f32, hp: vec3f, t: f32) -> vec3f {
  var c = col;
  if (ruleId > 0.5 && ruleId < 1.5) {                 // HUE
    c = mix(c, vf_rz_hue120(c) * 1.3 + vec3f(0.0, 0.18, 0.0), 0.9);
  } else if (ruleId < 2.5) {                          // WAVE
    let w = 0.45 + 0.55 * sin(hp.y * 3.6 + t * 3.2 + hp.x * 4.0);
    c = mix(c.zyx, vec3f(0.10, 0.45, 0.95) * (0.4 + c), w * 0.85);
  } else if (ruleId < 3.5) {                          // INVERT
    c = vec3f(1.0) - c;
  } else if (ruleId < 4.5) {                          // POSTERIZE
    c = floor(c * 5.0) / 5.0;
  } else if (ruleId < 5.5) {                          // TIME-SLOW: cold, languid pulse
    c = mix(c, vec3f(0.22, 0.42, 0.78), 0.55) * (0.72 + 0.14 * sin(t * 1.1));
  } else {                                            // TIME-FAST: warm, streaking
    let s = 0.5 + 0.5 * sin(hp.x * 9.0 - t * 15.0);
    c = mix(c, vec3f(1.0, 0.55, 0.2), 0.42) + vec3f(0.55, 0.22, 0.0) * s * 0.4;
  }
  return c;
}
// zones now come from UNIFORMS the hook fills from selectable fields (rule lives ON the
// field, so you can pick a zone and change its law): u31..34 = zoneA x,z,rule,radius (room-
// local); u35..38 = zoneB. Overlap composes B then A. radius<=0 means "no zone".
fn vf_rulezones(col0: vec3f, hp: vec3f, t: f32) -> vec3f {
  let q = vec2f(hp.x - 8.0, hp.z);
  let aR = uni(34); let bR = uni(38);
  if (aR < 0.01 && bR < 0.01) { return col0; }
  let dA = length(q - vec2f(uni(31), uni(32)));
  let dB = length(q - vec2f(uni(35), uni(36)));
  let inA = aR > 0.01 && dA < aR;
  let inB = bR > 0.01 && dB < bR;
  if (!inA && !inB) { return col0; }
  var col = col0;
  if (inB) { col = vf_rz_law(col, uni(37), hp, t); }
  if (inA) { col = vf_rz_law(col, uni(33), hp, t); }   // A over B on overlap
  var rim = 999.0;
  if (aR > 0.01) { rim = min(rim, abs(dA - aR)); }
  if (bR > 0.01) { rim = min(rim, abs(dB - bR)); }
  col += vec3f(1.0, 0.9, 0.5) * smoothstep(0.10, 0.0, rim) * 1.4;
  return col;
}

fn visual_s3(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let ro = uni4(60).xyz;
  let fov = max(uni4(60).w, 0.6);
  let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
  let sky = vec3f(0.02, 0.025, 0.05);

  // ── the world ──
  let wh = mod_w3_march(ro, rd, 0.02, 60.0, 96);
  var worldT = select(60.0, wh.x, wh.x >= 0.0);
  var col = sky;
  if (wh.x >= 0.0) {
    let pos = ro + rd * wh.x;
    let n = mod_w3_nrm(pos, 0.02);
    let ao = mod_w3_ao(pos, n);
    var alb = vec3f(0.30, 0.29, 0.36);                              // walls
    if (wh.y > 1.5 && wh.y < 2.5) { alb = vec3f(0.15, 0.14, 0.13); } // floor/dais
    if (wh.y > 2.5 && wh.y < 3.5) { alb = vec3f(0.22, 0.20, 0.24); } // column
    if (wh.y > 3.5) { alb = vec3f(0.55, 0.34, 0.14); }              // doorway trim
    // lantern (headlamp at the camera — vf-lightdark will move it to the player)
    let ld = normalize(ro - pos);
    let dist = length(ro - pos);
    let sh = mod_w3_shadow(pos + n * 0.04, ld, dist, 14.0);
    let diff = max(dot(n, ld), 0.0);
    let atten = 4.5 / (1.0 + 0.09 * dist * dist);
    col = alb * (vec3f(0.05, 0.06, 0.09) + vec3f(1.0, 0.82, 0.55) * diff * atten * sh) * ao;
  }

  // ── the population, depth-composited in front of the world ──
  var nearT = worldT;
  let cnt = popCount() / 2;
  for (var i = 0; i < cnt; i = i + 1) {
    let a = pop(i * 2);            // x, y, z, kind
    let b = pop(i * 2 + 1);        // hp01, phase, yaw, flags
    let kind = a.w;
    if (kind < 0.5) { continue; }  // empty slot
    let ppos = a.xyz;
    let isDemon = kind < 2.5;
    // BUG WAS HERE: sphere sat at the feet (y=0, r=1.4) → it clipped everything
    // above y=1.4: the ribcage, head, horns. Center it at torso height + widen so
    // the WHOLE body is inside the sphere test AND the local march below.
    let bc = ppos + vec3f(0.0, select(0.0, 1.05, isDemon), 0.0);
    let br = select(0.18, 1.6, isDemon);
    let sh = s3_sph(ro, rd, bc, br);
    // the neon HERO (flags b.w>4.5) superimposes THROUGH walls — never occluded by
    // the world, so a backed-out third-person camera always sees it. Everything else
    // is culled when it sits behind the world geometry.
    if (sh < 0.0 || (sh > nearT && b.w < 4.5)) { continue; }

    if (kind < 2.5) {
      // DEMON — local sphere-march (rotate the ray into the demon's yaw frame)
      let yaw = b.z;
      let cy = cos(-yaw); let sy = sin(-yaw);
      let o0 = ro - ppos;
      let lro = vec3f(cy * o0.x + sy * o0.z, o0.y, -sy * o0.x + cy * o0.z);
      let lrd = vec3f(cy * rd.x + sy * rd.z, rd.y, -sy * rd.x + cy * rd.z);
      var t = max(sh, 0.02);
      var hitT = -1.0;
      for (var s = 0; s < 30; s = s + 1) {
        let d = vf_demon(lro + lrd * t, b.y);
        if (d < 0.004) { hitT = t; break; }
        t = t + max(d * 0.8, 0.004);
        if ((t > nearT && b.w < 4.5) || t > sh + 2.0 * br) { break; }
      }
      if (hitT > 0.0 && (hitT < nearT || b.w > 4.5)) {
        if (b.w < 4.5) { nearT = hitT; }   // hero draws over the world but doesn't set depth (keeps fog right)
        let lp = lro + lrd * hitT;
        let e = 0.012;
        let nn = normalize(vec3f(
          vf_demon(lp + vec3f(e, 0.0, 0.0), b.y) - vf_demon(lp - vec3f(e, 0.0, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, e, 0.0), b.y) - vf_demon(lp - vec3f(0.0, e, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, 0.0, e), b.y) - vf_demon(lp - vec3f(0.0, 0.0, e), b.y)));
        let ll = normalize(lro - lp);                 // headlamp, in local frame
        let dist = length(ro - (ro + rd * hitT));
        let diff = max(dot(nn, ll), 0.0);
        let atten = 4.0 / (1.0 + 0.10 * dist * dist);
        let base = vec3f(0.11, 0.05, 0.045);          // charred flesh
        let ember = vec3f(1.0, 0.32, 0.07) * pow(clamp(0.6 - nn.y, 0.0, 1.0), 2.0) * (0.7 + 0.5 * sin(time * 6.0 + ppos.x));
        if (b.w > 4.5) {
          // NEON HERO — the player character: emissive, unlit by the crypt lantern,
          // a cyan->magenta pulse with a hot rim. flags(b.w)>4.5 marks it in the population.
          let pulse = 0.5 + 0.5 * sin(time * 3.2);
          let neon = mix(vec3f(0.16, 0.96, 1.0), vec3f(1.0, 0.24, 0.86), pulse);
          let rim = pow(1.0 - max(dot(nn, ll), 0.0), 2.2);
          col = neon * (1.1 + rim * 1.9) + vec3f(0.10, 0.34, 0.55);
        } else {
          col = base * (0.12 + diff * atten) + ember * 0.9;
        }
      }
    } else {
      // PROJECTILE / DEATH-BIT — emissive blob at the sphere hit
      if (sh < nearT) {
        nearT = sh;
        let life = clamp(b.x, 0.0, 1.0);
        if (kind > 4.5) { col = vec3f(1.0, 0.42, 0.12) * (0.5 + life * 1.6); }  // death ember
        else { col = s3_tracerColor(kind, life) * 1.4; }
      }
    }
  }

  // ── rule zones re-law the pixel by its world hit-point (before atmosphere so
  //    fog/embers still unify the room). Inert everywhere but the side chamber. ──
  col = vf_rulezones(col, ro + rd * nearT, time);

  // ── atmosphere over whatever we hit, then flashes, then HUD ──
  col = vf_atmos(col, ro + rd * nearT, rd, nearT, time);
  col += vec3f(1.0, 0.82, 0.5) * max(uni(15), 0.0) * 0.6;   // muzzle flash
  col += vec3f(1.0, 0.22, 0.16) * max(uni(16), 0.0) * 0.5;  // hit flash
  let hud = s3_hud(uv, uni(6), uni(7), uni(8), uni(12));
  col = mix(col, hud.rgb, hud.a);
  return vec4f(col, 1.0);
}

modules.wgsl:
// WORLD3 — the cafe's shared 3D raymarching kit (canonical copy).
// Everything ONE DAY, TIDEGLASS, and MARIONETTES 3D each hand-rolled, extracted
// once: camera, SDF primitives, domain ops, marcher, normals, soft shadows,
// AO, and a standard light rig. Ship it in your scene as a module:
//
//   { "type": "define_module", "name": "world3", "wgsl": <this file> }
//
// THE ONE CONTRACT — your scene defines the world map in its OWN module:
//
//   fn w3_map(p: vec3f) -> vec2f   // returns (signed distance, material id)
//
// WGSL resolves module-scope functions in any order, so the kit's marchers can
// call w3_map before your module defines it. A scene that ships world3 without
// defining w3_map will not compile — the contract is load-bearing.
//
// CAMERA CONVENTION (whiteboard rows 60–62, so hooks can drive the eye):
//   uni4(60) = ro.xyz, fov     ·  uni4(61) = target.xyz, roll(unused)
//   A hook that writes these makes any world3 scene orbit/walk for free.
//
// Typical visual:
//   let ro = uni4(60).xyz;  let fov = max(uni4(60).w, 0.6);
//   let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
//   let hit = mod_w3_march(ro, rd, 0.1, 60.0, 96);
//   if (hit.x > 0.0) {
//     let pos = ro + rd * hit.x;
//     let n = mod_w3_nrm(pos, 0.02);
//     let sh = mod_w3_shadow(pos + n * 0.05, sunDir, 30.0, 8.0);
//     let ao = mod_w3_ao(pos, n);
//     col = mod_w3_light(albedoFor(i32(hit.y)), n, rd, sunDir, sunCol, skyCol, sh, ao);
//   }
// Output linear HDR — the engine's ACES + bloom do the grading.

// ── camera ─────────────────────────────────────────────────────────────────
// Ray through a screen point for a look-at camera. uv is the visual's -1..1
// (y down — the flip is handled here, pass it raw).
fn mod_w3_ray(uv: vec2f, ro: vec3f, ta: vec3f, fov: f32) -> vec3f {
  let fw = normalize(ta - ro);
  let rt = normalize(cross(fw, vec3f(0.0, 1.0, 0.0)));
  let up = cross(rt, fw);
  return normalize(uv.x * rt * fov - uv.y * up * fov + fw);
}

// ── SDF primitives (3D) ────────────────────────────────────────────────────
fn mod_w3_sphere(p: vec3f, r: f32) -> f32 { return length(p) - r; }

fn mod_w3_box(p: vec3f, b: vec3f) -> f32 {
  let d = abs(p) - b;
  return length(max(d, vec3f(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

fn mod_w3_rbox(p: vec3f, b: vec3f, r: f32) -> f32 {
  return mod_w3_box(p, b - vec3f(r)) - r;
}

fn mod_w3_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - r;
}

// vertical capped cylinder: half-height h, radius r
fn mod_w3_cyl(p: vec3f, h: f32, r: f32) -> f32 {
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(r, h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

// tapered vertical cylinder: radius r0 at -h → r1 at +h (towers, spires)
fn mod_w3_cone(p: vec3f, h: f32, r0: f32, r1: f32) -> f32 {
  let t = clamp((p.y + h) / (2.0 * h), 0.0, 1.0);
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(mix(r0, r1, t), h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn mod_w3_torus(p: vec3f, R: f32, r: f32) -> f32 {
  return length(vec2f(length(p.xz) - R, p.y)) - r;
}

fn mod_w3_octa(p: vec3f, s: f32) -> f32 {
  let q = abs(p);
  return (q.x + q.y + q.z - s) * 0.57735027;
}

fn mod_w3_plane(p: vec3f, n: vec3f, d: f32) -> f32 { return dot(p, n) + d; }

// ── skeleton assembly (nodes + struts + tissue) ────────────────────────────
// Build forms as a GRAPH: struts between shared node points, joined with
// opSmoothUnion (the "linkage tissue"). Gaps become impossible by construction
// — parts share endpoints instead of hoping coordinates line up. Use tissue k
// at structural joints (0.2–0.5) and hard min for edges that must stay crisp.

// exact closed-form distance to a quadratic bezier strut (S start, Ctl control,
// E end, radius r) — the connective arc: vaults, arches, branches, cables
fn mod_w3_bezStrut(pos: vec3f, S: vec3f, Ctl: vec3f, E: vec3f, r: f32) -> f32 {
  let a = Ctl - S;
  let b = S - 2.0 * Ctl + E;
  let c = a * 2.0;
  let d = S - pos;
  let bb = dot(b, b);
  if (bb < 1e-9) {
    let pa = pos - S;
    let ba = E - S;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
  }
  let kk = 1.0 / bb;
  let kx = kk * dot(a, b);
  let ky = kk * (2.0 * dot(a, a) + dot(d, b)) / 3.0;
  let kz = kk * dot(d, a);
  let pp = ky - kx * kx;
  let qq = kx * (2.0 * kx * kx - 3.0 * ky) + kz;
  let h = qq * qq + 4.0 * pp * pp * pp;
  var res: f32;
  if (h >= 0.0) {
    let hs = sqrt(h);
    let x1 = (hs - qq) / 2.0;
    let x2 = (-hs - qq) / 2.0;
    let t = clamp(sign(x1) * pow(abs(x1), 0.3333333) + sign(x2) * pow(abs(x2), 0.3333333) - kx, 0.0, 1.0);
    let g = d + (c + b * t) * t;
    res = dot(g, g);
  } else {
    let z = sqrt(-pp);
    let v = acos(qq / (pp * z * 2.0)) / 3.0;
    let m = cos(v);
    let n = sin(v) * 1.7320508;
    let t1 = clamp((m + m) * z - kx, 0.0, 1.0);
    let t2 = clamp((-n - m) * z - kx, 0.0, 1.0);
    let g1 = d + (c + b * t1) * t1;
    let g2 = d + (c + b * t2) * t2;
    res = min(dot(g1, g1), dot(g2, g2));
  }
  return sqrt(res) - r;
}

// tapered strut between nodes (columns, spires, limbs): radius r1 at a → r2 at b
fn mod_w3_taperStrut(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r1, r2, h);
}

// round (Roman) arch opening — subtract from a wall. Origin at base center:
// straight sides height h, half-width w (semicircle top radius w), half-depth d in z
fn mod_w3_arch(p: vec3f, w: f32, h: f32, d: f32) -> f32 {
  let dxy = abs(p.xy - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect2 = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let top2 = length(p.xy - vec2f(0.0, h)) - w;
  let d2 = min(rect2, top2);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// Gothic lancet (ogival/pointed) arch profile: straight sides |x|<=w up to h,
// two-arc point peaking ph above h. 2D — extrude with mod_w3_lancet.
fn mod_w3_lancet2(q: vec2f, w: f32, h: f32, ph: f32) -> f32 {
  let R = (w * w + ph * ph) / (2.0 * w);
  let c = R - w;
  let dxy = abs(q - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let arcs = max(length(q - vec2f(-c, h)) - R, length(q - vec2f(c, h)) - R);
  let top = max(arcs, h - q.y);
  return min(rect, top);
}

// Gothic lancet arch opening in 3D — subtract from a wall. Base center origin,
// half-width w, straight height h, point rises ph above h, half-depth d in z
fn mod_w3_lancet(p: vec3f, w: f32, h: f32, ph: f32, d: f32) -> f32 {
  let d2 = mod_w3_lancet2(p.xy, w, h, ph);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// ── domain ops ─────────────────────────────────────────────────────────────
fn mod_w3_rotX(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}
fn mod_w3_rotY(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}
fn mod_w3_rotZ(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}
// infinite repetition on chosen axes (c = cell size per axis; 0 = no repeat)
fn mod_w3_repeat(p: vec3f, c: vec3f) -> vec3f {
  var q = p;
  if (c.x > 0.0) { q.x = (fract(p.x / c.x + 0.5) - 0.5) * c.x; }
  if (c.y > 0.0) { q.y = (fract(p.y / c.y + 0.5) - 0.5) * c.y; }
  if (c.z > 0.0) { q.z = (fract(p.z / c.z + 0.5) - 0.5) * c.z; }
  return q;
}
// polar repetition around Y: n copies; returns p in the first wedge
fn mod_w3_polar(p: vec3f, n: f32) -> vec3f {
  let ang = 6.2831853 / n;
  let a = atan2(p.z, p.x);
  let r = length(p.xz);
  let a2 = (fract(a / ang + 0.5) - 0.5) * ang;
  return vec3f(cos(a2) * r, p.y, sin(a2) * r);
}

// ── the marcher family (all call YOUR w3_map) ──────────────────────────────
// sphere-trace: returns (t, material) on hit, (-1, -1) on miss
fn mod_w3_march(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32, steps: i32) -> vec2f {
  var t = tmin;
  for (var i = 0; i < 256; i++) {
    if (i >= steps) { break; }
    let dm = w3_map(ro + rd * t);
    if (dm.x < 0.001 * t + 0.003) { return vec2f(t, dm.y); }
    t = t + max(dm.x * 0.9, 0.004);
    if (t > tmax) { break; }
  }
  return vec2f(-1.0, -1.0);
}

// tetrahedral 4-tap normal
fn mod_w3_nrm(p: vec3f, eps: f32) -> vec3f {
  let k = vec2f(1.0, -1.0);
  return normalize(
    k.xyy * w3_map(p + k.xyy * eps).x +
    k.yyx * w3_map(p + k.yyx * eps).x +
    k.yxy * w3_map(p + k.yxy * eps).x +
    k.xxx * w3_map(p + k.xxx * eps).x);
}

// soft shadow toward a light: k = penumbra hardness (8 soft … 32 crisp)
fn mod_w3_shadow(p: vec3f, ld: vec3f, tmax: f32, k: f32) -> f32 {
  var t = 0.03;
  var sh = 1.0;
  for (var i = 0; i < 24; i++) {
    let d = w3_map(p + ld * t).x;
    sh = min(sh, k * d / t);
    t = t + clamp(d, 0.02, 0.8);
    if (sh < 0.02 || t > tmax) { break; }
  }
  return clamp(sh, 0.0, 1.0);
}

// 4-tap ambient occlusion along the normal
fn mod_w3_ao(p: vec3f, n: vec3f) -> f32 {
  var occ = 0.0;
  var w = 1.0;
  for (var i = 1; i <= 4; i++) {
    let h = 0.04 * f32(i * i);
    occ = occ + w * (h - w3_map(p + n * h).x);
    w = w * 0.65;
  }
  return clamp(1.0 - 2.2 * occ, 0.0, 1.0);
}

// ── shading ────────────────────────────────────────────────────────────────
fn mod_w3_fresnel(n: vec3f, rd: vec3f, f0: f32) -> f32 {
  return f0 + (1.0 - f0) * pow(1.0 - clamp(dot(n, -rd), 0.0, 1.0), 5.0);
}

// the standard rig: sun key + sky fill + bounce, shadow and AO applied where
// each belongs (shadow kills the key, AO dims the fill), plus a spec lobe
fn mod_w3_light(alb: vec3f, n: vec3f, rd: vec3f, sunDir: vec3f, sunCol: vec3f, skyCol: vec3f, sh: f32, ao: f32) -> vec3f {
  let dif = clamp(dot(n, sunDir), 0.0, 1.0);
  let sky = 0.5 + 0.5 * n.y;
  let bou = clamp(-n.y, 0.0, 1.0) * 0.3;
  var c = alb * (sunCol * dif * sh + skyCol * sky * ao + skyCol * bou * ao);
  let hal = normalize(sunDir - rd);
  let spe = pow(clamp(dot(n, hal), 0.0, 1.0), 32.0) * dif * sh;
  c = c + sunCol * spe * 0.5 * mod_w3_fresnel(n, rd, 0.04);
  return c;
}

// aerial perspective: fold a hit color into the sky with distance
fn mod_w3_fog(c: vec3f, skyC: vec3f, t: f32, density: f32) -> vec3f {
  return mix(c, skyC, 1.0 - exp(-t * t * density));
}

// ANIM3 — articulated-chain animation kit (canonical copy).
// The layer between skel-lib (creature rigs) and world3 (raymarched space):
// two-bone IK, tapered limb SDFs, gait oscillators with planted feet, pose
// paths, and aim frames — everything needed to make a marched body MOVE well.
//
//   { "type": "define_module", "name": "anim3", "wgsl": <this file> }
//
// Design: everything is STATELESS — pure functions of time and parameters, so
// they run per-pixel in a visual with no CPU sync. Drive the inputs (targets,
// phases, headings) from a step hook via the whiteboard or the population
// buffer; the shader poses the body.
//
// The crowd pattern: hook publishes gpuPopulation entries [x, y, heading, phase]
// → the visual loops pop(i), builds each body in its local frame with
// mod_a3_gait(phase …) driving the legs. 4095 walkers, one dispatch.

// ── two-bone IK ────────────────────────────────────────────────────────────
// Classic solver: a chain root→mid→tip with segment lengths l1, l2 reaching
// for `target`. Returns the MID joint (elbow/knee). `pole` bends the joint
// toward it (knee forward, elbow back) — give it a point, not a direction.
// Unreachable targets clamp to full extension; degenerate poles self-heal.
fn mod_a3_ik2(root: vec3f, tgt: vec3f, l1: f32, l2: f32, pole: vec3f) -> vec3f {
  var to = tgt - root;
  var d = length(to);
  let maxR = l1 + l2 - 0.0001;
  d = clamp(d, abs(l1 - l2) + 0.0001, maxR);
  let dir = to / max(length(to), 0.0001);
  // law of cosines: distance from root to the mid joint's projection
  let a = (l1 * l1 - l2 * l2 + d * d) / (2.0 * d);
  let h = sqrt(max(l1 * l1 - a * a, 0.0));
  // bend plane: contains the chain axis, leans toward the pole
  var side = pole - root - dir * dot(pole - root, dir);
  let sl = length(side);
  if (sl < 0.001) { side = vec3f(0.0, 0.0, 1.0) - dir * dir.z; } else { side = side / sl; }
  return root + dir * a + normalize(side) * h;
}

// ── limb geometry ──────────────────────────────────────────────────────────
// tapered capsule: radius r0 at `a` → r1 at `b` (thigh→ankle, arm→wrist)
fn mod_a3_bone(p: vec3f, a: vec3f, b: vec3f, r0: f32, r1: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r0, r1, h);
}
// joint ball — drop one at every hinge to keep silhouettes smooth
fn mod_a3_joint(p: vec3f, at: vec3f, r: f32) -> f32 { return length(p - at) - r; }

// ── gait ───────────────────────────────────────────────────────────────────
// The planted-foot law (lifted from skel-lib's ladder): phase advances in
// STRIDE CYCLES (hook: ph += speed / strideLen * dt). Within one cycle a foot
// is planted for `duty` (moving backward at exactly body speed → zero world
// velocity) and swings forward for the rest, lifted on a sine arc.
// Returns (alongOffset, lift): foot position relative to its rest point,
// in units of strideLen.
fn mod_a3_gait(phase: f32, duty: f32) -> vec2f {
  let c = fract(phase);
  if (c < duty) {
    // stance: linear back-travel, no lift — the foot OWNS the ground
    let s = c / duty;
    return vec2f(0.5 - s, 0.0);
  }
  // swing: forward and up
  let s = (c - duty) / (1.0 - duty);
  return vec2f(-0.5 + s, sin(s * 3.14159) * 1.0);
}
// eased oscillator for secondary motion (tails, breathing, sway):
// sin with adjustable sharpness — sharp > 1 dwells at the extremes
fn mod_a3_sway(t: f32, freq: f32, sharp: f32) -> f32 {
  let s = sin(t * freq);
  return sign(s) * pow(abs(s), 1.0 / max(sharp, 0.001));
}

// ── pose paths ─────────────────────────────────────────────────────────────
// blend two joint positions (a pose is just a set of points — lerp each)
fn mod_a3_mix(a: vec3f, b: vec3f, t: f32) -> vec3f { return mix(a, b, smoothstep(0.0, 1.0, t)); }
// quadratic bezier through a lifted midpoint — a reach, a leap, a nod
fn mod_a3_arc(a: vec3f, peak: vec3f, b: vec3f, t: f32) -> vec3f {
  let u = 1.0 - t;
  return a * u * u + peak * 2.0 * u * t + b * t * t;
}

// ── aim frames ─────────────────────────────────────────────────────────────
// build a basis aimed along `fw` (head look-at, torso facing); transform a
// local point into it. worldUp guards collinearity.
fn mod_a3_aim(local: vec3f, origin: vec3f, fw0: vec3f) -> vec3f {
  let fw = normalize(fw0);
  var up = vec3f(0.0, 1.0, 0.0);
  if (abs(dot(fw, up)) > 0.99) { up = vec3f(0.0, 0.0, 1.0); }
  let rt = normalize(cross(up, fw));
  let u2 = cross(fw, rt);
  return origin + rt * local.x + u2 * local.y + fw * local.z;
}

// ── a whole walker, as the pattern to copy ─────────────────────────────────
// Biped legs in one call: body at `hips` heading +z in its local frame,
// phase in stride cycles, stride length L. Returns the SDF of both legs.
// (Offset the two feet half a cycle; IK bends knees toward the pole.)
fn mod_a3_legs(p: vec3f, hips: vec3f, phase: f32, L: f32, legLen: f32, r: f32) -> f32 {
  var d = 1e9;
  for (var s = 0; s < 2; s++) {
    let side = select(-1.0, 1.0, s == 1);
    let g = mod_a3_gait(phase + select(0.0, 0.5, s == 1), 0.55);
    let hip = hips + vec3f(side * legLen * 0.22, 0.0, 0.0);
    let foot = vec3f(hip.x, g.y * legLen * 0.22, g.x * L);
    let knee = mod_a3_ik2(hip, foot, legLen * 0.52, legLen * 0.52, hip + vec3f(0.0, 0.0, legLen));
    d = min(d, mod_a3_bone(p, hip, knee, r, r * 0.75));
    d = min(d, mod_a3_bone(p, knee, foot, r * 0.75, r * 0.5));
    d = min(d, mod_a3_joint(p, knee, r * 0.85));
  }
  return d;
}

// VEILFIRE · rooms.wgsl — the load-bearing scene SDF (vf-rooms node).
// EXPORT: fn w3_map(p: vec3f) -> vec2f  = (signed distance, material id).
//
// A WALKABLE Antichamber-style Gothic interior, carved SUBTRACTIVELY out of a
// solid rock block so rooms connect by construction (no coordinate seams):
//   d = solidBlock;  d = max(d, -naveAir);  d = max(d, -sideAir);  d = max(d, -door);
// then solids (columns, dais) are UNIONed back in with min(). Positive in open
// air, 0 at surfaces, negative inside rock — raymarchable from inside.
//
// ── ROOM EXTENTS (world units, y=0 is the floor) — movement/vf-* MIRROR THIS ──
//   NAVE (main hall):  x∈[-4, 4]   y∈[0, 9]   z∈[-9, 9]     (tall)
//   SIDE CHAMBER:      x∈[ 5,11]   y∈[0, 5]   z∈[-3.5, 3.5] (lower ceiling)
//   DIVIDING WALL:     x∈[ 4, 5]  (1 thick) — solid except the doorway
//   DOORWAY (lancet):  center x≈4.5, z=0, base y=0; opening z∈[-1.5,1.5],
//                      height y∈[0, 3.7] (straight to 2.5, point to 3.7),
//                      depth x∈[3.3, 5.7] (cuts the whole dividing wall)
//   COLONNADE:         two rows at x=±3.2, columns every 4 in z (z=0,±4,±8),
//                      r=0.4, floor→near ceiling (y∈[-0.5, 8.5])
//   DAIS (verticality, far +z end of nave):
//      step1: x∈[-3.5,3.5] y∈[0,1]   z∈[6,9]   (low platform)
//      step2: x∈[-3.5,3.5] y∈[0,2]   z∈[7.8,9.2] (upper ledge)
//   Suggested spawn: (0, 1.6, 0) facing +x toward the doorway, or -z down nave.
//
// MATERIAL IDS: 1 wall · 2 floor/dais · 3 column · 4 doorway/arch trim.
// Cheap: a handful of box/cyl/lancet evals, one z-repeat, no loops.

fn w3_map(p: vec3f) -> vec2f {
  // --- solid rock; carve the rooms out of it (block extended +x to x=18 for the escape hall) ---
  let d0 = mod_w3_box(p - vec3f(6.5, 4.5, 0.0), vec3f(11.5, 5.5, 10.0));
  let nave = mod_w3_box(p - vec3f(0.0, 4.5, 0.0), vec3f(4.0, 4.5, 9.0));
  let side = mod_w3_box(p - vec3f(8.0, 2.5, 0.0), vec3f(3.0, 2.5, 3.5));
  // ESCAPE HALL: a low, narrow corridor off the side chamber's far wall (x∈[11,18], z∈[-1,1]).
  let hall = mod_w3_box(p - vec3f(14.5, 1.2, 0.0), vec3f(3.5, 1.2, 1.0));

  // doorway: lancet arch, profile in (z,y), depth along x through the wall
  let qd = vec3f(p.z, p.y, p.x - 4.5);
  let door = mod_w3_lancet(qd, 1.5, 2.5, 1.2, 1.2);

  var d = d0;
  d = max(d, -nave);
  d = max(d, -side);
  d = max(d, -hall);
  d = max(d, -door);

  // shell material: floor low, doorway trim near the arch cut, else wall
  var mat = 1.0;
  if (p.y < 0.3) { mat = 2.0; }
  if (door < 0.35 && p.y < 3.9) { mat = 4.0; }

  // --- solids unioned back in ---
  // colonnade: mirrored rows at x=±3.2, repeated every 4 units in z
  let cz = (fract(p.z / 4.0 + 0.5) - 0.5) * 4.0;
  let colp = vec3f(abs(p.x) - 3.2, p.y - 4.0, cz);
  let col = mod_w3_cyl(colp, 4.5, 0.4);
  if (col < d) { d = col; mat = 3.0; }

  // dais / altar steps at the far +z end (verticality)
  let step1 = mod_w3_box(p - vec3f(0.0, 0.5, 7.5), vec3f(3.5, 0.5, 1.5));
  if (step1 < d) { d = step1; mat = 2.0; }
  let step2 = mod_w3_box(p - vec3f(0.0, 1.0, 8.5), vec3f(3.5, 1.0, 0.7));
  if (step2 < d) { d = step2; mat = 2.0; }

  return vec2f(d, mat);
}

// VEILFIRE — DEMONS. A gaunt, hunched, horned humanoid that WALKS.
// Built entirely from anim3-lib tapered-capsule bones + world3 struts so it reads
// as a silhouette at the edge of lantern light. Legs are driven by the planted-foot
// gait (mod_a3_gait(phase, 0.55)); arms counter-swing; head carries swept horns and
// a jutting snarl. Distance only — the integrator paints material / ember-crust.
//
//   { "type": "define_module", "name": "veilfire_demons", "wgsl": <this file> }
//
// EXPORT:  fn vf_demon(p: vec3f, phase: f32) -> f32
//   p     : local body space (heading +z, feet near y=0, center at origin)
//   phase : stride-cycle phase (fract cycles). Same phase feeds the population's
//           animPhase slot (pop(2i+1).y).
// Depends on world3-lib (mod_w3_taperStrut) + anim3-lib (bone/joint/gait/ik2/legs).

// fleshy smooth-union — organic joints without gaps; k small = tight seam
fn vf_smin(a: f32, b: f32, k: f32) -> f32 {
  let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

fn vf_demon(p: vec3f, phase: f32) -> f32 {
  let hipY = 0.88;      // hip height — feet reach y≈0
  let L = 0.5;          // stride length
  let legLen = 0.95;    // thigh+shin reach

  // ── legs: planted-foot gait, gaunt shins ─────────────────────────────────
  var d = mod_a3_legs(p, vec3f(0.0, hipY, 0.0), phase, L, legLen, 0.075);

  // subtle breathing / menace sway of the upper body
  let breathe = sin(phase * 6.2831853) * 0.02;

  // ── spine (hunched forward) + head + snarling jaw ────────────────────────
  let pelvis = vec3f(0.0, hipY, 0.0);
  let chest  = vec3f(0.0, hipY + 0.42, 0.10);
  let neck   = vec3f(0.0, hipY + 0.60, 0.16);
  let headC  = vec3f(0.0, hipY + 0.76, 0.20 + breathe);

  var body = mod_a3_bone(p, pelvis, chest, 0.11, 0.15);                 // gaunt ribcage
  body = vf_smin(body, mod_a3_bone(p, chest, neck, 0.13, 0.06), 0.08);  // taper to neck
  body = vf_smin(body, mod_a3_joint(p, headC, 0.14), 0.06);            // skull
  body = vf_smin(body,                                                  // jutting snarl
    mod_a3_bone(p, headC + vec3f(0.0, -0.02, 0.05), headC + vec3f(0.0, -0.06, 0.16), 0.09, 0.03), 0.05);
  d = min(d, body);

  // ── horns: swept up and back, crisp edges ────────────────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    let hb = headC + vec3f(sx * 0.08, 0.08, -0.02);
    let ht = headC + vec3f(sx * 0.16, 0.30, -0.18);
    d = min(d, mod_w3_taperStrut(p, hb, ht, 0.035, 0.004));
  }

  // ── arms: long, clawed, counter-swinging to the legs ─────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    // opposite phase offset to the same-side leg → natural counter-swing
    let g = mod_a3_gait(phase + select(0.5, 0.0, s == 1), 0.55);
    let shoulder = vec3f(sx * 0.20, hipY + 0.48, 0.06);
    let hand = vec3f(sx * 0.17, hipY - 0.32, 0.16 - g.x * 0.55);        // reach to mid-thigh
    let pole = shoulder + vec3f(sx * 0.35, -0.1, -0.35);               // elbow back/out
    let elbow = mod_a3_ik2(shoulder, hand, 0.44, 0.46, pole);
    var arm = mod_a3_bone(p, shoulder, elbow, 0.06, 0.045);
    arm = min(arm, mod_a3_bone(p, elbow, hand, 0.045, 0.028));
    arm = min(arm, mod_a3_joint(p, elbow, 0.05));
    // three splayed talons
    for (var c = 0; c < 3; c++) {
      let ca = (f32(c) - 1.0) * 0.12;
      let tip = hand + vec3f(sx * 0.03 + ca * 0.05, -0.14, 0.06 + ca * 0.02);
      arm = min(arm, mod_w3_taperStrut(p, hand, tip, 0.022, 0.002));
    }
    d = vf_smin(d, arm, 0.04);
  }

  // ── HORROR PASS (v2) — detail the ember-shading catches at the light's edge ──
  // ribcage: thin bones across the hunched chest → skeletal, ember-cracked
  for (var r = 0; r < 4; r++) {
    let ry = hipY + 0.13 + f32(r) * 0.085;
    let rz = 0.04 + f32(r) * 0.012;
    d = min(d, mod_a3_bone(p, vec3f(-0.115, ry, rz), vec3f(0.115, ry, rz), 0.012, 0.012));
  }
  // a sternum ridge down the ribs
  d = min(d, mod_a3_bone(p, vec3f(0.0, hipY + 0.10, 0.05), vec3f(0.0, hipY + 0.42, 0.09), 0.016, 0.010));
  // sunken eye sockets + a gaping maw carved from the skull (dark hollows read as a face)
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(-0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f( 0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(0.0, -0.055, 0.15)), 0.050));

  return d;
}

// enemies (node: enemies) — shared enemy shading helper. The enemy BODY draw is
// routed through veilfire/demons.wgsl's vf_demon inside renderer-mega; this holds
// the damage-flash tint the renderer can blend by hp so hurt demons read hot.
fn s3_enemyTint(hp01: f32) -> vec3f {
  return mix(vec3f(1.0, 0.28, 0.16), vec3f(0.11, 0.05, 0.045), clamp(hp01, 0.0, 1.0));
}

// shooter3 / projectiles — thin glowing energy bolts (tracers)
// Cheap capsule SDF + emissive HDR color the renderer adds on hit-glow.
// Exports:
//   s3_tracer(p, a, b)            -> f32   thin bolt from a to b (radius ~0.06)
//   s3_tracerColor(kind, life01)  -> vec3f linear HDR emissive (3=player, 4=enemy)

// A thin glowing bolt: a capsule from a to b. Cheap — one clamp/dot/length.
fn s3_tracer(p: vec3f, a: vec3f, b: vec3f) -> f32 {
  return mod_w3_capsule(p, a, b, 0.06);
}

// Emissive HDR color the renderer adds. Brightest when freshly fired (life01~1),
// fading toward death (life01~0). kind 3 = player (hot cyan-white), 4 = enemy (sick green).
fn s3_tracerColor(kind: f32, life01: f32) -> vec3f {
  let l = clamp(life01, 0.0, 1.0);
  // hot core (near-white at spawn) blended toward the tinted tail as it ages
  let playerHot  = vec3f(0.55, 1.0, 1.0);   // cyan
  let playerCore = vec3f(1.0, 1.0, 1.0);    // white-hot
  let enemyHot   = vec3f(0.35, 1.0, 0.15);  // sick green
  let enemyCore  = vec3f(0.85, 1.0, 0.6);   // pale green-white
  let isEnemy = step(3.5, kind);            // 0 for kind<=3, 1 for kind>=4
  let hot  = mix(playerHot, enemyHot, isEnemy);
  let core = mix(playerCore, enemyCore, isEnemy);
  // core dominates when fresh; tint takes over as it fades
  let tint = mix(hot, core, l);
  // HDR emission: strong when fresh, glowing dim tail when old
  let energy = mix(1.2, 9.0, l * l);
  return tint * energy;
}

// VEILFIRE — atmosphere. Dread mood layered over a plainly-lit color.
//   vf_atmos(c, pos, rd, t, time):
//     c    = lit color at the hit (linear HDR)
//     pos  = hit point in world space
//     rd   = ray direction (unit)
//     t    = hit distance (fog falloff)
//     time = seconds
//   returns the color, dread-soaked. Output stays LINEAR HDR — no tonemap here.
//
// Four cheap layers, in order:
//   1. cool desaturation with a warm firelight bias (drain life, keep the fire)
//   2. torch flicker — layered sin-noise multiplying the whole scene
//   3. depth fog toward near-black cold murk (dread deepens it)
//   4. faint drifting ember specks low in the frame
//
// Mood dials read from the whiteboard (see SPEC): uni(12)=dread01, uni(18)=fogDensity.
// Both degrade gracefully to sane defaults when unset (zero).

fn vf_hash11(n: f32) -> f32 { return fract(sin(n * 43758.5453) * 12345.6789); }

fn vf_atmos(c: vec3f, pos: vec3f, rd: vec3f, t: f32, time: f32) -> vec3f {
  var col = c;

  let dread = clamp(uni(12), 0.0, 1.0);
  let fogD  = max(uni(18), 0.0);

  // ── 1. cool desaturation + warm firelight bias ─────────────────────────────
  // Drain saturation toward grey (harder the more dread), then re-tint: warm
  // ember in the lit/bright regions, cold blue in the shadows.
  let lum   = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  let desat = mix(col, vec3f(lum), 0.42 + 0.28 * dread);
  let warm  = vec3f(1.18, 0.60, 0.28);
  let cool  = vec3f(0.52, 0.66, 0.96);
  let tint  = mix(cool, warm, clamp(lum * 1.6, 0.0, 1.0));
  col = desat * tint;

  // ── 2. torch flicker — layered sin-noise, multiplies everything ────────────
  let f1 = sin(time * 11.0) * 0.5 + sin(time * 17.3 + 1.7) * 0.3 + sin(time * 29.0) * 0.2;
  let f2 = sin(time * 3.1 + 0.5);
  let flick = 1.0 + 0.06 * f1 + 0.03 * f2;   // roughly ±9% breathing
  col = col * flick;

  // ── 3. depth fog — a LIFTED cold haze (KINDLE murk). Fog toward near-black is
  // invisible in a dark room; a lifted blue-grey veils distance so the air reads
  // thick. Two bands: a near haze that lifts shadows + a far murk that swallows.
  let density = fogD + 0.010 + 0.012 * dread;
  let fogAmt  = 1.0 - exp(-t * t * density);
  let haze    = vec3f(0.055, 0.072, 0.110);       // cold blue-grey — the visible fog
  col = mix(col, haze, fogAmt);
  col = col + haze * 0.35 * fogAmt;                // scatter lift so it glows, not just dims

  // ── 4. drifting ember specks, low in the frame ─────────────────────────────
  // Parameterize by ray direction so motes float in view; drift upward in time.
  let ep = vec2f(rd.x * 6.0, rd.y * 6.0 - time * 0.35);
  var ember = 0.0;
  for (var k = 0; k < 3; k = k + 1) {
    let sc   = 1.0 + f32(k) * 1.7;
    let g    = ep * sc + vec2f(f32(k) * 13.7, f32(k) * 7.3);
    let cell = floor(g);
    let fr   = fract(g) - 0.5;
    let h    = vf_hash11(cell.x * 57.0 + cell.y * 131.0 + f32(k) * 3.0);
    let on   = step(0.92, h);                 // only a few cells host an ember
    let jit  = vec2f(vf_hash11(h * 21.0) - 0.5, vf_hash11(h * 47.0) - 0.5) * 0.6;
    let d    = length(fr - jit);
    let mote = on * smoothstep(0.09, 0.0, d);
    let tw   = 0.5 + 0.5 * sin(time * (4.0 + h * 6.0) + h * 30.0);  // twinkle
    ember = ember + mote * tw;
  }
  // Sit near the low end (bottom of view) and glow warmer through the murk.
  let lowBias  = smoothstep(0.30, -0.45, rd.y);
  let emberCol = vec3f(1.30, 0.52, 0.16);
  col = col + emberCol * ember * lowBias * (0.35 + 0.55 * fogAmt);

  return col;
}

// shooter3 HUD — screen-space overlay for the horror-shooter. No raymarch.
// Exports s3_hud(uv, hp01, ammo, score, dread01) -> vec4f (rgb, alpha); alpha 0
// where nothing is drawn so the integrator can composite it over the world.
//
// uv arrives -1..1 with y DOWN — the engine convention (uv.y=-1 top, +1 bottom;
// see render-core "MATCH THE ENGINE … uv.y increases DOWNWARD"). That already
// matches char5x7 / printInt (p in [0,1]², y DOWN), so s = uv*0.5+0.5 with no
// flip renders glyphs upright. Palette is thin, cold-white ink
// over near-black, with a rising red dread wash so the frame turns ominous as
// dread01 → 1. Legible on black; restrained on a lit scene.

// ── glyph cell helpers (screen coords s: 0..1, y DOWN) ────────────────────
// draw one glyph inside a box; returns coverage 0..1
fn s3_boxChar(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, code: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return char5x7(p, code);
}
// draw a right-aligned integer inside a box
fn s3_boxInt(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, value: f32, digits: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return printInt(p, value, digits);
}
// one glyph within a monospace run: start x0, cell width cw, index j (0.8 fill)
fn s3_cellChar(s: vec2f, x0: f32, cw: f32, y0: f32, y1: f32, j: i32, code: i32) -> f32 {
  let cx0 = x0 + f32(j) * cw;
  return s3_boxChar(s, cx0, cx0 + cw * 0.82, y0, y1, code);
}

fn s3_hud(uv: vec2f, hp01: f32, ammo: f32, score: f32, dread01: f32) -> vec4f {
  // screen coords, top-left origin, y DOWN — matches the glyph font + engine.
  let s = vec2f(uv.x * 0.5 + 0.5, uv.y * 0.5 + 0.5);
  let hp = clamp(hp01, 0.0, 1.0);
  let dr = clamp(dread01, 0.0, 1.0);

  var col = vec3f(0.0);
  var a = 0.0;

  // ── dread wash: a red vignette that swells from the corners with dread01 ──
  // (built in uv space so it is symmetric regardless of the glyph y-flip)
  {
    let edge = smoothstep(0.55, 1.25, length(uv));   // 0 centre → 1 corners
    // a slow, uneasy pulse so high dread never sits perfectly still
    let breath = 0.82 + 0.18 * sin(uni(0) * 2.1);
    let vig = edge * dr * breath;
    col = vec3f(0.42, 0.02, 0.015) * vig;
    a = vig * 0.65;
  }

  // ── HEALTH BAR — bottom-left, red→green by hp01, dark empty track, frame ──
  {
    let x0 = 0.035; let x1 = 0.315; let y0 = 0.905; let y1 = 0.940;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let bt = 0.0035;                                          // border thickness
      let border = s.x < x0 + bt || s.x > x1 - bt || s.y < y0 + bt || s.y > y1 - bt;
      let fillX = x0 + (x1 - x0) * hp;
      if (border) {
        col = vec3f(0.55, 0.56, 0.62); a = 0.85;
      } else if (s.x <= fillX) {
        // red at 0 → amber mid → green at full; scale value so low HP reads hot
        let hc = mix(vec3f(0.95, 0.09, 0.06), vec3f(0.16, 0.92, 0.26), smoothstep(0.0, 1.0, hp));
        col = hc * (0.85 + 0.15 * hp); a = 0.92;
      } else {
        col = vec3f(0.05, 0.02, 0.02); a = 0.55;                // depleted track
      }
    }
    // "HP" label just above the bar
    let ly0 = 0.868; let ly1 = 0.898;
    let lc = max(s3_cellChar(s, 0.035, 0.024, ly0, ly1, 0, 72),   // H
                 s3_cellChar(s, 0.035, 0.024, ly0, ly1, 1, 80));  // P
    if (lc > 0.0) { col = vec3f(0.72, 0.74, 0.80); a = lc * 0.9; }
  }

  // ── AMMO — bottom-right, printInt (3 digits), with a small label ──
  {
    let x0 = 0.80; let x1 = 0.965; let y0 = 0.905; let y1 = 0.945;
    let cov = s3_boxInt(s, x0, x1, y0, y1, ammo, 3);
    if (cov > 0.0) { col = vec3f(0.86, 0.88, 0.94); a = cov * 0.95; }
    // "AMMO" label above the count
    let ly0 = 0.868; let ly1 = 0.898;
    let lx0 = 0.80; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 65);   // A
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 79)); // O
    if (lab > 0.0) { col = vec3f(0.66, 0.68, 0.74); a = lab * 0.85; }
  }

  // ── SCORE — top-right, printInt (6 digits), with a label ──
  {
    let x0 = 0.74; let x1 = 0.965; let y0 = 0.070; let y1 = 0.110;
    let cov = s3_boxInt(s, x0, x1, y0, y1, score, 6);
    if (cov > 0.0) { col = vec3f(0.90, 0.90, 0.95); a = cov * 0.95; }
    // "SCORE" label above the number
    let ly0 = 0.032; let ly1 = 0.062;
    let lx0 = 0.74; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 83);   // S
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 67)); // C
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 79)); // O
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 82)); // R
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 4, 69)); // E
    if (lab > 0.0) { col = vec3f(0.62, 0.63, 0.70); a = lab * 0.82; }
  }

  // ── DREAD METER — thin vertical bar, right edge, fills bottom→top ──
  {
    let x0 = 0.972; let x1 = 0.990; let y0 = 0.32; let y1 = 0.90;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let fillTop = y1 - (y1 - y0) * dr;                 // fills upward with dread
      if (s.y >= fillTop) {
        let up = (y1 - s.y) / (y1 - y0);                 // 0 bottom → 1 top of bar
        let hot = mix(vec3f(0.55, 0.05, 0.04), vec3f(1.0, 0.28, 0.12), up);
        col = hot; a = 0.9;
      } else {
        col = vec3f(0.06, 0.02, 0.02); a = 0.5;          // empty channel
      }
    }
  }

  // ── CROSSHAIR — thin center cross with a gap, cold-white, reddens w/ dread ──
  {
    let ax = abs(uv.x); let ay = abs(uv.y);
    let th = 0.0038;
    let inR = 0.013; let outR = 0.050;
    let horiz = ay < th && ax > inR && ax < outR;
    let vert  = ax < th && ay > inR && ay < outR;
    let dot   = length(uv) < 0.0028;
    if (horiz || vert || dot) {
      col = mix(vec3f(0.92, 0.95, 1.0), vec3f(1.0, 0.18, 0.12), dr);
      a = 0.9;
    }
  }

  return vec4f(col, clamp(a, 0.0, 1.0));
}

stepHooks.code:
function pz_blocked(x, z) {
  const cr = 0.8;
  for (const cx of [-3.2, 3.2]) { for (const cz of [-8, -4, 0, 4, 8]) {
    if ((x - cx) * (x - cx) + (z - cz) * (z - cz) < cr * cr) return true;
  } } return false;
}
function pz_walkable(x, z) {
  const R = 0.4;
  const nave = x >= -4 + R && x <= 4 - R && z >= -9 + R && z <= 9 - R;
  const side = x >= 5 + R && x <= 11 - R && z >= -3.5 + R && z <= 3.5 - R;
  const door = x >= 3.3 && x <= 5.7 && z >= -1.5 + R && z <= 1.5 - R;
  const hall = x >= 11 - R && x <= 18 - R && z >= -1 + R && z <= 1 - R;   // the escape corridor
  return (nave || side || door || hall) && !pz_blocked(x, z);
}
try {
  const wd = sim.worldData
  if (!wd.__vf) wd.__vf = {}
  const V = wd.__vf
  const sdt = Math.min(dt, 1 / 30)
  V.t = (V.t || 0) + sdt
  const u = Array.isArray(wd.gpuUniforms) ? wd.gpuUniforms : new Array(256).fill(0)
  while (u.length < 256) u.push(0)
  const inp = wd.input || {}
  const ptr = inp.pointer || {}

  // spawn in the side room, facing the far wall (the hallway is +x across the room)
  if (V.mv !== 4) {
    V.px = 6.0; V.py = 1.7; V.pz = -2.6; V.yaw = 1.5708; V.pitch = -0.12
    V.vy = 0; V.ground = 1; V.lx = null; V.ly = null; V.mv = 4
    V.dlt = [0.0, 2.0944, 4.1888]; V.trap = null; V.win = 0; V.firePrev = false
    V.hp = 1.0; V.grab = null; V.biteT = 0; V.flash = 0; V.hyaw = 1.5708
  }

  // ── the two law CELLS come from selectable fields; the click-throttle overrides ──
  const RULES = { hue: 1, wave: 2, invert: 3, posterize: 4, slow: 5, fast: 6 }
  const readZone = (name, dz, dRule, dR) => {
    let lx = 0.0, lz = dz, rule = dRule, r = dR
    const f = (sim.fields && sim.fields.getFieldByName) ? sim.fields.getFieldByName(name) : null
    if (f && f.transform) {
      lx = (f.transform.x - 256) / 256 * 3.0
      lz = (f.transform.y - 256) / 256 * 3.2
      const p = f.properties || {}; const rv = p.rule
      if (typeof rv === 'string' && RULES[rv] != null) rule = RULES[rv]
      else if (typeof rv === 'number') rule = rv
      if (typeof p.radius === 'number') r = p.radius
    }
    return { lx, lz, rule, r }
  }
  const zA = readZone('Cell A',  1.7, RULES.wave, 1.7)   // upper lane (neutral until throttled)
  const zB = readZone('Cell B', -1.7, RULES.hue,  1.7)   // lower lane (neutral until throttled)
  if (V.trap === 'A') { zA.rule = RULES.slow; zB.rule = RULES.fast }
  else if (V.trap === 'B') { zB.rule = RULES.slow; zA.rule = RULES.fast }
  u[31] = zA.lx; u[32] = zA.lz; u[33] = zA.rule; u[34] = zA.r
  u[35] = zB.lx; u[36] = zB.lz; u[37] = zB.rule; u[38] = zB.r
  V.rzf = ((V.rzf || 0) + 1) % 360; u[30] = V.rzf

  const factorAt = (x, z) => {
    const qx = x - 8.0, qz = z; let f = 1.0
    if (zA.r > 0.01 && Math.hypot(qx - zA.lx, qz - zA.lz) < zA.r) { f *= (zA.rule === 5 ? 0.18 : zA.rule === 6 ? 2.2 : 1.0) }
    if (zB.r > 0.01 && Math.hypot(qx - zB.lx, qz - zB.lz) < zB.r) { f *= (zB.rule === 5 ? 0.18 : zB.rule === 6 ? 2.2 : 1.0) }
    return f
  }

  // ── PLAYER — a body in the field: your step is scaled by the cell underfoot ──
  const pf = factorAt(V.px, V.pz)
  const step = sdt * pf
  if (V.lx == null) { V.lx = ptr.x != null ? ptr.x : 256; V.ly = ptr.y != null ? ptr.y : 256 }
  const mx = ptr.x != null ? ptr.x : V.lx, my = ptr.y != null ? ptr.y : V.ly
  const absS = 0.006, relS = 0.0052
  V.yaw -= (mx - V.lx) * absS + (inp.lookX || 0) * relS
  V.pitch = Math.max(-1.2, Math.min(1.2, V.pitch - ((my - V.ly) * absS + (inp.lookY || 0) * relS)))
  V.lx = mx; V.ly = my
  const fx = Math.sin(V.yaw), fz = Math.cos(V.yaw)
  const rx = -Math.cos(V.yaw), rz = Math.sin(V.yaw)
  // MOVE is locked once a demon has you (you can still look, helplessly). Otherwise walk.
  if (!V.grab) {
    const spd = 5.5, mF = inp.moveY || 0, mS = inp.moveX || 0
    const wdx = fx * mF + rx * mS, wdz = fz * mF + rz * mS
    const dx = wdx * spd * step, dz = wdz * spd * step
    let nx = V.px, nz = V.pz
    if (pz_walkable(V.px + dx, V.pz)) nx = V.px + dx
    if (pz_walkable(nx, V.pz + dz)) nz = V.pz + dz
    V.px = nx; V.pz = nz
    if (mF || mS) V.hyaw = Math.atan2(wdx, wdz)   // the hero faces where it's skating
    if (inp.action && V.ground) { V.vy = 4.4; V.ground = 0 }
    V.vy -= 12.0 * step; V.py += V.vy * step
    if (V.py <= 1.7) { V.py = 1.7; V.vy = 0; V.ground = 1 }
  }

  const cp = Math.cos(V.pitch), sp = Math.sin(V.pitch)

  // ── THROTTLE: click sets the cell you're aiming at as the TRAP (slow); the other goes fast ──
  let aimX = V.px + fx * 3.0, aimZ = V.pz + fz * 3.0
  if (sp < -0.03) { const tt = V.py / (-sp); aimX = V.px + fx * cp * tt; aimZ = V.pz + fz * cp * tt }
  const dAaim = Math.hypot(aimX - 8.0, aimZ - zA.lz), dBaim = Math.hypot(aimX - 8.0, aimZ - zB.lz)
  const firing = !!(ptr && ptr.pressed)
  if (firing && !V.firePrev && !V.win && !V.grab) { V.trap = (dAaim < dBaim) ? 'A' : 'B' }
  V.firePrev = firing

  const pop = []
  if (V.grab) {
    // ── CAUGHT: the demon is latched to your vision, biting until you die. The
    // FIELD sets the tempo — in a fast cell it snaps and rips you quickly; in a
    // slow cell the whole thing is slow-motion but you are slowed too and cannot
    // pull away. Either way it rides your face down to nothing. ──
    const pf = factorAt(V.px, V.pz)
    const tempo = 0.35 + pf                                 // fast field bites/drains faster
    V.hp = (V.hp == null ? 1.0 : V.hp) - sdt * 0.30 * tempo
    V.biteT = (V.biteT || 0) + sdt * tempo
    if (V.biteT > 0.55) { V.biteT = 0; V.flash = 1.0 }      // a fresh bite
    V.flash = Math.max(0, (V.flash || 0) - sdt * 3.5)
    u[16] = V.flash                                          // red bite flash (hit-flash slot)
    // the demon CLUTCHING the hero: it surges onto the body on each bite, orbiting so
    // its limbs read against the hero from the third-person camera.
    const clutch = 0.30 + 0.22 * (0.5 + 0.5 * Math.sin(V.biteT * 11.4))
    const ga = (V.t || 0) * 0.7
    const gx = V.px + Math.sin(ga) * clutch, gz = V.pz + Math.cos(ga) * clutch
    const gyaw = Math.atan2(V.px - gx, V.pz - gz)            // lunge into the hero
    pop.push(gx, 0.0, gz, 1.0, 1.0, V.t * 9.0, gyaw, 1.0)    // atk flag set
    if (V.hp <= 0) {                                         // dead -> back to the start of the run
      V.grab = null; V.hp = 1.0; V.flash = 0; V.px = 6.0; V.pz = -2.6; V.trap = null
    }
  } else if (!V.win) {
    // ── DEMONS circulate between the two lanes; a slowed cell pins them. Step into
    //    a cell that holds a demon and it GRABS you. ──
    for (let i = 0; i < 3; i++) {
      const ph = i * 2.0944
      const lt = V.dlt[i]
      const x = 8.0 + 1.1 * Math.sin(lt * 0.5 + ph)
      const z = 1.7 * Math.sin(lt * 0.8 + ph)               // patrols upper(+1.7) <-> lower(-1.7)
      const bob = Math.abs(Math.sin(lt * 2.4 + ph)) * 0.08
      const yaw = Math.cos(lt * 0.8 + ph) >= 0 ? 0.0 : Math.PI
      const gait = lt * 1.6 + ph
      pop.push(x, bob, z, 1.0, 1.0, gait, yaw, 0.0)
      V.dlt[i] = lt + sdt * factorAt(x, z)
      if (Math.hypot(x - V.px, z - V.pz) < 0.95) { V.grab = { i }; V.biteT = 0.5; V.flash = 1.0 }  // it has you
    }
  }
  // ── THE NEON HERO — the player's body, rendered at the player position (flags=5
  //    marks it neon in the shader). Faces the skate direction; gait glides. ──
  pop.push(V.px, 0.0, V.pz, 1.0, 1.0, (V.t || 0) * 2.2, (V.hyaw != null ? V.hyaw : V.yaw), 5.0)
  V.pop = pop; wd.gpuPopulation = pop
  u[6] = (V.hp == null ? 1.0 : V.hp)                         // HP bar reflects the drain

  // ── WIN: reach the escape hall past the far wall ──
  if (!V.win && !V.grab && V.px > 11.4) V.win = 1

  // ── THIRD-PERSON camera: backed out behind the hero along the look direction.
  //    No wall-dodging clamp needed — the hero superimposes THROUGH walls, so even
  //    when the chamber is tight and a wall sits between camera and hero, you still
  //    see it. Height is capped just under the ceiling so the camera stays out of rock.
  const camDist = 3.8, camHt = 2.5
  u[240] = V.px - fx * camDist; u[241] = Math.min(V.py + camHt, 4.6); u[242] = V.pz - fz * camDist; u[243] = 1.2
  u[244] = V.px; u[245] = V.py + 0.3; u[246] = V.pz; u[247] = 0
  wd.gpuUniforms = u
} catch (e) {}

visualTypes.wgsl:
// shooter3 MEGASHADER (node: renderer-mega). ONE visual raymarches the world
// (w3_map from veilfire/rooms) and depth-composites the whole population in a
// single dispatch — demons (vf_demon), projectiles/death-bits (emissive) — then
// atmosphere (vf_atmos), muzzle/hit flashes, and the HUD (s3_hud) on top.
//
// Occlusion is correct + cheap: each entity is first rejected by a ray-vs-
// bounding-sphere test and by `t > worldT` (behind a wall), so only entities the
// ray actually pierces IN FRONT of the world get a local march. Camera on
// uni4(60/61). w3_map + vf_demon + s3_* + vf_atmos come from sibling modules.

// ray → sphere near-t (negative if no hit; may be <0 if camera inside)
fn s3_sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> f32 {
  let oc = ro - c;
  let b = dot(oc, rd);
  let h = b * b - (dot(oc, oc) - r * r);
  if (h < 0.0) { return -1.0; }
  return -b - sqrt(h);
}

// ── RULE ZONES (laws as per-pixel fields) ───────────────────────────────────
// Two radial zones on the side-room floor plane (world centred at x=8, z=0). A
// pixel is re-lawed by which zone its WORLD HIT-POINT falls in, so walls, floor,
// AND a demon crossing the seam are all sliced per-pixel by the same test. The
// active law-set shifts by frame (uni(30), counted in the hook):
//   frames <120: zoneA hue-rotates, zoneB wave-ripples, overlap does BOTH.
//   frames 120-239: zoneA law swaps to INVERT (live, by data not deploy).
//   frames >=240: a posterize law is ADDED over BOTH zones.
fn vf_rz_hue120(c: vec3f) -> vec3f { return vec3f(c.b, c.r, c.g); }
// one law, by rule id. 1 hue · 2 wave · 3 invert · 4 posterize · 5 time-slow · 6 time-fast.
// The visual is only half of a law: the time laws (5/6) also scale MOTION in the hook.
fn vf_rz_law(col: vec3f, ruleId: f32, hp: vec3f, t: f32) -> vec3f {
  var c = col;
  if (ruleId > 0.5 && ruleId < 1.5) {                 // HUE
    c = mix(c, vf_rz_hue120(c) * 1.3 + vec3f(0.0, 0.18, 0.0), 0.9);
  } else if (ruleId < 2.5) {                          // WAVE
    let w = 0.45 + 0.55 * sin(hp.y * 3.6 + t * 3.2 + hp.x * 4.0);
    c = mix(c.zyx, vec3f(0.10, 0.45, 0.95) * (0.4 + c), w * 0.85);
  } else if (ruleId < 3.5) {                          // INVERT
    c = vec3f(1.0) - c;
  } else if (ruleId < 4.5) {                          // POSTERIZE
    c = floor(c * 5.0) / 5.0;
  } else if (ruleId < 5.5) {                          // TIME-SLOW: cold, languid pulse
    c = mix(c, vec3f(0.22, 0.42, 0.78), 0.55) * (0.72 + 0.14 * sin(t * 1.1));
  } else {                                            // TIME-FAST: warm, streaking
    let s = 0.5 + 0.5 * sin(hp.x * 9.0 - t * 15.0);
    c = mix(c, vec3f(1.0, 0.55, 0.2), 0.42) + vec3f(0.55, 0.22, 0.0) * s * 0.4;
  }
  return c;
}
// zones now come from UNIFORMS the hook fills from selectable fields (rule lives ON the
// field, so you can pick a zone and change its law): u31..34 = zoneA x,z,rule,radius (room-
// local); u35..38 = zoneB. Overlap composes B then A. radius<=0 means "no zone".
fn vf_rulezones(col0: vec3f, hp: vec3f, t: f32) -> vec3f {
  let q = vec2f(hp.x - 8.0, hp.z);
  let aR = uni(34); let bR = uni(38);
  if (aR < 0.01 && bR < 0.01) { return col0; }
  let dA = length(q - vec2f(uni(31), uni(32)));
  let dB = length(q - vec2f(uni(35), uni(36)));
  let inA = aR > 0.01 && dA < aR;
  let inB = bR > 0.01 && dB < bR;
  if (!inA && !inB) { return col0; }
  var col = col0;
  if (inB) { col = vf_rz_law(col, uni(37), hp, t); }
  if (inA) { col = vf_rz_law(col, uni(33), hp, t); }   // A over B on overlap
  var rim = 999.0;
  if (aR > 0.01) { rim = min(rim, abs(dA - aR)); }
  if (bR > 0.01) { rim = min(rim, abs(dB - bR)); }
  col += vec3f(1.0, 0.9, 0.5) * smoothstep(0.10, 0.0, rim) * 1.4;
  return col;
}

fn visual_s3(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let ro = uni4(60).xyz;
  let fov = max(uni4(60).w, 0.6);
  let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
  let sky = vec3f(0.02, 0.025, 0.05);

  // ── the world ──
  let wh = mod_w3_march(ro, rd, 0.02, 60.0, 96);
  var worldT = select(60.0, wh.x, wh.x >= 0.0);
  var col = sky;
  if (wh.x >= 0.0) {
    let pos = ro + rd * wh.x;
    let n = mod_w3_nrm(pos, 0.02);
    let ao = mod_w3_ao(pos, n);
    var alb = vec3f(0.30, 0.29, 0.36);                              // walls
    if (wh.y > 1.5 && wh.y < 2.5) { alb = vec3f(0.15, 0.14, 0.13); } // floor/dais
    if (wh.y > 2.5 && wh.y < 3.5) { alb = vec3f(0.22, 0.20, 0.24); } // column
    if (wh.y > 3.5) { alb = vec3f(0.55, 0.34, 0.14); }              // doorway trim
    // lantern (headlamp at the camera — vf-lightdark will move it to the player)
    let ld = normalize(ro - pos);
    let dist = length(ro - pos);
    let sh = mod_w3_shadow(pos + n * 0.04, ld, dist, 14.0);
    let diff = max(dot(n, ld), 0.0);
    let atten = 4.5 / (1.0 + 0.09 * dist * dist);
    col = alb * (vec3f(0.05, 0.06, 0.09) + vec3f(1.0, 0.82, 0.55) * diff * atten * sh) * ao;
  }

  // ── the population, depth-composited in front of the world ──
  var nearT = worldT;
  let cnt = popCount() / 2;
  for (var i = 0; i < cnt; i = i + 1) {
    let a = pop(i * 2);            // x, y, z, kind
    let b = pop(i * 2 + 1);        // hp01, phase, yaw, flags
    let kind = a.w;
    if (kind < 0.5) { continue; }  // empty slot
    let ppos = a.xyz;
    let isDemon = kind < 2.5;
    // BUG WAS HERE: sphere sat at the feet (y=0, r=1.4) → it clipped everything
    // above y=1.4: the ribcage, head, horns. Center it at torso height + widen so
    // the WHOLE body is inside the sphere test AND the local march below.
    let bc = ppos + vec3f(0.0, select(0.0, 1.05, isDemon), 0.0);
    let br = select(0.18, 1.6, isDemon);
    let sh = s3_sph(ro, rd, bc, br);
    // the neon HERO (flags b.w>4.5) superimposes THROUGH walls — never occluded by
    // the world, so a backed-out third-person camera always sees it. Everything else
    // is culled when it sits behind the world geometry.
    if (sh < 0.0 || (sh > nearT && b.w < 4.5)) { continue; }

    if (kind < 2.5) {
      // DEMON — local sphere-march (rotate the ray into the demon's yaw frame)
      let yaw = b.z;
      let cy = cos(-yaw); let sy = sin(-yaw);
      let o0 = ro - ppos;
      let lro = vec3f(cy * o0.x + sy * o0.z, o0.y, -sy * o0.x + cy * o0.z);
      let lrd = vec3f(cy * rd.x + sy * rd.z, rd.y, -sy * rd.x + cy * rd.z);
      var t = max(sh, 0.02);
      var hitT = -1.0;
      for (var s = 0; s < 30; s = s + 1) {
        let d = vf_demon(lro + lrd * t, b.y);
        if (d < 0.004) { hitT = t; break; }
        t = t + max(d * 0.8, 0.004);
        if ((t > nearT && b.w < 4.5) || t > sh + 2.0 * br) { break; }
      }
      if (hitT > 0.0 && (hitT < nearT || b.w > 4.5)) {
        if (b.w < 4.5) { nearT = hitT; }   // hero draws over the world but doesn't set depth (keeps fog right)
        let lp = lro + lrd * hitT;
        let e = 0.012;
        let nn = normalize(vec3f(
          vf_demon(lp + vec3f(e, 0.0, 0.0), b.y) - vf_demon(lp - vec3f(e, 0.0, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, e, 0.0), b.y) - vf_demon(lp - vec3f(0.0, e, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, 0.0, e), b.y) - vf_demon(lp - vec3f(0.0, 0.0, e), b.y)));
        let ll = normalize(lro - lp);                 // headlamp, in local frame
        let dist = length(ro - (ro + rd * hitT));
        let diff = max(dot(nn, ll), 0.0);
        let atten = 4.0 / (1.0 + 0.10 * dist * dist);
        let base = vec3f(0.11, 0.05, 0.045);          // charred flesh
        let ember = vec3f(1.0, 0.32, 0.07) * pow(clamp(0.6 - nn.y, 0.0, 1.0), 2.0) * (0.7 + 0.5 * sin(time * 6.0 + ppos.x));
        if (b.w > 4.5) {
          // NEON HERO — the player character: emissive, unlit by the crypt lantern,
          // a cyan->magenta pulse with a hot rim. flags(b.w)>4.5 marks it in the population.
          let pulse = 0.5 + 0.5 * sin(time * 3.2);
          let neon = mix(vec3f(0.16, 0.96, 1.0), vec3f(1.0, 0.24, 0.86), pulse);
          let rim = pow(1.0 - max(dot(nn, ll), 0.0), 2.2);
          col = neon * (1.1 + rim * 1.9) + vec3f(0.10, 0.34, 0.55);
        } else {
          col = base * (0.12 + diff * atten) + ember * 0.9;
        }
      }
    } else {
      // PROJECTILE / DEATH-BIT — emissive blob at the sphere hit
      if (sh < nearT) {
        nearT = sh;
        let life = clamp(b.x, 0.0, 1.0);
        if (kind > 4.5) { col = vec3f(1.0, 0.42, 0.12) * (0.5 + life * 1.6); }  // death ember
        else { col = s3_tracerColor(kind, life) * 1.4; }
      }
    }
  }

  // ── rule zones re-law the pixel by its world hit-point (before atmosphere so
  //    fog/embers still unify the room). Inert everywhere but the side chamber. ──
  col = vf_rulezones(col, ro + rd * nearT, time);

  // ── atmosphere over whatever we hit, then flashes, then HUD ──
  col = vf_atmos(col, ro + rd * nearT, rd, nearT, time);
  col += vec3f(1.0, 0.82, 0.5) * max(uni(15), 0.0) * 0.6;   // muzzle flash
  col += vec3f(1.0, 0.22, 0.16) * max(uni(16), 0.0) * 0.5;  // hit flash
  let hud = s3_hud(uv, uni(6), uni(7), uni(8), uni(12));
  col = mix(col, hud.rgb, hud.a);
  return vec4f(col, 1.0);
}

modules.wgsl:
// WORLD3 — the cafe's shared 3D raymarching kit (canonical copy).
// Everything ONE DAY, TIDEGLASS, and MARIONETTES 3D each hand-rolled, extracted
// once: camera, SDF primitives, domain ops, marcher, normals, soft shadows,
// AO, and a standard light rig. Ship it in your scene as a module:
//
//   { "type": "define_module", "name": "world3", "wgsl": <this file> }
//
// THE ONE CONTRACT — your scene defines the world map in its OWN module:
//
//   fn w3_map(p: vec3f) -> vec2f   // returns (signed distance, material id)
//
// WGSL resolves module-scope functions in any order, so the kit's marchers can
// call w3_map before your module defines it. A scene that ships world3 without
// defining w3_map will not compile — the contract is load-bearing.
//
// CAMERA CONVENTION (whiteboard rows 60–62, so hooks can drive the eye):
//   uni4(60) = ro.xyz, fov     ·  uni4(61) = target.xyz, roll(unused)
//   A hook that writes these makes any world3 scene orbit/walk for free.
//
// Typical visual:
//   let ro = uni4(60).xyz;  let fov = max(uni4(60).w, 0.6);
//   let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
//   let hit = mod_w3_march(ro, rd, 0.1, 60.0, 96);
//   if (hit.x > 0.0) {
//     let pos = ro + rd * hit.x;
//     let n = mod_w3_nrm(pos, 0.02);
//     let sh = mod_w3_shadow(pos + n * 0.05, sunDir, 30.0, 8.0);
//     let ao = mod_w3_ao(pos, n);
//     col = mod_w3_light(albedoFor(i32(hit.y)), n, rd, sunDir, sunCol, skyCol, sh, ao);
//   }
// Output linear HDR — the engine's ACES + bloom do the grading.

// ── camera ─────────────────────────────────────────────────────────────────
// Ray through a screen point for a look-at camera. uv is the visual's -1..1
// (y down — the flip is handled here, pass it raw).
fn mod_w3_ray(uv: vec2f, ro: vec3f, ta: vec3f, fov: f32) -> vec3f {
  let fw = normalize(ta - ro);
  let rt = normalize(cross(fw, vec3f(0.0, 1.0, 0.0)));
  let up = cross(rt, fw);
  return normalize(uv.x * rt * fov - uv.y * up * fov + fw);
}

// ── SDF primitives (3D) ────────────────────────────────────────────────────
fn mod_w3_sphere(p: vec3f, r: f32) -> f32 { return length(p) - r; }

fn mod_w3_box(p: vec3f, b: vec3f) -> f32 {
  let d = abs(p) - b;
  return length(max(d, vec3f(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

fn mod_w3_rbox(p: vec3f, b: vec3f, r: f32) -> f32 {
  return mod_w3_box(p, b - vec3f(r)) - r;
}

fn mod_w3_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - r;
}

// vertical capped cylinder: half-height h, radius r
fn mod_w3_cyl(p: vec3f, h: f32, r: f32) -> f32 {
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(r, h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

// tapered vertical cylinder: radius r0 at -h → r1 at +h (towers, spires)
fn mod_w3_cone(p: vec3f, h: f32, r0: f32, r1: f32) -> f32 {
  let t = clamp((p.y + h) / (2.0 * h), 0.0, 1.0);
  let d = abs(vec2f(length(p.xz), p.y)) - vec2f(mix(r0, r1, t), h);
  return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn mod_w3_torus(p: vec3f, R: f32, r: f32) -> f32 {
  return length(vec2f(length(p.xz) - R, p.y)) - r;
}

fn mod_w3_octa(p: vec3f, s: f32) -> f32 {
  let q = abs(p);
  return (q.x + q.y + q.z - s) * 0.57735027;
}

fn mod_w3_plane(p: vec3f, n: vec3f, d: f32) -> f32 { return dot(p, n) + d; }

// ── skeleton assembly (nodes + struts + tissue) ────────────────────────────
// Build forms as a GRAPH: struts between shared node points, joined with
// opSmoothUnion (the "linkage tissue"). Gaps become impossible by construction
// — parts share endpoints instead of hoping coordinates line up. Use tissue k
// at structural joints (0.2–0.5) and hard min for edges that must stay crisp.

// exact closed-form distance to a quadratic bezier strut (S start, Ctl control,
// E end, radius r) — the connective arc: vaults, arches, branches, cables
fn mod_w3_bezStrut(pos: vec3f, S: vec3f, Ctl: vec3f, E: vec3f, r: f32) -> f32 {
  let a = Ctl - S;
  let b = S - 2.0 * Ctl + E;
  let c = a * 2.0;
  let d = S - pos;
  let bb = dot(b, b);
  if (bb < 1e-9) {
    let pa = pos - S;
    let ba = E - S;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
  }
  let kk = 1.0 / bb;
  let kx = kk * dot(a, b);
  let ky = kk * (2.0 * dot(a, a) + dot(d, b)) / 3.0;
  let kz = kk * dot(d, a);
  let pp = ky - kx * kx;
  let qq = kx * (2.0 * kx * kx - 3.0 * ky) + kz;
  let h = qq * qq + 4.0 * pp * pp * pp;
  var res: f32;
  if (h >= 0.0) {
    let hs = sqrt(h);
    let x1 = (hs - qq) / 2.0;
    let x2 = (-hs - qq) / 2.0;
    let t = clamp(sign(x1) * pow(abs(x1), 0.3333333) + sign(x2) * pow(abs(x2), 0.3333333) - kx, 0.0, 1.0);
    let g = d + (c + b * t) * t;
    res = dot(g, g);
  } else {
    let z = sqrt(-pp);
    let v = acos(qq / (pp * z * 2.0)) / 3.0;
    let m = cos(v);
    let n = sin(v) * 1.7320508;
    let t1 = clamp((m + m) * z - kx, 0.0, 1.0);
    let t2 = clamp((-n - m) * z - kx, 0.0, 1.0);
    let g1 = d + (c + b * t1) * t1;
    let g2 = d + (c + b * t2) * t2;
    res = min(dot(g1, g1), dot(g2, g2));
  }
  return sqrt(res) - r;
}

// tapered strut between nodes (columns, spires, limbs): radius r1 at a → r2 at b
fn mod_w3_taperStrut(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r1, r2, h);
}

// round (Roman) arch opening — subtract from a wall. Origin at base center:
// straight sides height h, half-width w (semicircle top radius w), half-depth d in z
fn mod_w3_arch(p: vec3f, w: f32, h: f32, d: f32) -> f32 {
  let dxy = abs(p.xy - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect2 = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let top2 = length(p.xy - vec2f(0.0, h)) - w;
  let d2 = min(rect2, top2);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// Gothic lancet (ogival/pointed) arch profile: straight sides |x|<=w up to h,
// two-arc point peaking ph above h. 2D — extrude with mod_w3_lancet.
fn mod_w3_lancet2(q: vec2f, w: f32, h: f32, ph: f32) -> f32 {
  let R = (w * w + ph * ph) / (2.0 * w);
  let c = R - w;
  let dxy = abs(q - vec2f(0.0, h * 0.5)) - vec2f(w, h * 0.5);
  let rect = length(max(dxy, vec2f(0.0))) + min(max(dxy.x, dxy.y), 0.0);
  let arcs = max(length(q - vec2f(-c, h)) - R, length(q - vec2f(c, h)) - R);
  let top = max(arcs, h - q.y);
  return min(rect, top);
}

// Gothic lancet arch opening in 3D — subtract from a wall. Base center origin,
// half-width w, straight height h, point rises ph above h, half-depth d in z
fn mod_w3_lancet(p: vec3f, w: f32, h: f32, ph: f32, d: f32) -> f32 {
  let d2 = mod_w3_lancet2(p.xy, w, h, ph);
  let wz = vec2f(d2, abs(p.z) - d);
  return min(max(wz.x, wz.y), 0.0) + length(max(wz, vec2f(0.0)));
}

// ── domain ops ─────────────────────────────────────────────────────────────
fn mod_w3_rotX(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}
fn mod_w3_rotY(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}
fn mod_w3_rotZ(p: vec3f, a: f32) -> vec3f {
  let c = cos(a); let s = sin(a);
  return vec3f(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}
// infinite repetition on chosen axes (c = cell size per axis; 0 = no repeat)
fn mod_w3_repeat(p: vec3f, c: vec3f) -> vec3f {
  var q = p;
  if (c.x > 0.0) { q.x = (fract(p.x / c.x + 0.5) - 0.5) * c.x; }
  if (c.y > 0.0) { q.y = (fract(p.y / c.y + 0.5) - 0.5) * c.y; }
  if (c.z > 0.0) { q.z = (fract(p.z / c.z + 0.5) - 0.5) * c.z; }
  return q;
}
// polar repetition around Y: n copies; returns p in the first wedge
fn mod_w3_polar(p: vec3f, n: f32) -> vec3f {
  let ang = 6.2831853 / n;
  let a = atan2(p.z, p.x);
  let r = length(p.xz);
  let a2 = (fract(a / ang + 0.5) - 0.5) * ang;
  return vec3f(cos(a2) * r, p.y, sin(a2) * r);
}

// ── the marcher family (all call YOUR w3_map) ──────────────────────────────
// sphere-trace: returns (t, material) on hit, (-1, -1) on miss
fn mod_w3_march(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32, steps: i32) -> vec2f {
  var t = tmin;
  for (var i = 0; i < 256; i++) {
    if (i >= steps) { break; }
    let dm = w3_map(ro + rd * t);
    if (dm.x < 0.001 * t + 0.003) { return vec2f(t, dm.y); }
    t = t + max(dm.x * 0.9, 0.004);
    if (t > tmax) { break; }
  }
  return vec2f(-1.0, -1.0);
}

// tetrahedral 4-tap normal
fn mod_w3_nrm(p: vec3f, eps: f32) -> vec3f {
  let k = vec2f(1.0, -1.0);
  return normalize(
    k.xyy * w3_map(p + k.xyy * eps).x +
    k.yyx * w3_map(p + k.yyx * eps).x +
    k.yxy * w3_map(p + k.yxy * eps).x +
    k.xxx * w3_map(p + k.xxx * eps).x);
}

// soft shadow toward a light: k = penumbra hardness (8 soft … 32 crisp)
fn mod_w3_shadow(p: vec3f, ld: vec3f, tmax: f32, k: f32) -> f32 {
  var t = 0.03;
  var sh = 1.0;
  for (var i = 0; i < 24; i++) {
    let d = w3_map(p + ld * t).x;
    sh = min(sh, k * d / t);
    t = t + clamp(d, 0.02, 0.8);
    if (sh < 0.02 || t > tmax) { break; }
  }
  return clamp(sh, 0.0, 1.0);
}

// 4-tap ambient occlusion along the normal
fn mod_w3_ao(p: vec3f, n: vec3f) -> f32 {
  var occ = 0.0;
  var w = 1.0;
  for (var i = 1; i <= 4; i++) {
    let h = 0.04 * f32(i * i);
    occ = occ + w * (h - w3_map(p + n * h).x);
    w = w * 0.65;
  }
  return clamp(1.0 - 2.2 * occ, 0.0, 1.0);
}

// ── shading ────────────────────────────────────────────────────────────────
fn mod_w3_fresnel(n: vec3f, rd: vec3f, f0: f32) -> f32 {
  return f0 + (1.0 - f0) * pow(1.0 - clamp(dot(n, -rd), 0.0, 1.0), 5.0);
}

// the standard rig: sun key + sky fill + bounce, shadow and AO applied where
// each belongs (shadow kills the key, AO dims the fill), plus a spec lobe
fn mod_w3_light(alb: vec3f, n: vec3f, rd: vec3f, sunDir: vec3f, sunCol: vec3f, skyCol: vec3f, sh: f32, ao: f32) -> vec3f {
  let dif = clamp(dot(n, sunDir), 0.0, 1.0);
  let sky = 0.5 + 0.5 * n.y;
  let bou = clamp(-n.y, 0.0, 1.0) * 0.3;
  var c = alb * (sunCol * dif * sh + skyCol * sky * ao + skyCol * bou * ao);
  let hal = normalize(sunDir - rd);
  let spe = pow(clamp(dot(n, hal), 0.0, 1.0), 32.0) * dif * sh;
  c = c + sunCol * spe * 0.5 * mod_w3_fresnel(n, rd, 0.04);
  return c;
}

// aerial perspective: fold a hit color into the sky with distance
fn mod_w3_fog(c: vec3f, skyC: vec3f, t: f32, density: f32) -> vec3f {
  return mix(c, skyC, 1.0 - exp(-t * t * density));
}

// ANIM3 — articulated-chain animation kit (canonical copy).
// The layer between skel-lib (creature rigs) and world3 (raymarched space):
// two-bone IK, tapered limb SDFs, gait oscillators with planted feet, pose
// paths, and aim frames — everything needed to make a marched body MOVE well.
//
//   { "type": "define_module", "name": "anim3", "wgsl": <this file> }
//
// Design: everything is STATELESS — pure functions of time and parameters, so
// they run per-pixel in a visual with no CPU sync. Drive the inputs (targets,
// phases, headings) from a step hook via the whiteboard or the population
// buffer; the shader poses the body.
//
// The crowd pattern: hook publishes gpuPopulation entries [x, y, heading, phase]
// → the visual loops pop(i), builds each body in its local frame with
// mod_a3_gait(phase …) driving the legs. 4095 walkers, one dispatch.

// ── two-bone IK ────────────────────────────────────────────────────────────
// Classic solver: a chain root→mid→tip with segment lengths l1, l2 reaching
// for `target`. Returns the MID joint (elbow/knee). `pole` bends the joint
// toward it (knee forward, elbow back) — give it a point, not a direction.
// Unreachable targets clamp to full extension; degenerate poles self-heal.
fn mod_a3_ik2(root: vec3f, tgt: vec3f, l1: f32, l2: f32, pole: vec3f) -> vec3f {
  var to = tgt - root;
  var d = length(to);
  let maxR = l1 + l2 - 0.0001;
  d = clamp(d, abs(l1 - l2) + 0.0001, maxR);
  let dir = to / max(length(to), 0.0001);
  // law of cosines: distance from root to the mid joint's projection
  let a = (l1 * l1 - l2 * l2 + d * d) / (2.0 * d);
  let h = sqrt(max(l1 * l1 - a * a, 0.0));
  // bend plane: contains the chain axis, leans toward the pole
  var side = pole - root - dir * dot(pole - root, dir);
  let sl = length(side);
  if (sl < 0.001) { side = vec3f(0.0, 0.0, 1.0) - dir * dir.z; } else { side = side / sl; }
  return root + dir * a + normalize(side) * h;
}

// ── limb geometry ──────────────────────────────────────────────────────────
// tapered capsule: radius r0 at `a` → r1 at `b` (thigh→ankle, arm→wrist)
fn mod_a3_bone(p: vec3f, a: vec3f, b: vec3f, r0: f32, r1: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - mix(r0, r1, h);
}
// joint ball — drop one at every hinge to keep silhouettes smooth
fn mod_a3_joint(p: vec3f, at: vec3f, r: f32) -> f32 { return length(p - at) - r; }

// ── gait ───────────────────────────────────────────────────────────────────
// The planted-foot law (lifted from skel-lib's ladder): phase advances in
// STRIDE CYCLES (hook: ph += speed / strideLen * dt). Within one cycle a foot
// is planted for `duty` (moving backward at exactly body speed → zero world
// velocity) and swings forward for the rest, lifted on a sine arc.
// Returns (alongOffset, lift): foot position relative to its rest point,
// in units of strideLen.
fn mod_a3_gait(phase: f32, duty: f32) -> vec2f {
  let c = fract(phase);
  if (c < duty) {
    // stance: linear back-travel, no lift — the foot OWNS the ground
    let s = c / duty;
    return vec2f(0.5 - s, 0.0);
  }
  // swing: forward and up
  let s = (c - duty) / (1.0 - duty);
  return vec2f(-0.5 + s, sin(s * 3.14159) * 1.0);
}
// eased oscillator for secondary motion (tails, breathing, sway):
// sin with adjustable sharpness — sharp > 1 dwells at the extremes
fn mod_a3_sway(t: f32, freq: f32, sharp: f32) -> f32 {
  let s = sin(t * freq);
  return sign(s) * pow(abs(s), 1.0 / max(sharp, 0.001));
}

// ── pose paths ─────────────────────────────────────────────────────────────
// blend two joint positions (a pose is just a set of points — lerp each)
fn mod_a3_mix(a: vec3f, b: vec3f, t: f32) -> vec3f { return mix(a, b, smoothstep(0.0, 1.0, t)); }
// quadratic bezier through a lifted midpoint — a reach, a leap, a nod
fn mod_a3_arc(a: vec3f, peak: vec3f, b: vec3f, t: f32) -> vec3f {
  let u = 1.0 - t;
  return a * u * u + peak * 2.0 * u * t + b * t * t;
}

// ── aim frames ─────────────────────────────────────────────────────────────
// build a basis aimed along `fw` (head look-at, torso facing); transform a
// local point into it. worldUp guards collinearity.
fn mod_a3_aim(local: vec3f, origin: vec3f, fw0: vec3f) -> vec3f {
  let fw = normalize(fw0);
  var up = vec3f(0.0, 1.0, 0.0);
  if (abs(dot(fw, up)) > 0.99) { up = vec3f(0.0, 0.0, 1.0); }
  let rt = normalize(cross(up, fw));
  let u2 = cross(fw, rt);
  return origin + rt * local.x + u2 * local.y + fw * local.z;
}

// ── a whole walker, as the pattern to copy ─────────────────────────────────
// Biped legs in one call: body at `hips` heading +z in its local frame,
// phase in stride cycles, stride length L. Returns the SDF of both legs.
// (Offset the two feet half a cycle; IK bends knees toward the pole.)
fn mod_a3_legs(p: vec3f, hips: vec3f, phase: f32, L: f32, legLen: f32, r: f32) -> f32 {
  var d = 1e9;
  for (var s = 0; s < 2; s++) {
    let side = select(-1.0, 1.0, s == 1);
    let g = mod_a3_gait(phase + select(0.0, 0.5, s == 1), 0.55);
    let hip = hips + vec3f(side * legLen * 0.22, 0.0, 0.0);
    let foot = vec3f(hip.x, g.y * legLen * 0.22, g.x * L);
    let knee = mod_a3_ik2(hip, foot, legLen * 0.52, legLen * 0.52, hip + vec3f(0.0, 0.0, legLen));
    d = min(d, mod_a3_bone(p, hip, knee, r, r * 0.75));
    d = min(d, mod_a3_bone(p, knee, foot, r * 0.75, r * 0.5));
    d = min(d, mod_a3_joint(p, knee, r * 0.85));
  }
  return d;
}

// VEILFIRE · rooms.wgsl — the load-bearing scene SDF (vf-rooms node).
// EXPORT: fn w3_map(p: vec3f) -> vec2f  = (signed distance, material id).
//
// A WALKABLE Antichamber-style Gothic interior, carved SUBTRACTIVELY out of a
// solid rock block so rooms connect by construction (no coordinate seams):
//   d = solidBlock;  d = max(d, -naveAir);  d = max(d, -sideAir);  d = max(d, -door);
// then solids (columns, dais) are UNIONed back in with min(). Positive in open
// air, 0 at surfaces, negative inside rock — raymarchable from inside.
//
// ── ROOM EXTENTS (world units, y=0 is the floor) — movement/vf-* MIRROR THIS ──
//   NAVE (main hall):  x∈[-4, 4]   y∈[0, 9]   z∈[-9, 9]     (tall)
//   SIDE CHAMBER:      x∈[ 5,11]   y∈[0, 5]   z∈[-3.5, 3.5] (lower ceiling)
//   DIVIDING WALL:     x∈[ 4, 5]  (1 thick) — solid except the doorway
//   DOORWAY (lancet):  center x≈4.5, z=0, base y=0; opening z∈[-1.5,1.5],
//                      height y∈[0, 3.7] (straight to 2.5, point to 3.7),
//                      depth x∈[3.3, 5.7] (cuts the whole dividing wall)
//   COLONNADE:         two rows at x=±3.2, columns every 4 in z (z=0,±4,±8),
//                      r=0.4, floor→near ceiling (y∈[-0.5, 8.5])
//   DAIS (verticality, far +z end of nave):
//      step1: x∈[-3.5,3.5] y∈[0,1]   z∈[6,9]   (low platform)
//      step2: x∈[-3.5,3.5] y∈[0,2]   z∈[7.8,9.2] (upper ledge)
//   Suggested spawn: (0, 1.6, 0) facing +x toward the doorway, or -z down nave.
//
// MATERIAL IDS: 1 wall · 2 floor/dais · 3 column · 4 doorway/arch trim.
// Cheap: a handful of box/cyl/lancet evals, one z-repeat, no loops.

fn w3_map(p: vec3f) -> vec2f {
  // --- solid rock; carve the rooms out of it ---
  let d0 = mod_w3_box(p - vec3f(3.5, 4.5, 0.0), vec3f(8.5, 5.5, 10.0));
  let nave = mod_w3_box(p - vec3f(0.0, 4.5, 0.0), vec3f(4.0, 4.5, 9.0));
  let side = mod_w3_box(p - vec3f(8.0, 2.5, 0.0), vec3f(3.0, 2.5, 3.5));

  // doorway: lancet arch, profile in (z,y), depth along x through the wall
  let qd = vec3f(p.z, p.y, p.x - 4.5);
  let door = mod_w3_lancet(qd, 1.5, 2.5, 1.2, 1.2);

  var d = d0;
  d = max(d, -nave);
  d = max(d, -side);
  d = max(d, -door);

  // shell material: floor low, doorway trim near the arch cut, else wall
  var mat = 1.0;
  if (p.y < 0.3) { mat = 2.0; }
  if (door < 0.35 && p.y < 3.9) { mat = 4.0; }

  // --- solids unioned back in ---
  // colonnade: mirrored rows at x=±3.2, repeated every 4 units in z
  let cz = (fract(p.z / 4.0 + 0.5) - 0.5) * 4.0;
  let colp = vec3f(abs(p.x) - 3.2, p.y - 4.0, cz);
  let col = mod_w3_cyl(colp, 4.5, 0.4);
  if (col < d) { d = col; mat = 3.0; }

  // dais / altar steps at the far +z end (verticality)
  let step1 = mod_w3_box(p - vec3f(0.0, 0.5, 7.5), vec3f(3.5, 0.5, 1.5));
  if (step1 < d) { d = step1; mat = 2.0; }
  let step2 = mod_w3_box(p - vec3f(0.0, 1.0, 8.5), vec3f(3.5, 1.0, 0.7));
  if (step2 < d) { d = step2; mat = 2.0; }

  return vec2f(d, mat);
}

// VEILFIRE — DEMONS. A gaunt, hunched, horned humanoid that WALKS.
// Built entirely from anim3-lib tapered-capsule bones + world3 struts so it reads
// as a silhouette at the edge of lantern light. Legs are driven by the planted-foot
// gait (mod_a3_gait(phase, 0.55)); arms counter-swing; head carries swept horns and
// a jutting snarl. Distance only — the integrator paints material / ember-crust.
//
//   { "type": "define_module", "name": "veilfire_demons", "wgsl": <this file> }
//
// EXPORT:  fn vf_demon(p: vec3f, phase: f32) -> f32
//   p     : local body space (heading +z, feet near y=0, center at origin)
//   phase : stride-cycle phase (fract cycles). Same phase feeds the population's
//           animPhase slot (pop(2i+1).y).
// Depends on world3-lib (mod_w3_taperStrut) + anim3-lib (bone/joint/gait/ik2/legs).

// fleshy smooth-union — organic joints without gaps; k small = tight seam
fn vf_smin(a: f32, b: f32, k: f32) -> f32 {
  let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

fn vf_demon(p: vec3f, phase: f32) -> f32 {
  let hipY = 0.88;      // hip height — feet reach y≈0
  let L = 0.5;          // stride length
  let legLen = 0.95;    // thigh+shin reach

  // ── legs: planted-foot gait, gaunt shins ─────────────────────────────────
  var d = mod_a3_legs(p, vec3f(0.0, hipY, 0.0), phase, L, legLen, 0.075);

  // subtle breathing / menace sway of the upper body
  let breathe = sin(phase * 6.2831853) * 0.02;

  // ── spine (hunched forward) + head + snarling jaw ────────────────────────
  let pelvis = vec3f(0.0, hipY, 0.0);
  let chest  = vec3f(0.0, hipY + 0.42, 0.10);
  let neck   = vec3f(0.0, hipY + 0.60, 0.16);
  let headC  = vec3f(0.0, hipY + 0.76, 0.20 + breathe);

  var body = mod_a3_bone(p, pelvis, chest, 0.11, 0.15);                 // gaunt ribcage
  body = vf_smin(body, mod_a3_bone(p, chest, neck, 0.13, 0.06), 0.08);  // taper to neck
  body = vf_smin(body, mod_a3_joint(p, headC, 0.14), 0.06);            // skull
  body = vf_smin(body,                                                  // jutting snarl
    mod_a3_bone(p, headC + vec3f(0.0, -0.02, 0.05), headC + vec3f(0.0, -0.06, 0.16), 0.09, 0.03), 0.05);
  d = min(d, body);

  // ── horns: swept up and back, crisp edges ────────────────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    let hb = headC + vec3f(sx * 0.08, 0.08, -0.02);
    let ht = headC + vec3f(sx * 0.16, 0.30, -0.18);
    d = min(d, mod_w3_taperStrut(p, hb, ht, 0.035, 0.004));
  }

  // ── arms: long, clawed, counter-swinging to the legs ─────────────────────
  for (var s = 0; s < 2; s++) {
    let sx = select(-1.0, 1.0, s == 1);
    // opposite phase offset to the same-side leg → natural counter-swing
    let g = mod_a3_gait(phase + select(0.5, 0.0, s == 1), 0.55);
    let shoulder = vec3f(sx * 0.20, hipY + 0.48, 0.06);
    let hand = vec3f(sx * 0.17, hipY - 0.32, 0.16 - g.x * 0.55);        // reach to mid-thigh
    let pole = shoulder + vec3f(sx * 0.35, -0.1, -0.35);               // elbow back/out
    let elbow = mod_a3_ik2(shoulder, hand, 0.44, 0.46, pole);
    var arm = mod_a3_bone(p, shoulder, elbow, 0.06, 0.045);
    arm = min(arm, mod_a3_bone(p, elbow, hand, 0.045, 0.028));
    arm = min(arm, mod_a3_joint(p, elbow, 0.05));
    // three splayed talons
    for (var c = 0; c < 3; c++) {
      let ca = (f32(c) - 1.0) * 0.12;
      let tip = hand + vec3f(sx * 0.03 + ca * 0.05, -0.14, 0.06 + ca * 0.02);
      arm = min(arm, mod_w3_taperStrut(p, hand, tip, 0.022, 0.002));
    }
    d = vf_smin(d, arm, 0.04);
  }

  // ── HORROR PASS (v2) — detail the ember-shading catches at the light's edge ──
  // ribcage: thin bones across the hunched chest → skeletal, ember-cracked
  for (var r = 0; r < 4; r++) {
    let ry = hipY + 0.13 + f32(r) * 0.085;
    let rz = 0.04 + f32(r) * 0.012;
    d = min(d, mod_a3_bone(p, vec3f(-0.115, ry, rz), vec3f(0.115, ry, rz), 0.012, 0.012));
  }
  // a sternum ridge down the ribs
  d = min(d, mod_a3_bone(p, vec3f(0.0, hipY + 0.10, 0.05), vec3f(0.0, hipY + 0.42, 0.09), 0.016, 0.010));
  // sunken eye sockets + a gaping maw carved from the skull (dark hollows read as a face)
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(-0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f( 0.055, 0.035, 0.10)), 0.040));
  d = max(d, -mod_w3_sphere(p - (headC + vec3f(0.0, -0.055, 0.15)), 0.050));

  return d;
}

// enemies (node: enemies) — shared enemy shading helper. The enemy BODY draw is
// routed through veilfire/demons.wgsl's vf_demon inside renderer-mega; this holds
// the damage-flash tint the renderer can blend by hp so hurt demons read hot.
fn s3_enemyTint(hp01: f32) -> vec3f {
  return mix(vec3f(1.0, 0.28, 0.16), vec3f(0.11, 0.05, 0.045), clamp(hp01, 0.0, 1.0));
}

// shooter3 / projectiles — thin glowing energy bolts (tracers)
// Cheap capsule SDF + emissive HDR color the renderer adds on hit-glow.
// Exports:
//   s3_tracer(p, a, b)            -> f32   thin bolt from a to b (radius ~0.06)
//   s3_tracerColor(kind, life01)  -> vec3f linear HDR emissive (3=player, 4=enemy)

// A thin glowing bolt: a capsule from a to b. Cheap — one clamp/dot/length.
fn s3_tracer(p: vec3f, a: vec3f, b: vec3f) -> f32 {
  return mod_w3_capsule(p, a, b, 0.06);
}

// Emissive HDR color the renderer adds. Brightest when freshly fired (life01~1),
// fading toward death (life01~0). kind 3 = player (hot cyan-white), 4 = enemy (sick green).
fn s3_tracerColor(kind: f32, life01: f32) -> vec3f {
  let l = clamp(life01, 0.0, 1.0);
  // hot core (near-white at spawn) blended toward the tinted tail as it ages
  let playerHot  = vec3f(0.55, 1.0, 1.0);   // cyan
  let playerCore = vec3f(1.0, 1.0, 1.0);    // white-hot
  let enemyHot   = vec3f(0.35, 1.0, 0.15);  // sick green
  let enemyCore  = vec3f(0.85, 1.0, 0.6);   // pale green-white
  let isEnemy = step(3.5, kind);            // 0 for kind<=3, 1 for kind>=4
  let hot  = mix(playerHot, enemyHot, isEnemy);
  let core = mix(playerCore, enemyCore, isEnemy);
  // core dominates when fresh; tint takes over as it fades
  let tint = mix(hot, core, l);
  // HDR emission: strong when fresh, glowing dim tail when old
  let energy = mix(1.2, 9.0, l * l);
  return tint * energy;
}

// VEILFIRE — atmosphere. Dread mood layered over a plainly-lit color.
//   vf_atmos(c, pos, rd, t, time):
//     c    = lit color at the hit (linear HDR)
//     pos  = hit point in world space
//     rd   = ray direction (unit)
//     t    = hit distance (fog falloff)
//     time = seconds
//   returns the color, dread-soaked. Output stays LINEAR HDR — no tonemap here.
//
// Four cheap layers, in order:
//   1. cool desaturation with a warm firelight bias (drain life, keep the fire)
//   2. torch flicker — layered sin-noise multiplying the whole scene
//   3. depth fog toward near-black cold murk (dread deepens it)
//   4. faint drifting ember specks low in the frame
//
// Mood dials read from the whiteboard (see SPEC): uni(12)=dread01, uni(18)=fogDensity.
// Both degrade gracefully to sane defaults when unset (zero).

fn vf_hash11(n: f32) -> f32 { return fract(sin(n * 43758.5453) * 12345.6789); }

fn vf_atmos(c: vec3f, pos: vec3f, rd: vec3f, t: f32, time: f32) -> vec3f {
  var col = c;

  let dread = clamp(uni(12), 0.0, 1.0);
  let fogD  = max(uni(18), 0.0);

  // ── 1. cool desaturation + warm firelight bias ─────────────────────────────
  // Drain saturation toward grey (harder the more dread), then re-tint: warm
  // ember in the lit/bright regions, cold blue in the shadows.
  let lum   = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  let desat = mix(col, vec3f(lum), 0.42 + 0.28 * dread);
  let warm  = vec3f(1.18, 0.60, 0.28);
  let cool  = vec3f(0.52, 0.66, 0.96);
  let tint  = mix(cool, warm, clamp(lum * 1.6, 0.0, 1.0));
  col = desat * tint;

  // ── 2. torch flicker — layered sin-noise, multiplies everything ────────────
  let f1 = sin(time * 11.0) * 0.5 + sin(time * 17.3 + 1.7) * 0.3 + sin(time * 29.0) * 0.2;
  let f2 = sin(time * 3.1 + 0.5);
  let flick = 1.0 + 0.06 * f1 + 0.03 * f2;   // roughly ±9% breathing
  col = col * flick;

  // ── 3. depth fog — a LIFTED cold haze (KINDLE murk). Fog toward near-black is
  // invisible in a dark room; a lifted blue-grey veils distance so the air reads
  // thick. Two bands: a near haze that lifts shadows + a far murk that swallows.
  let density = fogD + 0.010 + 0.012 * dread;
  let fogAmt  = 1.0 - exp(-t * t * density);
  let haze    = vec3f(0.055, 0.072, 0.110);       // cold blue-grey — the visible fog
  col = mix(col, haze, fogAmt);
  col = col + haze * 0.35 * fogAmt;                // scatter lift so it glows, not just dims

  // ── 4. drifting ember specks, low in the frame ─────────────────────────────
  // Parameterize by ray direction so motes float in view; drift upward in time.
  let ep = vec2f(rd.x * 6.0, rd.y * 6.0 - time * 0.35);
  var ember = 0.0;
  for (var k = 0; k < 3; k = k + 1) {
    let sc   = 1.0 + f32(k) * 1.7;
    let g    = ep * sc + vec2f(f32(k) * 13.7, f32(k) * 7.3);
    let cell = floor(g);
    let fr   = fract(g) - 0.5;
    let h    = vf_hash11(cell.x * 57.0 + cell.y * 131.0 + f32(k) * 3.0);
    let on   = step(0.92, h);                 // only a few cells host an ember
    let jit  = vec2f(vf_hash11(h * 21.0) - 0.5, vf_hash11(h * 47.0) - 0.5) * 0.6;
    let d    = length(fr - jit);
    let mote = on * smoothstep(0.09, 0.0, d);
    let tw   = 0.5 + 0.5 * sin(time * (4.0 + h * 6.0) + h * 30.0);  // twinkle
    ember = ember + mote * tw;
  }
  // Sit near the low end (bottom of view) and glow warmer through the murk.
  let lowBias  = smoothstep(0.30, -0.45, rd.y);
  let emberCol = vec3f(1.30, 0.52, 0.16);
  col = col + emberCol * ember * lowBias * (0.35 + 0.55 * fogAmt);

  return col;
}

// shooter3 HUD — screen-space overlay for the horror-shooter. No raymarch.
// Exports s3_hud(uv, hp01, ammo, score, dread01) -> vec4f (rgb, alpha); alpha 0
// where nothing is drawn so the integrator can composite it over the world.
//
// uv arrives -1..1 with y DOWN — the engine convention (uv.y=-1 top, +1 bottom;
// see render-core "MATCH THE ENGINE … uv.y increases DOWNWARD"). That already
// matches char5x7 / printInt (p in [0,1]², y DOWN), so s = uv*0.5+0.5 with no
// flip renders glyphs upright. Palette is thin, cold-white ink
// over near-black, with a rising red dread wash so the frame turns ominous as
// dread01 → 1. Legible on black; restrained on a lit scene.

// ── glyph cell helpers (screen coords s: 0..1, y DOWN) ────────────────────
// draw one glyph inside a box; returns coverage 0..1
fn s3_boxChar(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, code: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return char5x7(p, code);
}
// draw a right-aligned integer inside a box
fn s3_boxInt(s: vec2f, x0: f32, x1: f32, y0: f32, y1: f32, value: f32, digits: i32) -> f32 {
  if (s.x < x0 || s.x > x1 || s.y < y0 || s.y > y1) { return 0.0; }
  let p = vec2f((s.x - x0) / (x1 - x0), (s.y - y0) / (y1 - y0));
  return printInt(p, value, digits);
}
// one glyph within a monospace run: start x0, cell width cw, index j (0.8 fill)
fn s3_cellChar(s: vec2f, x0: f32, cw: f32, y0: f32, y1: f32, j: i32, code: i32) -> f32 {
  let cx0 = x0 + f32(j) * cw;
  return s3_boxChar(s, cx0, cx0 + cw * 0.82, y0, y1, code);
}

fn s3_hud(uv: vec2f, hp01: f32, ammo: f32, score: f32, dread01: f32) -> vec4f {
  // screen coords, top-left origin, y DOWN — matches the glyph font + engine.
  let s = vec2f(uv.x * 0.5 + 0.5, uv.y * 0.5 + 0.5);
  let hp = clamp(hp01, 0.0, 1.0);
  let dr = clamp(dread01, 0.0, 1.0);

  var col = vec3f(0.0);
  var a = 0.0;

  // ── dread wash: a red vignette that swells from the corners with dread01 ──
  // (built in uv space so it is symmetric regardless of the glyph y-flip)
  {
    let edge = smoothstep(0.55, 1.25, length(uv));   // 0 centre → 1 corners
    // a slow, uneasy pulse so high dread never sits perfectly still
    let breath = 0.82 + 0.18 * sin(uni(0) * 2.1);
    let vig = edge * dr * breath;
    col = vec3f(0.42, 0.02, 0.015) * vig;
    a = vig * 0.65;
  }

  // ── HEALTH BAR — bottom-left, red→green by hp01, dark empty track, frame ──
  {
    let x0 = 0.035; let x1 = 0.315; let y0 = 0.905; let y1 = 0.940;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let bt = 0.0035;                                          // border thickness
      let border = s.x < x0 + bt || s.x > x1 - bt || s.y < y0 + bt || s.y > y1 - bt;
      let fillX = x0 + (x1 - x0) * hp;
      if (border) {
        col = vec3f(0.55, 0.56, 0.62); a = 0.85;
      } else if (s.x <= fillX) {
        // red at 0 → amber mid → green at full; scale value so low HP reads hot
        let hc = mix(vec3f(0.95, 0.09, 0.06), vec3f(0.16, 0.92, 0.26), smoothstep(0.0, 1.0, hp));
        col = hc * (0.85 + 0.15 * hp); a = 0.92;
      } else {
        col = vec3f(0.05, 0.02, 0.02); a = 0.55;                // depleted track
      }
    }
    // "HP" label just above the bar
    let ly0 = 0.868; let ly1 = 0.898;
    let lc = max(s3_cellChar(s, 0.035, 0.024, ly0, ly1, 0, 72),   // H
                 s3_cellChar(s, 0.035, 0.024, ly0, ly1, 1, 80));  // P
    if (lc > 0.0) { col = vec3f(0.72, 0.74, 0.80); a = lc * 0.9; }
  }

  // ── AMMO — bottom-right, printInt (3 digits), with a small label ──
  {
    let x0 = 0.80; let x1 = 0.965; let y0 = 0.905; let y1 = 0.945;
    let cov = s3_boxInt(s, x0, x1, y0, y1, ammo, 3);
    if (cov > 0.0) { col = vec3f(0.86, 0.88, 0.94); a = cov * 0.95; }
    // "AMMO" label above the count
    let ly0 = 0.868; let ly1 = 0.898;
    let lx0 = 0.80; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 65);   // A
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 77)); // M
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 79)); // O
    if (lab > 0.0) { col = vec3f(0.66, 0.68, 0.74); a = lab * 0.85; }
  }

  // ── SCORE — top-right, printInt (6 digits), with a label ──
  {
    let x0 = 0.74; let x1 = 0.965; let y0 = 0.070; let y1 = 0.110;
    let cov = s3_boxInt(s, x0, x1, y0, y1, score, 6);
    if (cov > 0.0) { col = vec3f(0.90, 0.90, 0.95); a = cov * 0.95; }
    // "SCORE" label above the number
    let ly0 = 0.032; let ly1 = 0.062;
    let lx0 = 0.74; let cw = 0.026;
    var lab = s3_cellChar(s, lx0, cw, ly0, ly1, 0, 83);   // S
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 1, 67)); // C
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 2, 79)); // O
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 3, 82)); // R
    lab = max(lab, s3_cellChar(s, lx0, cw, ly0, ly1, 4, 69)); // E
    if (lab > 0.0) { col = vec3f(0.62, 0.63, 0.70); a = lab * 0.82; }
  }

  // ── DREAD METER — thin vertical bar, right edge, fills bottom→top ──
  {
    let x0 = 0.972; let x1 = 0.990; let y0 = 0.32; let y1 = 0.90;
    if (s.x >= x0 && s.x <= x1 && s.y >= y0 && s.y <= y1) {
      let fillTop = y1 - (y1 - y0) * dr;                 // fills upward with dread
      if (s.y >= fillTop) {
        let up = (y1 - s.y) / (y1 - y0);                 // 0 bottom → 1 top of bar
        let hot = mix(vec3f(0.55, 0.05, 0.04), vec3f(1.0, 0.28, 0.12), up);
        col = hot; a = 0.9;
      } else {
        col = vec3f(0.06, 0.02, 0.02); a = 0.5;          // empty channel
      }
    }
  }

  // ── CROSSHAIR — thin center cross with a gap, cold-white, reddens w/ dread ──
  {
    let ax = abs(uv.x); let ay = abs(uv.y);
    let th = 0.0038;
    let inR = 0.013; let outR = 0.050;
    let horiz = ay < th && ax > inR && ax < outR;
    let vert  = ax < th && ay > inR && ay < outR;
    let dot   = length(uv) < 0.0028;
    if (horiz || vert || dot) {
      col = mix(vec3f(0.92, 0.95, 1.0), vec3f(1.0, 0.18, 0.12), dr);
      a = 0.9;
    }
  }

  return vec4f(col, clamp(a, 0.0, 1.0));
}

stepHooks.code:
try {
  const wd = sim.worldData
  if (!wd.__vf) wd.__vf = {}
  const V = wd.__vf
  V.t = (V.t || 0) + Math.min(dt, 1 / 30)
  const t = V.t
  const u = Array.isArray(wd.gpuUniforms) ? wd.gpuUniforms : new Array(256).fill(0)
  while (u.length < 256) u.push(0)

  // FIXED camera: stand at the side room's near wall, look down its centre at the
  // two floor zones (room centred at world x=8, z=0). ro,fov on uni4(60); target on uni4(61).
  u[240] = 8.0; u[241] = 2.15; u[242] = -3.4; u[243] = 1.28
  u[244] = 8.0; u[245] = 0.55; u[246] = 0.8;  u[247] = 0.0

  // RULE-ZONE time schedule -> uni(30): hue+wave -> invert -> +posterize, 6s loop.
  V.rzf = ((V.rzf || 0) + 1) % 360; u[30] = V.rzf
  wd.gpuUniforms = u

  // THE DANCERS: 3 demons, 120deg out of phase, sweeping x across BOTH zones so
  // each body is re-lawed limb by limb as it crosses the seam. Deterministic in t.
  const pop = []
  const N = 3
  for (let i = 0; i < N; i++) {
    const ph = i * 2.0944                                  // 120 degrees apart
    const x = 8.0 + 2.0 * Math.sin(t * 0.7 + ph)           // sweeps x in [6,10]: zone A -> overlap -> zone B
    const z = 0.18 * Math.sin(t * 1.6 + ph * 1.3)          // gentle sway
    const bob = Math.abs(Math.sin(t * 2.4 + ph)) * 0.10    // a little dance bounce
    const dir = Math.cos(t * 0.7 + ph)                     // sign = travel direction along x
    const yaw = dir >= 0 ? 1.5708 : -1.5708                // face the way it's walking (+x / -x)
    const gait = t * 1.7 + ph                              // advance the leg cycle -> real walk
    pop.push(x, bob, z, 1.0, 1.0, gait, yaw, 0.0)          // (x,y,z,kind=demon)(hp,gaitPhase,yaw,atk)
  }
  V.pop = pop
  wd.gpuPopulation = pop
} catch (e) {}

visualTypes.wgsl:
// shooter3 MEGASHADER (node: renderer-mega). ONE visual raymarches the world
// (w3_map from veilfire/rooms) and depth-composites the whole population in a
// single dispatch — demons (vf_demon), projectiles/death-bits (emissive) — then
// atmosphere (vf_atmos), muzzle/hit flashes, and the HUD (s3_hud) on top.
//
// Occlusion is correct + cheap: each entity is first rejected by a ray-vs-
// bounding-sphere test and by `t > worldT` (behind a wall), so only entities the
// ray actually pierces IN FRONT of the world get a local march. Camera on
// uni4(60/61). w3_map + vf_demon + s3_* + vf_atmos come from sibling modules.

// ray → sphere near-t (negative if no hit; may be <0 if camera inside)
fn s3_sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> f32 {
  let oc = ro - c;
  let b = dot(oc, rd);
  let h = b * b - (dot(oc, oc) - r * r);
  if (h < 0.0) { return -1.0; }
  return -b - sqrt(h);
}

// ── RULE ZONES (laws as per-pixel fields) ───────────────────────────────────
// Two radial zones on the side-room floor plane (world centred at x=8, z=0). A
// pixel is re-lawed by which zone its WORLD HIT-POINT falls in, so walls, floor,
// AND a demon crossing the seam are all sliced per-pixel by the same test. The
// active law-set shifts by frame (uni(30), counted in the hook):
//   frames <120: zoneA hue-rotates, zoneB wave-ripples, overlap does BOTH.
//   frames 120-239: zoneA law swaps to INVERT (live, by data not deploy).
//   frames >=240: a posterize law is ADDED over BOTH zones.
fn vf_rz_hue120(c: vec3f) -> vec3f { return vec3f(c.b, c.r, c.g); }
fn vf_rulezones(col0: vec3f, hp: vec3f, t: f32) -> vec3f {
  let q = vec2f(hp.x - 8.0, hp.z);              // side-room-local floor coords
  let rr = 2.15 + 0.18 * sin(t * 0.6);          // radii breathe (zones keep animating)
  let dA = length(q - vec2f(-1.35, 0.0));
  let dB = length(q - vec2f( 1.35, 0.0));
  let inA = dA < rr;
  let inB = dB < rr;
  if (!inA && !inB) { return col0; }
  let frameN = uni(30);
  var col = col0;
  // ruleB — the WAVE law: a travelling chroma ripple over the pixels in zone B.
  if (inB) {
    let w = 0.45 + 0.55 * sin(hp.y * 3.6 + t * 3.2 + q.x * 4.0);
    col = mix(col.zyx, vec3f(0.10, 0.45, 0.95) * (0.4 + col), w * 0.85);
  }
  // ruleA — hue-rotate (bold), then INVERT after frame 120 (rule swap, mid-run).
  if (inA) {
    if (frameN < 120.0) { col = mix(col, vf_rz_hue120(col) * 1.3 + vec3f(0.0, 0.18, 0.0), 0.9); }
    else { col = vec3f(1.0) - col; }
  }
  // ruleC — posterize, ADDED over BOTH zones after frame 240 (rule added, mid-run).
  if (frameN >= 240.0) { col = floor(col * 5.0) / 5.0; }
  // lit rims so each zone boundary reads unmistakably in the dark.
  let rim = min(abs(dA - rr), abs(dB - rr));
  col += vec3f(1.0, 0.9, 0.5) * smoothstep(0.10, 0.0, rim) * 1.4;
  return col;
}

fn visual_s3(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let ro = uni4(60).xyz;
  let fov = max(uni4(60).w, 0.6);
  let rd = mod_w3_ray(uv, ro, uni4(61).xyz, fov);
  let sky = vec3f(0.02, 0.025, 0.05);

  // ── the world ──
  let wh = mod_w3_march(ro, rd, 0.02, 60.0, 96);
  var worldT = select(60.0, wh.x, wh.x >= 0.0);
  var col = sky;
  if (wh.x >= 0.0) {
    let pos = ro + rd * wh.x;
    let n = mod_w3_nrm(pos, 0.02);
    let ao = mod_w3_ao(pos, n);
    var alb = vec3f(0.30, 0.29, 0.36);                              // walls
    if (wh.y > 1.5 && wh.y < 2.5) { alb = vec3f(0.15, 0.14, 0.13); } // floor/dais
    if (wh.y > 2.5 && wh.y < 3.5) { alb = vec3f(0.22, 0.20, 0.24); } // column
    if (wh.y > 3.5) { alb = vec3f(0.55, 0.34, 0.14); }              // doorway trim
    // lantern (headlamp at the camera — vf-lightdark will move it to the player)
    let ld = normalize(ro - pos);
    let dist = length(ro - pos);
    let sh = mod_w3_shadow(pos + n * 0.04, ld, dist, 14.0);
    let diff = max(dot(n, ld), 0.0);
    let atten = 4.5 / (1.0 + 0.09 * dist * dist);
    col = alb * (vec3f(0.05, 0.06, 0.09) + vec3f(1.0, 0.82, 0.55) * diff * atten * sh) * ao;
  }

  // ── the population, depth-composited in front of the world ──
  var nearT = worldT;
  let cnt = popCount() / 2;
  for (var i = 0; i < cnt; i = i + 1) {
    let a = pop(i * 2);            // x, y, z, kind
    let b = pop(i * 2 + 1);        // hp01, phase, yaw, flags
    let kind = a.w;
    if (kind < 0.5) { continue; }  // empty slot
    let ppos = a.xyz;
    let isDemon = kind < 2.5;
    // BUG WAS HERE: sphere sat at the feet (y=0, r=1.4) → it clipped everything
    // above y=1.4: the ribcage, head, horns. Center it at torso height + widen so
    // the WHOLE body is inside the sphere test AND the local march below.
    let bc = ppos + vec3f(0.0, select(0.0, 1.05, isDemon), 0.0);
    let br = select(0.18, 1.6, isDemon);
    let sh = s3_sph(ro, rd, bc, br);
    if (sh < 0.0 || sh > nearT) { continue; }        // ray misses, or behind the world

    if (kind < 2.5) {
      // DEMON — local sphere-march (rotate the ray into the demon's yaw frame)
      let yaw = b.z;
      let cy = cos(-yaw); let sy = sin(-yaw);
      let o0 = ro - ppos;
      let lro = vec3f(cy * o0.x + sy * o0.z, o0.y, -sy * o0.x + cy * o0.z);
      let lrd = vec3f(cy * rd.x + sy * rd.z, rd.y, -sy * rd.x + cy * rd.z);
      var t = max(sh, 0.02);
      var hitT = -1.0;
      for (var s = 0; s < 30; s = s + 1) {
        let d = vf_demon(lro + lrd * t, b.y);
        if (d < 0.004) { hitT = t; break; }
        t = t + max(d * 0.8, 0.004);
        if (t > nearT || t > sh + 2.0 * br) { break; }
      }
      if (hitT > 0.0 && hitT < nearT) {
        nearT = hitT;
        let lp = lro + lrd * hitT;
        let e = 0.012;
        let nn = normalize(vec3f(
          vf_demon(lp + vec3f(e, 0.0, 0.0), b.y) - vf_demon(lp - vec3f(e, 0.0, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, e, 0.0), b.y) - vf_demon(lp - vec3f(0.0, e, 0.0), b.y),
          vf_demon(lp + vec3f(0.0, 0.0, e), b.y) - vf_demon(lp - vec3f(0.0, 0.0, e), b.y)));
        let ll = normalize(lro - lp);                 // headlamp, in local frame
        let dist = length(ro - (ro + rd * hitT));
        let diff = max(dot(nn, ll), 0.0);
        let atten = 4.0 / (1.0 + 0.10 * dist * dist);
        let base = vec3f(0.11, 0.05, 0.045);          // charred flesh
        let ember = vec3f(1.0, 0.32, 0.07) * pow(clamp(0.6 - nn.y, 0.0, 1.0), 2.0) * (0.7 + 0.5 * sin(time * 6.0 + ppos.x));
        col = base * (0.12 + diff * atten) + ember * 0.9;
      }
    } else {
      // PROJECTILE / DEATH-BIT — emissive blob at the sphere hit
      if (sh < nearT) {
        nearT = sh;
        let life = clamp(b.x, 0.0, 1.0);
        if (kind > 4.5) { col = vec3f(1.0, 0.42, 0.12) * (0.5 + life * 1.6); }  // death ember
        else { col = s3_tracerColor(kind, life) * 1.4; }
      }
    }
  }

  // ── rule zones re-law the pixel by its world hit-point (before atmosphere so
  //    fog/embers still unify the room). Inert everywhere but the side chamber. ──
  col = vf_rulezones(col, ro + rd * nearT, time);

  // ── atmosphere over whatever we hit, then flashes, then HUD ──
  col = vf_atmos(col, ro + rd * nearT, rd, nearT, time);
  col += vec3f(1.0, 0.82, 0.5) * max(uni(15), 0.0) * 0.6;   // muzzle flash
  col += vec3f(1.0, 0.22, 0.16) * max(uni(16), 0.0) * 0.5;  // hit flash
  let hud = s3_hud(uv, uni(6), uni(7), uni(8), uni(12));
  col = mix(col, hud.rgb, hud.a);
  return vec4f(col, 1.0);
}

stepHooks.code:
try {
  const wd = sim.worldData
  // a fresh session keeps the universe (positions are shared, live for all
  // players) but must drop per-session state: a stashed portalSig matches its
  // own frozen layout and would mute the doors forever, and a stashed
  // 'launched' latch would keep them mute after returning from a world.
  if (wd.__fresh) {
    delete wd.__fresh
    if (wd.__cu) {
      const R = wd.__cu
      R.portalSig = null; R.lastHover = -1; R.prevDown = false; R.kN = {}
      R.launched = 0; R.drag = 0; R.pollT = 0; R.sharedAt = 0
    }
  }
  // wake starts 0: a joining player adopts the shared universe at rest —
  // only real perturbations (a birth, a chant shift, a filter flip) wake it
  if (!wd.__cu || wd.__cu.v !== 2) wd.__cu = { v: 2, bubbles: {}, order: [], cam: { x: 256, y: 256, z: 1 },
    pollT: 0, wake: 0, mineKey: '', drag: 0, dx: 0, dy: 0, downX: 0, downY: 0, moved: 0, prevDown: false, lastHover: -1, kN: {} }
  const U = wd.__cu
  if (!U.boot) U.boot = Date.now()
  // CALM BOOT: for the first seconds, arrivals adopt the shared layout without
  // waking the field — the load must show the live state, never a guess that
  // then re-packs. (First poll runs with 700ms patience fallbacks; the 2s
  // re-poll's fuller data used to jolt every bubble.)
  const calmBoot = Date.now() - U.boot < 8000
  const dt2 = Math.min(dt, 0.05)
  // ── whose universe? MY WORLDS flips the door into a personal submain ──
  const MF = (typeof window !== 'undefined' && window.__cafeMine && window.__cafeMine.on) ? window.__cafeMine : null
  // PLAYER WORLDS — a big front-door bubble opens a filter of just the player-made
  // worlds (the same scene, spaces only). window.__cafePlayers carries the flag.
  // PLAYER WORLDS filter: 0 off · 1 makers directory · 'house' the house shelf
  const PLv = (typeof window !== 'undefined' && window.__cafePlayers) || 0
  const PL = PLv ? 1 : 0
  const HOUSE = PLv === 'house'
  // SUB-MAIN: the group layer. Every user can found ONE named sub-main —
  // a /group formation, not a world. The viewer shows only sub-mains (yours
  // at the heart); entering one morphs this same universe into the group's
  // shelf. window.__cafeSub carries the slug while inside a group.
  const SUB = !!wd.__submain
  const subKey = SUB ? String((typeof window !== 'undefined' && window.__cafeSub) || '') : ''
  const mineKey = MF ? String(MF.handle || MF.ownerId || MF.who || '') : PL ? (HOUSE ? 'house' : 'players') : (SUB ? 'sub:' + subKey : '')
  // every mode keeps its OWN persisted layout, so a joining player or a reload
  // adopts it AT REST instead of replaying the rim fly-in: main = the shared
  // universe, MY WORLDS = per-deed, SUB-MAIN = per-group (or the viewer roster).
  const layoutSlot = MF ? ('cafe:universe:mine:' + mineKey)
    : PL ? ('cafe:universe:' + (HOUSE ? 'house' : 'players'))
    : SUB ? ('cafe:universe:' + mineKey)
    : 'cafe:universe'
  // a filter/mode flip loads a DIFFERENT saved layout: re-poll now and clear the
  // adopt-watermark so the new slot is taken at rest. NO forced wake — if that
  // layout is saved the bubbles land settled; only a genuinely new world (the
  // newborn branch) wakes the field, so unchanged rosters never re-animate.
  if (U.mineKey !== mineKey) { U.mineKey = mineKey; U.pollT = 0; U.hintedEmpty = false; U.sharedAt = 0
    // NESTED PRESENCE (web/docs/presence-nesting-spec.md) — emit this view's
    // location path on view change (deduped by mineKey, no React-state lag). The
    // shell keys the live-cursor room off it. STEP 1: only PLAYER WORLDS acts on
    // this (the confirmed bleed); main + sub-mains keep their current rooms.
    if (typeof window !== 'undefined') {
      const path = MF ? 'main/mine/' + mineKey
        : PL ? (HOUSE ? 'main/players/house' : 'main/players')
        : SUB ? (subKey ? 'main/subs/sub:' + subKey : 'main/subs')
        : 'main'
      window.dispatchEvent(new CustomEvent('cafe:presence', { detail: { path } }))
    }
    // SNAP: a mode flip re-centers the view on the new roster instantly. Without
    // this the camera keeps wherever main was panned/zoomed, so MY WORLDS opens
    // off in a corner and never "arrives".
    U.cam.x = 256; U.cam.y = 256; U.cam.z = 1; U.drag = 0 }
  // a poke = the shell just changed a shelf; re-poll now instead of waiting
  const poke = (typeof window !== 'undefined' && window.__cafePoke) || 0
  if (poke > (U.pokeAt || 0)) { U.pokeAt = poke; U.pollT = 0 }
  const STYLE_OF = { 'FABRIC': 0, 'ORRERY': 1, 'GARNET': 2, 'ONE DAY': 3, 'SAIL': 4, 'SOLSTICE': 5, 'TIDERUNNER': 6, 'SIGNAL': 7 }
  const hueOf = n => { let h = 0; for (const c of n) h = (h * 31 + c.charCodeAt(0)) % 997; return (h % 100) / 100 }
