  return vec4f(col, 1.0);
}

fn visual_carveproof(uv: vec2f, t: f32, wd: WorldData) -> vec3f {
  var col = vec3f(0.02, 0.03, 0.06);
  // starfield backdrop
  let g = fract(uv * 9.0) - 0.5;
  col += vec3f(0.05) * smoothstep(0.02, 0.0, length(g)) * step(0.93, fract(sin(dot(floor(uv*9.0), vec2f(12.9898,78.233)))*43758.5453));
  // THE PENTAGON — the game's sigil, drawn by 5 half-planes
  let c = uv;
  var dPent = -10.0;
  for (var k = 0; k < 5; k++) {
    let a = 6.2831853 * f32(k) / 5.0 - 1.5707963;
    let n = vec2f(cos(a), sin(a));
    dPent = max(dPent, dot(c, n) - 0.28);
  }
  let edge = smoothstep(0.012, 0.0, abs(dPent));
  col += vec3f(0.2, 0.9, 0.6) * edge * (0.7 + 0.3 * sin(t * 2.0));
  col += vec3f(0.05, 0.3, 0.2) * smoothstep(0.0, -0.25, dPent);
  // ORBITERS — one per carved function (14), riding a ring
  for (var i = 0; i < 14; i++) {
    let a = t * 0.5 + 6.2831853 * f32(i) / 14.0;
    let p = vec2f(cos(a), sin(a)) * 0.62;
    let d = length(uv - p);
    col += vec3f(0.9, 0.6, 0.2) * smoothstep(0.03, 0.0, d);
  }
  // PULSE RING driven by the hook (proof the hook runs): wd.pulse 0..1
  let pr = abs(length(uv) - (0.35 + wd.pulse * 0.45));
  col += vec3f(0.4, 0.6, 1.0) * smoothstep(0.02, 0.0, pr) * (1.0 - wd.pulse);
  return col;
}

fn visual_carveproof(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  // DIAGNOSTIC: reveal the uv range. 0..1 -> smooth gradient; 0..512 -> stripes
  return vec4f(fract(uv.x), fract(uv.y), fract(uv.x / 512.0) * 0.5 + 0.25, 1.0);
}

