    fy += uy*pull - uy*0.04/(d*d+0.006)
  }
  n.vx = (n.vx + fx*dt2) * 0.985; n.vy = (n.vy + fy*dt2) * 0.985
}
for (const n of C.nodes) { n.x += n.vx*dt2; n.y += n.vy*dt2 }
// filaments are EARNED while close, decay apart
for (let i = 0; i < N; i++) for (let j = i+1; j < N; j++) {
  const d = Math.hypot(C.nodes[i].x-C.nodes[j].x, C.nodes[i].y-C.nodes[j].y)
  const f = C.fil[i][j]
  const v = d < 0.56 ? Math.min(1, f + dt2*0.5) : Math.max(0, f - dt2*0.25)
  C.fil[i][j] = v; C.fil[j][i] = v
}
// champion = most held relations; a long reign fatigues its affinities
let best = -1, bs = -1
for (let i = 0; i < N; i++) { let s = 0; for (let j = 0; j < N; j++) s += C.fil[i][j]; if (s > bs) { bs = s; best = i } }
if (best === C.champ) {
  C.reignT += dt2
  if (C.reignT > 6) for (let j = 0; j < N; j++) { C.aff[C.champ][j] *= (1 - dt2*0.12); C.aff[j][C.champ] = C.aff[C.champ][j] }
} else { C.champ = best; C.reignT = 0 }
// publish to the shader: 20 positions · champ + reign · top 12 filaments as (i,j,strength)
const u = []
for (const n of C.nodes) u.push(n.x, n.y)
u.push(C.champ, Math.min(1, C.reignT / 8))
const tops = []
for (let i = 0; i < N; i++) for (let j = i+1; j < N; j++) if (C.fil[i][j] > 0.03) tops.push([C.fil[i][j], i, j])
tops.sort((a, b) => b[0] - a[0])
for (let k = 0; k < 12; k++) { const t3 = tops[k]; u.push(t3 ? t3[1] : -1, t3 ? t3[2] : -1, t3 ? t3[0] : 0) }
wd.gpuUniforms = u

