fn visual_prov_shape(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  if (d > 0.92) { return vec4f(0.0); }
  let pulse = 0.85 + 0.15 * sin(time * 2.0 + params.x * 6.28);
  let rim = smoothstep(0.92, 0.7, d);
  return vec4f(color.rgb * (0.5 + 0.5 * rim) * pulse, 1.0);
}

fn visual_base(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let c = mix(vec3f(0.10,0.13,0.26), vec3f(0.03,0.04,0.09), clamp(d,0.0,1.0));
  return vec4f(c, 1.0);
}

fn visual_orb(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv * 1.1);
  if (d > 1.0) { return behind; }
  let pulse = 0.5 + 0.5 * sin(time * 2.0);
  let glow = smoothstep(1.0, 0.0, d) * (0.6 + 0.4 * pulse);
  return vec4f(mix(behind.rgb, vec3f(0.40,0.72,1.0), glow), 1.0);
}

fn visual_ring(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let r = abs(d - 0.72);
  let m = smoothstep(0.05, 0.0, r);
  let a = 0.55 + 0.45 * sin(time * 3.0 + atan2(uv.y, uv.x) * 6.0);
  return vec4f(mix(behind.rgb, vec3f(1.0,0.62,0.22), m*a), 1.0);
}

