fn visual_ship(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let g = vec2f((uv.x * 0.5 + 0.5) * 512.0, (uv.y * 0.5 + 0.5) * 512.0);  // uv → grid coords
  for (var i = 0; i < 32; i++) {
    if (i >= popCount()) { break; }
    let e = pop(i);                          // x, y, kind, radius (grid coords)
    if (distance(g, e.xy) < e.w) {
      markPop(i);                            // ← ENTITY OWNER: this pixel belongs to part i
      let k = i32(e.z);
      var c = vec3f(0.5);
      if (k == 0) { c = vec3f(0.43, 0.47, 0.55); }   // HULL
      if (k == 1) { c = vec3f(0.59, 0.59, 0.63); }   // ARMOR
      if (k == 2) { c = vec3f(0.80, 0.35, 0.27); }   // GUN
      if (k == 3) { c = vec3f(0.35, 0.67, 0.80); }   // ENGINE
      if (k == 4) { c = vec3f(0.86, 0.74, 0.47); }   // CORE
      let d = distance(g, e.xy) / e.w;
      return vec4f(c * (0.6 + 0.4 * (1.0 - d)), 1.0);
    }
  }
  return vec4f(0.02, 0.03, 0.05, 1.0);       // dark background (opaque → superimpose branch)
}
